	[146] = {
		describe_id = "Untuk setiap Pokémon sekutu tipe Api atau Naga dalam pertempuran, memperoleh #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK dasar",
		zawakeEffectDesc_vn = "Para cada Pokémon aliado do tipo Fogo ou Dragão na batalha, ganha #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK básico; adiciona [Burn] a uma unidade inimiga aleatória por 2 rodadas antes do início de cada grande rodada quando existirem outras unidades do tipo Fogo no lado aliado; se houver 3 ou mais unidades do tipo Fogo no campo aliado, no final de cada grande rodada, causa 60% P.DMG a todas as unidades inimigas no estado Burn.",
		describe_vn = "Para cada Pokémon aliado do tipo Fogo ou Dragão na batalha, ganha #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK básico",
		starEffectDesc_id = "Efek ekstra: Mengabaikan 20% P.DEF saat menyerang [Burn] target",
		zawakeEffectDesc_th = "สำหรับโปเกมอนพันธมิตรประเภทไฟหรือมังกรทุกตัวในการต่อสู้ จะได้รับ #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK พื้นฐาน เพิ่ม [Burn] ให้กับยูนิตศัตรูแบบสุ่มเป็นเวลา 2 รอบก่อนเริ่มรอบใหญ่แต่ละรอบ เมื่อมียูนิตประเภทไฟอื่นอยู่ในฝั่งพันธมิตร หากมียูนิตประเภทไฟ 3 ตัวขึ้นไปบนสนามพันธมิตร เมื่อสิ้นสุดแต่ละรอบใหญ่ จะสร้าง P.DMG 60% ให้กับยูนิตศัตรูทั้งหมดในสถานะเผาไหม้",
		starEffectDesc_kr = "추가 효과: [Burn] 대상 공격 시 P.DEF 20% 무시",
		describe_es = "Por cada Pokémon aliado de tipo Fuego o Dragón en la batalla, gana #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK básico",
		zawakeSimpleDesc_en = "#C0x5c9970#adds [Burn] to a random enemy unit for 2 rounds before the start of each big round when other Fire-type units exist on the allied side; if there are 3 or more Fire-type units on the allied field, at the end of each big round, deals 60% P.DMG to all enemy units in Burn state.",
		starEffectDesc_es = "Efecto extra: Ignora el 20% P.DEF al atacar [Burn] objetivos",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: ไม่สนใจ P.DEF 20% เมื่อโจมตีเป้าหมาย [Burn]",
		zawakeEffectDesc_id = "Untuk setiap Pokémon sekutu tipe Api atau Naga dalam pertempuran, memperoleh #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK dasar; menambahkan [Burn] ke unit musuh acak selama 2 ronde sebelum dimulainya setiap ronde besar ketika unit tipe Api lainnya ada di pihak sekutu; jika terdapat 3 atau lebih unit Tipe Api di medan gabungan, di akhir setiap putaran besar, menimbulkan 60% P.DMG ke semua unit musuh dalam kondisi Terbakar.",
		zawakeEffectDesc_es = "Por cada Pokémon aliado de tipo Fuego o Dragón en la batalla, gana #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK básico; agrega [Burn] a una unidad enemiga aleatoria durante 2 rondas antes del inicio de cada ronda grande cuando existen otras unidades de tipo Fuego en el lado aliado; Si hay 3 o más unidades de tipo Fuego en el campo aliado, al final de cada ronda grande, inflige un 60% de P.DMG a todas las unidades enemigas en estado Burn.",
		describe_en = "For every Fire or Dragon type ally Pokémon in the battle, gains #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# basic P.ATK",
		zawakeSimpleDesc_th = "#C0x5c9970#เพิ่ม [Burn] ไปยังยูนิตศัตรูแบบสุ่มเป็นเวลา 2 รอบก่อนเริ่มรอบใหญ่แต่ละรอบ เมื่อมียูนิตประเภทไฟอื่นอยู่ในฝั่งพันธมิตร หากมียูนิตประเภทไฟ 3 ตัวขึ้นไปบนสนามพันธมิตร เมื่อสิ้นสุดแต่ละรอบใหญ่ จะสร้าง P.DMG 60% ให้กับยูนิตศัตรูทั้งหมดในสถานะเผาไหม้",
		zawakeEffectDesc_kr = "전투에 참여한 모든 불꽃 또는 용 유형 아군 포켓몬에 대해 #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# 기본 P.ATK를 얻습니다. 아군 측에 다른 화재 유형 유닛이 있는 경우 각 큰 라운드가 시작되기 전 2라운드 동안 무작위 적 유닛에 [Burn]를 추가합니다. 아군 필드에 화염 유형 유닛이 3개 이상 있을 경우, 각 빅 라운드 종료 시 화상 상태에 있는 모든 적 유닛에게 60% P.DMG를 줍니다.",
		zawakeSimpleDesc_kr = "#C0x5c9970#아군 측에 다른 화염 유형 유닛이 있는 경우 각 큰 라운드가 시작되기 전 2라운드 동안 무작위 적 유닛에 [Burn]를 추가합니다. 아군 필드에 화염 유형 유닛이 3개 이상 있을 경우, 각 빅 라운드 종료 시 화상 상태에 있는 모든 적 유닛에게 60% P.DMG를 줍니다.",
		zawakeEffectDesc_en = "For every Fire or Dragon type ally Pokémon in the battle, gains #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# basic P.ATK; adds [Burn] to a random enemy unit for 2 rounds before the start of each big round when other Fire-type units exist on the allied side; if there are 3 or more Fire-type units on the allied field, at the end of each big round, deals 60% P.DMG to all enemy units in Burn state.",
		describe_kr = "전투에 참여하는 모든 불꽃 또는 드래곤 유형 아군 포켓몬마다 #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# 기본 P.ATK를 얻습니다.",
		zawakeSimpleDesc_vn = "#C0x5c9970#adiciona [Burn] a uma unidade inimiga aleatória por 2 rodadas antes do início de cada grande rodada quando existirem outras unidades do tipo Fogo no lado aliado; se houver 3 ou mais unidades do tipo Fogo no campo aliado, no final de cada grande rodada, causa 60% P.DMG a todas as unidades inimigas no estado Burn.",
		zawakeSimpleDesc_id = "#C0x5c9970#menambahkan [Burn] ke unit musuh acak selama 2 ronde sebelum dimulainya setiap ronde besar ketika unit tipe Api lainnya ada di pihak sekutu; jika terdapat 3 atau lebih unit Tipe Api di medan gabungan, di akhir setiap putaran besar, menimbulkan 60% P.DMG ke semua unit musuh dalam kondisi Terbakar.",
		starEffectDesc_vn = "Efeito extra: Ignora 20% P.DEF ao atacar alvos [Burn]",
		zawakeSimpleDesc_es = "#C0x5c9970# agrega [Burn] a una unidad enemiga aleatoria durante 2 rondas antes del inicio de cada ronda grande cuando existen otras unidades de tipo Fuego en el lado aliado; Si hay 3 o más unidades de tipo Fuego en el campo aliado, al final de cada ronda grande, inflige un 60% de P.DMG a todas las unidades enemigas en estado Burn.",
		describe_th = "สำหรับโปเกมอนพันธมิตรประเภทไฟหรือมังกรทุกตัวในการต่อสู้ จะได้รับ #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B# P.ATK พื้นฐาน",
		starEffectDesc_en = "Extra effect: Ignores 20% P.DEF when attacking [Burn] targets",
