		zawakeEffectDesc_vn = "Pidgeotto lança um único inimigo para o céu e o ataca com gravidade para lidar com#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, e aumenta permanentemente o SPD do Pokémon aliado em 10%, e este efeito duplica para Pokémon do tipo Flying",
		simDesc_es = "Pidgeotto lanza un único objetivo enemigo al cielo y le da un fuerte golpe usando la gravedad. Inflige daño adicional a objetivos con una velocidad inferior a la suya.",
		describe_es = "Pidgeotto lanza un único enemigo al cielo y lo ataca con gravedad para infligir#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, y aumenta el SPD de los Pokémon aliados en un 10% durante 3 rondas, y este efecto se duplica para los Pokémon de tipo Volador.",
		zawakeEffectDesc_th = "ปิเจออตโตขว้างศัตรูตัวเดียวขึ้นไปบนฟ้าแล้วโจมตีด้วยแรงโน้มถ่วงเพื่อสร้างความเสียหาย#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B# และเพิ่ม SPD ของโปเกมอนพันธมิตรอย่างถาวร 10% และเอฟเฟกต์นี้จะเพิ่มเป็นสองเท่าให้กับโปเกมอนประเภทบิน",
		starEffectDesc_id = "Efek tambahan: Jurus Ultimate berikutnya akan memberikan tambahan 20% damage pada unit dengan kecepatan lebih rendah dari dirinya",
		starEffectDesc_es = "Efecto adicional: el próximo movimiento definitivo infligirá un 20 % de daño adicional a las unidades con una velocidad inferior a la suya.",
		zawakeSimpleDesc_en = "increase allied Pokémon's SPD by 10% for 3 rounds, and this effect doubles to Flying-Type Pokémon\n#F20#\n#F40##C0x5c9970#→permanently increase allied Pokémon's SPD by 10%, and this effect doubles to Flying-Type Pokémon",
		describe_vn = "Pidgeotto lança um único inimigo para o céu e o ataca com gravidade para lidar com #C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B# e aumenta o SPD do Pokémon aliado em 10% por 3 rodadas, e esse efeito dobra para Pokémon do tipo Voador",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: ท่าไม้ตายครั้งต่อไปจะสร้างความเสียหายเพิ่มเติม 20% ให้กับยูนิตที่มีความเร็วต่ำกว่าตัวเอง",
		starEffectDesc_vn = "Efeito adicional: O próximo movimento Ultimate causará 20% de dano extra a unidades com velocidade menor que ele",
		zawakeEffectDesc_kr = "피지오토는 적 한 마리를 하늘로 던져 중력 공격을 가해 #C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#를 처리하며, 아군 포켓몬의 속도를 영구적으로 10% 증가시킵니다. 비행타입 포켓몬에게는 이 효과가 2배로 적용됩니다.",
		describe_en = "Pidgeotto throws a single enemy to the sky and attacks it with gravity to deal#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, and increase allied Pokémon's SPD by 10% for 3 rounds, and this effect doubles to Flying-Type Pokémon",
		zawakeEffectDesc_id = "Pidgeotto melemparkan satu musuh ke langit dan menyerangnya dengan gravitasi untuk menangani#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, dan secara permanen meningkatkan SPD Pokémon sekutu sebesar 10%, dan efek ini berlipat ganda menjadi Pokémon Tipe Terbang",
		describe_id = "Pidgeotto melemparkan satu musuh ke langit dan menyerangnya dengan gravitasi untuk menangani#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, dan meningkatkan SPD Pokémon sekutu sebanyak 10% sebanyak 3 putaran, dan efek ini berlipat ganda menjadi Pokémon Tipe Terbang",
		simDesc_en = "Pidgeotto hurls a single enemy target to the sky and give it a heavy blow using gravity. It deals extra damage to targets with speed lower than itself",
		simDesc_vn = "Pidgeotto lança um único alvo inimigo para o céu e dá-lhe um golpe forte usando a gravidade. Causa dano extra a alvos com velocidade menor que a dele",
		describe_kr = "피지오토는 적 한 마리를 하늘로 던져 중력으로 공격해 처리하며 #C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, 아군 포켓몬의 속도를 3초간 10% 증가시킵니다. 이 효과는 비행타입 포켓몬에게 2배로 적용됩니다.",
		simDesc_th = "Pidgeotto ขว้างศัตรูเป้าหมายเดียวขึ้นไปบนท้องฟ้า และโจมตีอย่างหนักหน่วงโดยใช้แรงโน้มถ่วง สร้างความเสียหายเพิ่มเติมแก่เป้าหมายด้วยความเร็วที่ต่ำกว่าตัวมันเอง",
		zawakeEffectDesc_es = "Pidgeotto lanza un solo enemigo al cielo y lo ataca con gravedad para infligir#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, y aumentar permanentemente el SPD de los Pokémon aliados en un 10%. y este efecto se duplica para los Pokémon de tipo volador.",
		starEffectDesc_kr = "추가 효과: 다음 궁극기가 자신보다 속도가 느린 유닛에게 20%의 추가 피해를 입힙니다.",
		zawakeEffectDesc_en = "Pidgeotto throws a single enemy to the sky and attacks it with gravity to deal#C0xE69900#480%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#, and permanently increase allied Pokémon's SPD by 10%, and this effect doubles to Flying-Type Pokémon",
		simDesc_kr = "피지오토는 적 대상 하나를 하늘로 던지고 중력을 이용해 강한 타격을 가합니다. 자신보다 속도가 느린 대상에게 추가 피해를 입힙니다.",
		zawakeSimpleDesc_th = "เพิ่ม SPD ของโปเกมอนฝ่ายเดียวกัน 10% เป็นเวลา 3 รอบ และเอฟเฟกต์นี้จะเพิ่มเป็นสองเท่ากับโปเกมอนประเภทบิน\n#F20#\n#F40##C0x5c9970#→เพิ่ม SPD ของโปเกมอนพันธมิตรอย่างถาวร 10% และเอฟเฟกต์นี้จะเพิ่มเป็นสองเท่ากับการบิน- พิมพ์โปเกมอน",
		zawakeSimpleDesc_kr = "3라운드 동안 아군 포켓몬의 속도가 10% 증가하고 이 효과는 비행형 포켓몬에게 2배가 됩니다\n#F20#\n#F40##C0x5c9970#→아군 포켓몬의 속도가 영구적으로 10% 증가하며 이 효과는 비행형 포켓몬에게 2배가 됩니다. 포켓몬 종류",
		starEffectDesc_en = "Additional effect: The next Ultimate move will deal extra 20% damage to units with speed lower than itself",
		zawakeSimpleDesc_vn = "aumenta o SPD dos Pokémon aliados em 10% por 3 rodadas, e esse efeito dobra para Pokémon do tipo Voador\n#F20#\n#F40##C0x5c9970#→aumenta permanentemente o SPD dos Pokémon aliados em 10%, e esse efeito dobra para os Pokémon Voadores- Digite Pokémon",
		zawakeSimpleDesc_id = "meningkatkan SPD Pokémon sekutu sebesar 10% selama 3 putaran, dan efek ini berlipat ganda menjadi Pokémon Tipe Terbang\n#F20#\n#F40##C0x5c9970#→meningkatkan SPD Pokémon sekutu secara permanen sebesar 10%, dan efek ini berlipat ganda menjadi Terbang- Ketik Pokemon",
		id = 523,
		zawakeSimpleDesc_es = "aumenta la VEL de los Pokémon aliados en un 10 % durante 3 rondas, y este efecto se duplica para los Pokémon de tipo Volador\n#F20#\n#F40##C0x5c9970#→aumenta permanentemente la VEL de los Pokémon aliados en un 10 % y este efecto se duplica para los Pokémon Voladores. Tipo Pokémon",
		simDesc_id = "Pidgeotto melemparkan satu target musuh ke langit dan memberikan pukulan keras menggunakan gravitasi. Ini memberikan kerusakan ekstra pada target dengan kecepatan lebih rendah dari dirinya sendiri"
	},
