	[1923] = {
		describe_th = "Venomoth ทำให้ศัตรูสับสนด้วยการเต้นรำที่น่าหลงใหล ก่อนที่จะทำให้มันประหลาดใจด้วยการกัดที่ดูดเลือดของศัตรูเป้าหมายเดียว สร้างความเสียหาย#C0x3D8A99#440% SP.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#SP.DMG#C0x5B545B# ท่านี้ดูดพลังชีวิต 30% และดูดซับ P.ATK และ SP.ATK ของเป้าหมายอย่างถาวร 8% (การดูดซึมแต่ละครั้งถูกจำกัดไว้ที่ไม่เกิน 40% ของค่าสถานะของตัวเองและสูงสุด 3 สแต็ค)",
		describe_en = "Venomoth confuses its enemy with a captivating dance, before surprising it with a bite that sucks the single enemy target's blood, dealing#C0x3D8A99#440% SP.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#SP.DMG#C0x5B545B#. This move carries a 30% lifesteal, and permanently absorbs the target's P.ATK and SP.ATK by 8% (each absorption is limited to no more than 40% of its own stats and up to 3 stacks)",
		simDesc_es = "Venomoth confunde a su enemigo con una danza cautivadora, antes de sorprenderlo con un mordisco que chupa la sangre del único objetivo enemigo. Este movimiento conlleva una tasa de robo de salud y absorbe el P.ATK y SP.ATK del objetivo.",
		describe_es = "Venomoth confunde a su enemigo con una danza cautivadora, antes de sorprenderlo con un mordisco que chupa la sangre del único objetivo enemigo, causando#C0x3D8A99#440% SP.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#SP.DMG#C0x5B545B#. Este movimiento conlleva un robo de vida del 30% y absorbe permanentemente el P.ATK y SP.ATK del objetivo en un 8% (cada absorción está limitada a no más del 40% de sus propias estadísticas y hasta 3 acumulaciones).",
		starEffectDesc_vn = "Aumente as taxas de roubo de saúde em 50%",
		starEffectDesc_id = "Meningkatkan tingkat Pencurian Kesehatan sebesar 50%",
		starEffectDesc_es = "Aumentar las tasas de robo de salud en un 50%",
		describe_vn = "Venomoth confunde seu inimigo com uma dança cativante, antes de surpreendê-lo com uma mordida que suga o sangue do único alvo inimigo, distribuindo#C0x3D8A99#440% SP.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#SP.DMG#C0x5B545B#. Este movimento carrega 30% de roubo de vida e absorve permanentemente o P.ATK e SP.ATK do alvo em 8% (cada absorção é limitada a não mais que 40% de suas próprias estatísticas e até 3 pilhas)",
		starEffectDesc_th = "เพิ่มอัตราการขโมยสุขภาพ 50%",
		describe_id = "Venomoth membingungkan musuhnya dengan tarian menawan, sebelum mengejutkannya dengan gigitan yang menghisap darah target tunggal musuh, menyebabkan#C0x3D8A99#440% SP.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#SP.DMG#C0x5B545B#. Jurus ini membawa 30% lifesteal, dan secara permanen menyerap P.ATK dan SP.ATK target sebesar 8% (setiap penyerapan dibatasi tidak lebih dari 40% statistiknya sendiri dan maksimal 3 tumpukan)",
		simDesc_en = "Venomoth confuses its enemy with a captivating dance, before surprising it with a bite that sucks the single enemy target's blood. This move carries a Health Steal rate, and absorbs the target's P.ATK and SP.ATK.",
		simDesc_vn = "Venomoth confunde seu inimigo com uma dança cativante, antes de surpreendê-lo com uma mordida que suga o sangue do único alvo inimigo. Este movimento carrega uma taxa de roubo de saúde e absorve o P.ATK e SP.ATK do alvo.",
		describe_kr = "베노모스는 매혹적인 춤으로 적을 혼란시킨 뒤, 적 한 명의 피를 빨아들이는 입으로 놀라게 하여#C0x3D8A99#440% SP.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#SP.DMG#C0x5B545B#를 줍니다. 이 기술은 30%의 생명력을 빼앗고 대상의 P.ATK와 SP.ATK를 8% 영구적으로 흡수합니다. (각 흡수는 자신의 능력치의 40% 이하, 최대 3중첩으로 제한됩니다.)",
		simDesc_th = "Venomoth สร้างความสับสนให้กับศัตรูด้วยท่าเต้นที่น่าหลงใหล ก่อนที่จะทำให้มันประหลาดใจด้วยการกัดที่ดูดเลือดของเป้าหมายศัตรูเพียงตัวเดียว ท่านี้มีอัตราการขโมยสุขภาพ และดูดซับ P.ATK และ SP.ATK ของเป้าหมาย",
