	[2313] = {
		describe_th = "แมนกี้คว้าเถาวัลย์แล้วแกว่งไปพร้อมกับมัน โดยเข้าสู่ [Rage] เป็นเวลา 3 รอบ (ความโกรธ: เพิ่มคริติคอล 40% และความเร็ว 20%) ก่อนที่จะโจมตีศัตรูเป้าหมายเดี่ยวอย่างดุเดือดและสร้างความเสียหาย#C0xE69900#460% P.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#P.DMG#C0x5B545B#. หลังจากการโจมตี มันจะทำการโจมตีพื้นฐานต่อทั้งศัตรูและพันธมิตร (จนกว่าสถานะ Rage จะสิ้นสุดลงเนื่องจากไม่สามารถลบล้างได้)",
		describe_en = "Mankey grabs a vine and swings along with it, while entering [Rage] for 3 rounds (Rage: Increases crit by 40% and speed by 20%) before furiously attacking the single target enemy and dealing#C0xE69900#460% P.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#P.DMG#C0x5B545B#. After the attack, it will continue to deal basic attack to both enemies and allies (until the Rage state ends as it cannot be dispelled)",
		simDesc_es = "Mankey agarra una enredadera y se balancea con ella, mientras entra en estado de ira antes de atacar furiosamente al único objetivo enemigo. Después del ataque, continuará lanzando ataques básicos tanto a enemigos como a aliados.",
		describe_es = "Mankey agarra una enredadera y se balancea con ella, mientras entra en [Rage] durante 3 rondas (Rabia: aumenta el crítico en un 40 % y la velocidad en un 20 %) antes de atacar furiosamente al enemigo objetivo único y causar #C0xE69900#460 % P.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#P.DMG#C0x5B545B#. Después del ataque, continuará realizando ataques básicos tanto a enemigos como a aliados (hasta que finalice el estado de Rabia, ya que no se puede disipar).",
		starEffectDesc_vn = "O crítico aumenta em 50% e a velocidade aumenta em 30% quando no estado [Rage]",
		starEffectDesc_id = "Kritik meningkat sebesar 50% dan kecepatan meningkat sebesar 30% ketika dalam kondisi [Rage]",
		starEffectDesc_es = "El crítico aumenta en un 50% y la velocidad aumenta en un 30% cuando está en estado [Rage]",
		describe_vn = "Mankey agarra uma videira e balança junto com ela, enquanto entra em [Rage] por 3 rodadas (Rage: aumenta o crítico em 40% e a velocidade em 20%) antes de atacar furiosamente o inimigo de alvo único e distribuir #C0xE69900#460% P.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#P.DMG#C0x5B545B#. Após o ataque, ele continuará a desferir ataques básicos tanto aos inimigos quanto aos aliados (até que o estado de Fúria termine, pois não pode ser dissipado)",
		starEffectDesc_th = "คริติคอลเพิ่มขึ้น 50% และความเร็วเพิ่มขึ้น 30% เมื่ออยู่ในสถานะ [Rage]",
		describe_id = "Mankey meraih sebatang pohon anggur dan mengayunkannya, sambil memasukkan [Rage] selama 3 ronde (Rage: Meningkatkan kritik sebesar 40% dan kecepatan sebesar 20%) sebelum menyerang musuh dengan ganas dan menangani#C0xE69900#460% P.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#P.DMG#C0x5B545B#. Setelah menyerang, ia akan terus memberikan serangan dasar kepada musuh dan sekutu (sampai status Rage berakhir karena tidak dapat dihilangkan)",
		simDesc_en = "Mankey grabs a vine and swings along with it, while entering the Rage state before furiously attacking the single enemy target. After the attack, it will continue to deal basic attacks to both enemies and allies",
		simDesc_vn = "Mankey agarra uma videira e balança junto com ela, enquanto entra no estado de Fúria antes de atacar furiosamente o único alvo inimigo. Após o ataque, ele continuará a desferir ataques básicos tanto aos inimigos quanto aos aliados.",
		describe_kr = "Mankey grabs a vine and swings along with it, while entering [Rage] for 3 rounds (Rage: Increases crit by 40% and speed by 20%) before furiously attacking the single target enemy and dealing#C0xE69900#460% P.ATK#C0x5B545B#+$(skillLevel*4*50)$#C0xF13B54#P.DMG#C0x5B545B#. After the attack, it will continue to deal basic attack to both enemies and allies (until the Rage state ends as it cannot be dispelled)",
		simDesc_th = "Mankey คว้าเถาวัลย์แล้วแกว่งไปพร้อมกับมัน ขณะเข้าสู่สถานะ Rage ก่อนที่จะโจมตีเป้าหมายศัตรูตัวเดียวอย่างดุเดือด หลังจากการโจมตี มันจะทำการโจมตีพื้นฐานต่อทั้งศัตรูและพันธมิตร",
		starEffectDesc_kr = "[Rage] 상태일 때 크리티컬 50% 증가, 속도 30% 증가",
		simDesc_kr = "맨키가 덩굴을 잡고 휘두르며 분노 상태가 된 후 단일 적 대상을 맹렬하게 공격합니다. 공격 후에는 적과 아군 모두에게 계속해서 기본 공격을 가합니다.",
		starEffectDesc_en = "Crit increases by 50% and speed increases by 30% when in [Rage] state",
		id = 2313,
