	},
	[2541] = {
		zawakeEffectDesc_es = "Politoed canta en voz alta para interferir con el enemigo y atacar furtivamente a un solo enemigo, causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, aumentando un 20% de velocidad propia y un 40%. SP.DEF durante 2 rondas.",
		zawakeEffectDesc_vn = "Politoed canta alto para interferir no inimigo e atacar furtivamente um único inimigo, distribuindo #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, aumentando 20% de velocidade própria e 40% SP.DEF por 2 rodadas.",
		describe_th = "Politoed ร้องเพลงเสียงดังเพื่อเข้าไปยุ่งเกี่ยวกับศัตรูและแอบโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B# เพิ่มความเร็วของตัวเอง 10% และ 20% SP.DEF จำนวน 2 รอบ",
		zawakeEffectDesc_kr = "폴리토에드는 큰 소리로 노래를 불러 적을 방해하고 단일 적에게 기습 공격을 가해 #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#를 처리하여 자신의 속도가 20%, 속도가 40% 증가합니다. 2라운드 동안 SP.DEF.",
		zawakeEffectDesc_th = "Politoed ร้องเพลงเสียงดังเพื่อเข้าไปยุ่งเกี่ยวกับศัตรูและแอบโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B# เพิ่มความเร็วของตัวเอง 20% และ 40% SP.DEF จำนวน 2 รอบ",
		describe_en = "Politoed sings loudly to interfere with the enemy and sneak attack on a single enemy, dealing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, increasing 10% own Speed and 20% SP.DEF for 2 rounds.",
		describe_es = "Politoed canta en voz alta para interferir con el enemigo y atacar furtivamente a un solo enemigo, causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, aumentando un 10% de velocidad propia y un 20%. SP.DEF durante 2 rondas.",
		zawakeSimpleDesc_en = "Increase own SPD by 10% and SP.DEF by 20% for 2 rounds.\n#F20# \n#F40##C0x5c9970#→Increase own SPD by 20% and SP.DEF by 40% for3 rounds.",
		describe_vn = "Politoed canta alto para interferir no inimigo e atacar furtivamente um único inimigo, distribuindo #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, aumentando 10% de velocidade própria e 20% SP.DEF por 2 rodadas.",
		zawakeEffectDesc_en = "Politoed sings loudly to interfere with the enemy and sneak attack on a single enemy, dealing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, increasing 20% own Speed and 40% SP.DEF for 2 rounds.",
		zawakeSimpleDesc_vn = "Aumente o SPD próprio em 10% e o SP.DEF em 20% por 2 rodadas.\n#F20# \n#F40##C0x5c9970#→Aumente o SPD próprio em 20% e o SP.DEF em 40% por 3 rodadas.",
		zawakeSimpleDesc_id = "Meningkatkan SPD sendiri sebesar 10% dan SP.DEF sebesar 20% selama 2 putaran.\n#F20# \n#F40##C0x5c9970#→Meningkatkan SPD sendiri sebesar 20% dan SP.DEF sebesar 40% selama 3 putaran.",
		zawakeSimpleDesc_es = "Aumenta tu propio SPD en un 10 % y SP.DEF en un 20 % durante 2 rondas.\n#F20# \n#F40##C0x5c9970# → Aumenta tu propio SPD en un 20 % y SP.DEF en un 40 % durante 3 rondas.",
		describe_id = "Politoed bernyanyi dengan keras untuk mengganggu musuh dan menyerang secara diam-diam pada satu musuh, menyebabkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, meningkatkan 10% Kecepatan sendiri dan 20% SP.DEF untuk 2 putaran.",
		zawakeSimpleDesc_kr = "2라운드 동안 자신의 SPD가 10%, SP.DEF가 20% 증가합니다.\n#F20# \n#F40##C0x5c9970#→3라운드 동안 자신의 SPD가 20%, SP.DEF가 40% 증가합니다.",
		zawakeEffectDesc_id = "Politoed bernyanyi dengan keras untuk mengganggu musuh dan menyerang secara diam-diam pada satu musuh, menghasilkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, meningkatkan 20% Kecepatan sendiri dan 40% SP.DEF untuk 2 putaran.",
		describe_kr = "폴리토에드는 큰 소리로 노래를 부르며 적을 방해하고 단일 적에게 기습 공격을 가해 #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#를 처리하여 자신의 속도가 10%, 속도가 20% 증가합니다. 2라운드 동안 SP.DEF.",
		zawakeSimpleDesc_th = "เพิ่ม SPD ของตัวเอง 10% และ SP.DEF 20% เป็นเวลา 2 รอบ\n#F20# \n#F40##C0x5c9970#→เพิ่ม SPD ของตัวเอง 20% และ SP.DEF 40% สำหรับ 3 รอบ",
		id = 2541
