	[2542] = {
		zawakeEffectDesc_es = "Politoed condensa una esfera de aura de agua para disparar a un solo enemigo, causando #150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, disipa 1 efecto de control o desventaja sobre sí mismo y un aliado aleatorio de tipo agua. Y aumenta su velocidad en un 10 %. durante 2 rondas.",
		zawakeEffectDesc_vn = "Politoed condensa uma Esfera de Aura de Água para atirar em um único inimigo, causando#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, dissipa 1 efeito de controle ou Debuff em si mesmo e em um aliado aleatório do tipo Água.E aumenta sua velocidade em 10%. por 2 rodadas.",
		describe_th = "Politoed ควบแน่นออร่าน้ำทรงกลมเพื่อยิงใส่ศัตรูตัวเดียว สร้างความเสียหาย#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, ลบล้างเอฟเฟกต์การควบคุมหรือดีบัฟ 1 ครั้งบนตัวมันเองและพันธมิตรประเภทน้ำแบบสุ่ม",
		zawakeEffectDesc_kr = "폴리토에드는 물의 오라 구체를 응축해 적 1명에게 발사하여 #150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#을 처리하고, 자신과 무작위 물형 아군의 제어 효과 1개 또는 디버프 1개를 해제하고 속도를 10% 증가시킵니다. 2라운드 동안.",
		zawakeEffectDesc_th = "Politoed ควบแน่นออร่าน้ำทรงกลมเพื่อยิงใส่ศัตรูตัวเดียว สร้างความเสียหาย#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B# ลบล้างเอฟเฟกต์การควบคุมหรือดีบัฟ 1 ครั้งบนตัวมันเองและพันธมิตรประเภทน้ำแบบสุ่ม และเพิ่มความเร็วของมัน 10% เป็นเวลา 2 รอบ",
		describe_en = "Politoed condenses a Water Aura Sphere to shot at a single enemy, dealing#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, dispels 1 Control effect or Debuff on itself and a random Water Type ally.",
		describe_es = "Politoed condensa una esfera de aura de agua para disparar a un solo enemigo, causando#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, disipa 1 efecto de control o desventaja sobre sí mismo y un aliado aleatorio de tipo agua.",
		zawakeSimpleDesc_en = "#C0x5c9970#Increase own and Water-type ally SPD by 10% for 2 rounds.",
		describe_vn = "Politoed condensa uma Esfera de Aura de Água para atirar em um único inimigo, causando#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, dissipa 1 efeito de controle ou Debuff em si mesmo e em um aliado aleatório do tipo Água.",
		zawakeEffectDesc_en = "Politoed condenses a Water Aura Sphere to shot at a single enemy, dealing#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, dispels 1 Control effect or Debuff on itself and a random Water Type ally.And increase its speed by 10% for 2 rounds.",
		zawakeSimpleDesc_vn = "#C0x5c9970#Aumenta o SPD do próprio aliado e do tipo Água em 10% por 2 rodadas.",
		zawakeSimpleDesc_id = "#C0x5c9970#Meningkatkan SPD milik sendiri dan sekutu tipe Air sebesar 10% selama 2 ronde.",
		zawakeSimpleDesc_es = "#C0x5c9970#Aumenta el SPD propio y del aliado tipo Agua en un 10 % durante 2 rondas.",
		describe_id = "Politoed memadatkan Bola Aura Air untuk menembak ke satu musuh, menimbulkan#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, menghilangkan 1 efek Kontrol atau Debuff pada dirinya sendiri dan sekutu Tipe Air secara acak.",
		zawakeSimpleDesc_kr = "#C0x5c9970#2라운드 동안 자신과 물형 아군 SPD가 10% 증가합니다.",
		zawakeEffectDesc_id = "Politoed memadatkan Bola Aura Air untuk menembak ke satu musuh, menimbulkan#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, menghilangkan 1 efek Kontrol atau Debuff pada dirinya sendiri dan sekutu Tipe Air secara acak. Dan meningkatkan kecepatannya sebesar 10% selama 2 putaran.",
		describe_kr = "폴리토에드는 물의 오라 구체를 응축해 단일 적에게 발사하여#150%SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#을 처리하고, 자신과 무작위 물형 아군에게 제어 효과 또는 디버프 1개를 해제합니다.",
		zawakeSimpleDesc_th = "#C0x5c9970#เพิ่ม SPD พันธมิตรของตัวเองและประเภทน้ำ 10% เป็นเวลา 2 รอบ",
