	[2653] = {
		describe_th = "อลาคาซัมเรียกช้อนจิตออกมาโจมตีศัตรูทั้งหมดเพื่อสร้างความเสียหาย#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# โดยมีโอกาส 35% ที่จะ [Petrify] เป้าหมายเป็นเวลา 1 รอบ (ปิดการใช้งาน : ไม่สามารถเคลื่อนที่ได้ ลดความเสียหายเพิ่มขึ้น 30%) เป้าหมายที่ไม่ปิดการใช้งานจะลด SP.DEF ลง 30% เป็นเวลา 2 รอบ",
		zawakeEffectDesc_vn = "Alakazam invoca uma colher mental para atacar todos os inimigos para lidar com #C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, com 35% de chance de [Petrify] alvos por 1 rodada (Desativar : Incapaz de se mover. Redução de dano aumentada em 30%), alvos não desabilitados reduzem seu SP.DEF em 30% por 2 rodadas e aumentam a chance de serem desabilitados na próxima vez em 5%, o efeito pode acumular até ser desabilitado",
		simDesc_es = "Alakazam invoca una cuchara mental para atacar a todos los enemigos, con la posibilidad de desactivar objetivos. Los objetivos no afectados verán reducida su SP.DEF.",
		describe_es = "Alakazam invoca una cuchara mental para atacar a todos los enemigos y repartir#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, con un 35% de probabilidad de [Petrify] objetivos durante 1 ronda (Desactivar : No se puede mover. La reducción de daño aumentó en un 30%), los objetivos no discapacitados reducen su SP.DEF en un 30% durante 2 rondas.",
		zawakeEffectDesc_th = "อลาคาซัมเรียกช้อนจิตออกมาโจมตีศัตรูทั้งหมดเพื่อสร้างความเสียหาย#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# โดยมีโอกาส 35% ที่จะ [Petrify] เป้าหมายเป็นเวลา 1 รอบ (ปิดการใช้งาน : ไม่สามารถเคลื่อนที่ได้ ลดความเสียหายเพิ่มขึ้น 30%) เป้าหมายที่ไม่ปิดการใช้งานจะลด SP.DEF ลง 30% เป็นเวลา 2 รอบ และเพิ่มโอกาสถูกปิดการใช้งานในครั้งต่อไป 5% เอฟเฟกต์สามารถซ้อนทับได้จนกว่าจะถูกปิดการใช้งาน",
		starEffectDesc_id = "Efek tambahan: Kecepatan menimbulkan [Petrify] meningkat sebesar 5% dan menimbulkan kerusakan tambahan sebesar 30% pada target dengan SP.ATK lebih rendah dari dirinya sendiri.",
		starEffectDesc_es = "Efecto adicional: la tasa de infligir [Petrify] aumenta en un 5% e inflige un 30% de daño adicional a objetivos con SP.ATK más bajo que él mismo.",
		zawakeSimpleDesc_en = "#C0x5c9970#and increase the chance of being disabled next time by 5%, the effect can stack until being disabled",
		describe_vn = "Alakazam invoca uma colher mental para atacar todos os inimigos para lidar com #C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, com 35% de chance de [Petrify] alvos por 1 rodada (Desativar : Incapaz de se mover. Redução de dano aumentada em 30%), alvos não desabilitados reduzem seu SP.DEF em 30% por 2 rodadas",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: อัตราการสร้าง [Petrify] เพิ่มขึ้น 5% และสร้างความเสียหายเพิ่มเติม 30% ให้กับเป้าหมายที่มี SP.ATK ต่ำกว่าตัวมันเอง",
		starEffectDesc_vn = "Efeito adicional: A taxa de inflição [Petrify] aumenta em 5% e causa 30% de dano extra a alvos com SP.ATK menor que ele mesmo.",
		zawakeEffectDesc_kr = "알라카잠은 정신수저를 소환하여 모든 적을 공격하여 거래를 합니다#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, 35%의 확률로 1라운드 동안 [Petrify] 대상을 공격합니다(비활성화) : 움직일 수 없습니다. 데미지 감소 30% 증가), 비활성화되지 않은 대상은 SP.DEF를 2라운드 동안 30% 감소시키고 다음번 비활성화될 확률을 5% 증가시킵니다. 비활성화될 때까지 효과는 중첩됩니다.",
		describe_en = "Alakazam summons a mental spoon to attack all enemies to deal#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, with 35% chance to [Petrify] targets for 1 round (Disable: Unable to move. Damage reduction increased by 30%), not disabled targets reduce their SP.DEF by 30% for 2 rounds",
		zawakeEffectDesc_id = "Alakazam memanggil sendok mental untuk menyerang semua musuh untuk menangani#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, dengan peluang 35% untuk [Petrify] target selama 1 putaran (Nonaktifkan : Tidak dapat bergerak, Pengurangan damage meningkat sebesar 30%), target yang tidak dinonaktifkan mengurangi SP.DEF mereka sebesar 30% selama 2 putaran dan meningkatkan kemungkinan dinonaktifkan di lain waktu sebesar 5%, efeknya dapat ditumpuk hingga dinonaktifkan",
		describe_id = "Alakazam memanggil sendok mental untuk menyerang semua musuh untuk menangani#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, dengan peluang 35% untuk [Petrify] target selama 1 putaran (Nonaktifkan : Tidak dapat bergerak. Pengurangan kerusakan meningkat sebesar 30%), target yang tidak dinonaktifkan mengurangi SP.DEF sebesar 30% selama 2 putaran",
		simDesc_en = "Alakazam summons a mental spoon to attack all enemies, with a chance to Disable targets. Unaffected targets will have their SP.DEF reduced instead",
		simDesc_vn = "Alakazam invoca uma colher mental para atacar todos os inimigos, com chance de desativar os alvos. Alvos não afetados terão seu SP.DEF reduzido",
		describe_kr = "알라카잠은 정신수저를 소환하여 모든 적을 공격하여 거래를 합니다#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, 35%의 확률로 1라운드 동안 [Petrify] 대상을 공격합니다(비활성화) : 이동 불가, 데미지 감소 30% 증가), 비활성화되지 않은 대상은 2라운드 동안 SP.DEF를 30% 감소시킵니다.",
		simDesc_th = "Alakazam เรียกช้อนทางจิตออกมาโจมตีศัตรูทั้งหมด โดยมีโอกาสที่จะปิดการใช้งานเป้าหมาย เป้าหมายที่ไม่ได้รับผลกระทบจะถูกลด SP.DEF แทน",
		zawakeEffectDesc_es = "Alakazam invoca una cuchara mental para atacar a todos los enemigos y tratar#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, con un 35% de probabilidad de [Petrify] objetivos durante 1 ronda (Desactivar : No se puede mover. La reducción de daño aumentó en un 30%), los objetivos no deshabilitados reducen su SP.DEF en un 30% durante 2 rondas y aumentan la probabilidad de quedar deshabilitado la próxima vez en un 5%, el efecto se puede acumular hasta que se deshabilite.",
		starEffectDesc_kr = "추가 효과 : [Petrify] 적중률이 5% 증가하고, 자신보다 SP.ATK가 낮은 대상에게 30% 추가 데미지를 줍니다.",
		zawakeEffectDesc_en = "Alakazam summons a mental spoon to attack all enemies to deal#C0x3D8A99#140%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, with 35% chance to [Petrify] targets for 1 round (Disable: Unable to move. Damage reduction increased by 30%), not disabled targets reduce their SP.DEF by 30% for 2 rounds and increase the chance of being disabled next time by 5%, the effect can stack until being disabled",
		simDesc_kr = "알라카잠은 정신수저를 소환하여 모든 적을 공격하고 일정 확률로 대상을 비활성화합니다. 영향을 받지 않은 대상은 대신 SP.DEF가 감소합니다.",
		zawakeSimpleDesc_th = "#C0x5c9970#และเพิ่มโอกาสที่จะถูกปิดการใช้งานในครั้งถัดไปอีก 5% เอฟเฟกต์สามารถซ้อนกันได้จนกว่าจะถูกปิดการใช้งาน",
		zawakeSimpleDesc_kr = "#C0x5c9970#다음 번에 비활성화될 확률이 5% 증가합니다. 비활성화될 때까지 효과가 누적될 수 있습니다.",
		starEffectDesc_en = "Additional effect: Rate of inflicting [Petrify] increases by 5% and deals extra 30% damage to targets with lower SP.ATK than itself.",
		zawakeSimpleDesc_vn = "#C0x5c9970#e aumenta a chance de ser desabilitado na próxima vez em 5%, o efeito pode acumular até ser desabilitado",
		zawakeSimpleDesc_id = "#C0x5c9970#dan tingkatkan kemungkinan dinonaktifkan berikutnya sebesar 5%, efeknya dapat ditumpuk hingga dinonaktifkan",
		id = 2653,
		zawakeSimpleDesc_es = "#C0x5c9970#y aumenta la posibilidad de ser desactivado la próxima vez en un 5%, el efecto se puede acumular hasta que se desactiva",
		simDesc_id = "Alakazam memanggil sendok mental untuk menyerang semua musuh, dengan peluang untuk Menonaktifkan target. Target yang tidak terpengaruh akan dikurangi SP.DEF-nya"
	},
	[2656] = {
		describe_id = "Tingkatkan tingkat kendali $(10+skillLevel*0.2-0.2)$% milik sendiri; \n Saat HP milik sendiri kurang dari 30% untuk pertama kalinya, pindahkan sisa Kebingungan ke dua Pokemon sekutu secara acak selama 2 ronde agar mereka dapat [Petrify] menargetkan dengan peluang 40%",
		zawakeEffectDesc_vn = "Aumentar a própria taxa de controle de $(10+skillLevel*0.2-0.2)$%; \n Quando o próprio HP estiver abaixo de 30% pela primeira vez, transfira o Confusion restante para dois Pokémon aliados aleatórios por 2 rodadas para torná-los capazes de [Petrify] atingir alvos com 40% de chance; quando Pokémon do tipo Psíquico ganham Confusão, há 60% de chance de [Petrify] atingir o alvo por 1 rodada ao atacar",
		describe_vn = "Aumentar a própria taxa de controle de $(10+skillLevel*0.2-0.2)$%; \n Quando o próprio HP for inferior a 30% pela primeira vez, transfira o Confusion restante para dois Pokémon aliados aleatórios por 2 rodadas para torná-los capazes de [Petrify] atingir alvos com 40% de chance",
		starEffectDesc_id = "Efek tambahan: Jika HP-nya tidak pernah turun di bawah 30%, kecepatannya meningkat sebesar 20%",
		zawakeEffectDesc_th = "เพิ่มอัตราการควบคุม $(10+skillLevel*0.2-0.2)$% ของตัวเอง \n เมื่อ HP ของตัวเองต่ำกว่า 30% เป็นครั้งแรก ให้โอนความสับสนที่เหลือไปยังโปเกมอนพันธมิตรแบบสุ่มสองตัวเป็นเวลา 2 รอบ เพื่อให้พวกเขาสามารถ [Petrify] เป้าหมายที่มีโอกาส 40%; เมื่อโปเกมอนประเภทพลังจิตเกิดความสับสน มีโอกาส 60% ที่จะ [Petrify] เป้าหมายเป็นเวลา 1 รอบเมื่อทำการโจมตี",
		starEffectDesc_kr = "추가 효과 : HP가 30% 이하로 떨어진 적이 없다면 속도가 20% 증가합니다.",
		describe_es = "Aumentar la propia tasa de control del $(10+skillLevel*0.2-0.2)$%; \n Cuando tu HP sea inferior al 30% por primera vez, transfiere la Confusión restante a dos Pokémon aliados aleatorios durante 2 rondas para que puedan [Petrify] objetivos con un 40% de probabilidad.",
		zawakeSimpleDesc_en = "#C0x5c9970#when Psychic-type Pokémon gain Confusion, there is a 60% chance to [Petrify] the target for 1 round when attacking",
		starEffectDesc_es = "Efecto adicional: si su HP nunca ha caído por debajo del 30%, su velocidad aumenta en un 20%.",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: หาก HP ไม่เคยลดลงต่ำกว่า 30% ความเร็วของมันจะเพิ่มขึ้น 20%",
		zawakeEffectDesc_id = "Tingkatkan tingkat kendali $(10+skillLevel*0.2-0.2)$% milik sendiri; \n Saat HP milik sendiri lebih rendah dari 30% untuk pertama kalinya, pindahkan sisa Kebingungan ke dua Pokemon sekutu acak selama 2 ronde agar mereka dapat [Petrify] menargetkan dengan peluang 40%; ketika Pokémon tipe Psikis memperoleh Kebingungan, ada peluang 60% untuk [Petrify] target selama 1 putaran saat menyerang",
