	[3213] = {
		describe_th = "สโลว์โปกใช้พลังจิตเรียกน้ำปั่นป่วนมาโจมตีศัตรูเป้าหมายเดียว สร้าง #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# ลืมความเจ็บปวดเมื่อใช้ทักษะขั้นสูงสุด ล้างความเสียหายที่ยังไม่ได้รับการแก้ไข 40% และเพิ่ม [Forgetful] ให้กับตัวเองเป็นเวลา 2 รอบ\n#F20# \n#F40#[Forgetful]: เอฟเฟกต์บัฟพิเศษ ไม่สามารถลบล้างได้ ลบล้างการควบคุมแบบสุ่มหรือเอฟเฟกต์ด้านลบ 1 ครั้งก่อนที่จะเคลื่อนที่ด้วยตนเอง",
		zawakeEffectDesc_vn = "Slowpoke usa seu poder psíquico para invocar água turbulenta para atacar um único alvo inimigo, distribuindo #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, esquece a dor ao usar sua habilidade Ultimate , elimina 40% do dano não resolvido e adiciona [Forgetful] a todos os aliados por 2 rodadas\n#F20# \n#F40#[Forgetful]: Efeito de buff especial, não pode ser dissipado, dissipa 1 controle aleatório ou efeito negativo antes de se mover",
		simDesc_es = "Slowpoke usa su poder psíquico para invocar agua turbulenta para atacar a un solo objetivo enemigo y olvidar el dolor pasado cuando usa su habilidad definitiva.",
		describe_es = "Slowpoke usa su poder psíquico para invocar agua turbulenta para atacar a un solo objetivo enemigo, causando #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, olvida el dolor al usar su habilidad definitiva. , elimina el 40% del daño no resuelto y agrega [Forgetful] a uno mismo durante 2 rondas\n#F20# \n#F40#[Forgetful]: efecto de mejora especial, no se puede disipar, disipa 1 control aleatorio o efecto negativo antes de moverse",
		zawakeEffectDesc_th = "สโลว์โปกใช้พลังจิตเรียกน้ำปั่นป่วนมาโจมตีศัตรูเป้าหมายเดียว สร้าง #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# ลืมความเจ็บปวดเมื่อใช้ทักษะขั้นสูงสุด ล้างความเสียหายที่ยังไม่ได้รับการแก้ไข 40% และเพิ่ม [Forgetful] ให้กับพันธมิตรทั้งหมดเป็นเวลา 2 รอบ\n#F20# \n#F40#[Forgetful]: เอฟเฟกต์บัฟพิเศษ ไม่สามารถลบล้างได้ ลบล้างการควบคุมแบบสุ่มหรือเอฟเฟกต์เชิงลบ 1 ครั้งก่อนที่จะเคลื่อนที่ด้วยตนเอง",
		starEffectDesc_id = "Peningkatan efek: Menghapus 80% kerusakan yang belum terselesaikan saat menggunakan skill Ultimate",
		starEffectDesc_es = "Aumento de efecto: elimina el 80% del daño no resuelto cuando se usa la habilidad definitiva.",
		zawakeSimpleDesc_en = "After using the ultimate skill, add [Forgetful] to itself for 2 rounds\n#F20# #F40##C0x5c9970# → After using the ultimate skill, add [Forgetful] to all allies for 2 rounds.",
		describe_vn = "Slowpoke usa seu poder psíquico para invocar água turbulenta para atacar um único alvo inimigo, distribuindo #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, esquece a dor ao usar sua habilidade Ultimate , elimina 40% dos danos não resolvidos e adiciona [Forgetful] a si mesmo por 2 rodadas\n#F20# \n#F40#[Forgetful]: Efeito de buff especial, não pode ser dissipado, dissipa 1 controle aleatório ou efeito negativo antes de se mover",
		starEffectDesc_th = "เพิ่มเอฟเฟกต์: ล้างความเสียหายที่ยังไม่ได้รับการแก้ไข 80% เมื่อใช้ทักษะขั้นสูงสุด",
		starEffectDesc_vn = "Aumento de efeito: elimina 80% dos danos não resolvidos ao usar a habilidade Ultimate",
		zawakeEffectDesc_kr = "슬로포크는 초능력을 이용해 격랑을 소환하여 단일 적 대상을 공격하며 #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 주며 궁극기 사용 시 고통을 잊어버립니다. , 해결되지 않은 피해의 40%를 제거하고 2라운드 동안 모든 아군에게 [Forgetful]를 추가합니다\n#F20# \n#F40#[Forgetful]: 특수 버프 효과, 해제할 수 없음, 자체 이동 전 무작위 제어 또는 부정적 효과 1개 해제",
		describe_en = "Slowpoke uses its psychic power to summon turbulent water to attack a single enemy target, dealing #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, forgets the pain when using its Ultimate skill, clears 40% of unresolved damage and adds [Forgetful] to self for 2 rounds\n#F20# \n#F40#[Forgetful]: Special buff effect, cannot be dispelled, dispels 1 random control or negative effect before self move",
		zawakeEffectDesc_id = "Slowpoke menggunakan kekuatan psikisnya untuk memanggil air yang bergejolak untuk menyerang satu target musuh, memberikan #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, lupakan rasa sakit saat menggunakan skill Ultimate-nya , menghapus 40% kerusakan yang belum terselesaikan dan menambahkan [Forgetful] ke semua sekutu selama 2 putaran\n#F20# \n#F40#[Forgetful]: Efek buff spesial, tidak bisa dihilangkan, menghilangkan 1 kontrol acak atau efek negatif sebelum bergerak sendiri",
		describe_id = "Slowpoke menggunakan kekuatan psikisnya untuk memanggil air yang bergejolak untuk menyerang satu target musuh, memberikan #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, lupakan rasa sakit saat menggunakan skill Ultimate-nya , menghapus 40% kerusakan yang belum terselesaikan dan menambahkan [Forgetful] ke diri sendiri selama 2 ronde\n#F20# \n#F40#[Forgetful]: Efek buff khusus, tidak bisa dihilangkan, menghilangkan 1 kontrol acak atau efek negatif sebelum bergerak sendiri",
		simDesc_en = "Slowpoke uses its psychic power to summon turbulent water to attack a single enemy target, and forget the past pain when using its Ultimate skill",
		simDesc_vn = "Slowpoke usa seu poder psíquico para invocar águas turbulentas para atacar um único alvo inimigo e esquecer a dor do passado ao usar sua habilidade Ultimate",
		describe_kr = "슬로포크는 초능력을 이용해 격랑을 소환하여 단일 적 대상을 공격하며 #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 주며 궁극기 사용 시 고통을 잊어버립니다. , 해결되지 않은 피해의 40%를 제거하고 2라운드 동안 자신에게 [Forgetful]를 추가합니다\n#F20# \n#F40#[Forgetful]: 특수 버프 효과, 해제할 수 없음, 자신이 이동하기 전에 무작위 제어 또는 부정적 효과 1개를 해제합니다.",
		simDesc_th = "Slowpoke ใช้พลังจิตเรียกน้ำปั่นป่วนมาโจมตีศัตรูเป้าหมายเดียว และลืมความเจ็บปวดในอดีตเมื่อใช้ทักษะอัลติเมท",
		zawakeEffectDesc_es = "Slowpoke usa su poder psíquico para invocar agua turbulenta para atacar a un solo objetivo enemigo, causando #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, olvida el dolor al usar su habilidad definitiva. , elimina el 40 % del daño no resuelto y agrega [Forgetful] a todos los aliados durante 2 rondas\n#F20# \n#F40#[Forgetful]: efecto de mejora especial, no se puede disipar, disipa 1 control aleatorio o efecto negativo antes del movimiento automático.",
		starEffectDesc_kr = "효과 부스트 : 궁극기 사용 시 미해결 데미지 80% 클리어",
		zawakeEffectDesc_en = "Slowpoke uses its psychic power to summon turbulent water to attack a single enemy target, dealing #C0x3D8A99#490% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, forgets the pain when using its Ultimate skill, clears 40% of unresolved damage and adds [Forgetful] to all allies for 2 rounds\n#F20# \n#F40#[Forgetful]: Special buff effect, cannot be dispelled, dispels 1 random control or negative effect before self move",
		simDesc_kr = "슬로우포크는 초능력을 이용해 격랑을 소환해 단일 적 대상을 공격하고, 궁극기 사용 시 과거의 고통을 잊는다.",
		zawakeSimpleDesc_th = "หลังจากใช้ทักษะขั้นสูงสุด เพิ่ม [Forgetful] ให้กับตัวเอง 2 รอบ\n#F20# #F40##C0x5c9970# → หลังจากใช้ทักษะขั้นสูงสุด ให้เพิ่ม [Forgetful] ให้กับพันธมิตรทั้งหมดเป็นเวลา 2 รอบ",
		zawakeSimpleDesc_kr = "궁극기 사용 후 자신에게 [Forgetful]를 2라운드 동안 추가\n#F20# #F40##C0x5c9970# → 궁극기 사용 후 아군 전체에게 2라운드 동안 [Forgetful]를 추가합니다.",
		starEffectDesc_en = "Effect boost: Clears 80% of unresolved damage when using the Ultimate skill",
		zawakeSimpleDesc_vn = "Depois de usar a habilidade final, adicione [Forgetful] a si mesmo por 2 rodadas\n#F20# #F40##C0x5c9970# → Depois de usar a habilidade final, adicione [Forgetful] a todos os aliados por 2 rodadas.",
		zawakeSimpleDesc_id = "Setelah menggunakan skill ulti, tambahkan [Forgetful] ke dirinya sendiri selama 2 ronde\n#F20# #F40##C0x5c9970# → Setelah menggunakan skill ulti, tambahkan [Forgetful] ke semua sekutu selama 2 ronde.",
		id = 3213,
		zawakeSimpleDesc_es = "Después de usar la habilidad definitiva, agrega [Forgetful] a sí mismo durante 2 rondas\n#F20# #F40##C0x5c9970# → Después de usar la habilidad definitiva, agrega [Forgetful] a todos los aliados durante 2 rondas.",
		simDesc_id = "Slowpoke menggunakan kekuatan psikisnya untuk memanggil air yang bergejolak untuk menyerang satu target musuh, dan melupakan rasa sakit di masa lalu saat menggunakan skill Ultimate-nya."
	},
	[3216] = {
		describe_id = "#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# kerusakan apa pun yang diterima Slowpoke akan teratasi di akhir langkah berikutnya; jika Slowpoke diserang secara aktif lebih dari 3 kali selama ronde besar, 30% dari kerusakan yang belum terselesaikan akan hilang di akhir ronde besar",
		zawakeEffectDesc_vn = "Efeito adicional: Slowpoke é bom em pescar com a cauda. Unidades atacando Slowpoke terão 50% de chance de serem adicionadas【ficar fisgado】permanentemente, 【ficar fisgado】só pode ser adicionado uma vez por batalha\n#F20#\n#F40#【ficar fisgado】: efeito de controle especial, não pode ser dissipado. 【ficar fisgado】As unidades só podem escolher Slowpoke como alvo quando em ação e quando o dano do ataque é reduzido em 50% ， Este efeito é removido quando Slowpoke é derrotado",
		describe_vn = "O #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# de qualquer dano que o Slowpoke sofrer será resolvido no final do próximo movimento; se Slowpoke for atacado ativamente mais de 3 vezes durante a grande rodada, 30% do dano não resolvido será eliminado no final da grande rodada",
		starEffectDesc_id = "Efek tambahan: Slowpoke pandai memancing dengan ekornya. Unit yang menyerang Slowpoke akan memiliki peluang 50% untuk ditambahkan 【terkait】 secara permanen, 【terkait】 hanya dapat ditambahkan satu kali per pertempuran\n#F20#\n#F40# 【terkait】: efek kontrol khusus, tidak bisa dihilangkan. 【Dapatkan ketagihan】Unit hanya dapat memilih Slowpoke sebagai target saat beraksi. Efek ini hilang ketika Slowpoke dikalahkan",
		zawakeEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: Slowpoke สามารถตกปลาโดยใช้หางได้ดี ยูนิตที่โจมตีสโลว์โปกจะมีโอกาส 50% ที่จะถูกเพิ่ม【ติดตะขอ】ถาวร 【ติดตะขอ】สามารถเพิ่มได้เพียงครั้งเดียวต่อการต่อสู้\n#F20#\n#F40#【ติดตะขอ】: เอฟเฟกต์การควบคุมพิเศษไม่สามารถ ถูกไล่ออก 【ติดงอมแงม】ยูนิตสามารถเลือก Slowpoke เป็นเป้าหมายได้เมื่อทำงานและเมื่อความเสียหายจากการโจมตีลดลง 50%，เอฟเฟกต์นี้จะถูกลบออกเมื่อพ่ายแพ้ Slowpoke",
		starEffectDesc_kr = "추가 효과 : 슬로우포크는 꼬리로 낚시를 잘한다. 슬로포크를 공격하는 유닛은 50% 확률로 영구적으로 [푹] 추가되며, [푹]은 전투당 한 번만 추가할 수 있습니다\n#F20#\n#F40#[푹]: 특수 제어 효과, 불가능 쫓겨나다. 【푹 빠지다】유닛은 행동 중일 때만 Slowpoke를 목표로 선택할 수 있습니다. 이 효과는 슬로우포크가 패배하면 제거됩니다.",
		describe_es = "El #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# de cualquier daño que reciba Slowpoke se resolverá al final del siguiente movimiento; Si Slowpoke es atacado activamente más de 3 veces durante la gran ronda, el 30 % del daño no resuelto se eliminará al final de la gran ronda.",
		zawakeSimpleDesc_en = "#C0x5c9970# [Hooked] Unit deals 50% reduced damage when attacking Slowking.",
		starEffectDesc_es = "Efecto adicional: Slowpoke es bueno pescando con la cola. Las unidades que ataquen a Slowpoke tendrán un 50% de probabilidad de ser agregadas 【quedar enganchado】permanentemente, 【ganchar】solo se puede agregar una vez por batalla\n#F20#\n#F40#【ganchar】efecto de control especial, no se puede ser disipado. 【Engancharse】Las unidades solo pueden elegir a Slowpoke como objetivos cuando están en acción. Este efecto se elimina cuando Slowpoke es derrotado.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: Slowpoke สามารถตกปลาโดยใช้หางได้ดี ยูนิตที่โจมตีสโลว์โปกจะมีโอกาส 50% ที่จะถูกเพิ่ม【ติดตะขอ】ถาวร 【ติดตะขอ】สามารถเพิ่มได้เพียงครั้งเดียวต่อการต่อสู้\n#F20#\n#F40#【ติดตะขอ】: เอฟเฟกต์การควบคุมพิเศษไม่สามารถ ถูกไล่ออก 【ติดงอมแงม】ยูนิตจะสามารถเลือก Slowpoke เป็นเป้าหมายได้เมื่อดำเนินการเท่านั้น เอฟเฟกต์นี้จะถูกลบออกเมื่อกำจัด Slowpoke",
		zawakeEffectDesc_id = "Efek tambahan: Slowpoke pandai memancing dengan ekornya. Unit yang menyerang Slowpoke akan memiliki peluang 50% untuk ditambahkan 【terkait】 secara permanen, 【terkait】 hanya dapat ditambahkan satu kali per pertempuran\n#F20#\n#F40# 【terkait】: efek kontrol khusus, tidak bisa dihilangkan. 【Terpikat】Unit hanya dapat memilih Slowpoke sebagai target saat beraksi dan saat menyerang, damage berkurang 50%,Efek ini hilang saat Slowpoke dikalahkan",
		zawakeEffectDesc_es = "Efecto adicional: Slowpoke es bueno pescando con la cola. Las unidades que ataquen a Slowpoke tendrán un 50 % de probabilidad de ser agregadas 【quedar enganchado】permanentemente, 【ganchar】solo se puede agregar una vez por batalla\n#F20#\n#F40#【ganchar】efecto de control especial, no se puede ser disipado. 【Engancharse】Las unidades solo pueden elegir a Slowpoke como objetivos cuando están en acción y cuando el daño de ataque se reduce en un 50%. Este efecto se elimina cuando Slowpoke es derrotado.",
		describe_en = "The #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# of any damage that Slowpoke takes will be resolved at the end of the next move; if Slowpoke is actively attacked more than 3 times during the big round, 30% of the unresolved damage will be cleared at the end of the big round",
		zawakeSimpleDesc_th = "#C0x5c9970# [Hooked] ยูนิตสร้างความเสียหายลดลง 50% เมื่อโจมตีสโลว์กิ้ง",
		zawakeEffectDesc_kr = "추가 효과 : 슬로우포크는 꼬리로 낚시를 잘한다. 슬로포크를 공격하는 유닛은 50% 확률로 영구적으로 [푹] 추가되며, [푹]은 전투당 한 번만 추가할 수 있습니다\n#F20#\n#F40#[푹]: 특수 제어 효과, 불가능 쫓겨나다. 【푹 빠지다】유닛은 행동 중일 때와 공격 피해가 50% 감소할 때만 슬로우포크를 대상으로 선택할 수 있습니다. 이 효과는 슬로포크가 패배하면 제거됩니다.",
		zawakeSimpleDesc_kr = "#C0x5c9970# [Hooked] 슬로킹 공격 시 유닛이 주는 피해가 50% 감소합니다.",
		zawakeEffectDesc_en = "Additional effect: Slowpoke is good at fishing with its tail. Units attacking Slowpoke will have a 50% chance to be added【get hooked】permanently, 【get hooked】can only be added once per battle\n#F20#\n#F40#【get hooked】: special control effect, can not be dispelled. 【get hooked】Units can only choose Slowpoke as targets when in action and when attacking damage is reduced by 50%，This effect is removed when Slowpoke is defeated",
		describe_kr = "Slowpoke가 받는 피해의 #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#는 다음 이동이 끝날 때 해결됩니다. 빅 라운드 동안 슬로우포크를 3회 이상 적극적으로 공격할 경우, 빅 라운드 종료 시 해결되지 않은 피해의 30%가 클리어됩니다.",
		zawakeSimpleDesc_vn = "#C0x5c9970# [Hooked] A unidade causa 50% de redução de dano ao atacar Slowking.",
		zawakeSimpleDesc_id = "#C0x5c9970# [Hooked] Unit memberikan 50% pengurangan kerusakan saat menyerang Slowking.",
		starEffectDesc_vn = "Efeito adicional: Slowpoke é bom em pescar com a cauda. Unidades atacando Slowpoke terão 50% de chance de serem adicionadas【ficar fisgado】permanentemente, 【ficar fisgado】só pode ser adicionado uma vez por batalha\n#F20#\n#F40#【ficar fisgado】: efeito de controle especial, não pode ser dissipado. 【ficar fisgado】As unidades só podem escolher Slowpoke como alvo quando em ação. Este efeito é removido quando Slowpoke é derrotado",
		zawakeSimpleDesc_es = "#C0x5c9970# [Hooked] La unidad inflige un 50 % menos de daño al atacar a Slowking.",
		describe_th = "#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# ของความเสียหายใดๆ ที่ Slowpoke ได้รับจะได้รับการแก้ไขเมื่อสิ้นสุดการเคลื่อนไหวครั้งถัดไป หาก Slowpoke ถูกโจมตีมากกว่า 3 ครั้งในรอบใหญ่ 30% ของความเสียหายที่ยังไม่ได้รับการแก้ไขจะถูกเคลียร์เมื่อสิ้นสุดรอบใหญ่",
		starEffectDesc_en = "Additional effect: Slowpoke is good at fishing with its tail. Units attacking Slowpoke will have a 50% chance to be added【get hooked】permanently, 【get hooked】can only be added once per battle\n#F20#\n#F40#【get hooked】: special control effect, can not be dispelled. 【get hooked】Units can only choose Slowpoke as targets when in action. This effect is removed when Slowpoke is defeated",
