	[3232] = {
		zawakeEffectDesc_es = "Slowking escupe una burbuja psíquica para atacar a un solo objetivo enemigo, causando #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# y agregando [Leader] a sí mismo durante 2 rondas\n #F20# \n#F40#[Leader]: Efecto de bonificación especial, no se puede disipar, cuando [Leader] está en el campo, todos los aliados aumentarán la tasa de acierto en un 20% y la tasa de resistencia de control en un 15%; después de que otros aliados se mueven, [Leader] elimina el 15% del daño no resuelto",
		zawakeEffectDesc_vn = "Slowking cospe uma bolha psíquica para atacar um único alvo inimigo, distribuindo #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# e adicionando [Leader] a si mesmo por 2 rodadas\n #F20# \n#F40#[Leader]: Efeito bônus especial, não pode ser dissipado, quando [Leader] estiver em campo, todos os aliados aumentarão a taxa de acerto em 20% e a taxa de resistência ao controle em 15%; depois que outros aliados se movem, [Leader] elimina 15% dos danos não resolvidos",
		describe_th = "การชะลอความเร็วจะพ่นฟองพลังจิตออกมาเพื่อโจมตีศัตรูเป้าหมายเดียว สร้าง #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม [Leader] ให้กับตัวเองเป็นเวลา 2 รอบ\n #F20# \n#F40#[Leader]: เอฟเฟกต์โบนัสพิเศษ ไม่สามารถลบล้างได้ เมื่อ [Leader] อยู่บนสนาม พันธมิตรทั้งหมดจะเพิ่มอัตราการโจมตี 20% และอัตราการต้านทานการควบคุม 15%; หลังจากที่พันธมิตรอื่นเคลื่อนไหว [Leader] ล้าง 15% ของความเสียหายที่ยังไม่ได้รับการแก้ไข",
		zawakeEffectDesc_kr = "Slowking은 정신 거품을 내뿜어 단일 적 대상을 공격하고 #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리하고 2라운드 동안 자신에게 [Leader]를 추가합니다\n #F20# \n#F40#[Leader]: 특별 보너스 효과, 해제 불가, [Leader]가 필드에 있을 때 모든 아군 적중률이 20%, 제어 저항률이 15% 증가합니다. 다른 아군이 이동한 후 [Leader] 해결되지 않은 피해의 15%가 지워집니다.",
		zawakeEffectDesc_th = "การชะลอความเร็วจะพ่นฟองพลังจิตออกมาเพื่อโจมตีศัตรูเป้าหมายเดียว สร้าง #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม [Leader] ให้กับตัวเองเป็นเวลา 2 รอบ\n #F20# \n#F40#[Leader]: เอฟเฟกต์โบนัสพิเศษ ไม่สามารถลบล้างได้ เมื่อ [Leader] อยู่บนสนาม พันธมิตรทั้งหมดจะเพิ่มอัตราการโจมตี 20% และอัตราการต้านทานการควบคุม 15%; หลังจากที่พันธมิตรอื่นเคลื่อนไหว [Leader] ล้าง 15% ของความเสียหายที่ยังไม่ได้รับการแก้ไข",
		describe_en = "Slowking spits out a Psychic Bubble to attack a single enemy target, dealing #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# and adding [Leader] to itself for 2 rounds\n#F20# \n#F40#[Leader]: Special bonus effect, cannot be dispelled, when [Leader] is on the field, all allies will increase the hit rate by 20% and the control resist rate by 15%; after other allies move, [Leader] clears 15% of unresolved damage",
		describe_es = "Slowking escupe una burbuja psíquica para atacar a un solo objetivo enemigo, causando #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# y agregando [Leader] a sí mismo durante 2 rondas\n #F20# \n#F40#[Leader]: Efecto de bonificación especial, no se puede disipar, cuando [Leader] está en el campo, todos los aliados aumentarán la tasa de acierto en un 20 % y la tasa de resistencia de control en un 15 %; después de que otros aliados se mueven, [Leader] elimina el 15% del daño no resuelto",
		zawakeSimpleDesc_en = "[Leader] increases the entire team's hit rate by 15% and crowd control resistance by 10%. After other allies have acted, [Leader] clears 10% of unresolved damage from itself. #F20# #F40##C0x5c9970# → [Leader] increases the entire team's hit rate by 20% and control resist rate by 15%. After other allies have acted, [Leader] clears 15% of unresolved damage from itself.",
		describe_vn = "Slowking cospe uma bolha psíquica para atacar um único alvo inimigo, distribuindo #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# e adicionando [Leader] a si mesmo por 2 rodadas\n #F20# \n#F40#[Leader]: Efeito bônus especial, não pode ser dissipado, quando [Leader] estiver em campo, todos os aliados aumentarão a taxa de acerto em 20% e a taxa de resistência ao controle em 15%; depois que outros aliados se movem, [Leader] elimina 15% dos danos não resolvidos",
		zawakeEffectDesc_en = "Slowking spits out a Psychic Bubble to attack a single enemy target, dealing #C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# and adding [Leader] to itself for 2 rounds\n#F20# \n#F40#[Leader]: Special bonus effect, cannot be dispelled, when [Leader] is on the field, all allies will increase the hit rate by 20% and the control resist rate by 15%; after other allies move, [Leader] clears 15% of unresolved damage",
