	[3236] = {
		describe_id = "Kerusakan acak yang diterima Slowking #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B# akan diselesaikan pada akhir tindakan selanjutnya；Jika frekuensi serangan aktif Daidai King dalam satu ronde melebihi tiga, 30% dari kerusakan yang belum terselesaikan akan dibersihkan pada akhir putaran.",
