	[3513] = {
		describe_th = "หัวทั้งสองของ Doduo ใช้สมองเดียวกัน และสามารถโจมตีศัตรูในแนวหน้าได้อย่างต่อเนื่อง สร้างความเสียหาย #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*26)$#C0xF13B54#P.DMG#C0x5B545B# Doduo อาจเข้าสู่สถานะใดสถานะหนึ่งต่อไปนี้ระหว่างการโจมตี: กระแสจิต - เพิ่มความเสียหาย 80%; ความไม่ลงรอยกัน - ลดความเสียหายลง 50%; ปกติ - ไม่มีการเปลี่ยนแปลงความเสียหาย",
		describe_en = "The two heads of Doduo shares the same brain, and can deal continuous attacks to enemies in the front line, dealing #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*26)$#C0xF13B54#P.DMG#C0x5B545B#. Doduo may enter one of the following status during the attack: Telepathy - increases damage by 80%; Disharmony - reduces damage by 50%; Normal - no change to damage",
		simDesc_es = "Los dos jefes de Doduo comparten el mismo cerebro y pueden lanzar ataques continuos a los enemigos en la primera línea. Existe la posibilidad de que el daño de este movimiento aumente o se reduzca.",
		describe_es = "Las dos cabezas de Doduo comparten el mismo cerebro y pueden realizar ataques continuos a los enemigos en la línea del frente, causando #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*26)$#C0xF13B54#P.DMG#C0x5B545B#. Doduo puede entrar en uno de los siguientes estados durante el ataque: Telepatía: aumenta el daño en un 80%; Desarmonía: reduce el daño en un 50%; Normal: no hay cambios en el daño",
		starEffectDesc_vn = "Efeito extra: Crítico. DMG é garantido quando a Telepatia está ativa",
		starEffectDesc_id = "Efek tambahan: Kritik. DMG dijamin ketika Telepati aktif",
		starEffectDesc_es = "Efecto extra: Crítico. DMG está garantizado cuando la telepatía está activa",
		describe_vn = "As duas cabeças de Doduo compartilham o mesmo cérebro e podem desferir ataques contínuos aos inimigos na linha de frente, distribuindo #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*26)$#C0xF13B54#P.DMG#C0x5B545B#. Doduo pode entrar em um dos seguintes status durante o ataque: Telepatia – aumenta o dano em 80%; Desarmonia - reduz os danos em 50%; Normal - nenhuma alteração no dano",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: คริติคอล รับประกันความเสียหายเมื่อกระแสจิตทำงาน",
		describe_id = "Kedua kepala Doduo berbagi otak yang sama, dan dapat melancarkan serangan terus menerus ke musuh di garis depan, menghasilkan #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*26)$#C0xF13B54#P.DMG#C0x5B545B#. Doduo dapat memasuki salah satu status berikut selama serangan: Telepati - meningkatkan kerusakan sebesar 80%; Ketidakharmonisan - mengurangi kerusakan sebesar 50%; Normal - tidak ada perubahan kerusakan",
