	[3813] = {
		describe_th = "เชลล์เดอร์ส่ายลิ้นใหญ่และพ่นสเปรย์ออกไปจำนวนมากเพื่อโจมตีเป้าหมายศัตรูทั้งหมด สร้างความเสียหาย#C0xE69900#150% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B# มีโอกาส 80% ที่จะทำให้ศัตรูเข้ามา แถวหลังให้ตก [Ice Trap] 2 รอบ หากอยู่ใน [Ice Trap] แล้ว มีโอกาส 100% ที่จะ [Frozen] เป้าหมายเป็นเวลา 2 รอบ และเพิ่ม P.DEF 100% เป็นเวลา 1 รอบ จากนั้นจึงถอยกลับเข้าไปในเปลือกและป้องกันตัวเองจนถึงเทิร์นถัดไป (HP ทั้งหมด ของกระสุนคือ 3000% ของ P.DEF เริ่มต้นของ Shellder ไม่สามารถถอยกลับเข้าไปในกระสุนได้เมื่อ HP ของ Shellder เป็น 0)",
		zawakeEffectDesc_vn = "Efeito Adicional: Durante a retração para o projétil, aumenta adicional de 20% de redução de dano e 50% de Reflexo de DMG passivo da Armadura de Espinho",
		simDesc_es = "Shellder agitó su gran lengua y lanzó toneladas de salpicaduras para atacar a todos los objetivos enemigos, tiene la posibilidad de infligir [Ice Trap] al objetivo y luego se retrae dentro del caparazón para defenderse.",
		describe_es = "Shellder agitó su gran lengua y lanzó toneladas de salpicaduras para atacar a todos los objetivos enemigos, causando#C0xE69900#150% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, 80% de probabilidad de causar enemigos en fila de atrás para caer en [Ice Trap] durante 2 rondas. Si ya está en [Ice Trap], 100 % de posibilidades de [Frozen] el objetivo durante 2 rondas y aumenta el 100 % P.DEF durante 1 ronda, luego se retrae dentro del caparazón y se protege hasta el siguiente turno (el HP total del caparazón es 3000% del P.DEF inicial de Shellder, no puede retraerse dentro del caparazón cuando el HP de Shellder es 0)",
		zawakeEffectDesc_th = "ผลกระทบเพิ่มเติม: ในระหว่างการถอยกลับไปยังกระสุน เพิ่มการลดความเสียหายเพิ่มเติม 20% และ การสะท้อนความเสียหายของเกราะ Thorn แบบพาสซีฟ 50%",
		starEffectDesc_id = "Efek Tambahan: Selama menarik kembali cangkang, meningkatkan tambahan pengurangan kerusakan sebesar 20%.",
		starEffectDesc_es = "Efecto adicional: durante la retracción al caparazón, aumenta un 20% adicional de reducción de daño",
		zawakeSimpleDesc_en = "During retracting to the shell, increases DMG Reflection of Thorn Armor by 50%",
		describe_vn = "Shellder balançou sua língua grande e pulverizou toneladas de respingos para atacar todos os alvos inimigos, distribuindo#C0xE69900#150% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, 80% de chance de causar inimigos em fileira de trás para cair em [Ice Trap] por 2 rodadas. Se já estiver em [Ice Trap], 100% de chance de [Frozen] atingir o alvo por 2 rodadas, e aumentar 100% P.DEF por 1 rodada, então retrair para dentro da carapaça e se proteger por último até o próximo turno (o HP total do projétil é 3000% do P.DEF inicial do Shellder, não é possível retrair para dentro do projétil quando o HP do Shellder é 0)",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: ในระหว่างการถอยกลับเข้าสู่กระสุน เพิ่มการลดความเสียหายเพิ่มเติม 20%",
		starEffectDesc_vn = "Efeito Adicional: Durante a retração para o projétil, aumenta a redução adicional de 20% de dano",
		zawakeEffectDesc_kr = "추가 효과: 껍질로 후퇴하는 동안 가시 갑옷의 피해 감소가 20% 추가로 증가하고 패시브 데미지 반사가 50% 증가합니다.",
		describe_en = "Shellder shook its big tongue and sprayed out tons of splashes to attack all enemy targets, dealing#C0xE69900#150% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, 80% chance of causing enemies in back row to fall into [Ice Trap] for 2 rounds. If it is already in [Ice Trap], 100% chance to [Frozen] the target for 2 rounds, and increase 100% P.DEF for 1 round, then retract into the shell and protect itself last until the next turn (the total HP of the shell is 3000% of initial P.DEF of Shellder, cannot to retract into the shell when Shellder’s HP is 0)",
		zawakeEffectDesc_id = "Efek Tambahan: Selama menarik kembali cangkang, meningkatkan tambahan 20% pengurangan kerusakan dan 50% DMG pasif Refleksi Thorn Armor",
		describe_id = "Shellder menggelengkan lidahnya yang besar dan menyemprotkan banyak percikan untuk menyerang semua target musuh, menyebabkan#C0xE69900#150% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, 80% kemungkinan menyebabkan musuh masuk barisan belakang untuk jatuh ke [Ice Trap] selama 2 putaran. Jika sudah dalam [Ice Trap], 100% berpeluang mencapai [Frozen] target selama 2 ronde, dan meningkatkan 100% P.DEF selama 1 ronde, lalu menarik kembali ke dalam cangkang dan melindungi dirinya bertahan hingga giliran berikutnya (total HP dari shell adalah 3000% dari P.DEF awal Shellder, tidak dapat ditarik kembali ke dalam shell ketika HP Shellder adalah 0)",
		simDesc_en = "Shellder shook its big tongue and sprayed out tons of splashes to attack all enemy targets,  chance to deal [Ice Trap] to target, then retract into shell to defend itself.",
		simDesc_vn = "Shellder balançou sua língua grande e disparou toneladas de respingos para atacar todos os alvos inimigos, chance de acertar [Ice Trap] no alvo e, em seguida, retrair-se para dentro do projétil para se defender.",
