	[3942] = {
		zawakeEffectDesc_kr = "메가 젠가가 단일 적 대상에게 그림자 광선을 발사하여 #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, 젠가의 HP가 50% 이상일 경우 100% 확률로 가함 [Fear] 2라운드를 목표로 하는 상태입니다. 젠가 자신의 HP가 50% 미만인 경우 일정량만큼 대상의 HP를 훔칩니다. (헬스 훔치기량: 메가 젠가의 50% SP.ATK, 데미지는 고정 데미지), [Fear] 상태에서 대상을 공격할 때 체력 훔치기량이 2배가 됩니다.",
		zawakeEffectDesc_vn = "Mega Gengar dispara um Shadow Ray em um único alvo inimigo, distribuindo#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, se o HP de Gengar for superior a 50%, 100% de chance de infligir [Fear] estado para atingir por 2 rodadas. Se o HP do próprio Gengar for inferior a 50%, roube HP do alvo com certa quantidade (quantidade de roubo de saúde: 50% de SP.ATK de Mega Gengar, o dano é dano verdadeiro), dobra a quantidade de roubo de saúde ao atacar o alvo no estado [Fear]",
		simDesc_es = "Mega Gengar dispara un Shadow Ray a un solo objetivo enemigo",
		describe_en = "Mega Gengar shoots a Shadow Ray to a single enemy target, dealing#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, if Gengar's HP over 50%, 100% chance to inflict [Fear] state to target for 2 rounds. If Gengar's own HP less than 50%, steal HP from target with certain amount (Life steal amount: Mega Gengar's 30% Sp.ATK, the damage is true damage), and having 40% chance to [Fear] target, doubles life steal amount when attacking target in [Fear] state",
		zawakeEffectDesc_th = "เมก้าเก็นการ์ยิงลำแสงเงาไปยังศัตรูเป้าหมายเดียว สร้างความเสียหาย#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# หาก HP ของเก็นการ์เกิน 50% มีโอกาส 100% ที่จะสร้างความเสียหาย [Fear] รัฐตั้งเป้า 2 รอบ หาก HP ของ Gengar น้อยกว่า 50% ให้ขโมย HP จากเป้าหมายด้วยจำนวนที่กำหนด (จำนวนการขโมยสุขภาพ: SP.ATK 50% ของ Mega Gengar ความเสียหายคือความเสียหายจริง) เพิ่มปริมาณการขโมยสุขภาพเป็นสองเท่าเมื่อโจมตีเป้าหมายในสถานะ [Fear]",
		describe_es = "Mega Gengar dispara un Rayo de Sombra a un solo objetivo enemigo, causando#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, si el HP de Gengar supera el 50%, 100% de probabilidad de infligir [Fear] Estado para apuntar durante 2 rondas. Si el propio HP de Gengar es inferior al 50%, roba HP del objetivo con una cierta cantidad (cantidad de robo de vida: 30% Sp.ATK de Mega Gengar, el daño es daño verdadero) y al tener un 40% de probabilidad de [Fear] objetivo, duplica el robo de vida. cantidad al atacar al objetivo en estado [Fear]",
		simDesc_vn = "Mega Gengar dispara um Shadow Ray em um único alvo inimigo",
		zawakeSimpleDesc_en = "#C0x5c9970#Increase the amount of lifesteal by 50% of its SP.ATK",
		describe_vn = "Mega Gengar dispara um Shadow Ray em um único alvo inimigo, distribuindo#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, se o HP de Gengar for superior a 50%, 100% de chance de infligir [Fear] estado para atingir por 2 rodadas. Se o HP do próprio Gengar for inferior a 50%, roube HP do alvo com certa quantidade (quantidade de roubo de vida: Sp.ATK de 30% de Mega Gengar, o dano é dano verdadeiro), e tendo 40% de chance de [Fear] alvo, dobra o roubo de vida quantidade ao atacar o alvo no estado [Fear]",
		zawakeEffectDesc_id = "Mega Gengar menembakkan Shadow Ray ke satu target musuh, menimbulkan#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, jika HP Gengar lebih dari 50%, 100% peluang menimbulkan [Fear] menyatakan target untuk 2 putaran. Jika HP Gengar sendiri kurang dari 50%, mencuri HP dari target dengan jumlah tertentu (Jumlah Health Steal: 50% SP.ATK Mega Gengar, damagenya adalah true damage), menggandakan jumlah Health steal ketika menyerang target dalam keadaan [Fear]",
		zawakeEffectDesc_es = "Mega Gengar dispara un Rayo de Sombra a un solo objetivo enemigo, causando#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, si el HP de Gengar supera el 50%, 100% de probabilidad de infligir [Fear] Estado para apuntar durante 2 rondas. Si el propio HP de Gengar es inferior al 50%, roba HP del objetivo con cierta cantidad (cantidad de robo de salud: 50% SP.ATK de Mega Gengar, el daño es daño verdadero), duplica la cantidad de robo de salud cuando ataca al objetivo en estado [Fear]",
		describe_th = "เมก้าเก็นการ์ยิงลำแสงเงาไปยังศัตรูเป้าหมายเดียว สร้างความเสียหาย#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# หาก HP ของเก็นการ์เกิน 50% มีโอกาส 100% ที่จะสร้างความเสียหาย [Fear] รัฐตั้งเป้า 2 รอบ หาก HP ของ Gengar น้อยกว่า 50% ให้ขโมย HP จากเป้าหมายด้วยจำนวนที่กำหนด (จำนวนขโมยชีวิต: Sp.ATK 30% ของ Mega Gengar ความเสียหายคือความเสียหายจริง) และมีโอกาส 40% ที่จะ [Fear] เป้าหมาย เพิ่มการขโมยพลังชีวิตเป็นสองเท่า จำนวนเมื่อโจมตีเป้าหมายในสถานะ [Fear]",
		zawakeSimpleDesc_th = "#C0x5c9970#เพิ่มปริมาณการดูดเลือด 50% ของ SP.ATK",
		zawakeSimpleDesc_kr = "#C0x5c9970#생명력 흡수량이 SP.ATK의 50%만큼 증가합니다.",
		describe_id = "Mega Gengar menembakkan Shadow Ray ke satu target musuh, menimbulkan#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, jika HP Gengar lebih dari 50%, 100% peluang menimbulkan [Fear] menyatakan target untuk 2 putaran. Jika HP Gengar sendiri kurang dari 50%, mencuri HP dari target dengan jumlah tertentu (Jumlah Life steal: 30% Sp.ATK Mega Gengar, damage yang dihasilkan adalah true damage), dan mempunyai 40% peluang untuk [Fear] target, menggandakan life steal jumlah saat menyerang target dalam kondisi [Fear]",
		simDesc_en = "Mega Gengar fires a Shadow Ray to a single enemy target",
		zawakeEffectDesc_en = "Mega Gengar shoots a Shadow Ray to a single enemy target, dealing#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, if Gengar's HP over 50%, 100% chance to inflict [Fear] state to target for 2 rounds. If Gengar's own HP less than 50%, steal HP from target with certain amount (Health Steal amount: Mega Gengar's 50% SP.ATK, the damage is true damage), doubles Health steal amount when attacking target in [Fear] state",
		describe_kr = "메가 젠가가 단일 적 대상에게 그림자 광선을 발사하여 #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, 젠가의 HP가 50% 이상일 경우 100% 확률로 가함 [Fear] 2라운드를 목표로 하는 상태입니다. 젠가 자신의 HP가 50% 미만일 경우 일정량(라이프 스틸량: 메가 젠가의 Sp.ATK 30%, 데미지는 고정 데미지)만큼 대상의 HP를 빼앗고, 40% 확률로 대상에게 [Fear] 라이프 스틸을 두 배로 훔친다. [Fear] 상태에서 대상을 공격할 때의 금액",
		simDesc_th = "Mega Gengar ยิง Shadow Ray ไปยังเป้าหมายศัตรูตัวเดียว",
		zawakeSimpleDesc_vn = "#C0x5c9970#Aumenta a quantidade de roubo de vida em 50% do seu SP.ATK",
