	[4413] = {
		describe_th = "#C0xC0C0C0#Exeggcute Cyclone!!#C0x5B545B#\n#F10#\n#F40#Exeggcute หมุนไปรอบๆ และปล่อยพายุไซโคลนเพื่อโจมตีศัตรู สร้างความเสียหาย #C0x3D8A99#510%SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# SP.DMG#C0x5B545B# มีโอกาส 100% ที่จะสร้างเป้าหมาย [Sleep] เป็นเวลา 2 รอบ (เมื่อเป้าหมายถูกปลุกพลัง จะได้รับ DMG เท่ากับ 100% ของ SP.ATK ของ Exeggcute) Exeggcute กินหนึ่งในแต่ละประเภทที่เก็บเกี่ยวได้ [Berry] จากนั้นโยนแกน Berry ที่เหลือไปที่ศัตรูแบบสุ่ม แต่ละแกนของ Berry จะสร้าง SP.DMG เท่ากับ 80% ของ SP.ATK ของ Exeggcute",
		zawakeEffectDesc_vn = "Efeito Adicional: Colha todos os obtidos [Berry] 2 de cada vez",
		simDesc_es = "Exeggcute gira, libera un ciclón para atacar a un enemigo, haciendo que el objetivo caiga en [Sleep], y se come uno de cada tipo de [Berry] cosechado, luego arroja los núcleos de Berry sobrantes a enemigos aleatorios.",
		describe_es = "#C0xC0C0C0#¡¡Exeggcute Cyclone!! #C0x5B545B#\n#F10#\n#F40#Exeggcute gira y libera un ciclón para atacar a un enemigo, causando #C0x3D8A99#510%SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# SP.DMG#C0x5B545B#, tiene un 100% de posibilidades de alcanzar el objetivo [Sleep] durante 2 rondas (cuando el objetivo se despierta, recibe DAÑO igual al 100% del SP.ATK de Exeggcute). Exeggcute come uno de cada tipo de cosechado [Berry], luego arroja los núcleos de Berry sobrantes a enemigos aleatorios, cada núcleo de Berry causa SP.DMG equivalente al 80% del SP.ATK de Exeggcute.",
		zawakeEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เก็บเกี่ยวทั้งหมดที่ได้รับ [Berry] 2 อันต่อครั้ง",
		starEffectDesc_id = "Efek tambahan: Dapatkan semua [Berry] yang dipanen sekaligus",
		starEffectDesc_es = "Efecto adicional: Gana todo lo cosechado [Berry] de una vez",
		zawakeSimpleDesc_en = "Harvest all obtained [Berry] at a time\n#F20#\n#F40##C0x5c9970#→Harvest all obtained [Berry] 2 at a time",
		describe_vn = "#C0xC0C0C0#Exeggcute Cyclone!!#C0x5B545B#\n#F10#\n#F40#Exeggcute gira e libera um ciclone para atacar um inimigo, distribuindo #C0x3D8A99#510%SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54# SP.DMG#C0x5B545B#, tem 100% de chance de acertar o alvo [Sleep] por 2 rodadas (Quando o alvo é despertado, ele recebe DMG igual a 100% do SP.ATK do Exeggcute). Exeggcute come um de cada tipo colhido [Berry], então joga os núcleos de Berry restantes em inimigos aleatórios, cada núcleo de Berry distribui SP.DMG igual a 80% do SP.ATK de Exeggcute.",
