		zawakeEffectDesc_vn = "#C0xC0C0C0#Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor lança uma Berry Bomb para atacar um inimigo, distribuindo #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG #C0x5B545B#, come um [Berry] colhido aleatoriamente e, adicionalmente, colhe 2 [Berry].",
		describe_th = "#C0xC0C0C0#ปัง!#C0x5B545B#\n#F10#\n#F40#Exeggutor ขว้าง Berry Bomb เพื่อโจมตีศัตรู สร้างความเสียหาย #C0x3D8A99#160% SP.ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG #C0x5B545B# กินแบบสุ่มที่เก็บเกี่ยว [Berry] และเก็บเกี่ยวเพิ่มเติม 1[Berry]",
		zawakeEffectDesc_kr = "#C0xC0C0C0#쾅!#C0x5B545B#\n#F10#\n#F40#Exeggutor가 베리 폭탄을 던져 적을 공격하고 #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG를 처리합니다. #C0x5B545B#, 무작위로 수확한 [Berry]를 먹고, 추가적으로 2[Berry]을 수확합니다.",
		zawakeEffectDesc_th = "#C0xC0C0C0#ปัง!#C0x5B545B#\n#F10#\n#F40#Exeggutor ขว้าง Berry Bomb เพื่อโจมตีศัตรู สร้างความเสียหาย #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG #C0x5B545B# กินแบบสุ่มที่เก็บเกี่ยว [Berry] และเก็บเกี่ยวเพิ่มเติม 2 [Berry]",
		describe_en = "#C0xC0C0C0#Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor throws a Berry Bomb to attack an enemy, dealing #C0x3D8A99#160% SP.ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG#C0x5B545B#, eats a random harvested [Berry], and additionally harvest 1[Berry].",
		describe_es = "#C0xC0C0C0#¡Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor lanza una bomba de baya para atacar a un enemigo, causando #C0x3D8A99#160% SP.ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG #C0x5B545B#, come un [Berry] cosechado al azar y, además, cosecha 1[Berry].",
		zawakeSimpleDesc_en = "gets 1 extra [Berry]\n#F20#\n#F40##C0x5c9970#→gets 2 extra [Berry]",
		describe_vn = "#C0xC0C0C0#Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor lança uma Berry Bomb para atacar um inimigo, distribuindo #C0x3D8A99#160% SP.ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG #C0x5B545B#, come um [Berry] colhido aleatoriamente e, adicionalmente, colhe 1[Berry].",
		zawakeEffectDesc_en = "#C0xC0C0C0#Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor throws a Berry Bomb to attack an enemy, dealing #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, eats a random harvested [Berry], and additionally harvest 2 [Berry].",
		zawakeSimpleDesc_vn = "ganha 1 extra [Berry]\n#F20#\n#F40##C0x5c9970#→ganha 2 extras [Berry]",
		zawakeSimpleDesc_id = "dapat 1 tambahan [Berry]\n#F20#\n#F40##C0x5c9970#→dapat 2 tambahan [Berry]",
		zawakeSimpleDesc_es = "obtiene 1 extra [Berry]\n#F20#\n#F40##C0x5c9970# →obtiene 2 extra [Berry]",
		describe_id = "#C0xC0C0C0#Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor melempar Bom Berry untuk menyerang musuh, menyebabkan #C0x3D8A99#160% SP.ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG #C0x5B545B#, makan yang dipanen secara acak [Berry], dan tambahan panen 1[Berry].",
		zawakeSimpleDesc_kr = "1개 추가 [Berry]\n#F20#\n#F40##C0x5c9970#→2개 추가 [Berry]",
		zawakeEffectDesc_id = "#C0xC0C0C0#Bang!#C0x5B545B#\n#F10#\n#F40#Exeggutor melempar Bom Berry untuk menyerang musuh, menyebabkan #C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG #C0x5B545B#, makan yang dipanen acak [Berry], dan tambahan panen 2 [Berry].",
		describe_kr = "#C0xC0C0C0#쾅!#C0x5B545B#\n#F10#\n#F40#Exeggutor가 베리 폭탄을 던져 적을 공격하고 #C0x3D8A99#160% SP.ATK #C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54# SP.DMG를 줍니다. #C0x5B545B#, 무작위로 수확한 [Berry]를 먹고, 추가로 1[Berry]을 수확합니다.",
		zawakeSimpleDesc_th = "ได้เพิ่ม 1 รายการ [Berry]\n#F20#\n#F40##C0x5c9970#→ได้เพิ่ม 2 รายการ [Berry]",
