	[4423] = {
		describe_th = "#C0xC0C0C0#ยิง!#C0x5B545B#\n#F10#\n#F40#Exeggutor เตะหัวของมันอย่างลูกบอลใส่ศัตรูอย่างแรง สร้างความเสียหาย #C0x3D8A99#520% SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#SP .DMG#C0x5B545B# มีโอกาส 100% ที่จะสร้างเป้าหมาย [Sleep] เป็นเวลา 2 รอบ (เมื่อเป้าหมายถูกปลุกพลัง จะได้รับ DMG เท่ากับ 100% ของ SP.ATK ของ Exeggutor) Exeggutor กินหนึ่งในแต่ละประเภทที่เก็บเกี่ยวได้ [Berry] จากนั้นโยนแกน Berry ที่เหลือไปที่ศัตรูแบบสุ่ม แต่ละแกนของ Berry จะสร้าง SP.DMG เท่ากับ 80% ของ SP.ATK ของ Exeggutor",
		zawakeEffectDesc_vn = "Efeito adicional: Ganhe 2 [Berries] para cada tipo colhido de uma só vez",
		simDesc_es = "Exeggutor patea vigorosamente su cabeza como una pelota hacia un enemigo, marca el objetivo [Sleep], come uno de cada tipo de cosechado [Berry] y luego arroja los núcleos de bayas sobrantes a enemigos aleatorios.",
		describe_es = "#C0xC0C0C0#¡Dispara!#C0x5B545B#\n#F10#\n#F40#Exeggutor patea su cabeza como una pelota hacia un enemigo vigorosamente, causando #C0x3D8A99#520% SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#SP .DMG#C0x5B545B#, tiene un 100% de posibilidades de alcanzar el objetivo [Sleep] durante 2 rondas (cuando el objetivo se despierta, recibe DAÑO igual al 100% del SP.ATK de Exeggutor). Exeggutor come uno de cada tipo de cosechado [Berry], luego arroja los núcleos de Berry sobrantes a enemigos aleatorios, cada núcleo de Berry causa SP.DMG igual al 80% del SP.ATK de Exeggutor.",
		zawakeEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: ได้รับ 2 [Berries] สำหรับการเก็บเกี่ยวแต่ละประเภทในคราวเดียว",
		starEffectDesc_id = "Efek tambahan: Dapatkan semua [Berry] yang dipanen sekaligus",
		starEffectDesc_es = "Efecto adicional: Gana todo lo cosechado [Berry] de una vez",
		zawakeSimpleDesc_en = "Harvest all obtained [Berry] at a time\n#F20#\n#F40##C0x5c9970#→Harvest all obtained [Berry] 2 at a time",
		describe_vn = "?? .DMG#C0xC0C0C0#, tem 100% de chance de acertar o alvo #C0x5B545B# por 2 rodadas (Quando o alvo é despertado, ele recebe DMG igual a 100% do SP.ATK do Exeggutor). Exeggutor come um de cada tipo colhido #F10#, então joga os núcleos de Berry restantes em inimigos aleatórios, cada núcleo de Berry distribui SP.DMG igual a 80% do SP.ATK de Exeggutor.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: ได้รับผลผลิตทั้งหมด [Berry] ในคราวเดียว",
		starEffectDesc_vn = "Efeito adicional: Ganhe todos os [Berry] colhidos de uma vez",
		zawakeEffectDesc_kr = "추가 효과: 수확한 종류별로 동시에 2 [Berries] 획득",
		describe_en = "#C0xC0C0C0#Shoot!#C0x5B545B#\n#F10#\n#F40#Exeggutor kicks its head as a ball to an enemy vigorously, dealing #C0x3D8A99#520% SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#SP.DMG#C0x5B545B#, has a 100% chance to make target [Sleep] for 2 rounds (When the target is awakened, it receives DMG equal to 100% of Exeggutor's SP.ATK). Exeggutor eats one of each type of harvested [Berry], then throw the leftover Berry cores at random enemies, each Berry core deals SP.DMG equal to 80% of Exeggutor's SP.ATK.",
		zawakeEffectDesc_id = "Efek tambahan: Mendapatkan 2 [Berries] untuk setiap jenis yang dipanen sekaligus",
		describe_id = "#C0xC0C0C0#Tembak!#C0x5B545B#\n#F10#\n#F40#Exeggutor menendang kepalanya seperti bola ke arah musuh dengan kuat, menghasilkan #C0x3D8A99#520% SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#SP .DMG#C0x5B545B#, berpeluang 100% mengenai target [Sleep] selama 2 ronde (Saat target dibangunkan, ia menerima DMG setara dengan 100% SP.ATK Exeggutor). Exeggutor memakan satu dari setiap jenis yang dipanen [Berry], lalu melemparkan sisa inti Berry ke musuh secara acak, setiap inti Berry menghasilkan SP.DMG setara dengan 80% SP.ATK Exeggutor.",
		simDesc_en = "Exeggutor kicks its head as a ball to an enemy vigorously, makes the target [Sleep], eats one of each type of harvested [Berry], then throw the leftover Berry cores at random enemies.",
		simDesc_vn = "Exeggutor chuta vigorosamente a cabeça como uma bola para um inimigo, acerta o alvo [Sleep], come um de cada tipo de [Berry] colhido e, em seguida, joga os núcleos de Berry restantes em inimigos aleatórios.",
		describe_kr = "#C0xC0C0C0#쏴!#C0x5B545B#\n#F10#\n#F40#Exeggutor가 적에게 공처럼 머리를 힘차게 걷어차며 #C0x3D8A99#520% SP.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#SP를 처리합니다. .DMG#C0x5B545B#, 2라운드 동안 타겟 [Sleep]를 만들 확률이 100%입니다(타겟이 각성되면 Exeggutor SP.ATK의 100%에 해당하는 DMG를 받습니다). Exeggutor는 수확한 각 유형 중 하나를 먹습니다 [Berry] 그런 다음 남은 베리 코어를 무작위 적에게 던집니다. 각 베리 코어는 Exeggutor SP.ATK의 80%에 해당하는 SP.DMG를 처리합니다.",
		simDesc_th = "Exeggutor เตะหัวเป็นลูกบอลใส่ศัตรูอย่างแรง ทำให้เป้าหมาย [Sleep] กินหนึ่งชนิดจากแต่ละประเภทที่เก็บเกี่ยว [Berry] จากนั้นโยนแกน Berry ที่เหลือไปที่ศัตรูแบบสุ่ม",
		zawakeEffectDesc_es = "Efecto adicional: Gana 2 [Berries] por cada tipo cosechado a la vez",
		starEffectDesc_kr = "추가 효과: 수확한 모든 [Berry]를 한 번에 획득",
		zawakeEffectDesc_en = "Additional effect: Gain 2 [Berries] for each harvested type at one time",
		simDesc_kr = "Exeggutor는 적에게 힘차게 머리를 공처럼 차고, 목표물을 [Sleep]로 만들고, 수확한 종류별로 하나씩 [Berry] 먹은 다음, 남은 베리 코어를 무작위 적에게 던집니다.",
		zawakeSimpleDesc_th = "เก็บเกี่ยวทั้งหมดที่ได้รับ [Berry] ครั้งละครั้ง\n#F20#\n#F40##C0x5c9970#→เก็บเกี่ยวทั้งหมดที่ได้รับ [Berry] 2 ครั้ง",
		zawakeSimpleDesc_kr = "획득량 모두 수확 [Berry] 한번에\n#F20#\n#F40##C0x5c9970#→ 획득량 모두 수확 [Berry] 2개 획득",
		starEffectDesc_en = "Additional effect: Gain all the harvested [Berry] at one time",
		zawakeSimpleDesc_vn = "Colha todos os obtidos [Berry] de cada vez\n#F20#\n#F40##C0x5c9970#→Colha todos os obtidos [Berry] 2 de cada vez",
		zawakeSimpleDesc_id = "Panen semua yang didapat [Berry] sekaligus\n#F20#\n#F40##C0x5c9970#→Panen semua yang didapat [Berry] 2 sekaligus",
		id = 4423,
		zawakeSimpleDesc_es = "Cosecha todo lo obtenido [Berry] a la vez\n#F20#\n#F40##C0x5c9970#→Cosecha todo lo obtenido [Berry] 2 a la vez",
		simDesc_id = "Exeggutor menendang kepalanya seperti bola ke arah musuh dengan kuat, membuat target [Sleep], memakan satu dari setiap jenis yang dipanen [Berry], lalu melemparkan sisa inti Berry ke musuh secara acak."
	},
