	[5026] = {
		describe_id = "Di akhir setiap putaran besar, jika Happiny tidak berada dalam efek kontrol, ia akan menetaskan telur untuk dimakan oleh sekutu dengan persentase HP terendah (Menyembuhkan jumlah batas HP Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#) , jika efek penyembuhan meluap, 20% dari jumlah yang meluap akan diubah secara permanen menjadi batas HP (ditumpuk hingga 3 kali)",
		zawakeEffectDesc_vn = "No final de cada grande rodada, se Happiny não estiver em efeito de controle, ele chocará um ovo para um aliado com a menor porcentagem de HP para comer (curando a quantidade de limite de HP de Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP) , e adicionalmente aumenta as seis estatísticas básicas em 5% (até 3 vezes), se o efeito de cura transbordar, 20% da quantidade excedente será permanentemente convertida em limite de HP (acumular até 3 vezes)",
		describe_vn = "No final de cada grande rodada, se Happiny não estiver em efeito de controle, ele chocará um ovo para um aliado com a menor porcentagem de HP para comer (curando a quantidade de Happiny's#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#limite de HP) , se o efeito de cura transbordar, 20% da quantidade excedente será permanentemente convertida em limite de HP (acumular até 3 vezes)",
		starEffectDesc_id = "Efek Tambahan: Heart of Healing: Menghilangkan kontrol atau efek negatif pada sekutu acak di akhir setiap putaran",
		zawakeEffectDesc_th = "เมื่อสิ้นสุดรอบใหญ่แต่ละรอบ หากความสุขไม่อยู่ในเอฟเฟกต์ควบคุม มันจะฟักไข่ให้พันธมิตรที่มีเปอร์เซ็นต์ HP ต่ำที่สุดที่จะกิน (การรักษาจำนวนขีดจำกัด HP ของความสุข#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#จำกัด HP) และเพิ่มสเตตัสพื้นฐานหกเพิ่มเติมอีก 5% (สูงสุด 3 เท่า) หากเอฟเฟกต์การรักษาล้น ​​20% ของจำนวนล้นจะถูกแปลงเป็นขีดจำกัด HP อย่างถาวร (ซ้อนสูงสุด 3 ครั้ง)",
		starEffectDesc_kr = "추가 효과: 치유의 심장: 각 라운드가 끝날 때 무작위 아군에 대한 제어 또는 부정적인 효과를 해제합니다.",
		describe_es = "Al final de cada ronda grande, si Happiny no tiene el efecto de control, incubará un huevo para que lo coma un aliado con el porcentaje de HP más bajo (curando la cantidad de HP de Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#límite de HP) , si el efecto de curación se desborda, el 20% de la cantidad desbordada se convertirá permanentemente en límite de HP (se acumula hasta 3 veces)",
		zawakeSimpleDesc_en = "and additionally increases Basic six stats by 5%(up to 3 times)",
		starEffectDesc_es = "Efecto adicional: Corazón de curación: disipa un control o efecto negativo en un aliado aleatorio al final de cada ronda.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: หัวใจแห่งการรักษา: ยกเลิกการควบคุมหรือเอฟเฟกต์ด้านลบต่อพันธมิตรแบบสุ่มเมื่อสิ้นสุดแต่ละรอบ",
		zawakeEffectDesc_id = "Di akhir setiap putaran besar, jika Happiny tidak berada dalam efek kontrol, ia akan menetaskan telur untuk dimakan oleh sekutu dengan persentase HP terendah (Menyembuhkan jumlah batas HP Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#) , dan tambahan meningkatkan stat Basic six sebesar 5% (hingga 3 kali), jika efek penyembuhan meluap, 20% dari jumlah yang meluap akan diubah secara permanen menjadi batas HP (ditumpuk hingga 3 kali)",
		zawakeEffectDesc_es = "Al final de cada ronda grande, si Happiny no tiene el efecto de control, incubará un huevo para que lo coma un aliado con el porcentaje de HP más bajo (curando la cantidad de HP de Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#límite de HP) y, además, aumenta las seis estadísticas básicas en un 5% (hasta 3 veces). Si el efecto de curación se desborda, el 20% de la cantidad desbordada se convertirá permanentemente en límite de HP (se acumula hasta 3 veces).",
		describe_en = "At the end of each big round, if Happiny is not in controll effect, it will hatch an egg for an ally with the lowest HP percentage to eat (Healing the amount of Happiny’s#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP limit), if healing effect  overflows, 20% of the overflow amount will be permanently converted into HP limit (stack up to 3 times)",
		zawakeSimpleDesc_th = "และเพิ่มค่าสถานะพื้นฐานหกเพิ่มเติม 5% (สูงสุด 3 ครั้ง)",
		zawakeEffectDesc_kr = "각 큰 라운드가 끝날 때 행복이 제어 효과가 없으면 먹을 수 있는 HP 비율이 가장 낮은 아군에게 알을 부화합니다. (행복의 최대량#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP 한도 치유) , 기본 6스텟을 추가로 5%(최대 3회) 증가시키며, 힐링 효과가 넘치면 넘친 양의 20%가 HP한계로 영구적으로 전환됩니다(최대 3회 중첩).",
		zawakeSimpleDesc_kr = "기본 6스텟이 추가로 5%(최대 3배) 증가합니다.",
		zawakeEffectDesc_en = "At the end of each big round, if Happiny is not in controll effect, it will hatch an egg for an ally with the lowest HP percentage to eat (Healing the amount of Happiny’s#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP limit), and additionally increases Basic six stats by 5%(up to 3 times), if healing effect  overflows, 20% of the overflow amount will be permanently converted into HP limit (stack up to 3 times)",
		describe_kr = "각 큰 라운드가 끝날 때 행복이 제어 효과가 없으면 먹을 수 있는 HP 비율이 가장 낮은 아군에게 알을 부화합니다. (행복의 최대량#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP 한도 치유) , 회복 효과가 넘칠 경우, 넘친 양의 20%가 영구적으로 HP 제한으로 전환됩니다. (최대 3회 중첩 가능)",
		zawakeSimpleDesc_vn = "e adicionalmente aumenta as seis estatísticas básicas em 5% (até 3 vezes)",
		zawakeSimpleDesc_id = "dan tambahan meningkatkan statistik Basic six sebesar 5% (hingga 3 kali)",
		starEffectDesc_vn = "Efeito Adicional: Coração de Cura: Dissipa um efeito de controle ou negativo em um aliado aleatório no final de cada rodada",
		zawakeSimpleDesc_es = "y además aumenta las seis estadísticas básicas en un 5% (hasta 3 veces)",
		describe_th = "เมื่อสิ้นสุดรอบใหญ่แต่ละรอบ หากความสุขไม่อยู่ในเอฟเฟกต์ควบคุม มันจะฟักไข่ให้พันธมิตรที่มีเปอร์เซ็นต์ HP ต่ำที่สุดที่จะกิน (การรักษาจำนวนขีดจำกัด HP ของความสุข#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#จำกัด HP) หากผลการรักษาล้น ​​20% ของปริมาณล้นจะถูกแปลงเป็นขีดจำกัด HP อย่างถาวร (ซ้อนทับได้สูงสุด 3 ครั้ง)",
