	[5032] = {
		zawakeEffectDesc_es = "Blissey lanza una bola de luz curativa y cura a un aliado con la cantidad del límite de HP del 30% de Blissey+$(skillLevel*4*24)$, disipa un control o efecto negativo del objetivo y, además, cura el HP que equivale al 20% del HP máximo de Blissey del objetivo de otro aliado. con la relación de HP más baja",
		zawakeEffectDesc_vn = "Blissey lança uma bola de luz curativa e cura um aliado com a quantidade do limite de 30% de HP de Blissey + $(skillLevel*4*24)$, dissipa um controle ou efeito negativo do alvo e, adicionalmente, cura HP que equivale a 20% do HP máximo de Blissey do alvo de outro aliado com a menor proporção de HP",
		describe_th = "Blissey ขว้างลูกบอลแสงแห่งการรักษา และรักษาพันธมิตรด้วยจำนวน HP สูงสุด 30% ของ Blissey+$(skillLevel*4*24)$ และลบล้างการควบคุมหรือผลด้านลบออกจากเป้าหมาย",
		zawakeEffectDesc_kr = "블리세이가 치유의 빛의 공을 던져 블리세이의 HP 한도 30%+$(skillLevel*4*24)$ 만큼 아군을 치유하고 대상의 제어 또는 부정적인 효과를 해제하며 다른 아군 대상의 블리세이 최대 HP의 20%에 해당하는 HP를 추가로 치유합니다. HP 비율이 가장 낮습니다.",
		zawakeEffectDesc_th = "Blissey ขว้างลูกบอลแสงแห่งการรักษา และรักษาพันธมิตรด้วยจำนวน HP สูงสุด 30% ของ Blissey+$(skillLevel*4*24)$ ยกเลิกการควบคุมหรือผลด้านลบจากเป้าหมาย และยังรักษา HP เพิ่มเติมซึ่งเท่ากับ 20% ของ HP สูงสุดของ Blissey ของเป้าหมายของพันธมิตรอื่น ด้วยอัตราส่วน HP ต่ำสุด",
		describe_en = "Blissey throws a healing light ball, and healing an ally with the amount of Blissey’s 30% HP limit+$(skillLevel*4*24)$, and dispels a control or negative effect from target.",
		describe_es = "Blissey lanza una bola de luz curativa y cura a un aliado con la cantidad del límite de HP del 30% de Blissey+$(skillLevel*4*24)$, y disipa un control o efecto negativo del objetivo.",
		zawakeSimpleDesc_en = "additionally heals HP that equals to 20% of Blissey's max HP of another ally with the lowest HP ratio",
		describe_vn = "Blissey lança uma bola de luz curativa e cura um aliado com a quantidade do limite de 30% de HP de Blissey + $(skillLevel*4*24)$ e dissipa um controle ou efeito negativo do alvo.",
		zawakeEffectDesc_en = "Blissey throws a healing light ball, and healing an ally with the amount of Blissey’s 30% HP limit+$(skillLevel*4*24)$, dispels a control or negative effect from target, and additionally heals HP that equals to 20% of Blissey's max HP of another ally's target with the lowest HP ratio",
		zawakeSimpleDesc_vn = "adicionalmente cura HP que equivale a 20% do HP máximo de Blissey de outro aliado com a proporção de HP mais baixa",
		zawakeSimpleDesc_id = "tambahan menyembuhkan HP setara dengan 20% dari max HP Blissey sekutu lain dengan rasio HP terendah",
		zawakeSimpleDesc_es = "Además, cura HP que equivale al 20% del HP máximo de Blissey de otro aliado con la proporción de HP más baja.",
		describe_id = "Blissey melemparkan bola cahaya penyembuh, dan menyembuhkan sekutu dengan jumlah batas HP Blissey 30%+$(skillLevel*4*24)$, dan menghilangkan kontrol atau efek negatif dari target.",
		zawakeSimpleDesc_kr = "HP 비율이 가장 낮은 다른 아군의 블리시 최대 HP의 20%만큼 HP를 추가로 치료합니다.",
		zawakeEffectDesc_id = "Blissey melempar bola lampu penyembuh, dan menyembuhkan sekutu dengan jumlah 30% batas HP Blissey+$(skillLevel*4*24)$, menghilangkan kontrol atau efek negatif dari target, dan juga menyembuhkan HP yang setara dengan 20% HP maksimal Blissey pada target sekutu lain dengan rasio HP terendah",
		describe_kr = "블리시는 치유의 빛의 공을 던져 블리시의 HP 한도 30%+$(skillLevel*4*24)$만큼 아군을 치유하고 대상의 제어 또는 부정적인 효과를 해제합니다.",
		zawakeSimpleDesc_th = "ฮีล HP เพิ่มเติมซึ่งเท่ากับ 20% ของ HP สูงสุดของ Blissey ของพันธมิตรอื่นที่มีอัตราส่วน HP ต่ำที่สุด",
