	[5033] = {
		describe_th = "บลิสซีย์กลายเป็นนางฟ้าด้วยความเมตตา รักษาทั้งศัตรูและพันธมิตรด้วยจำนวน HP สูงสุด 50% ของบลิสซีย์+$(skillLevel*4*60)$ ผลการรักษาของโปเกมอนศัตรูลดลง 50% หลังจากได้รับอิทธิพลจากความสุข เอฟเฟกต์การรักษาของศัตรูลดลง 30% เป็นเวลา 2 รอบ",
		zawakeEffectDesc_vn = "Blissey se transforma em Anjo com coração misericordioso, cura todos os inimigos e aliados com a quantidade do limite de 50% de HP de Blissey + $(skillLevel*4*60)$. O efeito de cura dos Pokémons inimigos é reduzido em 50%. Após ser influenciado por Happiny, o efeito de cura dos inimigos foi reduzido em 30% por 2 rodadas. Para alvos cuja proporção de HP é inferior a 50%, o efeito de cura aumenta em 20%.",
		simDesc_es = "Blissey se convierte en Ángel con un corazón misericordioso, cura a todos los enemigos y aliados, el efecto curativo de los Pokémon enemigos se reduce en un 50%.",
		describe_es = "Blissey se convierte en Ángel con un corazón misericordioso, cura a todos los enemigos y aliados con la cantidad del límite de HP del 50% de Blissey+$(skillLevel*4*60)$. El efecto curativo de los Pokémon enemigos se reduce en un 50%. Después de ser influenciado por Happiny, el efecto curativo de los enemigos se redujo en un 30 % durante 2 rondas.",
		zawakeEffectDesc_th = "บลิสซีย์กลายเป็นนางฟ้าด้วยความเมตตา รักษาทั้งศัตรูและพันธมิตรด้วยจำนวน HP สูงสุด 50% ของบลิสซีย์+$(skillLevel*4*60)$ ผลการรักษาของโปเกมอนศัตรูลดลง 50% หลังจากได้รับอิทธิพลจากความสุข เอฟเฟกต์การรักษาของศัตรูลดลง 30% เป็นเวลา 2 รอบ สำหรับเป้าหมายที่มีอัตราส่วน HP ต่ำกว่า 50% ผลการรักษาจะเพิ่มขึ้น 20%",
		starEffectDesc_id = "Efek Tambahan: dan menghilangkan semua efek negatif dan kontrol pada target dengan persentase HP terendah. Target yang dipengaruhi oleh kecintaan Happiny, P.&Sp.ATK berkurang 20% ​​selama 2 ronde",
		starEffectDesc_es = "Efecto adicional: y disipa todos los efectos negativos y de control en el objetivo con el porcentaje de HP más bajo. Los objetivos influenciados por el amor de Happiny, P.&Sp.ATK se reducen en un 20 % durante 2 rondas.",
		zawakeSimpleDesc_en = "For targets whose HP ratio is lower than 50%, the healing effect is increased by 20%",
		describe_vn = "Blissey se transforma em Anjo com coração misericordioso, cura todos os inimigos e aliados com a quantidade do limite de 50% de HP de Blissey + $(skillLevel*4*60)$. O efeito de cura dos Pokémons inimigos é reduzido em 50%. Após ser influenciado por Happiny, efeito de cura dos inimigos reduzido em 30% por 2 rodadas",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: และลบล้างเอฟเฟกต์ด้านลบและการควบคุมทั้งหมดบนเป้าหมายที่มีเปอร์เซ็นต์ HP ต่ำที่สุด เป้าหมายที่ได้รับอิทธิพลจากความรักของ Happiny, P.&Sp.ATK ลดลง 20% เป็นเวลา 2 รอบ",
		starEffectDesc_vn = "Efeito Adicional: e dissipa todos os efeitos negativos e de controle no alvo com a menor porcentagem de HP. Alvos influenciados pelo amor de Happiny, P.&Sp.ATK são reduzidos em 20% por 2 rodadas",
		zawakeEffectDesc_kr = "블리시는 자비로운 마음으로 천사로 변신하고, 블리시의 HP 한도 50%+$(skillLevel*4*60)$만큼 적군과 아군 모두를 치유합니다. 적 포켓몬의 치유 효과가 50% 감소합니다. 행복의 영향을 받은 후 적의 치유 효과가 2라운드 동안 30% 감소합니다. HP 비율이 50% 미만인 대상의 경우 회복 효과가 20% 증가합니다.",
		describe_en = "Blissey turn into Angel with mercy heart, heals all both the enemy and allies with the amount of Blissey’s 50% HP limit+$(skillLevel*4*60)$. Healing effect of the enemy Pokémons reduces by 50%. After being influenced by Happiny, healing effect of enemies reduced by 30% for 2 rounds",
		zawakeEffectDesc_id = "Blissey berubah menjadi Malaikat dengan hati belas kasihan, menyembuhkan semua musuh dan sekutu dengan jumlah batas HP Blissey 50%+$(skillLevel*4*60)$. Efek penyembuhan dari Pokémon musuh berkurang sebesar 50%. Setelah terkena Happiny, efek penyembuhan musuh berkurang 30% selama 2 ronde. Untuk target yang rasio HP-nya lebih rendah dari 50%, efek penyembuhan meningkat sebesar 20%",
		describe_id = "Blissey berubah menjadi Malaikat dengan hati belas kasihan, menyembuhkan semua musuh dan sekutu dengan jumlah batas HP Blissey 50%+$(skillLevel*4*60)$. Efek penyembuhan Pokémon musuh berkurang sebesar 50%. Setelah terkena Happiny, efek penyembuhan musuh berkurang 30% selama 2 ronde",
		simDesc_en = "Blissey turn into Angel with mercy heart, heals all both the enemy and allies, healing effect of the enemy Pokémons reduces by 50%",
		simDesc_vn = "Blissey se transforma em Anjo com coração misericordioso, cura todos os inimigos e aliados, o efeito de cura dos Pokémons inimigos é reduzido em 50%",
		describe_kr = "블리시는 자비로운 마음으로 천사로 변신하고, 블리시의 HP 한도 50%+$(skillLevel*4*60)$만큼 적군과 아군 모두를 치유합니다. 적 포켓몬의 치유 효과가 50% 감소합니다. 행복의 영향을 받은 후 적의 치유 효과가 2라운드 동안 30% 감소합니다.",
		simDesc_th = "บลิสซีย์กลายเป็นนางฟ้าด้วยความเมตตา รักษาทั้งศัตรูและพันธมิตรทั้งหมด ผลการรักษาของโปเกมอนศัตรูลดลง 50%",
		zawakeEffectDesc_es = "Blissey se convierte en Ángel con un corazón misericordioso, cura a todos los enemigos y aliados con la cantidad del límite de HP del 50% de Blissey+$(skillLevel*4*60)$. El efecto curativo de los Pokémon enemigos se reduce en un 50%. Después de ser influenciado por Happiny, el efecto curativo de los enemigos se redujo en un 30% durante 2 rondas. Para objetivos cuya proporción de HP es inferior al 50%, el efecto curativo aumenta en un 20%.",
		starEffectDesc_kr = "추가 효과: HP 비율이 가장 낮은 대상에게 걸린 모든 부정적인 효과와 제어 효과를 해제합니다. Happiny, P.&Sp.ATK의 사랑에 영향을 받은 대상은 2라운드 동안 20% 감소합니다.",
		zawakeEffectDesc_en = "Blissey turn into Angel with mercy heart, heals all both the enemy and allies with the amount of Blissey’s 50% HP limit+$(skillLevel*4*60)$. Healing effect of the enemy Pokémons reduces by 50%. After being influenced by Happiny, healing effect of enemies reduced by 30% for 2 rounds. For targets whose HP ratio is lower than 50%, the healing effect is increased by 20%",
		simDesc_kr = "블리시는 자비로운 마음으로 천사로 변신하여 적과 아군 모두를 치유하고 적 포켓몬의 치유 효과를 50% 감소시킵니다.",
		zawakeSimpleDesc_th = "สำหรับเป้าหมายที่มีอัตราส่วน HP ต่ำกว่า 50% ผลการรักษาจะเพิ่มขึ้น 20%",
		zawakeSimpleDesc_kr = "HP 비율이 50% 미만인 대상의 경우 회복 효과가 20% 증가합니다.",
		starEffectDesc_en = "Additional Effect: and dispel all negative and control effects on the target with the lowest HP percentage. Targets influenced by the love of Happiny, P.&Sp.ATK reduce by 20% for 2 rounds",
		zawakeSimpleDesc_vn = "Para alvos cuja proporção de HP é inferior a 50%, o efeito de cura aumenta em 20%.",
		zawakeSimpleDesc_id = "Untuk target yang rasio HP-nya lebih rendah dari 50%, efek penyembuhan meningkat sebesar 20%",
		id = 5033,
		zawakeSimpleDesc_es = "Para objetivos cuya proporción de HP es inferior al 50%, el efecto curativo aumenta en un 20%.",
		simDesc_id = "Blissey berubah menjadi Malaikat dengan hati belas kasihan, menyembuhkan semua musuh dan sekutu, efek penyembuhan Pokémon musuh berkurang 50%"
	},
	[5036] = {
		describe_id = "Di akhir setiap putaran besar, jika Happiny tidak berada dalam efek kontrol, ia akan menetaskan telur untuk dimakan oleh sekutu dengan persentase HP terendah (Menyembuhkan jumlah batas HP Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#) , jika efek penyembuhan meluap, 20% dari jumlah yang meluap akan diubah secara permanen menjadi batas HP (ditumpuk hingga 3 kali)",
		zawakeEffectDesc_vn = "No final de cada grande rodada, se Happiny não estiver em efeito de controle, ele chocará um ovo para um aliado com a menor porcentagem de HP para comer (curando a quantidade de limite de HP de Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP) , e adicionalmente aumenta as seis estatísticas básicas em 5% (até 3 vezes), se o efeito de cura transbordar, 20% da quantidade excedente será permanentemente convertida em limite de HP (acumular até 3 vezes)",
		describe_vn = "No final de cada grande rodada, se Happiny não estiver em efeito de controle, ele chocará um ovo para um aliado com a menor porcentagem de HP para comer (curando a quantidade de Happiny's#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#limite de HP) , se o efeito de cura transbordar, 20% da quantidade excedente será permanentemente convertida em limite de HP (acumular até 3 vezes)",
		starEffectDesc_id = "Efek Tambahan: Heart of Healing: Menghilangkan kontrol atau efek negatif pada sekutu acak di akhir setiap putaran",
		zawakeEffectDesc_th = "เมื่อสิ้นสุดรอบใหญ่แต่ละรอบ หากความสุขไม่อยู่ในเอฟเฟกต์ควบคุม มันจะฟักไข่ให้พันธมิตรที่มีเปอร์เซ็นต์ HP ต่ำที่สุดที่จะกิน (การรักษาจำนวนขีดจำกัด HP ของความสุข#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#จำกัด HP) และเพิ่มสเตตัสพื้นฐานหกเพิ่มเติมอีก 5% (สูงสุด 3 เท่า) หากเอฟเฟกต์การรักษาล้น ​​20% ของจำนวนล้นจะถูกแปลงเป็นขีดจำกัด HP อย่างถาวร (ซ้อนสูงสุด 3 ครั้ง)",
		starEffectDesc_kr = "추가 효과: 치유의 심장: 각 라운드가 끝날 때 무작위 아군에 대한 제어 또는 부정적인 효과를 해제합니다.",
		describe_es = "Al final de cada ronda grande, si Happiny no tiene el efecto de control, incubará un huevo para que lo coma un aliado con el porcentaje de HP más bajo (curando la cantidad de HP de Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#límite de HP) , si el efecto de curación se desborda, el 20% de la cantidad desbordada se convertirá permanentemente en límite de HP (se acumula hasta 3 veces)",
		zawakeSimpleDesc_en = "and additionally increases Basic six stats by 5%(up to 3 times)",
		starEffectDesc_es = "Efecto adicional: Corazón de curación: disipa un control o efecto negativo en un aliado aleatorio al final de cada ronda.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: หัวใจแห่งการรักษา: ยกเลิกการควบคุมหรือเอฟเฟกต์ด้านลบต่อพันธมิตรแบบสุ่มเมื่อสิ้นสุดแต่ละรอบ",
		zawakeEffectDesc_id = "Di akhir setiap putaran besar, jika Happiny tidak berada dalam efek kontrol, ia akan menetaskan telur untuk dimakan oleh sekutu dengan persentase HP terendah (Menyembuhkan jumlah batas HP Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#) , dan tambahan meningkatkan stat Basic six sebesar 5% (hingga 3 kali), jika efek penyembuhan meluap, 20% dari jumlah yang meluap akan diubah secara permanen menjadi batas HP (ditumpuk hingga 3 kali)",
		zawakeEffectDesc_es = "Al final de cada ronda grande, si Happiny no tiene el efecto de control, incubará un huevo para que lo coma un aliado con el porcentaje de HP más bajo (curando la cantidad de HP de Happiny#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#límite de HP) y, además, aumenta las seis estadísticas básicas en un 5% (hasta 3 veces). Si el efecto de curación se desborda, el 20% de la cantidad desbordada se convertirá permanentemente en límite de HP (se acumula hasta 3 veces).",
		describe_en = "At the end of each big round, if Happiny is not in controll effect, it will hatch an egg for an ally with the lowest HP percentage to eat (Healing the amount of Happiny’s#C0x5c9970#$(50+skillLevel*0.4-0.4)$%#C0x5B545B#HP limit), if healing effect  overflows, 20% of the overflow amount will be permanently converted into HP limit (stack up to 3 times)",
