	[5743] = {
		describe_id = "Mega Scizor mengenai target dengan kekuatan yang kuat, dan mengejar dengan kecepatan ekstrim, menyerang satu musuh dengan HP terendah di barisan belakang, menyebabkan#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, mencuri 30% P.ATK target selama 3 ronde. Jika serangan ini tidak membunuh target, masukkan [Stealth] untuk 1 ronde (Efek spesial, tidak dapat dipilih, mengurangi 20% damage yang diterima dari serangan jarak jauh)",
		zawakeEffectDesc_vn = "Mega Scizor atinge o alvo com uma força poderosa e persegue com extrema velocidade, atacando um único inimigo com menor HP na última fileira, distribuindo#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, roubando 30% do P.ATK do alvo por 3 rodadas. Se este ataque não matar o alvo, digite [Stealth] por 1 rodada (efeito especial, não pode ser selecionado, reduz 60% do dano recebido do ataque à distância)",
		describe_vn = "Mega Scizor atinge o alvo com uma força poderosa e persegue com extrema velocidade, atacando um único inimigo com menor HP na última fileira, distribuindo#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, roubando 30% do P.ATK do alvo por 3 rodadas. Se este ataque não matar o alvo, digite [Stealth] por 1 rodada (efeito especial, não pode ser selecionado, reduz 20% do dano recebido do ataque à distância)",
		starEffectDesc_id = "Efek Tambahan: Jika Skill Ultimate tidak membunuh target, Anda dapat melakukan tindakan ekstra dan mengembalikan 40% konsumsi kemarahan",
		zawakeEffectDesc_th = "เมก้า ไซเซอร์ โจมตีเป้าหมายด้วยพลังอันทรงพลัง และไล่ตามด้วยความเร็วสูง โจมตีศัตรูตัวเดียวที่มี HP ต่ำสุดในแถวหลัง สร้างความเสียหาย#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B# ขโมย P.ATK ของเป้าหมาย 30% เป็นเวลา 3 รอบ หากการโจมตีนี้ไม่ฆ่าเป้าหมาย ให้เข้า [Stealth] เป็นเวลา 1 รอบ (เอฟเฟกต์พิเศษไม่สามารถเลือกได้ ลดความเสียหายที่ได้รับจากการโจมตีระยะไกล 60%)",
		starEffectDesc_kr = "추가 효과 : 궁극기가 대상을 죽이지 못할 경우 추가 행동을 할 수 있으며, 소모한 분노의 40%를 되돌려줍니다.",
		describe_es = "Mega Scizor golpea al objetivo con una fuerza poderosa y lo persigue con velocidad extrema, atacando a un solo enemigo con HP más bajo en la última fila, causando#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, robando el 30% del P.ATK del objetivo durante 3 rondas. Si este ataque no mata al objetivo, ingresa [Stealth] durante 1 ronda (Efecto especial, no se puede seleccionar, reduce el 20% del daño recibido del ataque a distancia)",
		zawakeSimpleDesc_en = "reduce 20% of damage taken from range attack\n#F20#\n#F40##C0x5c9970#→reduce 60% of damage taken from range attack#C0x5B545B#",
		starEffectDesc_es = "Efecto adicional: si la habilidad definitiva no mata al objetivo, puedes realizar una acción adicional y devolver el 40 % del consumo de ira.",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: หากทักษะขั้นสูงสุดไม่สังหารเป้าหมาย คุณสามารถดำเนินการพิเศษและรับความโกรธที่ใช้คืน 40%",
		zawakeEffectDesc_id = "Mega Scizor mengenai target dengan kekuatan yang kuat, dan mengejar dengan kecepatan ekstrim, menyerang satu musuh dengan HP terendah di barisan belakang, menyebabkan#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, mencuri 30% P.ATK target selama 3 ronde. Jika serangan ini tidak membunuh target, masukkan [Stealth] untuk 1 ronde (Efek spesial, tidak dapat dipilih, mengurangi 60% damage yang diterima dari serangan jarak jauh)",
		zawakeEffectDesc_es = "Mega Scizor golpea al objetivo con una fuerza poderosa y lo persigue con velocidad extrema, atacando a un solo enemigo con HP más bajo en la última fila, causando#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, robando el 30% del P.ATK del objetivo durante 3 rondas. Si este ataque no mata al objetivo, ingresa [Stealth] durante 1 ronda (Efecto especial, no se puede seleccionar, reduce el 60 % del daño recibido del ataque a distancia)",
		describe_en = "Mega Scizor hits the target with a powerful force, and pursue with extreme speed, attacking single enemy with lowest HP in the back row, dealing#C0xE69900#450% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, stealing 30% of the target’s P.ATK for 3 rounds. If this attack does not kill the target, enter [Stealth] for 1 round (Special effect, cannot be selected, reduce 20% of damage taken from range attack)",
