	[7314] = {
		describe_vn = "Lightning Power: Recupera $(100+skillLevel*1-1)$ pontos de raiva para todos os aliados quando entra no campo de batalha; Pokémons do tipo elétrico recuperam 50% de raiva adicional. Quando Zapdos está presente, Pokémons com [Electrify] tornam-se 12% mais vulneráveis ​​a ataques do tipo Elétrico.",
		describe_kr = "번개의 힘: 전장에 들어올 때 모든 아군의 분노 포인트를 $(100+skillLevel*1-1)$ 회복합니다. 전기타입 포켓몬은 추가로 50%의 분노를 회복합니다. Zapdos가 있으면 [Electrify]을 가진 포켓몬은 전기 유형 공격에 12% 더 취약해집니다.",
		describe_en = "Lightning Power: Recovers $(100+skillLevel*1-1)$ rage points for all allies when it enters the battlefield; electric-type Pokémons recovers an additional 50% rage. When Zapdos is present, Pokémons with [Electrify] become 12% more vulnerable to Electric-type attacks.",
		describe_id = "Kekuatan Petir: Memulihkan $(100+skillLevel*1-1)$ poin kemarahan untuk semua sekutu saat memasuki medan perang; Pokémon tipe listrik memulihkan 50% kemarahan tambahan. Saat Zapdos hadir, Pokémon dengan [Electrify] menjadi 12% lebih rentan terhadap serangan tipe Listrik.",
		id = 7314,
		describe_es = "Lightning Power: Recupera $(100+skillLevel*1-1)$ puntos de ira para todos los aliados cuando entra al campo de batalla; Los Pokémon de tipo eléctrico recuperan un 50% adicional de ira. Cuando Zapdos está presente, los Pokémon con [Electrify] se vuelven un 12% más vulnerables a los ataques de tipo Eléctrico.",
		describe_th = "พลังสายฟ้า: ฟื้นฟูคะแนนความโกรธ $(100+skillLevel*1-1)$ ให้กับพันธมิตรทั้งหมดเมื่อเข้าสู่สนามรบ โปเกมอนประเภทไฟฟ้าจะฟื้นพลังความโกรธเพิ่มอีก 50% เมื่อมี Zapdos โปเกมอนที่มี [Electrify] จะเสี่ยงต่อการโจมตีประเภทไฟฟ้ามากขึ้น 12%"
	},
	[7316] = {
