	[7516] = {
		describe_en = "For every negative effect or status condition on the target, its attack increases #C0x5c9970#$(5+skillLevel*0.05-0.05)$%#C0x5B545B#. If the negative effect or status condition is dragon-type, the damage multiplies up to 40%.",
