	},
	[7531] = {
		zawakeEffectDesc_kr = "Dragonite는 발톱으로 적 한 명을 빠르게 공격하여 처리합니다#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, 대상을 2라운드 동안 20% 취약하게 만들고 자신의 추가 10을 증가시킵니다. 2라운드 동안 P.ATK %",
		zawakeEffectDesc_vn = "Dragonite ataca um único inimigo com garras rapidamente para lidar com#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, tornando o alvo 20% vulnerável por 2 rodadas e aumentando seus próprios 10 extras % P.ATK por 2 rodadas",
