	[10723] = {
		describe_id = "Mega Heracross menabrak satu target musuh dengan tanduknya berturut-turut, lalu jatuh dari langit dan menghantam tanah, mengakibatkan #C0xE69900#190%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 kali, dengan peluang 50% untuk menyerang satu kali tambahan, hingga 3 serangan tambahan. Untuk setiap sekutu tipe Bug atau tipe Pertarungan, peluangnya meningkat sebesar 8%. Jika memiliki 10 lapis [Strength] maka akan menyerang sekali lagi, jika target tidak mati maka akan menjadi [taunted] selama 1 putaran.",
		zawakeEffectDesc_vn = "Mega Heracross atinge um único alvo inimigo com seus chifres seguidos, depois cai do céu e atinge o chão, distribui#C0xE69900#190% P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 vezes, com 75% de chance de atacar uma vez adicional, até 5 ataques adicionais. Para cada aliado do tipo Bug ou Fighting, a chance aumenta em 8%. Se tiver 10 camadas de [Strength], atacará mais uma vez, se o alvo não estiver morto, será [taunted] por 1 rodada.",
		describe_vn = "Mega Heracross atinge um único alvo inimigo com seus chifres seguidos, depois cai do céu e atinge o chão, causando #C0xE69900#190%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 vezes, com 50% de chance de atacar uma vez adicional, até 3 ataques adicionais. Para cada aliado do tipo Bug ou Fighting, a chance aumenta em 8%. Se tiver 10 camadas de [Strength], atacará mais uma vez, se o alvo não estiver morto, será [taunted] por 1 rodada.",
		starEffectDesc_id = "Peluang dasar serangan tambahan meningkat sebesar 15%, dan rasio setiap kerusakan meningkat menjadi 200%",
		zawakeEffectDesc_th = "เมก้า เฮราครอส พุ่งชนศัตรูเป้าหมายเดียวด้วยเขาของมันติดต่อกัน แล้วตกลงมาจากท้องฟ้ากระแทกพื้น สร้างความเสียหาย#C0xE69900#190% P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 ครั้ง โดยมีโอกาส 75% ที่จะโจมตีเพิ่มเติมอีกครั้ง สูงสุด 5 ครั้ง สำหรับพันธมิตรประเภทแมลงหรือประเภทต่อสู้ทุกตัว โอกาสจะเพิ่มขึ้น 8% ถ้ามี [Strength] 10 ชั้น มันจะโจมตีอีกครั้ง ถ้าเป้าหมายยังไม่ตาย ก็จะเป็น [taunted] 1 รอบ",
		starEffectDesc_kr = "기본 추가 공격 확률이 15% 증가하고, 각 데미지 비율이 200%로 증가됩니다.",
		describe_es = "Mega Heracross embiste a un solo objetivo enemigo con sus cuernos en fila, luego cae del cielo y golpea el suelo, inflige #C0xE69900#190%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 veces, con un 50% de probabilidad de atacar una vez adicional, hasta 3 ataques adicionales. Por cada aliado de tipo Insecto o Lucha, la probabilidad aumenta en un 8%. Si tiene 10 capas de [Strength], atacará una vez más, si el objetivo no está muerto, será [taunted] durante 1 ronda.",
		zawakeSimpleDesc_en = "with a 50% chance to attack one additional time, up to 3 additional attacks\n#F20#\n#F40##C0x5c9970#→with a 75% chance to attack one additional time, up to 5 additional attacks",
		starEffectDesc_es = "La probabilidad básica de ataque adicional aumenta en un 15% y la proporción de cada daño aumenta al 200%.",
		starEffectDesc_th = "โอกาสพื้นฐานของการโจมตีเพิ่มเติมเพิ่มขึ้น 15% และอัตราส่วนของความเสียหายแต่ละครั้งเพิ่มขึ้นเป็น 200%",
		zawakeEffectDesc_id = "Mega Heracross menabrak satu target musuh dengan tanduknya berturut-turut, lalu jatuh dari langit dan menghantam tanah, mengakibatkan#C0xE69900#190% P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 kali, dengan peluang 75% untuk menyerang satu kali tambahan, hingga 5 serangan tambahan. Untuk setiap sekutu tipe Bug atau tipe Pertarungan, peluangnya meningkat sebesar 8%. Jika memiliki 10 lapis [Strength] maka akan menyerang sekali lagi, jika target tidak mati maka akan menjadi [taunted] selama 1 putaran.",
		zawakeEffectDesc_es = "Mega Heracross embiste a un solo objetivo enemigo con sus cuernos en fila, luego cae del cielo y golpea el suelo, inflige#C0xE69900#190% P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 veces, con un 75% de probabilidad de atacar una vez adicional, hasta 5 ataques adicionales. Por cada aliado de tipo Insecto o Lucha, la probabilidad aumenta en un 8%. Si tiene 10 capas de [Strength], atacará una vez más, si el objetivo no está muerto, será [taunted] durante 1 ronda.",
		describe_en = "Mega Heracross rams a single enemy target with its horns in a row, then falls from the sky and hits the ground, deals #C0xE69900#190%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 times, with a 50% chance to attack one additional time, up to 3 additional attacks. For every Bug-type or Fighting-type ally, chance is increased by 8%. If it has 10 layers of [Strength], it will attack once more, if the target is not dead, it will be [taunted] for 1 round.",
		zawakeSimpleDesc_th = "มีโอกาส 50% ที่จะโจมตีเพิ่มเติม 1 ครั้ง สูงสุด 3 การโจมตี\n#F20#\n#F40##C0x5c9970#→มีโอกาส 75% ที่จะโจมตีเพิ่มเติม 1 ครั้ง สูงสุด 5 การโจมตี",
		zawakeEffectDesc_kr = "메가 헤라크로스는 적 한 마리를 뿔로 일렬로 공격한 후 하늘에서 떨어져 땅에 부딪혀 거래를 합니다#C0xE69900#190% P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 75% 확률로 1회 추가 공격, 최대 5회 추가 공격. 벌레형, 격투형 아군 하나당 확률이 8%씩 증가합니다. [Strength]의 10겹이 있으면 한 번 더 공격하고, 대상이 죽지 않으면 1라운드 동안 [taunted]가 됩니다.",
		zawakeSimpleDesc_kr = "50% 확률로 1회 추가 공격, 최대 3회 추가 공격\n#F20#\n#F40##C0x5c9970#→75% 확률로 1회 추가 공격, 최대 5회 추가 공격",
		zawakeEffectDesc_en = "Mega Heracross rams a single enemy target with its horns in a row, then falls from the sky and hits the ground, deals#C0xE69900#190% P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 times, with a 75% chance to attack one additional time, up to 5 additional attacks. For every Bug-type or Fighting-type ally, chance is increased by 8%. If it has 10 layers of [Strength], it will attack once more, if the target is not dead, it will be [taunted] for 1 round.",
		describe_kr = "메가 헤라크로스는 적 한 마리를 뿔로 일렬로 공격한 후 하늘에서 떨어져 땅에 부딪혀 #C0xE69900#190%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3을 처리합니다. 50% 확률로 1회 추가 공격, 최대 3회 추가 공격. 벌레형, 격투형 아군 하나당 확률이 8%씩 증가합니다. [Strength]의 10겹이 있으면 한 번 더 공격하고, 대상이 죽지 않으면 1라운드 동안 [taunted]가 됩니다.",
		zawakeSimpleDesc_vn = "com 50% de chance de atacar uma vez adicional, até 3 ataques adicionais\n#F20#\n#F40##C0x5c9970#→com 75% de chance de atacar uma vez adicional, até 5 ataques adicionais",
		zawakeSimpleDesc_id = "dengan peluang 50% untuk menyerang satu kali tambahan, hingga 3 serangan tambahan\n#F20#\n#F40##C0x5c9970#→dengan peluang 75% untuk menyerang satu kali tambahan, hingga 5 serangan tambahan",
		starEffectDesc_vn = "A chance básica de ataque adicional aumenta em 15% e a proporção de cada dano aumenta para 200%",
		zawakeSimpleDesc_es = "con un 50% de probabilidad de atacar una vez adicional, hasta 3 ataques adicionales\n#F20#\n#F40##C0x5c9970#→con un 75% de probabilidad de atacar una vez adicional, hasta 5 ataques adicionales",
		describe_th = "เมก้า เฮราครอส พุ่งชนศัตรูเป้าหมายเดียวด้วยเขาของมันติดต่อกัน แล้วตกลงมาจากท้องฟ้ากระแทกพื้น สร้างความเสียหาย #C0xE69900#190%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# 3 ครั้ง โดยมีโอกาส 50% ที่จะโจมตีเพิ่มเติมอีกครั้ง สูงสุด 3 ครั้ง สำหรับพันธมิตรประเภทแมลงหรือประเภทต่อสู้ทุกตัว โอกาสจะเพิ่มขึ้น 8% ถ้ามี [Strength] 10 ชั้น มันจะโจมตีอีกครั้ง ถ้าเป้าหมายยังไม่ตาย ก็จะเป็น [taunted] 1 รอบ",
		starEffectDesc_en = "The basic chance of additional attack is increased by 15%, and the ratio of each damage is increased to 200%",
		id = 10723
	},
	[10726] = {
		describe_id = "Setelah setiap 3 serangan (yang diakumulasikan dalam seluruh pertempuran), serangan berikutnya menghasilkan kerusakan sebenarnya sebesar #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK pada target; \nSaat memberikan damage, dapatkan lapisan [Strength](Strength: buff, tidak bisa dihilangkan, meningkatkan P.ATK sebesar 3%, hingga 10 tumpukan, saat menerima damage fatal, 6 tumpukan Strength dapat digunakan untuk mempertahankan 1 HP), sesuai dengan jumlah Pokémon tipe Bug dan tipe Fighting di lapangan, dapatkan tumpukan [Strength] yang sesuai di awal pertempuran",
		zawakeEffectDesc_vn = "Após cada 2 ataques (acumulados em toda a batalha), o próximo ataque vem com dano verdadeiro de #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATKno alvo; \nAo causar dano, ganhe uma camada de [Strength](Força: buff, não pode ser dissipado, aumenta P.ATK em 3%, até 10 pilhas, ao receber dano fatal, 6 pilhas de Força podem ser consumidas para reter 1 HP), de acordo com o número de Pokémon do tipo Bug e do tipo Fighting no campo, obtenha as pilhas correspondentes de [Strength] no início da batalha",
		describe_vn = "Após cada 3 ataques (acumulados em toda a batalha), o próximo ataque vem com dano verdadeiro de #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK no alvo; \nAo causar dano, ganhe uma camada de [Strength](Força: buff, não pode ser dissipado, aumenta P.ATK em 3%, até 10 pilhas, ao receber dano fatal, 6 pilhas de Força podem ser consumidas para reter 1 HP), de acordo com o número de Pokémon do tipo Bug e do tipo Fighting no campo, obtenha as pilhas correspondentes de [Strength] no início da batalha",
		starEffectDesc_id = "Efek tambahan: Setelah setiap 3 serangan (diakumulasikan dalam seluruh pertempuran), serangan berikutnya memiliki tingkat Pencurian Kesehatan sebesar 40%.",
		zawakeEffectDesc_th = "หลังจากการโจมตีทุกๆ 2 ครั้ง (สะสมในการต่อสู้ทั้งหมด) การโจมตีครั้งต่อไปจะมาพร้อมกับความเสียหายจริงของตัวเองที่#C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATKบนเป้าหมาย \nเมื่อสร้างความเสียหาย ได้รับชั้น [Strength](ความแข็งแกร่ง: บัฟ ไม่สามารถลบล้างได้ เพิ่ม P.ATK 3% สูงสุด 10 สแต็ค เมื่อได้รับความเสียหายร้ายแรง สามารถใช้ Strength 6 สแต็ค เพื่อคงไว้ 1 HP) ตามจำนวนโปเกมอนประเภท Bug และประเภทต่อสู้บนสนาม จะได้รับสแต็คที่สอดคล้องกัน [Strength] เมื่อเริ่มการต่อสู้",
		starEffectDesc_kr = "추가 효과: 매 3번의 공격(전체 전투에서 누적) 후 다음 공격은 40%의 체력 강탈 비율을 갖습니다.",
		describe_es = "Después de cada 3 ataques (acumulados en toda la batalla), el siguiente ataque viene con un daño verdadero propio de #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK en el objetivo; \nAl infligir daño, gana una capa de [Strength](Fuerza: mejora, no se puede disipar, aumenta P.ATK en un 3%, hasta 10 acumulaciones, al recibir daño fatal, se pueden consumir 6 acumulaciones de Fuerza para retener 1 HP ), según la cantidad de Pokémon de tipo Bicho y de tipo Lucha en el campo, obtén las acumulaciones correspondientes de [Strength] al comienzo de la batalla.",
		zawakeSimpleDesc_en = "After every 3 attacks (cumulated in the whole battle)\n#F20#\n#F40##C0x5c9970#→After every 2 attacks (cumulated in the whole battle)",
		starEffectDesc_es = "Efecto adicional: después de cada 3 ataques (acumulados en toda la batalla), el siguiente ataque conlleva una tasa de robo de salud del 40 %.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: หลังจากการโจมตีทุก ๆ 3 ครั้ง (สะสมในการต่อสู้ทั้งหมด) การโจมตีครั้งถัดไปจะมีอัตราการขโมยพลังชีวิต 40%",
		zawakeEffectDesc_id = "Setelah setiap 2 serangan (diakumulasikan dalam seluruh pertempuran), serangan berikutnya menghasilkan kerusakan sebenarnya sebesar#C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATKon target; \nSaat memberikan damage, dapatkan lapisan [Strength](Strength: buff, tidak bisa dihilangkan, meningkatkan P.ATK sebesar 3%, hingga 10 tumpukan, saat menerima damage fatal, 6 tumpukan Strength dapat digunakan untuk mempertahankan 1 HP), sesuai dengan jumlah Pokémon tipe Bug dan tipe Fighting di lapangan, dapatkan tumpukan [Strength] yang sesuai di awal pertempuran",
		zawakeEffectDesc_es = "Después de cada 2 ataques (acumulados en toda la batalla), el siguiente ataque viene con un daño verdadero propio de#C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK en el objetivo; \nAl infligir daño, gana una capa de [Strength](Fuerza: mejora, no se puede disipar, aumenta P.ATK en un 3%, hasta 10 acumulaciones, al recibir daño fatal, se pueden consumir 6 acumulaciones de Fuerza para retener 1 HP ), según la cantidad de Pokémon de tipo Bicho y de tipo Lucha en el campo, obtén las acumulaciones correspondientes de [Strength] al comienzo de la batalla.",
		describe_en = "After every 3 attacks (cumulated in the whole battle), the next attack comes with own true damage of #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK on the target; \nWhen dealing damage, gain a layer of [Strength](Strength: buff, cannot be dispelled, increases P.ATK by 3%, up to 10 stacks, when taking fatal damage, 6 stacks of Strength can be consumed to retain 1 HP), according to the number of Bug-type and Fighting-type Pokémon on the field, get the corresponding stacks of [Strength] at the beginning of the battle",
		zawakeSimpleDesc_th = "หลังจากการโจมตีทุกๆ 3 ครั้ง (สะสมในการต่อสู้ทั้งหมด)\n#F20#\n#F40##C0x5c9970#→หลังจากการโจมตีทุกๆ 2 ครั้ง (สะสมในการต่อสู้ทั้งหมด)",
		zawakeEffectDesc_kr = "After every 2 attacks (cumulated in the whole battle), the next attack comes with own true damage of#C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATKon the target; \nWhen dealing damage, gain a layer of [Strength](Strength: buff, cannot be dispelled, increases P.ATK by 3%, up to 10 stacks, when taking fatal damage, 6 stacks of Strength can be consumed to retain 1 HP), according to the number of Bug-type and Fighting-type Pokémon on the field, get the corresponding stacks of [Strength] at the beginning of the battle",
		zawakeSimpleDesc_kr = "3회 공격 후(전투 전체 누적)\n#F20#\n#F40##C0x5c9970#→2회 공격 후(전체 전투 누적)",
		zawakeEffectDesc_en = "After every 2 attacks (cumulated in the whole battle), the next attack comes with own true damage of#C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATKon the target; \nWhen dealing damage, gain a layer of [Strength](Strength: buff, cannot be dispelled, increases P.ATK by 3%, up to 10 stacks, when taking fatal damage, 6 stacks of Strength can be consumed to retain 1 HP), according to the number of Bug-type and Fighting-type Pokémon on the field, get the corresponding stacks of [Strength] at the beginning of the battle",
		describe_kr = "After every 3 attacks (cumulated in the whole battle), the next attack comes with own true damage of #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK on the target; \nWhen dealing damage, gain a layer of [Strength](Strength: buff, cannot be dispelled, increases P.ATK by 3%, up to 10 stacks, when taking fatal damage, 6 stacks of Strength can be consumed to retain 1 HP), according to the number of Bug-type and Fighting-type Pokémon on the field, get the corresponding stacks of [Strength] at the beginning of the battle",
		zawakeSimpleDesc_vn = "Após cada 3 ataques (acumulados em toda a batalha)\n#F20#\n#F40##C0x5c9970#→Após cada 2 ataques (acumulados em toda a batalha)",
		zawakeSimpleDesc_id = "Setelah setiap 3 serangan (diakumulasikan di seluruh pertempuran)\n#F20#\n#F40##C0x5c9970#→Setelah setiap 2 serangan (diakumulasikan di seluruh pertempuran)",
		starEffectDesc_vn = "Efeito adicional: Após cada 3 ataques (acumulados em toda a batalha), o próximo ataque acarreta uma taxa de roubo de saúde de 40%.",
		zawakeSimpleDesc_es = "Después de cada 3 ataques (acumulados en toda la batalla)\n#F20#\n#F40##C0x5c9970#→Después de cada 2 ataques (acumulados en toda la batalla)",
		describe_th = "หลังจากการโจมตีทุกๆ 3 ครั้ง (สะสมในการต่อสู้ทั้งหมด) การโจมตีครั้งต่อไปจะมาพร้อมกับความเสียหายจริงของตัวเอง #C0x5c9970#$(50+skillLevel*0.2-0.2)$%#C0x5B545B#P.ATK บนเป้าหมาย; \nเมื่อสร้างความเสียหาย ได้รับชั้น [Strength](ความแข็งแกร่ง: บัฟ ไม่สามารถลบล้างได้ เพิ่ม P.ATK 3% สูงสุด 10 สแต็ค เมื่อได้รับความเสียหายร้ายแรง สามารถใช้ Strength 6 สแต็ค เพื่อคงไว้ 1 HP) ตามจำนวนโปเกมอนประเภท Bug และประเภทต่อสู้บนสนาม จะได้รับสแต็คที่สอดคล้องกัน [Strength] เมื่อเริ่มการต่อสู้",
		starEffectDesc_en = "Additional effect: After every 3 attacks (cumulated in the whole battle), the next attack carries a 40% Health Steal rate",
		id = 10726
	},
	[10811] = {
		zawakeEffectDesc_kr = "단단한 발톱으로 적 한 명을 베어 상대하기#C0xE69900#90%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, 2라운드 동안 자신의 P.ATK가 25% 증가합니다.",
		zawakeEffectDesc_vn = "Corte um único inimigo com garras duras para lidar com#C0xE69900#90%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B# e aumente seus próprios 25% de P.ATK por 2 rodadas",
