	[11733] = {
		describe_id = "Mega Houndoom datang dari neraka, memuntahkan api neraka yang membara untuk menyerang semua musuh, memberikan #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# SP.DMG#C0x5B545B#, mencuri 20% P.DEF dan SP. DEF dari semua musuh dengan perbandingan 1:2 dan didistribusikan secara merata ke P.ATK&SP.ATK semua sekutu selama 2 ronde; meningkatkan Pencurian Kesehatan sekutu Tipe Gelap sebesar 30% selama 2 putaran. Memberi semua sekutu [Solar Power Plus] selama 2 ronde (Efek spesial: Mengganti Tenaga Surya, memberikan 30% bonus DMG Tipe Api, kehilangan 10% HP saat ini sebelum setiap ronde, dan memperoleh 24% bonus DMG secara permanen)",
		zawakeEffectDesc_vn = "Mega Houndoom vem do inferno, cospe fogo do inferno escaldante para atacar todos os inimigos, distribuindo #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# SP.DMG#C0x5B545B#, rouba 20% P.DEF e SP. DEF de todos os inimigos na proporção de 1:2 e distribuída uniformemente para P.ATK e SP.ATK de todos os aliados por 2 rodadas; aumenta o roubo de saúde dos aliados do tipo Dark em 30% por 2 rodadas. Concede [Solar Power Plus] a todos os aliados por 2 rodadas (efeito especial: substitui a energia solar, aumenta 30% de bônus de DMG do tipo fogo e 20% de redução de DMG, perde 10% do HP atual antes de cada rodada e ganha permanentemente 24% de bônus de DMG)",
		describe_vn = "Mega Houndoom vem do inferno, cospe fogo do inferno escaldante para atacar todos os inimigos, distribuindo #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# SP.DMG#C0x5B545B#, rouba 20% P.DEF e SP. DEF de todos os inimigos na proporção de 1:2 e distribuída uniformemente para P.ATK e SP.ATK de todos os aliados por 2 rodadas; aumenta o roubo de saúde dos aliados do tipo Dark em 30% por 2 rodadas. Concede [Solar Power Plus] a todos os aliados por 2 rodadas (Efeito especial: Substitui Energia Solar, concede 30% de bônus de DMG do Tipo Fogo, perde 10% do HP atual antes de cada rodada e ganha permanentemente 24% de bônus de DMG)",
		starEffectDesc_id = "Efek tambahan: Menyerap 30% SP.DEF & P.DEF dari musuh di barisan depan",
		zawakeEffectDesc_th = "เมก้า ฮาวดูมมาจากนรก พ่นไฟนรกที่แผดเผาโจมตีศัตรูทั้งหมด สร้าง #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# SP.DMG#C0x5B545B# ขโมย P.DEF และ SP 20% DEF จากศัตรูทั้งหมดตามสัดส่วน 1:2 และกระจายไปยัง P.ATK&SP.ATK ของพันธมิตรทั้งหมดเท่าๆ กันเป็นเวลา 2 รอบ เพิ่มการขโมยสุขภาพของพันธมิตรประเภทมืด 30% เป็นเวลา 2 รอบ ให้พันธมิตรทั้งหมด [Solar Power Plus] เป็นเวลา 2 รอบ (เอฟเฟกต์พิเศษ: แทนที่พลังงานแสงอาทิตย์, เพิ่มโบนัส DMG ประเภทไฟ 30% และลด DMG 20%, สูญเสีย HP ปัจจุบัน 10% ก่อนแต่ละรอบ และได้รับโบนัส DMG 24% อย่างถาวร)",
		starEffectDesc_kr = "추가 효과 : 전열 적의 SP.DEF, P.DEF 30% 흡수",
		describe_es = "Mega Houndoom viene del infierno, arroja fuego abrasador del infierno para atacar a todos los enemigos, causando #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# SP.DMG#C0x5B545B#, roba 20% P.DEF y SP. DEF de todos los enemigos en proporción de 1:2 y se distribuye uniformemente a P.ATK&SP.ATK de todos los aliados durante 2 rondas; aumenta el robo de salud de los aliados de tipo oscuro en un 30 % durante 2 rondas. Otorga a todos los aliados [Solar Power Plus] durante 2 rondas (Efecto especial: reemplaza la energía solar, otorga una bonificación de daño de tipo fuego del 30 %, pierde un 10 % de HP actual antes de cada ronda y gana permanentemente una bonificación de daño del 24 %)",
		zawakeSimpleDesc_en = "Solar Power Plus grants 20% DMG Reduction",
		starEffectDesc_es = "Efecto adicional: Absorbe 30% SP.DEF y P.DEF de los enemigos de la primera fila",
