	[12821] = {
		zawakeEffectDesc_es = "#C0xC0C0C0#Flash~~#C0x5B545B#\n#F10#\n#F40#Celebi usa el poder del tiempo y el espacio para flashear y atacar a un solo objetivo enemigo#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$of#C0xF13B54#SP.DMG#C0x5B545B#.Celebi toma su propio poder en el futuro y aumenta sus seis estadísticas en un 15% (se acumula hasta 2 veces) durante 2 rondas. Después de 2 rondas, el valor se reducirá (se puede disipar)",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Flash~~#C0x5B545B#\n#F10#\n#F40#Celebi usa o poder do tempo e do espaço para piscar para atacar um único alvo inimigo#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$of#C0xF13B54#SP.DMG#C0x5B545B#.Celebi pega seu próprio poder no futuro e aumenta suas seis estatísticas em 15% (acumular até 2 vezes) por 2 rodadas. Após 2 rodadas, o valor será reduzido (pode ser dissipado)",
		describe_th = "#C0xC0C0C0#แฟลช~~#C0x5B545B#\n#F10#\n#F40#เซเลบีใช้พลังของเวลาและพื้นที่เพื่อโจมตีศัตรูเป้าหมายเดียว จัดการ#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ ของ#C0xF13B54#SP.DMG#C0x5B545B#. เซเลบีคว้าพลังของตัวเองในอนาคต และเพิ่มค่าสถานะทั้งหกของมัน 10% (ซ้อนกันได้สูงสุด 2 ครั้ง) เป็นเวลา 2 รอบ หลังจาก 2 รอบ ค่าจะลดลง (สามารถลบล้างได้)",
		zawakeEffectDesc_kr = "#C0xC0C0C0#플래시~~#C0x5B545B#\n#F10#\n#F40#세레비는 시간과 공간의 힘을 이용해 섬광을 사용하여 단일 적 대상 딜을 공격합니다#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$of#C0xF13B54#SP.DMG#C0x5B545B#.셀레비는 미래에 자신의 힘을 붙잡고 2라운드 동안 6개의 능력치를 15%(최대 2회 중첩) 증가시킵니다. 2라운드 이후에는 수치가 감소합니다.(해제 가능)",
		zawakeEffectDesc_th = "#C0xC0C0C0#แฟลช~~#C0x5B545B#\n#F10#\n#F40#เซเลบีใช้พลังของเวลาและพื้นที่เพื่อแฟลชโจมตีเป้าหมายศัตรูตัวเดียว#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$of#C0xF13B54#SP.DMG#C0x5B545B#.เซเลบีคว้าพลังของตัวเองในอนาคต และเพิ่มค่าสถานะทั้ง 6 อัน 15% (ซ้อนทับได้สูงสุด 2 ครั้ง) เป็นเวลา 2 รอบ หลังจาก 2 รอบ ค่าจะลดลง(สามารถลบล้างได้)",
		describe_en = "#C0xC0C0C0#Flash~~#C0x5B545B#\n#F10#\n#F40#Celebi uses the power of time and space to flash to attack a single enemy targetdeal#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$of#C0xF13B54#SP.DMG#C0x5B545B#. Celebi grabs its own power in the future and increases its six stats by 10%(stack up to 2 time) for 2 rounds. After 2 round,the value will be reduced(can be dispelled)",
