	[13923] = {
		describe_th = "เคอร์เลียใช้พลังจิตเพื่อสร้างเวทีให้ตัวเองเต้นอย่างมีความสุข และใช้ลูกบอลพลังจิตเพื่อจบการแสดง สร้าง#C0x3D8A99#200% SP.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#SP.DMG#C0x5B545B# ทำให้เป้าหมายไม่สามารถมีเอฟเฟกต์บัฟใด ๆ เป็นเวลา 2 รอบ นอกจากนี้ยังมีโอกาส 25% ที่จะสร้าง [Infatuation] ให้กับศัตรูแนวหลังเป็นเวลา 1 รอบ",
		zawakeEffectDesc_vn = "Kirlia usa seu poder psíquico para criar um palco para dançar alegremente, e usa uma bola psíquica para encerrar a apresentação, distribuindo#C0x3D8A99#200% SP.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#SP.DMG#C0x5B545B# , impedindo o alvo de ter qualquer efeito de buff por 2 rodadas. Há também 40% de chance de infligir [Fascinate] aos inimigos da retaguarda por 1 rodada.",
		simDesc_es = "Kirlia usa su poder psíquico para crear un escenario para bailar felizmente y usa una bola psíquica para finalizar la actuación. Hace que la línea de fondo enemiga no pueda obtener ningún beneficio, con posibilidades de encantar a los objetivos.",
		describe_es = "Kirlia usa su poder psíquico para crear un escenario para bailar felizmente y usa una bola psíquica para finalizar la actuación, causando#C0x3D8A99#200% SP.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#SP.DMG#C0x5B545B# , impidiendo que el objetivo tenga cualquier efecto de mejora durante 2 rondas. También hay un 25 % de posibilidades de infligir [Infatuation] a los enemigos de la línea de fondo durante 1 ronda.",
		zawakeEffectDesc_th = "เคอร์เลียใช้พลังจิตเพื่อสร้างเวทีให้ตัวเองเต้นอย่างมีความสุข และใช้ลูกบอลพลังจิตเพื่อจบการแสดง สร้าง#C0x3D8A99#200% SP.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#SP.DMG#C0x5B545B# ทำให้เป้าหมายไม่สามารถมีเอฟเฟกต์บัฟใด ๆ เป็นเวลา 2 รอบ นอกจากนี้ยังมีโอกาส 40% ที่จะสร้าง [Fascinate] ให้กับศัตรูแนวหลังเป็นเวลา 1 รอบ",
		starEffectDesc_id = "Peningkatan efek: [Infatuation] tingkat keterampilan Ultimate meningkat 15%",
		starEffectDesc_es = "Aumento del efecto: [Infatuation] la tasa de habilidad definitiva aumenta un 15 %",
		zawakeSimpleDesc_en = "There is also a 25% chance of inflicting [Fascinate] to the back line enemies for 1 round.\n#F20#\n#F40##C0x5c9970#→There is also a 40% chance of inflicting [Fascinate] to the back line enemies for 1 round.",
		describe_vn = "Kirlia usa seu poder psíquico para criar um palco para dançar alegremente, e usa uma bola psíquica para encerrar a apresentação, distribuindo#C0x3D8A99#200% SP.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#SP.DMG#C0x5B545B# , impedindo o alvo de ter qualquer efeito de buff por 2 rodadas. Há também 25% de chance de infligir [Infatuation] aos inimigos da linha de trás por 1 rodada.",
		starEffectDesc_th = "เพิ่มเอฟเฟกต์: [Infatuation] อัตราทักษะขั้นสูงสุดเพิ่มขึ้น 15%",
		starEffectDesc_vn = "Aumento de efeito: [Infatuation] taxa de habilidade Ultimate aumenta 15%",
		zawakeEffectDesc_kr = "킬리아는 자신의 초능력을 이용해 스스로 무대를 만들어 즐겁게 춤을 추고, 초능력구를 이용해 퍼포먼스를 마무리하며 #C0x3D8A99#200% SP.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#SP.DMG#C0x5B545B# , 대상이 2라운드 동안 버프 효과를 받지 못하게 합니다. 또한 1라운드 동안 후방 적들에게 [Fascinate]를 줄 확률도 40%입니다.",
