	[18411] = {
		zawakeEffectDesc_kr = "앱솔이 적 한 명을 발톱으로 할퀴어 처리#C0xE69900#90%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#대상의 현재 HP의 12%를 훔치거나(또는 현재 자신의 HP 12%를 빼앗음) 던전 BOSS를 상대할 때 True DMG입니다)",
		zawakeEffectDesc_vn = "Absol arranha um único inimigo com garras para lidar com#C0xE69900#90%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#e roubar 12% do HP atual do alvo (ou possui 12% de HP atual ao enfrentar o Dungeon BOSS; é True DMG)",
