	[18413] = {
		describe_th = "Absol รู้สึกถึงหายนะ กระโดดขึ้นไปในอากาศ และโจมตีศัตรูเป็นแถว สร้างความเสียหาย (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B# หากเป้าหมายได้รับผลกระทบจาก [Disaster] จะสร้างความเสียหายเพิ่มเติม 40% และใช้ [Curse Mark] เป็นเวลา 3 รอบ (เครื่องหมายคำสาป: เอฟเฟกต์เชิงลบ ทำให้เป้าหมายสูญเสีย HP 15% ก่อนแต่ละรอบใหญ่ ซึ่งถือเป็นความเสียหายจริง หากเป้าหมายเป็นบอสดันเจี้ยนจะคำนวณตาม HP ที่เสียไปเอง)",
		zawakeEffectDesc_vn = "Absol sente o desastre, salta no ar e ataca os inimigos em coluna, infligindo (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Se o alvo estiver sendo afetado por [Disaster], inflige 40% de DMG extra e aplica [Curse Mark] por 3 rodadas (Curse Mark: Efeito negativo, faz com que o alvo perca 25% de HP antes de cada grande rodada, o que é considerado True DMG . Se o alvo for um chefe de masmorra, calcula com o próprio HP perdido)",
		simDesc_es = "Absol siente la llegada del desastre y salta alto en el aire antes de atacar a los enemigos seguidos, e inflige daño adicional a los objetivos con efecto Desastre mientras les agrega Cruse.",
		describe_es = "Absol siente el desastre, salta en el aire y ataca a los enemigos en columna, infligiendo (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Si el objetivo está siendo afectado por [Disaster], inflige un 40 % de DAÑO adicional y aplica [Curse Mark] durante 3 rondas (Marca de maldición: efecto negativo, hace que el objetivo pierda un 15 % de HP antes de cada ronda grande, lo que se toma como DAÑO verdadero (Si el objetivo es un jefe de mazmorra, se calcula con el propio HP perdido).",
		zawakeEffectDesc_th = "Absol รู้สึกถึงหายนะ กระโดดขึ้นไปในอากาศ และโจมตีศัตรูเป็นแถว สร้างความเสียหาย (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B# หากเป้าหมายได้รับผลกระทบจาก [Disaster] จะสร้างความเสียหายพิเศษ 40% และใช้ [Curse Mark] เป็นเวลา 3 รอบ (เครื่องหมายคำสาป: เอฟเฟกต์เชิงลบ ทำให้เป้าหมายสูญเสีย HP 25% ก่อนแต่ละรอบใหญ่ ซึ่งถือเป็นความเสียหายจริง หากเป้าหมายเป็นบอสดันเจี้ยนจะคำนวณตาม HP ที่เสียไปเอง)",
		starEffectDesc_id = "Efek tambahan: Setiap kali Tanda Kutukan terpicu, ia memperoleh tambahan 20% kerusakan Kutukan setelahnya",
		starEffectDesc_es = "Efecto adicional: Cada vez que se activa la Marca de Maldición, obtiene un 20% adicional de daño de Maldición posteriormente.",
		zawakeSimpleDesc_en = "Curse Mark: Negative effect, causes the target to lose 15% HP before each big round\n#F20#\n#F40##C0x5c9970#→Curse Mark: Negative effect, causes the target to lose 25% HP before each big round",
		describe_vn = "Absol sente o desastre, salta no ar e ataca os inimigos em coluna, infligindo (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Se o alvo estiver sendo afetado por [Disaster], inflige 40% de DMG extra e aplica [Curse Mark] por 3 rodadas (Curse Mark: Efeito negativo, faz com que o alvo perca 15% de HP antes de cada grande rodada, que é considerado True DMG . Se o alvo for um chefe de masmorra, calcula com o próprio HP perdido)",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: แต่ละครั้งที่ Curse Mark ทำงาน จะได้รับความเสียหายเพิ่มเติม 20% ในภายหลัง",
		starEffectDesc_vn = "Efeito adicional: Cada vez que a Marca Amaldiçoada é ativada, ela ganha 20% de dano adicional de Maldição subsequentemente",
		zawakeEffectDesc_kr = "앱솔은 재난을 느끼고 공중으로 도약해 기둥 안의 적들을 공격해 (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B# 피해를 입힙니다. 대상이 [Disaster]의 영향을 받는 경우 40%의 추가 피해를 입히고 3라운드 동안 [Curse Mark]를 적용합니다. (저주 표시: 부정적인 효과, 각 큰 라운드 전에 대상의 HP가 25% 감소하며 이는 True DMG로 간주됩니다. .대상이 던전보스일 경우 자신의 잃은 HP로 계산)",
		describe_en = "Absol feels the disaster, leaps in the air, and attacks enemies in a column, inflicting (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. If the target is being affected by [Disaster], inflicts 40% extra DMG and applies [Curse Mark] for 3 rounds (Curse Mark: Negative effect, causes the target to lose 15% HP before each big round, which is taken as True DMG. If the target is a dungeon boss, calculates with own lost HP)",
		zawakeEffectDesc_id = "Absol merasakan bencana, melompat ke udara, dan menyerang musuh dalam satu kolom, menimbulkan (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Jika target terkena [Disaster], menimbulkan 40% DMG ekstra dan menerapkan [Curse Mark] selama 3 ronde (Tanda Kutukan: Efek negatif, menyebabkan target kehilangan 25% HP sebelum setiap ronde besar, yang dianggap sebagai True DMG .Jika targetnya adalah Dungeon Boss, hitung dengan HP miliknya yang hilang)",
		describe_id = "Absol merasakan bencana, melompat ke udara, dan menyerang musuh dalam satu kolom, menimbulkan (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Jika target terkena [Disaster], menimbulkan 40% DMG ekstra dan menerapkan [Curse Mark] selama 3 ronde (Tanda Kutukan: Efek negatif, menyebabkan target kehilangan 15% HP sebelum setiap ronde besar, yang dianggap sebagai True DMG .Jika targetnya adalah Dungeon Boss, hitung dengan HP miliknya yang hilang)",
		simDesc_en = "Absol senses the advent of the disaster and jumps high into the air before attacking enemies in a row, and deals extra damage to targets with Disaster effect while adding Cruse on them",
		simDesc_vn = "Absol sente o advento do desastre e salta alto antes de atacar os inimigos em sequência, e causa dano extra aos alvos com efeito Desastre enquanto adiciona Cruse neles",
		describe_kr = "앱솔은 재난을 느끼고 공중으로 도약해 기둥 안의 적들을 공격해 (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B# 피해를 입힙니다. 대상이 [Disaster]의 영향을 받는 경우 40%의 추가 피해를 입히고 3라운드 동안 [Curse Mark]를 적용합니다. (저주 표시: 부정적인 효과, 각 큰 라운드 전에 대상의 HP가 15% 감소하며 이는 True DMG로 간주됩니다. .대상이 던전보스일 경우 자신의 잃은 HP로 계산)",
		simDesc_th = "Absol สัมผัสได้ถึงการมาถึงของภัยพิบัติและกระโดดขึ้นไปในอากาศก่อนที่จะโจมตีศัตรูติดต่อกัน และสร้างความเสียหายเพิ่มเติมให้กับเป้าหมายที่มีเอฟเฟกต์ Disaster พร้อมทั้งเพิ่ม Cruse ให้กับพวกเขา",
		zawakeEffectDesc_es = "Absol siente el desastre, salta en el aire y ataca a los enemigos en columna, infligiendo (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Si el objetivo está siendo afectado por [Disaster], inflige un 40 % de DAÑO adicional y aplica [Curse Mark] durante 3 rondas (Marca de maldición: efecto negativo, hace que el objetivo pierda un 25 % de HP antes de cada ronda grande, lo que se toma como DAÑO verdadero (Si el objetivo es un jefe de mazmorra, se calcula con el propio HP perdido).",
		starEffectDesc_kr = "추가 효과: 저주 표식이 발동될 때마다 저주 피해가 20%씩 추가로 증가합니다.",
		zawakeEffectDesc_en = "Absol feels the disaster, leaps in the air, and attacks enemies in a column, inflicting (#C0xE69900#210% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. If the target is being affected by [Disaster], inflicts 40% extra DMG and applies [Curse Mark] for 3 rounds (Curse Mark: Negative effect, causes the target to lose 25% HP before each big round, which is taken as True DMG. If the target is a dungeon boss, calculates with own lost HP)",
		simDesc_kr = "앱솔은 재난의 도래를 감지하고 공중으로 높이 뛰어올라 적을 연속으로 공격하며, 재난 효과가 있는 대상에게 추가 피해를 주고 크루스를 부여합니다.",
		zawakeSimpleDesc_th = "เครื่องหมายคำสาป: เอฟเฟกต์เชิงลบ ทำให้เป้าหมายสูญเสีย HP 15% ก่อนแต่ละรอบใหญ่\n#F20#\n#F40##C0x5c9970#→เครื่องหมายคำสาป: เอฟเฟกต์เชิงลบ ทำให้เป้าหมายสูญเสีย HP 25% ก่อนแต่ละรอบใหญ่",
		zawakeSimpleDesc_kr = "저주 표시: 부정적인 효과, 각 큰 라운드 전에 대상의 HP가 15% 감소합니다\n#F20#\n#F40##C0x5c9970#→저주 표시: 부정적인 효과, 각 큰 라운드 전에 대상의 HP가 25% 감소합니다.",
		starEffectDesc_en = "Additional effect: Each time the Curse Mark is triggered, it gains an extra 20% Curse damage subsequently",
		zawakeSimpleDesc_vn = "Curse Mark: Efeito negativo, faz com que o alvo perca 15% de HP antes de cada grande rodada\n#F20#\n#F40##C0x5c9970#→Curse Mark: Efeito negativo, faz com que o alvo perca 25% de HP antes de cada grande rodada",
		zawakeSimpleDesc_id = "Curse Mark: Efek negatif, menyebabkan target kehilangan 15% HP sebelum setiap putaran besar\n#F20#\n#F40##C0x5c9970#→Curse Mark: Efek negatif, menyebabkan target kehilangan 25% HP sebelum setiap putaran besar",
		id = 18413,
		zawakeSimpleDesc_es = "Marca de maldición: efecto negativo, hace que el objetivo pierda un 15 % de HP antes de cada ronda grande\n#F20#\n#F40##C0x5c9970# → Marca de maldición: efecto negativo, hace que el objetivo pierda un 25 % de HP antes de cada ronda grande",
		simDesc_id = "Absol merasakan datangnya bencana dan melompat tinggi ke udara sebelum menyerang musuh secara berturut-turut, dan memberikan kerusakan ekstra pada target dengan efek Bencana sambil menambahkan Cruse pada mereka."
	},
	[18416] = {
		describe_id = "Pokémon yang menyerang Absol, dan musuh secara acak akan terkena efek [Disaster]; Pokémon yang diserang oleh Absol, dan musuh secara acak akan terkena efek [Disaster]. Ketika [Disaster] efektif, sebelum setiap ronde, akan mengalami salah satu efek berikut: HP maksimal berkurang sebesar #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.DEF dan P.DEF berkurang sebesar #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.ATK dan P.ATK berkurang sebesar #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, dan damage yang diterima berikutnya meningkat sebesar #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. Efeknya tidak menumpuk. Saat Absol dalam pertempuran, efek [Disaster] bertahan.",
		zawakeEffectDesc_vn = "Um Pokémon que ataca Absol e um inimigo aleatório sofrerão o efeito [Disaster]; Um Pokémon atacado por Absol e um inimigo aleatório sofrerão o efeito [Disaster]. Quando [Disaster] é efetivo, antes de cada rodada, sofre um dos seguintes efeitos: HP máximo reduzido em #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.DEF e P.DEF reduzidos em #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.ATK e P.ATK reduzidos em #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, e o próximo dano sofrido aumentado em #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. O efeito não acumula. Quando Absol está na batalha, o efeito [Disaster] dura. Após cada grande rodada, Absol punirá o Pokémon com [Disaster], tirando True DMG de 80% P.ATK de Absol",
		describe_vn = "Um Pokémon que ataca Absol e um inimigo aleatório sofrerão o efeito [Disaster]; Um Pokémon atacado por Absol e um inimigo aleatório sofrerão o efeito [Disaster]. Quando [Disaster] é efetivo, antes de cada rodada, sofre um dos seguintes efeitos: HP máximo reduzido em #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.DEF e P.DEF reduzidos em #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.ATK e P.ATK reduzidos em #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, e o próximo dano sofrido aumentado em #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. O efeito não acumula. Quando Absol está na batalha, o efeito de [Disaster] dura.",
		starEffectDesc_id = "Efek tambahan: Selama efek [Disaster], efek tersebut akan dipengaruhi oleh dua kemalangan acak sebelum dimulainya setiap putaran",
		zawakeEffectDesc_th = "โปเกมอนที่โจมตี Absol และศัตรูแบบสุ่มจะได้รับเอฟเฟกต์ [Disaster] โปเกมอนที่ถูกโจมตีโดย Absol และศัตรูแบบสุ่มหนึ่งตัวจะได้รับเอฟเฟกต์ [Disaster] เมื่อ [Disaster] มีผล ก่อนแต่ละรอบจะเกิดผลอย่างใดอย่างหนึ่งต่อไปนี้: HP สูงสุดลดลง #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.DEF และ P.DEF ลดลง #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.ATK และ P.ATK ลดลง #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B# และความเสียหายครั้งถัดไปที่ได้รับเพิ่มขึ้น #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B# เอฟเฟกต์ไม่ซ้อนกัน เมื่อ Absol อยู่ในการต่อสู้ เอฟเฟกต์ [Disaster] จะคงอยู่ หลังจากแต่ละรอบใหญ่ Absol จะลงโทษโปเกมอนด้วย [Disaster] โดยรับ True DMG จาก P.ATK 80% ของ Absol",
		starEffectDesc_kr = "추가 효과: [Disaster] 효과 동안 각 라운드가 시작되기 전에 두 가지 무작위 불행의 영향을 받습니다.",
		describe_es = "Un Pokémon que ataca a Absol y un enemigo aleatorio recibirán el efecto [Disaster]; Un Pokémon atacado por Absol y un enemigo aleatorio recibirán el efecto [Disaster]. Cuando [Disaster] es efectivo, antes de cada ronda, sufre uno de los siguientes efectos: HP máximo reducido en #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.DEF y P.DEF reducidos en #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, SP.ATK y P.ATK se redujeron en #C0x5c9970#$(5+skillLevel*0.1-0.1)$%#C0x5B545B#, y el siguiente daño recibido aumentó en #C0x5c9970#$(80+skillLevel*0.2-0.2)$%#C0x5B545B#. El efecto no se acumula. Cuando Absol está en la batalla, el efecto [Disaster] dura.",
