	[19216] = {
		describe_id = "Saat dikendalikan dengan skill, memulihkan HP sebesar $(100+skillLevel*1-1)$% dari SP.DEF miliknya (Saat dibekukan, penyembuhannya berlipat ganda); \nAura Skill: Target di sekitar Regice meningkatkan SP.DEF sebesar 30%, di akhir setiap putaran besar, menyembuhkan Pokémon Es teman sebesar 100% SP.DEF Regice.",
		zawakeEffectDesc_vn = "Quando controlado por uma habilidade, restaura HP igual a #C0x5c9970#$(100+skillLevel*1-1)$%#C0x5B545B# do próprio SP.DEF (Quando congelado, aumenta a cura em 100%); Cada alvo congelado no campo aumenta em 30% a redução de SP.DMG de Regice por 1 rodada;\nHabilidade de Aura:aliados ao redor de Regice aumentam seu SP.DEF em 30%. No final de cada grande rodada, cura Pokémon de Gelo aliados em 100% do SP.DEF de Regice",
		describe_vn = "Quando controlado por uma habilidade, restaura HP igual a $(100+skillLevel*1-1)$% do próprio SP.DEF (Quando congelado, dobra a cura); \nHabilidade de Aura: Os alvos ao redor de Regice aumentam SP.DEF em 30%, no final de cada grande rodada, cura Pokémon de Gelo aliados em 100% do SP.DEF de Regice.",
		starEffectDesc_id = "Memasuki status [Ice Core] segera setelah menerima DMG (hanya terpicu sekali)",
