	[19313] = {
		describe_th = "เรจิสตีลทำสมาธิเพื่อล็อคศัตรูสองคนด้วยเปอร์เซ็นต์ HP ต่ำสุด และยิงมันด้วยปืนเลเซอร์แฟลช สร้างความเสียหาย#C0x3D8A99#300%SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#และความเสียหายเท่ากับ 20 % ของคะแนนโล่ทั้งหมดที่ได้รับจาก Registeel (นับคะแนนโล่ที่มอบให้ตนเองและพันธมิตรและสแต็คตลอดการต่อสู้)",
		zawakeEffectDesc_vn = "Registeel medita para travar o inimigo com a menor porcentagem de HP e atira nele com a arma laser flash, infligindo (#C0x3D8A99#540% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54# SP.DMG#C0x5B545B# e DMG igual a 20% de todos os pontos de escudo concedidos pelo Registeel. (Conta os pontos de escudo concedidos a si mesmo e aos aliados e acumula durante a batalha), aumenta a redução de DMG do Pokémon tipo Aço aliado em 30% por 2 rodadas",
		simDesc_es = "Registeel medita para bloquear a un solo enemigo con el porcentaje de HP más bajo y le dispara con la pistola láser flash, infligiendo daño adicional según todos los puntos de escudo que posee Registeel.",
		describe_es = "Registeel medita para bloquear a dos enemigos con el porcentaje de HP más bajo y les dispara con la pistola láser flash, infligiendo#C0x3D8A99#300%SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#y DMG igual a 20. % de todos los puntos de escudo que otorga Registeel. (Cuenta los puntos de escudo otorgados a uno mismo y a sus aliados y se acumula a lo largo de la batalla)",
		zawakeEffectDesc_th = "Registeel นั่งสมาธิเพื่อล็อคศัตรูด้วยเปอร์เซ็นต์ HP ต่ำสุด และยิงมันด้วยปืนเลเซอร์แฟลช สร้างความเสียหาย (#C0x3D8A99#540% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54# SP.DMG#C0x5B545B# และ DMG เท่ากัน มากถึง 20% ของคะแนนโล่ทั้งหมดที่ได้รับจาก Registeel (นับคะแนนโล่ที่มอบให้ตนเองและพันธมิตร และสแตคตลอดการต่อสู้) เพิ่มการลดความเสียหายโปเกมอนประเภทเหล็กของพันธมิตร 30% เป็นเวลา 2 รอบ",
		starEffectDesc_id = "Memiliki peluang 60% [Elimination] dengan menggunakan Ultimate pada target dengan HP lebih rendah dari 30%. (dapat mengabaikan Anti-Death, Resurrection, dan efek lainnya; jika Rarity target lebih tinggi dari itu, semua HP akan berkurang); jika HP target saat ini 5x lebih tinggi dari HP Maksmu, [Elimination] tidak dapat dipicu",
		starEffectDesc_es = "Tiene un 60% [Elimination] de posibilidades al usar Ultimate en objetivos con menos del 30% de HP. (puede ignorar Anti-Muerte, Resurrección y otros efectos; si la Rareza del objetivo es mayor, todos los HP se reducirán); Si el HP actual del objetivo es 5 veces mayor que su HP máximo, [Elimination] no se puede activar",
		zawakeSimpleDesc_en = "increase ally Steel Type Pokemon DMG reduction by 30% for 2 rounds",
		describe_vn = "Registeel medita para travar dois inimigos com a menor porcentagem de HP e atira neles com a arma laser flash, infligindo#C0x3D8A99#300%SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#e DMG igual a 20 % de todos os pontos de escudo concedidos pelo Registeel. (Conta os pontos de escudo concedidos a si mesmo e aos aliados e acumula durante a batalha)",
		starEffectDesc_th = "มีโอกาส 60% [Elimination] โดยใช้ท่าไม้ตายกับเป้าหมายที่มี HP ต่ำกว่า 30% (สามารถเพิกเฉยต่อ Anti-Death, Resurrection และเอฟเฟกต์อื่น ๆ ได้ หากความหายากของเป้าหมายสูงกว่านั้น HP ทั้งหมดจะลดลง) หาก HP ปัจจุบันของเป้าหมายสูงกว่า HP สูงสุดของคุณ 5 เท่า [Elimination] จะไม่สามารถถูกกระตุ้นได้",
		starEffectDesc_vn = "Tem 60% [Elimination] de chance de usar Ultimate em alvos com menos de 30% de HP. (pode ignorar Anti-Morte, Ressurreição e outros efeitos; se a Raridade do alvo for maior que ela, todo o HP será reduzido); se o HP atual do alvo for 5x maior que seu HP máximo, [Elimination] não pode ser acionado",
		zawakeEffectDesc_kr = "레지스틸은 HP가 가장 낮은 적을 잠그기 위해 명상하고 플래시 레이저 총으로 발사하여 (#C0x3D8A99#540% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54# SP.DMG#C0x5B545B#와 DMG가 동일하게 됩니다. Registeel이 부여하는 모든 쉴드 포인트의 20%까지. (자신과 아군에게 부여된 실드 포인트를 계산하고 전투 전반에 걸쳐 중첩됩니다), 아군 강철 타입 포켓몬의 피해 감소를 2라운드 동안 30% 증가시킵니다.",
		describe_en = "Registeel meditates to lock two enemies with the lowest HP percentage and shoots it with the flash laser gun, inflicting#C0x3D8A99#300%SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#and DMG equal to 20% of all shield points Registeel grants. (Counts shield points granted to self and allies and stacks across the battle)",
		zawakeEffectDesc_id = "Registeel bermeditasi untuk mengunci musuh dengan persentase HP terendah dan menembaknya dengan senjata laser flash, menimbulkan (#C0x3D8A99#540% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54# SP.DMG#C0x5B545B# dan DMG setara hingga 20% dari semua poin perisai yang diberikan Registeel. (Menghitung poin perisai yang diberikan kepada diri sendiri dan sekutu dan ditumpuk di seluruh pertempuran), meningkatkan pengurangan DMG Pokemon Tipe Baja sekutu sebesar 30% selama 2 putaran",
		describe_id = "Registeel bermeditasi untuk mengunci dua musuh dengan persentase HP terendah dan menembaknya dengan senjata laser flash, menimbulkan#C0x3D8A99#300%SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#dan DMG setara dengan 20 % dari semua poin perisai yang diberikan Registeel. (Menghitung poin perisai yang diberikan kepada diri sendiri dan sekutu serta menumpuknya di seluruh pertempuran)",
		simDesc_en = "Registeel meditates to lock a single enemy with the lowest HP percentage and shoots it with the flash laser gun, inflicting extra DMG based on all shield points Registeel owns.",
		simDesc_vn = "Registeel medita para bloquear um único inimigo com a menor porcentagem de HP e atira nele com a arma laser flash, infligindo DMG extra com base em todos os pontos de escudo que Registeel possui.",
		describe_kr = "레지스틸은 HP 비율이 가장 낮은 적 2명을 잠그고 플래시 레이저 총으로 발사하여#C0x3D8A99#300%SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B# 및 DMG를 20으로 적용합니다. Registeel이 부여하는 모든 쉴드 포인트의 %입니다. (자신과 아군에게 부여된 쉴드 포인트를 계산하고 전투 전반에 걸쳐 누적됩니다.)",
		simDesc_th = "Registeel นั่งสมาธิเพื่อล็อคศัตรูหนึ่งตัวด้วยเปอร์เซ็นต์ HP ต่ำสุด และยิงมันด้วยปืนเลเซอร์แฟลช สร้างความเสียหายเพิ่มเติมตามคะแนนโล่ทั้งหมดที่ Registeel เป็นเจ้าของ",
		zawakeEffectDesc_es = "Registeel medita para bloquear al enemigo con el porcentaje de HP más bajo y le dispara con la pistola láser flash, infligiendo (#C0x3D8A99#540% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54# SP.DMG#C0x5B545B# y DMG igual hasta el 20% de todos los puntos de escudo que otorga Registeel. (Cuenta los puntos de escudo otorgados a uno mismo y a sus aliados y se acumula a lo largo de la batalla), aumenta la reducción de daño de los Pokémon tipo acero de los aliados en un 30 % durante 2 rondas.",
		starEffectDesc_kr = "HP가 30% 미만인 대상에게 궁극기를 사용하면 60% [Elimination] 확률이 있습니다. (죽음 방지, 부활 등의 효과를 무시할 수 있습니다. 대상의 희귀도가 이보다 높으면 모든 HP가 감소합니다.) 대상의 현재 HP가 최대 HP보다 5배 높으면 [Elimination]가 발동되지 않습니다.",
		zawakeEffectDesc_en = "Registeel meditates to lock the enemy with the lowest HP percentage and shoots it with the flash laser gun, inflicting (#C0x3D8A99#540% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$) #C0xF13B54# SP.DMG#C0x5B545B# and DMG equal to 20% of all shield points Registeel grants. (Counts shield points granted to self and allies and stacks across the battle),increase ally Steel Type Pokemon DMG reduction by 30% for 2 rounds",
		simDesc_kr = "레지스틸은 명상을 통해 HP 비율이 가장 낮은 적 하나를 가두어 플래시 레이저 총으로 쏘고, 레지스틸이 보유한 모든 쉴드 포인트에 따라 추가 데미지를 입힙니다.",
		zawakeSimpleDesc_th = "เพิ่มการลด DMG โปเกมอนประเภทเหล็กของเพื่อนร่วมทีม 30% เป็นเวลา 2 รอบ",
		zawakeSimpleDesc_kr = "아군 강철타입 포켓몬의 데미지 감소를 2라운드 동안 30% 증가시킵니다.",
		starEffectDesc_en = "Has a 60% [Elimination] chance by using Ultimate on targets with lower than 30% HP. (can ignore Anti-Death, Resurrection and other effects; if target's Rarity is higher than it, all HP will be reduced); if target's current HP is 5x higher than your Max HP, [Elimination] cannot be triggered",
		zawakeSimpleDesc_vn = "aumenta a redução de DMG do Pokémon tipo Aço aliado em 30% por 2 rodadas",
		zawakeSimpleDesc_id = "meningkatkan pengurangan DMG Pokemon Tipe Baja sekutu sebesar 30% selama 2 ronde",
		id = 19313,
		zawakeSimpleDesc_es = "Aumenta la reducción de daño de Pokémon tipo acero de un aliado en un 30 % durante 2 rondas.",
		simDesc_id = "Registeel bermeditasi untuk mengunci satu musuh dengan persentase HP terendah dan menembaknya dengan senjata laser flash, menimbulkan DMG ekstra berdasarkan semua poin perisai yang dimiliki Registeel."
	},
	[19316] = {
		describe_id = "Penyerapan Besi: Menyerap#C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#DMG efektif yang diterima dalam ronde besar. Di akhir ronde besar, menyembunyikan 1,5*DMG yang diserap ke dalam titik perisai; Keterampilan Aura: meningkatkan 10% DMG",
		zawakeEffectDesc_vn = "Absorve #C0x5c9970#$(50+skillLevel*0.1-0.1)$%#C0x5B545B#de DMG efetivo obtido em uma grande rodada. No final da grande rodada, os abrigos absorveram 2x o DMG em pontos de escudo\nHabilidade de aura: aumenta a redução de DMG de toda a equipe em 10%",
		describe_vn = "Absorção de Ferro: Absorve#C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#do DMG efetivo recebido em uma grande rodada. No final da grande rodada, os coverts 1,5* absorveram DMG em pontos de escudo; Habilidade de Aura: aumenta 10% de DMG",
		starEffectDesc_id = "Tingkatkan kecepatan blok untuk sementara sebesar 60% sebelum serangan pertama di setiap putaran.",
		zawakeEffectDesc_th = "ดูดซับความเสียหายที่มีประสิทธิภาพ #C0x5c9970#$(50+skillLevel*0.1-0.1)$%#C0x5B545B# ในรอบใหญ่ ในตอนท้ายของรอบใหญ่ ปกปิด DMG ที่ดูดซับ 2 เท่าเป็นคะแนนโล่\n ทักษะออร่า: เพิ่มการลด DMG ของทั้งทีม 10%",
		starEffectDesc_kr = "각 라운드에서 첫 번째 공격이 발생하기 전에 일시적으로 차단율이 60% 증가합니다.",
		describe_es = "Absorción de hierro: Absorbe #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#del DAÑO efectivo recibido durante una gran ronda. Al final de la gran ronda, convierte 1,5*DAÑO absorbido en puntos de escudo; Habilidad de aura: aumenta 10% DAÑO",
		zawakeSimpleDesc_en = "converts 1.5x effective DMG absorption to its Shield\n#F20#\n#F40##C0x5c9970#→+10% Absorption and converts 2x effective DMG absorption to its Shield",
		starEffectDesc_es = "Aumenta temporalmente la tasa de bloqueo en un 60 % antes del primer ataque en cada ronda.",
		starEffectDesc_th = "เพิ่มอัตราการบล็อกชั่วคราว 60% ก่อนการโจมตีครั้งแรกในแต่ละรอบ",
		zawakeEffectDesc_id = "Menyerap #C0x5c9970#$(50+skillLevel*0.1-0.1)$%#C0x5B545B#DMG efektif yang diambil dalam ronde besar. Di akhir ronde besar, menyamarkan 2x DMG yang diserap menjadi poin perisai\nSkill Aura: meningkatkan Pengurangan DMG seluruh tim sebesar 10%",
		zawakeEffectDesc_es = "Absorbe el #C0x5c9970#$(50+skillLevel*0.1-0.1)$%#C0x5B545B#del DAÑO efectivo recibido durante una gran ronda. Al final de la gran ronda, los encubiertos absorben 2 veces el DAÑO en puntos de escudo.\nHabilidad de aura: aumenta la reducción de DAÑO de todo el equipo en un 10 %.",
		describe_en = "Iron Absorb: Absorbs#C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#of effective DMG taken over a big round. At the end of the big round, coverts 1.5*absorbed DMG into shield points; Aura Skill: increase 10% DMG",
