	[19613] = {
		describe_th = "เคียวเกรสร้างสึนามิที่กั้นระหว่างศัตรู 6 ครั้ง การเด้งครั้งแรกจะสร้างความเสียหาย #C0x3D8A99#300% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#(กระเด้งเป้าหมายที่แตกต่างกันสำหรับแต่ละความเสียหายสองครั้งติดต่อกัน ไม่ ชิ่งได้นานขึ้นเมื่อมีเพียงเป้าหมายเดียว ความเสียหายลดลง 30% สำหรับการชิ่งแต่ละครั้งในทักษะโจมตีจุดตายหนึ่งครั้ง) การชิ่งแต่ละครั้งจะลด SPD ของเป้าหมายลง 10% และเพิ่มช่องโหว่ประเภทน้ำ 8% นาน 2 รอบ",
		zawakeEffectDesc_vn = "Efeito adicional: dissipa aleatoriamente 1 a 2 buffs para alvos que foram devolvidos, diminui 20% de bônus de DMG e taxa crítica para alvos (incapaz de acumular), dura 2 rodadas; E dissipa 1 efeito de controle de Pokémon aliado",
		simDesc_es = "Kyogre crea un tsunami que salta entre los enemigos y cada rebote reduce la velocidad del objetivo.",
		describe_es = "Kyogre crea un tsunami que salta entre enemigos 6 veces, el primer rebote inflige #C0x3D8A99#300% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#(Rebota en un objetivo diferente por cada dos daños consecutivos, no rebotes más largos cuando solo hay un objetivo, el daño se reduce en un 30% por cada rebote en una habilidad letal), cada rebote reduce el SPD del objetivo en un 10% y agrega un 8% de vulnerabilidad de tipo agua, dura 2 rondas",
		zawakeEffectDesc_th = "ผลกระทบเพิ่มเติม: สุ่มลบบัฟ 1 ถึง 2 ไปยังเป้าหมายที่ถูกเด้ง ลดโบนัส DMG และอัตราคริติคอลไปยังเป้าหมาย 20% (ไม่สามารถซ้อนได้) คงอยู่เป็นเวลา 2 รอบ; และลบล้างเอฟเฟกต์ควบคุม 1 อันของโปเกมอนฝ่ายเดียวกัน",
		starEffectDesc_id = "Efek Tambahan: Menghilangkan 1 hingga 2 buff secara acak ke target yang dipantulkan, mengurangi 20% bonus DMG ke target (Tidak dapat ditumpuk), bertahan selama 2 ronde",
		starEffectDesc_es = "Efecto adicional: disipa aleatoriamente de 1 a 2 beneficios a los objetivos que han sido rebotados, disminuye el 20% de bonificación de DAÑO a los objetivos (no se puede acumular), dura 2 rondas",
		zawakeSimpleDesc_en = "decreases 20% DMG bonus to targets(Unable to stack), last for 2 rounds\n#F20#\n#F40##C0x5c9970#→decreases 20% DMG bonus&Crit rate to targets(Unable to stack), last for 2 rounds; And dispell 1 control effect of ally Pokemon",
		describe_vn = "Kyogre cria um tsunami que salta entre os inimigos por 6 vezes, primeiro rebatendo#C0x3D8A99#300% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#(Rebate alvos diferentes para cada dois danos consecutivos, não saltos mais longos quando há apenas um alvo, o dano é reduzido em 30% para cada salto em uma habilidade letal), cada salto reduz o SPD do alvo em 10% e adiciona 8% de vulnerabilidade do tipo água, dura 2 rodadas",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: สุ่มลบบัฟ 1 ถึง 2 ไปยังเป้าหมายที่ถูกเด้ง ลดโบนัส DMG 20% ไปยังเป้าหมาย (ไม่สามารถซ้อนได้) ใช้งานได้ 2 รอบ",
		starEffectDesc_vn = "Efeito adicional: dissipa aleatoriamente 1 a 2 buffs para alvos que foram rebatidos, diminui 20% do bônus de DMG para alvos (incapaz de acumular), dura 2 rodadas",
		zawakeEffectDesc_kr = "추가 효과: 튕겨진 대상에게 버프 1~2개를 무작위로 해제하고 대상에 대한 추가 데미지 및 치명타율을 20% 감소시킵니다(중첩 불가). 2라운드 동안 지속됩니다. 그리고 아군 포켓몬의 제어 효과 1개를 해제합니다.",
		describe_en = "Kyogre creates a tsunami that bounds between enemies for 6 times, first bounce dealing#C0x3D8A99#300% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#(Bounces different target for each two consecutive damage, no longer bounces when there is only one target, damage reduces by 30% for each bounce in one Lethal Skill), each bounce lowers target's SPD by 10% and adds 8% water-type Vulnerability, lasts for 2 rounds",
		zawakeEffectDesc_id = "Efek Tambahan: Menghilangkan 1 hingga 2 buff secara acak ke target yang dipantulkan, mengurangi 20% bonus DMG & tingkat Kritik ke target (Tidak dapat ditumpuk), bertahan selama 2 ronde; Dan menghilangkan 1 efek kontrol dari Pokemon sekutu",
		describe_id = "Kyogre menciptakan tsunami yang mengikat musuh sebanyak 6 kali, pantulan pertama menimbulkan#C0x3D8A99#300% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#(Memantul target berbeda untuk setiap dua kerusakan berturut-turut, tidak memantul lebih lama ketika hanya ada satu target, kerusakan berkurang sebesar 30% untuk setiap pantulan dalam satu Skill Lethal), setiap pantulan menurunkan SPD target sebesar 10% dan menambahkan 8% Kerentanan tipe air, berlangsung selama 2 putaran",
		simDesc_en = "Kyogre creates a tsunami that bounds between enemies, with each bounce reducing target's Speed",
		simDesc_vn = "Kyogre cria um tsunami que atravessa os inimigos, com cada salto reduzindo a velocidade do alvo",
		describe_kr = "가이오가는 6번 동안 적 사이를 경계하는 쓰나미를 일으키며 첫 번째 튕김 처리#C0x3D8A99#300% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#(2연속 피해마다 다른 대상을 튕겨냅니다. 대상이 1명일 경우 튕기는 시간이 길어지고 치명적인 스킬의 튕김당 피해가 30% 감소합니다), 튕길 때마다 대상의 SPD가 10% 감소하고 물형 취약성이 8% 추가되며 2라운드 동안 지속됩니다.",
		simDesc_th = "Kyogre สร้างสึนามิที่กั้นระหว่างศัตรู โดยแต่ละครั้งจะเด้งจะลดความเร็วของเป้าหมาย",
		zawakeEffectDesc_es = "Efecto adicional: disipa aleatoriamente de 1 a 2 beneficios a los objetivos que han sido rebotados, disminuye el 20% de bonificación de DAÑO y tasa de críticos a los objetivos (no se puede acumular), dura 2 rondas; Y disipa 1 efecto de control de Pokémon aliado.",
		starEffectDesc_kr = "추가 효과: 튕겨진 대상에게 무작위로 버프 1~2개 해제, 대상에 대한 추가 피해량 20% 감소(중첩 불가), 2라운드 동안 지속",
		zawakeEffectDesc_en = "Additional Effect: Randomly dispell 1 to 2 buff to targets been bounced, decreases 20% DMG bonus&Crit rate to targets(Unable to stack), last for 2 rounds; And dispell 1 control effect of ally Pokemon",
		simDesc_kr = "가이오그레는 적들 사이를 맴돌며 튕겨나갈 때마다 대상의 속도를 감소시키는 쓰나미를 생성합니다.",
		zawakeSimpleDesc_th = "ลดโบนัส DMG 20% ให้กับเป้าหมาย (ไม่สามารถซ้อนได้) มีผล 2 รอบ\n#F20#\n#F40##C0x5c9970# →ลดโบนัส DMG 20% และอัตราคริติคอลให้กับเป้าหมาย (ไม่สามารถซ้อนได้) มีผล 2 รอบ และลบล้างเอฟเฟกต์ควบคุม 1 อันของโปเกมอนฝ่ายเดียวกัน",
		zawakeSimpleDesc_kr = "대상에 대한 데미지 보너스 20% 감소(중첩 불가), 2라운드 동안 지속\n#F20#\n#F40##C0x5c9970#→대상에 대한 데미지 보너스 및 치명타율 20% 감소(중첩 불가), 2라운드 동안 지속; 그리고 아군 포켓몬의 제어 효과 1개를 해제합니다.",
		starEffectDesc_en = "Additional Effect: Randomly dispell 1 to 2 buff to targets been bounced, decreases 20% DMG bonus to targets(Unable to stack), last for 2 rounds",
		zawakeSimpleDesc_vn = "diminui 20% do bônus DMG para os alvos (incapaz de acumular), dura 2 rodadas\n#F20#\n#F40##C0x5c9970#→diminui 20% do bônus DMG e taxa crítica para os alvos (incapaz de empilhar), dura 2 rodadas; E dissipa 1 efeito de controle de Pokémon aliado",
		zawakeSimpleDesc_id = "mengurangi 20% bonus DMG ke target (Tidak dapat ditumpuk), bertahan selama 2 ronde\n#F20#\n#F40##C0x5c9970#→menurunkan 20% bonus DMG & tingkat Kritik ke target (Tidak dapat ditumpuk), bertahan selama 2 ronde; Dan menghilangkan 1 efek kontrol dari Pokemon sekutu",
		id = 19613,
		zawakeSimpleDesc_es = "disminuye el 20% de bonificación de DAÑO a los objetivos (no se puede acumular), dura 2 rondas\n#F20#\n#F40##C0x5c9970#→disminuye el 20% de bonificación de DAÑO y la tasa de críticos a los objetivos (no se puede acumular), dura 2 rondas; Y disipa 1 efecto de control de Pokémon aliado.",
