	[19616] = {
		describe_id = "Saat dalam pertempuran, tingkatkan dirinya#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, tingkatkan kemungkinan kebal terhadap semua efek kontrol sebesar#C0x5c9970#$(10+skillLevel*0.08-0.08)$%#C0x5B545B#(Efek spesial, tidak bisa dihilangkan), sekutu di sekitarnya mendapat setengah dari bonusnya. Sebelum setiap ronde besar dimulai, hilangkan 2 debuff dan efek kontrol dari sekutu. Sebelum gilirannya bergerak, menghilangkan 2 efek kontrol dan debuff dari sekutu, memulihkan HP milik sendiri sebesar 250% SP.DEF ketika efek menghilangkan skill pasif berhasil.",
		zawakeEffectDesc_vn = "Quando em batalha, aumente #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, aumente a chance de imunidade a todos os efeitos de controle em #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#(Efeito especial, não pode ser dissipado), aliados ao seu redor recebem metade de seu bônus. Antes de cada grande rodada começar, dissipe 2 debuffs e efeitos de controle dos aliados. Antes de seu turno de movimento, dissipa 2 efeitos de controle e debuff dos aliados, recupera HP de 250% de SP.DEF quando o efeito de dissipação de habilidade passiva é bem-sucedido.",
		describe_vn = "Quando em batalha, aumente #C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, aumente a chance de imunidade a todos os efeitos de controle em #C0x5c9970#$(10+skillLevel*0.08-0.08)$%#C0x5B545B#(Efeito especial, não pode ser dissipado), aliados ao seu redor recebem metade de seu bônus. Antes de cada grande rodada começar, dissipe 2 debuffs e efeitos de controle dos aliados. Antes de seu turno de movimento, dissipa 2 efeitos de controle e debuff dos aliados, recupera HP de 250% de SP.DEF quando o efeito de dissipação de habilidade passiva é bem-sucedido.",
		starEffectDesc_id = "Efek Tambahan: Saat dalam pertarungan, menurunkan 15% SPD dan Crit rate ke Pokémon musuh dengan Crit rate tertinggi (Tidak dapat dihilangkan)",
		zawakeEffectDesc_th = "เมื่ออยู่ในการต่อสู้ เพิ่มตัวเอง#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES เพิ่มโอกาสภูมิคุ้มกันต่อเอฟเฟกต์การควบคุมทั้งหมดด้วย#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#(เอฟเฟกต์พิเศษ ไม่สามารถลบล้างได้) พันธมิตรที่อยู่รอบ ๆ จะได้รับโบนัสครึ่งหนึ่ง ก่อนแต่ละรอบใหญ่จะเริ่มต้น ลบล้างดีบัฟ 2 อันและเอฟเฟกต์ควบคุมจากพันธมิตร ก่อนที่จะถึงเทิร์น ยกเลิกเอฟเฟกต์ควบคุม 2 อันและดีบัฟจากพันธมิตร ฟื้นฟู HP ของตัวเอง 250% SP.DEF เมื่อทักษะแบบพาสซีฟยกเลิกเอฟเฟกต์สำเร็จ",
		starEffectDesc_kr = "추가 효과: 전투 중 치명률이 가장 높은 적 포켓몬의 속도와 치명타율을 15% 감소(해제 불가)",
		describe_es = "Cuando está en batalla, aumenta#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, aumenta la posibilidad de inmunidad a todos los efectos de control en#C0x5c9970#$(10+skillLevel*0.08-0.08)$%#C0x5B545B#(Efecto especial, no se puede disipar), los aliados a su alrededor obtienen la mitad de su bonificación. Antes de que comience cada gran ronda, disipa 2 desventajas y efectos de control de los aliados. Antes de su turno de moverse, disipa 2 efectos de control y desventajas de los aliados, recupera HP de su propio 250% SP.DEF cuando el efecto de disipación de la habilidad pasiva tiene éxito.",
		zawakeSimpleDesc_en = "increase the own Immune Control rate by 20%~30% (special effect, can not be dispelled), and the surrounding allies get half of the bonus.",
		starEffectDesc_es = "Efecto adicional: cuando está en batalla, reduce el 15% de SPD y la tasa de críticos para los Pokémon enemigos con la tasa de críticos más alta (no se puede disipar)",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เมื่ออยู่ในการต่อสู้ ลด 15% ของ SPD และอัตราคริติคอลให้กับโปเกมอนศัตรูที่มีอัตราคริติคอลสูงสุด (ไม่สามารถลบล้างได้)",
		zawakeEffectDesc_id = "Saat dalam pertempuran, tingkatkan dirinya#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, tingkatkan kemungkinan kebal terhadap semua efek kontrol sebesar#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#(Efek spesial, tidak bisa dihilangkan), sekutu di sekitarnya mendapat setengah dari bonusnya. Sebelum setiap ronde besar dimulai, hilangkan 2 debuff dan efek kontrol dari sekutu. Sebelum gilirannya bergerak, menghilangkan 2 efek kontrol dan debuff dari sekutu, memulihkan HP milik sendiri sebesar 250% SP.DEF ketika efek menghilangkan skill pasif berhasil.",
		zawakeEffectDesc_es = "Cuando está en batalla, aumenta#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, aumenta la posibilidad de inmunidad a todos los efectos de control en#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#(Efecto especial, no se puede disipar), los aliados a su alrededor obtienen la mitad de su bonificación. Antes de que comience cada gran ronda, disipa 2 desventajas y efectos de control de los aliados. Antes de su turno de moverse, disipa 2 efectos de control y desventajas de los aliados, recupera HP de su propio 250% SP.DEF cuando el efecto de disipación de la habilidad pasiva tiene éxito.",
		describe_en = "When in battle, raise itself#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, raise itself the chance of immune to all control effect by#C0x5c9970#$(10+skillLevel*0.08-0.08)$%#C0x5B545B#(Special effect, can not be dispell), allies around it gets half of it's bonus. Before each big round starts, dispell 2 debuff and control effect from allies.  Before its turn to move, dispell 2 control effect and debuff from allies, recovers HP of own 250% SP.DEF when passive skill dispell effect succeed.",
		zawakeSimpleDesc_th = "เพิ่มอัตราการควบคุมภูมิคุ้มกันของตัวเอง 20%~30% (เอฟเฟกต์พิเศษ ไม่สามารถลบล้างได้) และพันธมิตรโดยรอบจะได้รับโบนัสครึ่งหนึ่ง",
		zawakeEffectDesc_kr = "전투 시 자신을 올립니다#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, 모든 제어 효과에 면역이 될 확률#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#(특수 효과, 해제 불가), 주변 아군은 보너스의 절반을 받습니다. 각 빅 라운드가 시작되기 전에 아군의 디버프와 제어 효과를 2개 해제합니다. 이동 차례 전 아군의 제어 효과와 디버프 2개를 해제하고, 패시브 스킬 해제 효과 성공 시 자신의 SP.DEF를 250% 회복합니다.",
		zawakeSimpleDesc_kr = "자신의 면역 제어율을 20%~30% 증가시키고(특수 효과, 해제할 수 없음) 주변 아군은 보너스의 절반을 받습니다.",
		zawakeEffectDesc_en = "When in battle, raise itself#C0x5c9970#$(60+skillLevel*0.2-0.2)$%#C0x5B545B#CRI RES, raise itself the chance of immune to all control effect by#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#(Special effect, can not be dispell), allies around it gets half of it's bonus. Before each big round starts, dispell 2 debuff and control effect from allies.  Before its turn to move, dispell 2 control effect and debuff from allies, recovers HP of own 250% SP.DEF when passive skill dispell effect succeed.",
