	[20228] = {
		zawakeEffectDesc_id = "Monferno melompat ke langit dan berubah menjadi roda api untuk bertabrakan dengan target tunggal musuh, menyebabkan#C0xE69900#150%P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, meningkatkan 15% dodge untuk 2 putaran (tambahan 4% dodge diberikan untuk setiap 10% bonus kecepatan, batas atas adalah 40%), dan [burn] ditambahkan ke target selama 3 putaran (burn: efek negatif, dapat ditumpuk hingga 5 kali dan setiap lapisan menyebabkan#C0xE69900#40%P.ATK#C0x5B545B#P.DMG sebelum dimulainya setiap putaran)",
		zawakeEffectDesc_vn = "Monferno saltou para o céu e se transformou em uma roda de fogo para colidir com o único alvo inimigo, causando#C0xE69900#150%P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, melhorando 15% de esquiva para 2 rodadas (4% de esquiva adicional é fornecida para cada 10% de bônus de velocidade, o limite superior é de 40%) e [burn] é adicionado ao alvo por 3 rodadas (queimadura: efeito negativo, pode ser empilhado até 5 vezes e cada camada causa#C0xE69900#40%P.ATK#C0x5B545B#P.DMG antes do início de cada rodada)",
		zawakeEffectDesc_es = "Monferno saltó al cielo y se convirtió en una rueda de llamas para chocar con el objetivo único enemigo, causando#C0xE69900#150%P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, mejorando un 15% la esquiva para 2 rondas (se proporciona un 4 % de esquiva adicional por cada 10 % de bonificación de velocidad, el límite superior es 40 %) y [burn] se agrega al objetivo durante 3 rondas (quemar: efecto negativo, se puede acumular hasta 5 veces y cada capa causa#C0xE69900#40%P.ATK#C0x5B545B#P.DMG antes del inicio de cada ronda)",
		zawakeEffectDesc_en = "Monferno leaped into the sky and turned into a flame wheel to collide with the enemy single target, causing#C0xE69900#150%P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, improving 15% dodge for 2 rounds (additional 4% dodge is provided for every 10% speed bonus, the upper limit is 40%), and [burn] is added to the target for 3 rounds (burn: negative effect, can be stacked up to 5 times and each layer causes#C0xE69900#40%P.ATK#C0x5B545B#P.DMG before the start of each round)",
		zawakeEffectDesc_th = "มอนเฟอร์โนกระโดดขึ้นไปบนท้องฟ้าและกลายเป็นกงล้อเพลิงเพื่อชนกับศัตรูเป้าหมายเดียว ทำให้#C0xE69900#150%P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B# ปรับปรุงการหลบหลีก 15% 2 รอบ (มีการหลบเพิ่มเติม 4% สำหรับทุก ๆ โบนัสความเร็ว 10% ขีดจำกัดบนคือ 40%) และ [burn] จะถูกเพิ่มเข้าไปในเป้าหมายเป็นเวลา 3 รอบ (เบิร์น: เอฟเฟกต์ด้านลบ สามารถซ้อนกันได้สูงสุด 5 ครั้ง และ แต่ละชั้นจะทำให้เกิด#C0xE69900#40%P.ATK#C0x5B545B#P.DMG ก่อนเริ่มแต่ละรอบ)",
		zawakeSimpleDesc_id = "meningkatkan 10% dodge selama 2 ronde (tambahan 4% dodge diberikan untuk setiap 10% bonus kecepatan, batas atas adalah 20%)\n#F20#\n#F40##C0x5c9970#→meningkatkan 15% dodge selama 2 ronde ( tambahan 4% dodge diberikan untuk setiap 10% bonus kecepatan, batas atas adalah 40%)",
		zawakeSimpleDesc_th = "ปรับปรุงการหลบหลีก 10% เป็นเวลา 2 รอบ (จะมีการหลบเพิ่ม 4% สำหรับทุก ๆ โบนัสความเร็ว 10% ขีดจำกัดบนคือ 20%)\n#F20#\n#F40##C0x5c9970#→ปรับปรุงการหลบหลีก 15% เป็นเวลา 2 รอบ ( มีการหลบหลีกเพิ่มเติม 4% สำหรับโบนัสความเร็วทุกๆ 10% ขีดจำกัดบนคือ 40%)",
		zawakeSimpleDesc_en = "improving 10% dodge for 2 rounds (additional 4% dodge is provided for every 10% speed bonus, the upper limit is 20%)\n#F20#\n#F40##C0x5c9970#→improving 15% dodge for 2 rounds (additional 4% dodge is provided for every 10% speed bonus, the upper limit is 40%)",
		zawakeSimpleDesc_vn = "melhorando 10% de esquiva por 2 rodadas (4% de esquiva adicional é fornecida para cada 10% de bônus de velocidade, o limite superior é de 20%)\n#F20#\n#F40##C0x5c9970#→melhorando 15% de esquiva por 2 rodadas ( esquiva adicional de 4% é fornecida para cada bônus de velocidade de 10%, o limite superior é de 40%)",
		zawakeSimpleDesc_es = "mejorando un 10% de esquiva durante 2 rondas (se proporciona un 4% de esquiva adicional por cada 10% de bonificación de velocidad, el límite superior es 20%)\n#F20#\n#F40##C0x5c9970#→mejorando un 15% de esquiva durante 2 rondas ( Se proporciona un 4% adicional de esquiva por cada 10% de bonificación de velocidad, el límite superior es 40%).",
		id = 20228,
		zawakeEffectDesc_kr = "몬페르노가 하늘로 뛰어올라 화염바퀴로 변해 적의 단일 대상과 충돌하여 #C0xE69900#150%P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#를 유발하여 회피율이 15% 향상되었습니다. 2라운드(10% 속도 보너스마다 추가 4% 회피 제공, 상한은 40%), [burn]가 3라운드 동안 대상에 추가됩니다(화상: 부정적 효과, 최대 5회 중첩 가능, 각 레이어는 각 라운드가 시작되기 전에#C0xE69900#40%P.ATK#C0x5B545B#P.DMG를 유발합니다)",
		zawakeSimpleDesc_kr = "2라운드 동안 10% 회피 향상(10% 속도 보너스마다 추가 4% 회피 제공, 상한은 20%)\n#F20#\n#F40##C0x5c9970#→2라운드 동안 15% 회피 향상( 속도 보너스 10%당 회피 4% 추가 제공, 상한은 40%)"
	},
