		zawakeEffectDesc_kr = "추가 효과: [Burning Soul]에 들어가면 Chimchar는 각 적의 라운드가 시작되기 전에 손실된 HP의 40%를 재생할 수 있습니다. 각 라운드가 시작되기 전에 300 분노를 얻으세요. [Burning Soul] 상태일 때 적 전체에게 [Scoring Flame] 부여",
		zawakeSimpleDesc_kr = "각 라운드가 시작되기 전에 300의 분노를 얻으십시오. [Burning Soul] 상태일 때 적 전체에게 [Scoring Flame] 부여",
		zawakeEffectDesc_en = "Extra effect: when enters [Burning Soul], Chimchar can regenerate 40% of the lost HP before the start of each enemy’s round.Get 300 Rage before the start of each own round; When in [Burning Soul] state, inflict [Scoring Flame] to all enemies",
		describe_kr = [[
#L10#타오르는 심장:#L0#HP 손실이 60% 이상에 도달하면 HP 손실 비율의 확률로 HP가 가득 차서 부활하여 입장할 수 있습니다.[Burning soul] 
불타는 영혼, 특수 상태, 속도, CRI 비율 및 CRI DMG는 #C0x5C9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#, 행동 전 매 턴마다 최대 HP가 20%씩 감소합니다
#F20#
#F40##L10#이중 주먹 싸움:#L0#침차르일 때 발동 확률 50% 속도는 대상의 속도보다 75% 더 높습니다(영혼을 매장하는 경우 100%). 쌍권투 발동 시 #C0x3D8A99#SP.ATK#C0x5B545B# 과 동일한 스킬로 추가 공격을 가합니다.]],
		zawakeSimpleDesc_vn = "Ganhe 300 Rage antes do início de cada rodada; Quando estiver no estado [Burning Soul], inflija [Scoring Flame] a todos os inimigos",
		zawakeSimpleDesc_id = "Dapatkan 300 Rage sebelum memulai setiap putaran; Ketika dalam kondisi [Burning Soul], berikan [Scoring Flame] ke semua musuh",
		starEffectDesc_vn = "Efeito extra: ao entrar em [Burning Soul], Infernape pode regenerar 40% do HP perdido antes do início do turno de cada inimigo",
		zawakeSimpleDesc_es = "Obtén 300 de ira antes del inicio de cada ronda; Cuando estés en el estado [Burning Soul], inflige [Scoring Flame] a todos los enemigos.",
		describe_th = [[
#L10#Blazing Heart:#L0#HP สูญเสียถึง 60% หรือมากกว่า มีความเป็นไปได้ที่สัดส่วนการสูญเสีย HP จะฟื้นคืนชีพด้วย HP เต็มและเข้าสู่ [Burning soul] 
 วิญญาณที่ลุกไหม้ สถานะพิเศษ ความเร็ว อัตรา CRI และ CRI DMG นั้น เพิ่มขึ้น#C0x5C9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# HP สูงสุดลดลง 20% ทุกเทิร์นก่อนดำเนินการ
#F20#
#F40##L10#การต่อสู้ด้วยกำปั้นคู่:#L0#โอกาส 50% ที่จะทริกเกอร์เมื่อชิมชาร์ ความเร็วสูงกว่าความเร็วของเป้าหมาย 75% (100% สำหรับการขุดวิญญาณ) เมื่อการต่อสู้ด้วยหมัดคู่เกิดขึ้น การโจมตีพิเศษด้วยทักษะเดียวกัน #C0x3D8A99#SP.ATK#C0x5B545B# จะเกิดขึ้น]],
		starEffectDesc_en = "Extra effect: when enters [Burning Soul], Infernape can regenerate 40% of the lost HP before the start of each enemy’s turn",
		id = 20236
	},
	[20237] = {
		zawakeEffectDesc_id = "Infernape mengayunkan tinju api yang membara untuk menyerang target tunggal musuh, menyebabkan#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, lalu meningkatkan dirinya sendiri 12% P.ATK dan 15 % kecepatan untuk 3 putaran (hingga 4 lapisan)",
		zawakeEffectDesc_vn = "Infernape balança um punho de chama escaldante para atacar o único alvo inimigo, causando #C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, e então melhorando 12% P.ATK e 15 % de velocidade por 3 rodadas (até 4 camadas)",
		zawakeEffectDesc_es = "Infernape balancea un puño de llamas abrasadoras para atacar al único objetivo enemigo, causando#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, y luego mejorándose a sí mismo 12% P.ATK y 15 % de velocidad para 3 rondas (hasta 4 capas)",
		zawakeEffectDesc_en = "Infernape swings a scorching flame fist to attack the enemy single target, causing#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#, and then improving itself 12% P.ATK and 15% speed for 3 rounds (up to 4 layers)",
