	[22423] = {
		describe_th = "ลูคาริโอกระโดดและรวบรวมพลังงานเพื่อโจมตีศัตรูเป้าหมายเดียวด้วยโฟกัสบลาสต์ สร้าง#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B# และรับประกันการโจมตีสำหรับท่านี้ หากเป้าหมายยังมีชีวิตอยู่ โดยที่มันยังคงอยู่ในคลื่นพลังงานของลูคาริโอ ลูคาริโอจะทำการโจมตีอีกครั้งก่อนที่เป้าหมายจะเคลื่อนไหว สร้างความเสียหาย 35% ของท่าอัลติเมท",
		zawakeEffectDesc_vn = "Lucario salta e reúne energia para atacar um único alvo inimigo com Focus Blast, distribuindo#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, e garante um acerto para este movimento. Se o alvo ainda estiver vivo, como permanece na onda de energia de Lucario, Lucario desferirá outro ataque antes do alvo fazer um movimento, causando 35% do dano da Ult Skill e restaurando a mesma quantidade de HP",
		simDesc_es = "Lucario salta y reúne energía para atacar a un solo objetivo enemigo con Focus Blast, y garantiza un golpe para este movimiento. Si el objetivo todavía está vivo, ya que permanece en la onda de energía de Lucario, Lucario realizará otro ataque antes de que el objetivo haga un movimiento, causando algo de daño del movimiento definitivo.",
		describe_es = "Lucario salta y reúne energía para atacar a un solo objetivo enemigo con Focus Blast, causando#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, y garantiza un golpe para este movimiento. Si el objetivo todavía está vivo, ya que permanece en la onda de energía de Lucario, Lucario realizará otro ataque antes de que el objetivo haga un movimiento, causando un 35% de daño del movimiento definitivo.",
		zawakeEffectDesc_th = "ลูคาริโอกระโดดและรวบรวมพลังงานเพื่อโจมตีศัตรูเป้าหมายเดียวด้วยโฟกัสบลาสต์ สร้าง#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B# และรับประกันการโจมตีสำหรับท่านี้ หากเป้าหมายยังมีชีวิตอยู่ เนื่องจากยังคงอยู่ในคลื่นพลังงานของ Lucario Lucario จะทำการโจมตีอีกครั้งก่อนที่เป้าหมายจะเคลื่อนที่ สร้างความเสียหาย 35% ของทักษะ Ult และฟื้นฟู HP ในปริมาณเท่าเดิม",
		starEffectDesc_id = "Efek tambahan: Gelombang energi menimbulkan kerusakan tambahan sebesar 35% pada gerakan Ultimate saat ini",
		starEffectDesc_es = "Efecto adicional: la onda de energía inflige un 35% de daño adicional en el movimiento definitivo actual.",
		zawakeSimpleDesc_en = "dealing 35% damage of the Ult Skill \n#F20#\n#F40##C0x5c9970#→dealing 35% damage of the Ult Skill and restore the same amount HP",
		describe_vn = "Lucario salta e reúne energia para atacar um único alvo inimigo com Focus Blast, distribuindo#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, e garante um acerto para este movimento. Se o alvo ainda estiver vivo, pois permanece na onda de energia de Lucario, Lucario desferirá outro ataque antes que o alvo faça um movimento, causando 35% do dano do movimento Ultimate.",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: คลื่นพลังงานสร้างความเสียหายเพิ่มเติม 35% ในท่าไม้ตายปัจจุบัน",
		starEffectDesc_vn = "Efeito adicional: Onda de energia causa 35% de dano extra no movimento Ultimate atual",
		zawakeEffectDesc_kr = "루카리오가 뛰어올라 에너지를 모아 집중 폭발로 단일 적 대상을 공격하며#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#를 가하고, 이 동작에 대한 명중을 보장합니다. 대상이 아직 살아 있으면 루카리오의 에너지 파동에 남아 있어 대상이 움직이기 전에 루카리오가 추가 공격을 가해 궁극기 스킬의 35% 대미지를 주고 같은 양의 HP를 회복합니다.",
		describe_en = "Lucario jumps up and gathers energy to attack a single enemy target with Focus Blast, dealing#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, and guarantees a hit for this move. If the target is still alive, as it remains in Lucario's energy wave, Lucario will deal another attack before the target makes a move, dealing 35% damage of the Ultimate move.",
		zawakeEffectDesc_id = "Lucario melompat dan mengumpulkan energi untuk menyerang satu target musuh dengan Focus Blast, menimbulkan#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, dan menjamin pukulan untuk gerakan ini. Jika target masih hidup, karena masih berada dalam gelombang energi Lucario, Lucario akan memberikan serangan lagi sebelum target bergerak, memberikan 35% damage dari Skill Ult dan memulihkan HP dalam jumlah yang sama.",
		describe_id = "Lucario melompat dan mengumpulkan energi untuk menyerang satu target musuh dengan Focus Blast, menimbulkan#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, dan menjamin pukulan untuk gerakan ini. Jika target masih hidup, karena masih berada dalam gelombang energi Lucario, Lucario akan memberikan serangan lagi sebelum target bergerak, menimbulkan 35% damage dari gerakan Ultimate.",
		simDesc_en = "Lucario jumps up and gathers energy to attack a single enemy target with Focus Blast, and guarantees a hit for this move. If the target is still alive, as it remains in Lucario's energy wave, Lucario will deal another attack before the target makes a move, dealing some damage of the Ultimate move.",
		simDesc_vn = "Lucario salta e reúne energia para atacar um único alvo inimigo com Focus Blast, e garante um acerto para este movimento. Se o alvo ainda estiver vivo, pois permanece na onda de energia de Lucario, Lucario desferirá outro ataque antes que o alvo faça um movimento, causando algum dano do movimento Ultimate.",
		describe_kr = "루카리오가 뛰어올라 에너지를 모아 집중 폭발로 단일 적 대상을 공격하며#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#를 가하고, 이 동작에 대한 명중을 보장합니다. 대상이 아직 살아 있으면 루카리오의 에너지 파동에 남아 있기 때문에 루카리오는 대상이 움직이기 전에 또 다른 공격을 가해 궁극기 피해량의 35%를 입힙니다.",
		simDesc_th = "Lucario กระโดดขึ้นและรวบรวมพลังงานเพื่อโจมตีศัตรูเป้าหมายเดียวด้วย Focus Blast และรับประกันการโจมตีสำหรับท่านี้ หากเป้าหมายยังมีชีวิตอยู่ เนื่องจากยังคงอยู่ในคลื่นพลังงานของ Lucario Lucario จะทำการโจมตีอีกครั้งก่อนที่เป้าหมายจะเคลื่อนที่ สร้างความเสียหายบางส่วนจากท่า Ultimate",
		zawakeEffectDesc_es = "Lucario salta y reúne energía para atacar a un solo objetivo enemigo con Focus Blast, causando#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, y garantiza un golpe para este movimiento. Si el objetivo todavía está vivo, ya que permanece en la onda de energía de Lucario, Lucario realizará otro ataque antes de que el objetivo haga un movimiento, causando un 35% de daño de la habilidad definitiva y restaurando la misma cantidad de HP.",
		starEffectDesc_kr = "추가 효과: 에너지 파동이 현재 궁극기 공격에서 35%의 추가 피해를 입힙니다.",
		zawakeEffectDesc_en = "Lucario jumps up and gathers energy to attack a single enemy target with Focus Blast, dealing#C0x3D8A99#480% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#SP.DMG#C0x5B545B#, and guarantees a hit for this move. If the target is still alive, as it remains in Lucario's energy wave, Lucario will deal another attack before the target makes a move, dealing 35% damage of the Ult Skill and restore the same amount HP",
		simDesc_kr = "루카리오가 뛰어올라 에너지를 모아 집중 폭발로 적 하나를 공격하고, 명중을 보장합니다. 대상이 아직 살아 있으면 루카리오의 에너지 파동에 남아 있기 때문에 루카리오는 대상이 움직이기 전에 또 다른 공격을 가하여 궁극기 피해를 입힙니다.",
		zawakeSimpleDesc_th = "สร้างความเสียหาย 35% ของทักษะ Ult \n#F20#\n#F40##C0x5c9970# →สร้างความเสียหาย 35% ของทักษะ Ult และฟื้นฟู HP ในปริมาณเท่าเดิม",
		zawakeSimpleDesc_kr = "울트 스킬 35% 데미지를 줍니다 \n#F20#\n#F40##C0x5c9970#→울트 스킬의 35% 데미지를 주고 같은 양의 HP를 회복합니다",
		starEffectDesc_en = "Additional effect: Energy wave deals extra 35% damage in the current Ultimate move",
		zawakeSimpleDesc_vn = "causando 35% de dano da Ult Skill \n#F20#\n#F40##C0x5c9970#→causando 35% de dano da Ult Skill e restaurando a mesma quantidade de HP",
		zawakeSimpleDesc_id = "menimbulkan 35% damage Skill Ult \n#F20#\n#F40##C0x5c9970#→menimbulkan 35% damage Skill Ult dan memulihkan HP dalam jumlah yang sama",
		id = 22423,
		zawakeSimpleDesc_es = "inflige un 35 % de daño de la habilidad definitiva \n#F20#\n#F40##C0x5c9970# → inflige un 35 % de daño de la habilidad definitiva y restaura la misma cantidad de HP",
		simDesc_id = "Lucario melompat dan mengumpulkan energi untuk menyerang satu target musuh dengan Focus Blast, dan menjamin pukulan untuk gerakan ini. Jika target masih hidup, karena masih berada dalam gelombang energi Lucario, Lucario akan memberikan serangan lagi sebelum target bergerak, memberikan sejumlah kerusakan pada gerakan Ultimate."
	},
