	[23653] = {
		describe_th = "โจมตีศัตรูด้วย SP.DEF ต่ำสุด",
		describe_en = "Attacks the enemy with the lowest SP.DEF",
		simDesc_es = "Palkia aparece desde otra dimensión, ataca al enemigo de retaguardia y ataca con Spacial Rend. (Seleccione el objetivo de línea de rugido con el SP.DEF más bajo en el modo Auto Battle). Inflige SP.DMG y fortalece los efectos espaciales. Si el objetivo queda fuera de combate, transfiere la cantidad de daño superada a un enemigo restante aleatorio.",
		describe_es = "Ataca al enemigo con el SP.DEF más bajo.",
		starEffectDesc_vn = "Após este Ultimate, você entrará no estado Hideaway e invocará uma Ilusão no local",
		starEffectDesc_id = "Setelah Ultimate ini, Anda akan memasuki kondisi Hideaway dan memanggil Illusion di tempat",
		starEffectDesc_es = "Después de este Ultimate, entrarás en el estado Hideaway y convocarás una ilusión en el acto.",
		zawakeSimpleDesc_en = "Additional Effect:Dispell 2 Defensive Buff of target\n The overflow DMG can be additionally directed to the enemy, and the transfer DMG ratio of the additionally selected target is 15%",
		describe_vn = "Ataca o inimigo com o menor SP.DEF",
		starEffectDesc_th = "หลังจากท่าไม้ตายนี้ คุณจะเข้าสู่สถานะ Hideaway และเรียกภาพลวงตาขึ้นมาทันที",
		zawakeSimpleDesc_th = "เอฟเฟกต์เพิ่มเติม:ปัดเป่าบัฟป้องกัน 2 อันของเป้าหมาย\n DMG ที่ล้นสามารถพุ่งตรงไปยังศัตรูเพิ่มเติมได้ และอัตราส่วน DMG การถ่ายโอนของเป้าหมายที่เลือกเพิ่มเติมคือ 15%",
		zawakeSimpleDesc_kr = "추가 효과:대상의 방어 버프 2개 해제\n 오버플로우 데미지는 추가로 적에게 향할 수 있으며, 추가로 선택한 대상의 전이 데미지 비율은 15%입니다.",
		zawakeSimpleDesc_vn = "Efeito Adicional:Dissipar 2 Bônus Defensivos do alvo\n O DMG de estouro pode ser direcionado adicionalmente para o inimigo, e a taxa de transferência de DMG do alvo adicionalmente selecionado é de 15%",
		zawakeSimpleDesc_id = "Efek Tambahan: Menghilangkan 2 Buff Defensif target\n DMG tambahan dapat diarahkan ke musuh, dan rasio DMG transfer dari target tambahan yang dipilih adalah 15%",
		describe_id = "Menyerang musuh dengan SP.DEF terendah",
		simDesc_en = "Palkia appears from another dimension, takes the rear-line enemy in, and attacks with Spacial Rend. (Select the roar-line target with the lowest SP.DEF in the Auto Battle mode). Inflicts SP.DMG and strengthens the space effects. If the target is knocked out, transfers the surpassed amount of DMG to a random remaining enemy",
		simDesc_vn = "Palkia aparece de outra dimensão, captura o inimigo da retaguarda e ataca com Spacial Rend. (Selecione o alvo da linha de rugido com o SP.DEF mais baixo no modo Auto Battle). Inflige SP.DMG e fortalece os efeitos espaciais. Se o alvo for nocauteado, transfere a quantidade de DANO superada para um inimigo restante aleatório",
		describe_kr = "SP.DEF가 가장 낮은 적을 공격합니다.",
		simDesc_th = "Palkia ปรากฏตัวจากอีกมิติหนึ่ง รับศัตรูแนวหลังเข้ามา และโจมตีด้วย Spacial Rend (เลือกเป้าหมายที่มี SP.DEF ต่ำสุดในโหมด Auto Battle) สร้างความเสียหาย SP.DMG และเพิ่มเอฟเฟกต์พื้นที่ หากเป้าหมายถูกทำให้ล้มลง จะถ่ายโอนความเสียหายที่เกินกว่านั้นไปยังศัตรูแบบสุ่มที่เหลือ",
		zawakeSimpleDesc_es = "Efecto adicional: Disipar 2 mejoras defensivas del objetivo\n El DAÑO desbordado se puede dirigir adicionalmente al enemigo, y la proporción de DAÑO de transferencia del objetivo seleccionado adicionalmente es del 15%",
		starEffectDesc_kr = "이 궁극기 이후에는 은신처 상태에 들어가 그 자리에서 환상을 소환하게 됩니다.",
		simDesc_kr = "다른 차원에서 나타난 펄기아는 후방의 적을 끌어들여 스페이셜 렌드로 공격한다. (자동 전투 모드에서는 SP.DEF가 가장 낮은 포효 대상을 선택하세요.) SP.DMG를 가하고 공간 효과를 강화합니다. 대상이 쓰러지면 초과한 피해량을 무작위로 남은 적에게 전달합니다.",
		starEffectDesc_en = "After this Ultimate, you will enter Hideaway state and summon an Illusion on the spot",
		id = 23653,
		simDesc_id = "Palkia muncul dari dimensi lain, menyerang musuh di garis belakang, dan menyerang dengan Spacial Rend. (Pilih target garis gemuruh dengan SP.DEF terendah dalam mode Pertempuran Otomatis). Menimbulkan SP.DMG dan memperkuat efek luar angkasa. Jika target tersingkir, mentransfer jumlah DMG yang melebihi jumlah tersebut ke musuh acak yang tersisa"
	},
	[23656] = {
		starEffectDesc_en = "When entering [Hideaway] state, it will create an Illusion on the spot (Palkia has 100% of its stats and can use its basic skills, but has no additional effects. Palkia applies the basic attack on the target with lowest SP.DEF once and then disappears)",
		describe_vn = "Ilusão",
		describe_th = "ภาพลวงตา",
		starEffectDesc_kr = "[Hideaway] 상태 진입 시 그 자리에서 환영을 생성합니다. (펄키아는 능력치 100%로 기본 스킬을 사용할 수 있지만, 추가 효과는 없습니다. 펄기아는 SP.DEF가 가장 낮은 대상에게 기본 공격을 1회 적용합니다. 그러다가 사라짐)",
		describe_es = "Espejismo",
		describe_en = "Illusion",
		zawakeSimpleDesc_vn = "\nBuff de Efeito: Duas rodadas de ação depois de [Hideaway], pode ser imune a Debuff e o DMG causado não pode ser evitado, com 10% de Roubo de Saúde por 1 rodada.",
		zawakeSimpleDesc_en = "\nEffect Buff: Two action round after [Hideaway], can immune to Debuff and the DMG caused can not be evaded, with 10% Health Steal for 1 round.",
		starEffectDesc_es = "Al entrar en el estado [Hideaway], creará una ilusión en el acto (Palkia tiene el 100% de sus estadísticas y puede usar sus habilidades básicas, pero no tiene efectos adicionales. Palkia aplica el ataque básico al objetivo con SP.DEF más bajo una vez). y luego desaparece)",
		starEffectDesc_th = "เมื่อเข้าสู่สถานะ [Hideaway] มันจะสร้างภาพลวงตาขึ้นมาทันที (Palkia มีสถิติ 100% และสามารถใช้ทักษะพื้นฐานได้ แต่ไม่มีเอฟเฟกต์เพิ่มเติม Palkia จะใช้การโจมตีพื้นฐานกับเป้าหมายที่มี SP.DEF ต่ำสุดหนึ่งครั้ง แล้วก็หายไป)",
		zawakeSimpleDesc_id = "\nEffect Buff: Dua ronde aksi setelah [Hideaway], dapat kebal terhadap Debuff dan DMG yang ditimbulkan tidak dapat dihindari, dengan 10% Health Steal selama 1 ronde.",
		zawakeSimpleDesc_es = "\nEfecto Buff: Dos rondas de acción después de [Hideaway], puede ser inmune a la Desventaja y el DAÑO causado no se puede evadir, con un 10% de Robo de Salud durante 1 ronda.",
		describe_id = "Ilusi",
		zawakeSimpleDesc_kr = "\n효과 버프: [Hideaway] 이후 2액션 라운드, 디버프에 면역이 되고 발생한 데미지를 회피할 수 없으며 1라운드 동안 10% 체력 강탈이 가능합니다.",
		describe_kr = "환각",
		starEffectDesc_vn = "Ao entrar no estado [Hideaway], ele criará uma Ilusão no local (Palkia tem 100% de suas estatísticas e pode usar suas habilidades básicas, mas não tem efeitos adicionais. Palkia aplica o ataque básico no alvo com menor SP.DEF uma vez e depois desaparece)",
		zawakeSimpleDesc_th = "\nเอฟเฟกต์บัฟ: สองรอบหลังจาก [Hideaway] สามารถต้านทานดีบัฟได้ และความเสียหายที่เกิดขึ้นนั้นไม่สามารถหลบเลี่ยงได้ พร้อมขโมยสุขภาพ 10% เป็นเวลา 1 รอบ",
		starEffectDesc_id = "Saat memasuki kondisi [Hideaway], ia akan menciptakan Ilusi di tempat (Palkia memiliki 100% statistiknya dan dapat menggunakan keterampilan dasar, namun tidak memiliki efek tambahan. Palkia menerapkan serangan dasar pada target dengan SP.DEF terendah satu kali dan kemudian menghilang)",
		id = 23656
	},
