	[23813] = {
		describe_th = "เรจิจิกัสค่อยๆ ตื่นจากพื้น และปล่อยคลื่นกระแทกหลายลูกเพื่อบดขยี้ศัตรูแถวหน้า สร้างความเสียหาย#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B# ซึ่งเป็น HP สูงสุดในปัจจุบันที่สูงกว่า มากกว่า HP สูงสุดของเป้าหมาย โบนัสความเสียหายเพิ่มเติมที่สูงกว่าในทักษะขั้นสูงสุดนี้ ความเสียหายเพิ่มเติมสูงสุด 200% \nสร้างความเสียหายจริงเพิ่มเติมด้วยจำนวน Regigigas 15% HP สูงสุดต่อเป้าหมาย (เพิกเฉยโล่) หลังจากทักษะขั้นสูงสุด",
		zawakeEffectDesc_vn = "Regigigas desperta lentamente do solo e lança múltiplas ondas de choque para esmagar os inimigos na primeira fila, distribuindo#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, o HP máximo atual mais alto do que o HP máximo do alvo, o maior dano bônus adicional nesta habilidade final, até 200% de dano adicional\nCausa dano verdadeiro adicional com a quantidade de Regigigas 20% de HP máximo para o alvo (Ignorar Escudo) após a habilidade final \nAntes do alvo na próxima rodada de movimento, distribua 60% de DMG desta Ult Skill ao alvo novamente",
		simDesc_es = "Slaking lanza un golpe definitivo que hace volar a un solo objetivo enemigo, sin tener en cuenta parte de su P.DEF. Se vuelve demasiado vago para moverse después de realizar el ataque.",
		describe_es = "Regigigas se despierta lentamente del suelo y lanza múltiples ondas de choque para aplastar a los enemigos en la primera fila, causando#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, el HP máximo actual más alto. que el HP máximo del objetivo, mayor daño adicional adicional en esta habilidad definitiva, hasta un 200 % de daño adicional.\nInflige daño verdadero adicional con la cantidad de Regigigas 15 % de HP máximo al objetivo (Ignorar escudo) después de la habilidad definitiva",
		zawakeEffectDesc_th = "เรจิจิกัสค่อยๆ ตื่นจากพื้น และปล่อยคลื่นกระแทกหลายลูกเพื่อบดขยี้ศัตรูแถวหน้า สร้างความเสียหาย#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B# ซึ่งเป็น HP สูงสุดในปัจจุบันที่สูงกว่า มากกว่า HP สูงสุดของเป้าหมาย โบนัสความเสียหายเพิ่มเติมที่สูงกว่าในทักษะขั้นสูงสุดนี้ ความเสียหายเพิ่มเติมสูงสุด 200% \nสร้างความเสียหายจริงเพิ่มเติมด้วยจำนวน Regigigas 20% HP สูงสุดต่อเป้าหมาย (เพิกเฉยโล่) หลังจากทักษะขั้นสูงสุด \nก่อนเป้าหมาย รอบการเคลื่อนที่ครั้งถัดไป สร้างความเสียหาย 60% ของทักษะอัลติเมทนี้ให้กับเป้าหมายอีกครั้ง",
		starEffectDesc_id = "Efek Tambahan: Setelah setiap Skill Ultimate digunakan, menurunkan batas Kemarahan sebesar 250 secara permanen (Stack 3 kali paling banyak), sebelum setiap menggunakan Skill Ultimate, meningkatkan 20% bonus P.DMG secara permanen (Stack 3 kali paling banyak)",
		starEffectDesc_es = "Efecto adicional: después de lanzar cada habilidad definitiva, se reduce el límite de 250 de ira de forma permanente (se acumula 3 veces como máximo), antes de cada lanzamiento de habilidad definitiva, se aumenta un 20 % de bonificación de P.DMG de forma permanente (se acumula 3 veces más)",
		zawakeSimpleDesc_en = "#C0x5c9970#Before the target's next move round, deal 60% DMG of this Ult Skill to the target again",
		describe_vn = "Regigigas desperta lentamente do solo e lança múltiplas ondas de choque para esmagar os inimigos na primeira fila, distribuindo#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, o HP máximo atual mais alto do que o HP máximo do alvo, o maior dano bônus adicional nesta habilidade final, até 200% de dano adicional\nCausa dano verdadeiro adicional com a quantidade de Regigigas 15% de HP máximo para o alvo (Ignorar Escudo) após a habilidade final",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: หลังจากร่าย Ultimate Skill แต่ละครั้ง จะลดขีดจำกัดความโกรธลง 250 อันอย่างถาวร (ซ้อนได้สูงสุด 3 ครั้ง) ก่อนร่าย Ultimate Skill แต่ละครั้ง เพิ่มโบนัส P.DMG ตัวเอง 20% อย่างถาวร (ซ้อนสูงสุด 3 เท่า)",
		starEffectDesc_vn = "Efeito Adicional: Após cada Ultimate Skill lançada, reduz o limite de 250 de Fúria permanentemente (Acumula 3 vezes mais), antes de cada Ultimate Skill lançada, aumenta 20% do bônus P.DMG permanentemente (Acumula 3 vezes mais)",
		zawakeEffectDesc_kr = "레지기가스는 천천히 지상에서 깨어나 다수의 충격파를 발사해 앞줄의 적을 박살내며 #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, 현재 최대 HP가 높을수록 공격합니다. 대상의 최대 HP보다 높을수록 본 얼티밋 스킬의 추가 보너스 데미지는 최대 200% 추가 데미지\n 얼티밋 스킬 후 대상(방패 무시)에게 최대 HP의 20%인 레지기가스 양으로 추가 트루 데미지를 줍니다 \n 대상의 전 다음 이동 라운드에 이 궁극기 스킬의 60% DMG를 대상에게 다시 가합니다.",
		describe_en = "Regigigas slowly awake from the ground, and launches multiple shock wave to crush enemies in front row, dealing#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, the higher  current Max HP than target's Max HP, the higher additional bonus damage in this Ultimate Skill, up to 200% additional damage\nDeals additional true damage with the amount of Regigigas 15% Max HP to target(Ignore Shield) after Ultimate Skill",
		zawakeEffectDesc_id = "Regigigas perlahan bangkit dari tanah, dan meluncurkan beberapa gelombang kejut untuk menghancurkan musuh di barisan depan, menyebabkan#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, semakin tinggi Max HP saat ini daripada Max HP target, semakin tinggi bonus damage tambahan pada Skill Ultimate ini, hingga 200% damage tambahan\nMenimbulkan true damage tambahan sebesar Regigigas 20% Max HP ke target (Abaikan Shield) setelah Skill Ultimate \nSebelum target putaran gerakan selanjutnya, menimbulkan 60% DMG dari Skill Ult ini ke target lagi",
		describe_id = "Regigigas perlahan bangkit dari tanah, dan meluncurkan beberapa gelombang kejut untuk menghancurkan musuh di barisan depan, menyebabkan#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, semakin tinggi Max HP saat ini daripada Max HP target, semakin tinggi bonus damage tambahan pada Skill Ultimate ini, damage tambahan hingga 200%\nMenimbulkan true damage tambahan sebesar Regigigas 15% Max HP ke target (Abaikan Shield) setelah Skill Ultimate",
		simDesc_en = "Slaking lands an ultimate punch making a single enemy target fly, while disregarding some of its P.DEF. It becomes too lazy to move after making the attack.",
		simDesc_vn = "Slaking acerta um soco definitivo fazendo um único alvo inimigo voar, enquanto desconsidera parte de seu P.DEF. Fica com preguiça de se mover depois de fazer o ataque.",
		describe_kr = "레지기가스는 천천히 지상에서 깨어나 다수의 충격파를 발사해 앞줄의 적을 박살내며 #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, 현재 최대 HP가 높을수록 공격합니다. 대상의 최대 HP보다 높을수록 해당 얼티밋 스킬의 추가 보너스 데미지가 최대 200% 추가 데미지\n 얼티밋 스킬 후 대상(방패 무시)에게 레지기가스의 최대 HP 15%만큼 추가 고정 데미지를 줍니다.",
		simDesc_th = "Slaking โจมตีด้วยหมัดขั้นสุดยอดทำให้เป้าหมายศัตรูตัวเดียวบินได้ โดยไม่สนใจ P.DEF บางส่วน มันขี้เกียจเกินไปที่จะเคลื่อนไหวหลังจากทำการโจมตี",
		zawakeEffectDesc_es = "Regigigas se despierta lentamente del suelo y lanza múltiples ondas de choque para aplastar a los enemigos en la primera fila, causando#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#P.DMG#C0x5B545B#, el HP máximo actual más alto. que el HP máximo del objetivo, mayor daño adicional adicional en esta habilidad definitiva, hasta un 200 % de daño adicional.\nInflige daño verdadero adicional con la cantidad de Regigigas 20 % de HP máximo al objetivo (Ignorar escudo) después de la habilidad definitiva. \nAntes del siguiente movimiento del objetivo. ronda, inflige el 60% de DAÑO de esta Habilidad Definitiva al objetivo nuevamente",
