	[24012] = {
		zawakeEffectDesc_es = "Cresselia toma prestada la fuerza de la luz de la luna para otorgarle HP a un enemigo de primera línea (#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) y lo arrastra al estado [Sweet Dream]. Si el aliado se despierta en la luna nueva, restaura 400 de ira; Si está en luna llena, previene DMG por 1 vez.",
		zawakeEffectDesc_vn = "Cresselia pega emprestada a força do luar para conceder HP a um inimigo da linha de frente (#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) e o arrasta para o status [Sweet Dream]. Se o aliado acordar na lua nova, restaura 400 de Fúria; Se for lua cheia, evita DMG por 1 vez",
		describe_th = "Cresselia ยืมความแข็งแกร่งจากแสงจันทร์เพื่อให้ศัตรูแนวหน้า (#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP และลากมันเข้าสู่สถานะ [Sweet Dream] หากพันธมิตรตื่นขึ้นมาในคืนพระจันทร์ใหม่ ฟื้นฟู Rage 400 หน่วย หากถึงพระจันทร์เต็มดวง จะป้องกัน DMG 1 ครั้ง",
		zawakeEffectDesc_kr = "크레세리아는 달빛의 힘을 빌려 최전선의 적(#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$)의 HP를 부여하고 [Sweet Dream] 상태로 끌어옵니다. 아군이 초승달에 깨어날 경우 400의 분노를 회복합니다. 보름달일 경우 1회 데미지 방지",
		zawakeEffectDesc_th = "Cresselia ยืมความแข็งแกร่งจากแสงจันทร์เพื่อให้ศัตรูแนวหน้า (#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP และลากมันเข้าสู่สถานะ [Sweet Dream] หากพันธมิตรตื่นขึ้นมาในพระจันทร์ใหม่ ฟื้นฟู Rage 400 หน่วย หากถึงพระจันทร์เต็มดวง จะป้องกัน DMG 1 ครั้ง",
		describe_en = "Cresselia borrows strength from moonlight to grant a front-line enemy (#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP and drags it into the [Sweet Dream] status. If the ally wakes up at the new moon, restores 400 Rage; If at the full moon, prevents DMG for 1 time",
		describe_es = "Cresselia toma prestada la fuerza de la luz de la luna para otorgar HP a un enemigo de primera línea (#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP y lo arrastra al estado [Sweet Dream]. Si el aliado se despierta en la luna nueva, restaura 400 de ira; Si está en luna llena, previene DMG por 1 vez.",
		zawakeSimpleDesc_en = "Healing ratio increased by 40%",
		describe_vn = "Cresselia pega emprestada a força do luar para conceder HP a um inimigo da linha de frente (#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) e o arrasta para o status [Sweet Dream]. Se o aliado acordar na lua nova, restaura 400 de Fúria; Se for lua cheia, evita DMG por 1 vez",
		zawakeEffectDesc_en = "Cresselia borrows strength from moonlight to grant a front-line enemy (#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP and drags it into the [Sweet Dream] status. If the ally wakes up at the new moon, restores 400 Rage; If at the full moon, prevents DMG for 1 time",
		zawakeSimpleDesc_vn = "Proporção de cura aumentada em 40%",
		zawakeSimpleDesc_id = "Rasio penyembuhan meningkat sebesar 40%",
		zawakeSimpleDesc_es = "La tasa de curación aumentó en un 40%.",
		describe_id = "Cresselia meminjam kekuatan dari cahaya bulan untuk memberikan musuh di garis depan (#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP dan menyeretnya ke status [Sweet Dream]. Jika sekutu terbangun di bulan baru, memulihkan 400 Kemarahan; Jika saat bulan purnama, mencegah DMG sebanyak 1 kali",
		zawakeSimpleDesc_kr = "치유율 40% 증가",
		zawakeEffectDesc_id = "Cresselia meminjam kekuatan dari cahaya bulan untuk memberikan musuh di garis depan (#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$) HP dan menyeretnya ke status [Sweet Dream]. Jika sekutu terbangun di bulan baru, memulihkan 400 Kemarahan; Jika saat bulan purnama, mencegah DMG sebanyak 1 kali",
		describe_kr = "크레세리아는 달빛의 힘을 빌려 최전선의 적(#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$)의 HP를 부여하고 [Sweet Dream] 상태로 끌어옵니다. 아군이 초승달에 깨어날 경우 400의 분노를 회복합니다. 보름달일 경우 1회 데미지 방지",
		zawakeSimpleDesc_th = "อัตราการรักษาเพิ่มขึ้น 40%",
