	[24422] = {
		zawakeEffectDesc_kr = "#C0xC0C0C0#날 수 없나요? 정말 안타깝습니다! #C0x5B545B#\n#F10#\n#F40#셰이민이 나뭇잎 폭풍을 일으켜 적 1명을 집어삼켜 #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#를 입힙니다. 1라운드 동안 적을 [Constrict]할 확률은 100%입니다. 셰이민 라인에 있는 아군에게 무작위 부정적인 효과 2개를 무작위 버프 2개로 바꾸고 2라운드 동안 피해량 보너스와 피해량 감소를 15% 증가시킵니다.",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Você não consegue voar? Que pena! #C0x5B545B#\n#F10#\n#F40#Shaymin cria uma tempestade de folhas para devorar 1 inimigo, infligindo #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. Há 100% de chance de [Constrict] inimigo por 1 rodada. Transforma 2 efeitos negativos aleatórios em 2 buffs aleatórios para aliados na linha de Shaymin e aumenta 15% de bônus de DMG e redução de DMG por 2 rodadas.",
		simDesc_es = "Shaymin crea una tormenta de hojas para devorar a 1 enemigo e infligir SP.DMG. Convierte 1 efecto negativo aleatorio en 1 beneficio aleatorio para los aliados en la línea de Shaymin y aumenta su bonificación de daño y su reducción de daño.",
		describe_en = "#C0xC0C0C0#Can't you fly? What a pity! #C0x5B545B#\n#F10#\n#F40#Shaymin creates a leaf storm to devour 1 enemy, inflicting #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. There is a 100% chance to [Constrict] enemy for 1 round. Turns 2 random negative effect to 2 random buff for allies in Shaymin's line.",
		zawakeEffectDesc_th = "#C0xC0C0C0#บินไม่ได้เหรอ? น่าเสียดาย! #C0x5B545B#\n#F10#\n#F40#เชมินสร้างพายุใบไม้เพื่อกลืนกินศัตรู 1 ตัว สร้างความเสียหาย #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B# มีโอกาส 100% ที่จะ [Constrict] ศัตรู 1 รอบ เปลี่ยนเอฟเฟกต์ด้านลบแบบสุ่ม 2 อันเป็นบัฟสุ่ม 2 อันสำหรับพันธมิตรในแนวของ Shaymin และเพิ่มโบนัส DMG 15% และลด DMG เป็นเวลา 2 รอบ",
		describe_es = "#C0xC0C0C0#¿No puedes volar? ¡Qué lástima! #C0x5B545B#\n#F10#\n#F40#Shaymin crea una tormenta de hojas para devorar a 1 enemigo, infligiendo #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. Hay un 100% de probabilidad de [Constrict] enemigo durante 1 ronda. Convierte 2 efectos negativos aleatorios en 2 beneficios aleatorios para los aliados en la línea de Shaymin.",
		simDesc_vn = "Shaymin cria uma tempestade de folhas para devorar 1 inimigo, infligindo SP.DMG. Transforma 1 efeito negativo aleatório em 1 buff aleatório para aliados na linha de Shaymin e aumenta seu bônus de DMG e redução de DMG",
		zawakeSimpleDesc_en = "and allies in Shaymin's line increases 15% DMG bonus and DMG Reduction for 2 rounds.",
		describe_vn = "#C0xC0C0C0#Você não consegue voar? Que pena! #C0x5B545B#\n#F10#\n#F40#Shaymin cria uma tempestade de folhas para devorar 1 inimigo, infligindo #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. Há 100% de chance de [Constrict] inimigo por 1 rodada. Transforma 2 efeitos negativos aleatórios em 2 buffs aleatórios para aliados na linha de Shaymin.",
		zawakeEffectDesc_id = "#C0xC0C0C0#Tidak bisakah kamu terbang? Sayang sekali! #C0x5B545B#\n#F10#\n#F40#Shaymin menciptakan badai daun untuk melahap 1 musuh, menyebabkan #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. Ada peluang 100% untuk [Constrict] musuh selama 1 putaran. Mengubah 2 efek negatif acak menjadi 2 buff acak untuk sekutu di barisan Shaymin dan meningkatkan 15% bonus DMG dan Pengurangan DMG selama 2 ronde.",
		zawakeEffectDesc_es = "#C0xC0C0C0#¿No puedes volar? ¡Qué lástima! #C0x5B545B#\n#F10#\n#F40#Shaymin crea una tormenta de hojas para devorar a 1 enemigo, infligiendo #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. Hay un 100% de probabilidad de [Constrict] enemigo durante 1 ronda. Convierte 2 efectos negativos aleatorios en 2 beneficios aleatorios para los aliados en la línea de Shaymin y aumenta un 15% de bonificación de DAÑO y reducción de DAÑO durante 2 rondas.",
		describe_th = "#C0xC0C0C0#บินไม่ได้เหรอ? น่าเสียดาย! #C0x5B545B#\n#F10#\n#F40#เชมินสร้างพายุใบไม้เพื่อกลืนกินศัตรู 1 ตัว สร้างความเสียหาย #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B# มีโอกาส 100% ที่จะ [Constrict] ศัตรู 1 รอบ สุ่มเปลี่ยนเอฟเฟกต์ด้านลบ 2 อันเป็นบัฟสุ่ม 2 อันสำหรับพันธมิตรในแนวของ Shaymin",
		zawakeSimpleDesc_th = "และพันธมิตรในสายของ Shaymin จะเพิ่มโบนัส DMG 15% และลด DMG เป็นเวลา 2 รอบ",
		zawakeSimpleDesc_kr = "Shaymin 라인에 있는 아군은 2라운드 동안 데미지 보너스와 데미지 감소가 15% 증가합니다.",
		describe_id = "#C0xC0C0C0#Tidak bisakah kamu terbang? Sayang sekali! #C0x5B545B#\n#F10#\n#F40#Shaymin menciptakan badai daun untuk melahap 1 musuh, menimbulkan #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. Ada peluang 100% untuk [Constrict] musuh selama 1 putaran. Mengubah 2 efek negatif acak menjadi 2 buff acak untuk sekutu di barisan Shaymin.",
		simDesc_en = "Shaymin creates a leaf storm to devour 1 enemy, inflicting SP.DMG. Turns 1 random negative effect to 1 random buff for allies in Shaymin's line and increases their DMG Bonus and DMG Reduction",
		zawakeEffectDesc_en = "#C0xC0C0C0#Can't you fly? What a pity! #C0x5B545B#\n#F10#\n#F40#Shaymin creates a leaf storm to devour 1 enemy, inflicting #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#. There is a 100% chance to [Constrict] enemy for 1 round. Turns 2 random negative effect to 2 random buff for allies in Shaymin's line and increases 15% DMG bonus and DMG Reduction for 2 rounds.",
		describe_kr = "#C0xC0C0C0#날 수 없나요? 정말 안타깝습니다! #C0x5B545B#\n#F10#\n#F40#셰이민이 나뭇잎 폭풍을 일으켜 적 1명을 집어삼켜 #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*60)$)#C0xF13B54# SP.DMG#C0x5B545B#를 입힙니다. 1라운드 동안 적을 [Constrict]할 확률은 100%입니다. 셰이미 라인에 있는 아군에게 무작위 부정적인 효과 2개를 무작위 버프 2개로 바꿉니다.",
