	[24723] = {
		describe_th = "เสิร์ฟจะโปรยเมล็ดจากด้านบน ซึ่งจะเติบโตเป็นเถาวัลย์ขนาดใหญ่เมื่อกระทบพื้น สร้างความเสียหาย (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#และฝังเมล็ดไอวี่ไว้ใต้ศัตรูทุกตัว ซึ่ง [Coils] พวกมันเป็นเวลา 1 รอบหลังจากที่พวกมันเคลื่อนที่",
		zawakeEffectDesc_vn = "Efeito extra: Durante Ultimate Entanglement, absorve HP do alvo que é igual a 70% da soma de SP.DEF e P.DEF de Servine (este DMG é True DMG); Se ele já estiver cheio de HP, transfira a Cura transbordada para o aliado com menor HP",
		simDesc_es = "Servine hace llover semillas desde arriba, que crecen hasta convertirse en grandes enredaderas al tocar el suelo. Ataca a todos los enemigos y los enrolla.",
		describe_es = "Servine hace llover semillas desde arriba, que crecen hasta convertirse en grandes enredaderas al tocar el suelo. Inflige (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#y entierra una semilla de hiedra debajo de cada enemigo, que los [Coils] durante 1 ronda después de que se mueven.",
		zawakeEffectDesc_th = "เอฟเฟกต์พิเศษ: ในช่วง Ultimate Entanglement ดูดซับ HP จากเป้าหมายซึ่งเท่ากับ 70% ของผลรวมของ SP.DEF และ P.DEF ของ Servine (DMG นี้คือ True DMG) หาก HP เต็มแล้ว ให้โอนการรักษาที่ล้นออกมา ไปยังพันธมิตรที่มี HP ต่ำที่สุด",
		starEffectDesc_id = "Efek ekstra: Selama Keterikatan Ultimate, menyerap HP dari target yang setara dengan 60% dari jumlah SP.DEF dan P.DEF Servine (DMG ini adalah True DMG)",
		starEffectDesc_es = "Efecto adicional: Durante Ultimate Entanglement, absorbe HP del objetivo que es igual al 60% de la suma de SP.DEF y P.DEF de Servine (este DMG es True DMG)",
		zawakeSimpleDesc_en = "absorbs HP increase to 70%; If itself is alredady full of HP, transfer the overflowed Healing to the ally with lowest HP",
		describe_vn = "Servine chove sementes de cima, que se transformam em grandes vinhas ao atingir o solo. Inflige (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#e enterra uma semente de hera embaixo de cada inimigo, que os [Coils] por 1 rodada após eles se moverem",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: ในช่วง Ultimate Entanglement ดูดซับ HP จากเป้าหมายซึ่งเท่ากับ 60% ของผลรวมของ SP.DEF และ P.DEF ของ Servine (DMG นี้เป็น DMG จริง)",
		starEffectDesc_vn = "Efeito extra: Durante Ultimate Entanglement, absorve HP do alvo que é igual a 60% da soma de SP.DEF e P.DEF de Servine (este DMG é True DMG)",
		zawakeEffectDesc_kr = "추가 효과: Ultimate Entanglement 동안 Servine의 SP.DEF와 P.DEF 합계의 70%에 해당하는 HP를 대상으로부터 흡수합니다(이 DMG는 True DMG입니다). 이미 HP가 가득 차 있으면 오버플로된 치유를 이전합니다. HP가 가장 낮은 아군에게",
		describe_en = "Servine rains seeds from above, which grow into big vines when hitting the ground. Inflicts (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#and buries an ivy seed beneath every enemy, which [Coils] them for 1 round after they move",
		zawakeEffectDesc_id = "Efek ekstra: Selama Keterikatan Ultimate, menyerap HP dari target yang setara dengan 70% dari jumlah SP.DEF dan P.DEF Servine (DMG ini adalah True DMG); Jika dirinya sudah penuh dengan HP, mentransfer Penyembuhan yang melimpah kepada sekutu dengan HP terendah",
		describe_id = "Servine menghujani benih dari atas, yang tumbuh menjadi tanaman merambat besar ketika menyentuh tanah. Menimbulkan (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#dan mengubur benih ivy di bawah setiap musuh, yang [Coils] mereka selama 1 ronde setelah mereka bergerak",
		simDesc_en = "Servine rains seeds from above, which grow into big vines when hitting the ground. Attacks all enemies and coils them",
		simDesc_vn = "Servine chove sementes de cima, que se transformam em grandes vinhas ao atingir o solo. Ataca todos os inimigos e os enrola",
		describe_kr = "서바인은 위에서 씨앗을 뿌리는데, 씨앗이 땅에 닿으면 큰 덩굴로 자라납니다. (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#를 가하고 모든 적 밑에 담쟁이덩굴 씨앗을 묻어 이동 후 1라운드 동안 [Coils]합니다.",
		simDesc_th = "เสิร์ฟจะโปรยเมล็ดจากด้านบน ซึ่งจะเติบโตเป็นเถาวัลย์ขนาดใหญ่เมื่อกระทบพื้น โจมตีศัตรูทั้งหมดและขดพวกมัน",
		zawakeEffectDesc_es = "Efecto adicional: Durante Ultimate Entanglement, absorbe HP del objetivo que es igual al 70% de la suma de SP.DEF y P.DEF de Servine (este DMG es True DMG); si ya está lleno de HP, transfiere la curación desbordada. al aliado con menor HP",
		starEffectDesc_kr = "추가 효과 : Ultimate Entanglement 중, Servine의 SP.DEF와 P.DEF 합산의 60%에 해당하는 대상의 HP를 흡수합니다. (이 DMG는 True DMG입니다.)",
		zawakeEffectDesc_en = "Extra effect: During Ultimate Entanglement, absorbs HP from the target which is equal to 70% of the sum of Servine's SP.DEF and P.DEF (this DMG is True DMG);If itself is alredady full of HP, transfer the overflowed Healing to the ally with lowest HP",
		simDesc_kr = "서바인은 위에서 씨앗을 뿌리는데, 씨앗이 땅에 닿으면 큰 덩굴로 자라납니다. 적 전체를 공격하고 휘감는다",
		zawakeSimpleDesc_th = "ดูดซับ HP เพิ่มขึ้นเป็น 70%; หากตัวเองมี HP เต็มแล้ว ให้โอนการรักษาที่มากเกินไปไปยังพันธมิตรที่มี HP ต่ำที่สุด",
		zawakeSimpleDesc_kr = "HP 증가량을 70%까지 흡수합니다. 자신의 HP가 이미 가득 찬 경우, HP가 가장 낮은 아군에게 넘치는 힐링을 전달합니다.",
		starEffectDesc_en = "Extra effect: During Ultimate Entanglement, absorbs HP from the target which is equal to 60% of the sum of Servine's SP.DEF and P.DEF (this DMG is True DMG)",
		zawakeSimpleDesc_vn = "absorve aumento de HP para 70%; Se já estiver cheio de HP, transfira a cura transbordada para o aliado com menor HP",
		zawakeSimpleDesc_id = "menyerap peningkatan HP hingga 70%; Jika HPnya sudah penuh, transfer Healing yang melimpah ke sekutu dengan HP terendah",
		id = 24723,
		zawakeSimpleDesc_es = "absorbe el aumento de HP al 70%; Si ya está lleno de HP, transfiere la curación desbordada al aliado con menor HP.",
		simDesc_id = "Servine menghujani benih dari atas, yang tumbuh menjadi tanaman merambat besar ketika menyentuh tanah. Menyerang semua musuh dan menggulungnya"
	},
	[24724] = {
		id = 24724
