	[24726] = {
		describe_th = "ไม่รับบัฟใดๆ จากผู้อื่น หากได้รับผลด้านลบใดๆ จะเปลี่ยนให้เป็นบัฟแบบสุ่ม \n ทักษะออร่า: พันธมิตรประเภทหญ้าทั้งหมดจะได้รับ $(10+skillLevel*0.1-0.1)$% ความเสียหายเคลื่อนที่",
		zawakeEffectDesc_vn = "Efeito extra: Após desmaiar, remove 1 efeito negativo de cada aliado e todos os buffs serão copiados para todos os aliados por 2 rodadas",
		simDesc_es = "Convierte todos los efectos negativos propios en un estado positivo aleatorio. Invalida el efecto positivo que le otorgan los aliados. Cuando está en el campo, aumenta un 15% el poder de las habilidades de Planta.",
		describe_es = "No acepta ningún beneficio proporcionado por otros. Si recibe algún efecto negativo, lo convierte en una mejora aleatoria;\nHabilidad de aura: todos los aliados de tipo Planta obtienen $(10+skillLevel*0.1-0.1)$% DAÑO de movimiento",
		zawakeEffectDesc_th = "เอฟเฟกต์พิเศษ: หลังจากเป็นลม ลบเอฟเฟกต์ด้านลบ 1 อันออกจากพันธมิตรแต่ละฝ่าย และบัฟทั้งหมดจะถูกคัดลอกไปยังพันธมิตรทั้งหมดเป็นเวลา 2 รอบ",
		starEffectDesc_id = "Efek ekstra: Setelah pingsan, semua buff akan disalin ke semua sekutu selama 2 ronde",
		starEffectDesc_es = "Efecto adicional: después de desmayarse, todas las ventajas se copiarán a todos los aliados durante 2 rondas.",
		zawakeSimpleDesc_en = "#C0x5c9970#After fainting, removes 1 negative effect from each allies",
		describe_vn = "Não aceita nenhum buff fornecido por terceiros. Se sofrer algum efeito negativo, transforma-o em um buff aleatório;\nHabilidade de Aura: Todos os aliados do tipo Grama ganham $(10+skillLevel*0.1-0.1)$% de DMG de Movimento",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: หลังจากเป็นลม บัฟทั้งหมดจะถูกคัดลอกไปยังพันธมิตรทั้งหมดเป็นเวลา 2 รอบ",
		starEffectDesc_vn = "Efeito extra: Após desmaiar, todos os buffs serão copiados para todos os aliados por 2 rodadas",
		zawakeEffectDesc_kr = "추가 효과: 기절 후 각 아군에게서 1개의 부정적인 효과를 제거하고 2라운드 동안 모든 버프가 모든 아군에게 복사됩니다.",
		describe_en = "Does not take any buff provided by others. If it takes any negative effect, turns it into a random buff;\nAura Skill: All Grass type allies gain $(10+skillLevel*0.1-0.1)$% Move DMG",
		zawakeEffectDesc_id = "Efek ekstra: Setelah pingsan, menghilangkan 1 efek negatif dari masing-masing sekutu dan semua buff akan disalin ke semua sekutu selama 2 putaran",
		describe_id = "Tidak mengambil buff apa pun yang diberikan orang lain. Jika terkena efek negatif, ubah menjadi buff acak;\nAura Skill: Semua sekutu tipe Rumput mendapat $(10+skillLevel*0.1-0.1)$% Move DMG",
		simDesc_en = "Turns all own negative effect into random positive status. Invalidates positive effect allies grant on it. When it is on the field, increases 15% power for Grass skills",
		simDesc_vn = "Transforma todos os seus próprios efeitos negativos em status positivo aleatório. Invalida o efeito positivo que os aliados concedem a ele. Quando está em campo, aumenta em 15% o poder das habilidades de Grama",
		describe_kr = "다른 사람이 제공하는 버프를 받지 않습니다. 부정적인 효과가 있으면 무작위 버프로 전환;\n오라 스킬: 모든 풀 유형 아군이 $(10+skillLevel*0.1-0.1)$% 이동 DMG를 얻습니다.",
		simDesc_th = "เปลี่ยนเอฟเฟกต์ด้านลบของตัวเองทั้งหมดให้เป็นสถานะด้านบวกแบบสุ่ม ทำให้เอฟเฟกต์เชิงบวกที่พันธมิตรมอบให้เป็นโมฆะ เมื่ออยู่ในสนาม เพิ่มพลังให้กับทักษะหญ้า 15%",
		zawakeEffectDesc_es = "Efecto adicional: después de desmayarse, elimina 1 efecto negativo de cada aliado y todas las ventajas se copiarán a todos los aliados durante 2 rondas.",
		starEffectDesc_kr = "추가 효과: 기절 후 2라운드 동안 모든 버프가 모든 아군에게 복사됩니다.",
		zawakeEffectDesc_en = "Extra effect: After fainting, removes 1 negative effect from each allies and all buffs will be copied to all allies for 2 rounds",
		simDesc_kr = "자신의 모든 부정적 효과를 무작위 긍정적 상태로 바꿉니다. 아군이 부여한 긍정적인 효과를 무효화합니다. 필드에 있을 때 풀 스킬의 위력이 15% 증가합니다.",
