	[24733] = {
		describe_th = "Serperior สร้างคุกเถาวัลย์ที่มั่นคง ซึ่งต่อมาจะระเบิดเพื่อสร้างความเสียหายให้กับศัตรูทั้งหมด สร้างความเสียหาย (#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#และฝังเมล็ดไอวี่ไว้ใต้ศัตรูทุกตัว ซึ่ง [Coils] พวกมันเป็นเวลา 1 รอบหลังจากที่พวกมันเคลื่อนที่",
		zawakeEffectDesc_vn = "Efeito extra: Durante Ultimate Entanglement, absorve HP do alvo que é igual a 70% da soma do SP.DEF e P.DEF de Serperior (este DMG é True DMG); Se já estiver cheio de HP, transfira a cura transbordada para o aliado com menor HP",
		simDesc_es = "Serperior crea una prisión de enredadera firme, que luego explota para dañar a todos los enemigos y los enrolla después de su siguiente movimiento.",
		describe_es = "Serperior construye una prisión de enredadera firme, que luego explota para dañar a todos los enemigos. Inflige (#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#y entierra una semilla de hiedra debajo de cada enemigo, que los [Coils] durante 1 ronda después de que se mueven.",
		zawakeEffectDesc_th = "เอฟเฟกต์พิเศษ: ในช่วง Ultimate Entanglement ดูดซับ HP จากเป้าหมายซึ่งเท่ากับ 70% ของผลรวมของ SP.DEF และ P.DEF ของ Serperior (DMG นี้เป็น DMG จริง); หากตัวเองมี HP เต็มแล้ว ให้โอนการรักษาที่มากเกินไปไปยังพันธมิตรที่มี HP ต่ำที่สุด",
		starEffectDesc_id = "Efek ekstra: Saat Ultimate Entanglement, menyerap HP dari target yang setara dengan 60% dari jumlah SP.DEF dan P.DEF Serperior (DMG ini adalah True DMG)",
		starEffectDesc_es = "Efecto adicional: Durante Ultimate Entanglement, absorbe HP del objetivo que es igual al 60% de la suma de SP.DEF y P.DEF de Serperior (este DMG es True DMG)",
		zawakeSimpleDesc_en = "absorbs HP increase to 70%; If itself is alredady full of HP, transfer the overflowed Healing to the ally with lowest HP",
		describe_vn = "Serperior faz uma prisão firme de videiras, que mais tarde explode causando danos a todos os inimigos. Inflige (#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#e enterra uma semente de hera embaixo de cada inimigo, que os [Coils] por 1 rodada após eles se moverem",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: ในช่วง Ultimate Entanglement ดูดซับ HP จากเป้าหมายซึ่งเท่ากับ 60% ของผลรวมของ SP.DEF และ P.DEF ของ Serperior (DMG นี้เป็น DMG จริง)",
		starEffectDesc_vn = "Efeito extra: Durante Ultimate Entanglement, absorve HP do alvo que é igual a 60% da soma de SP.DEF e P.DEF de Serperior (este DMG é True DMG)",
		zawakeEffectDesc_kr = "추가 효과: Ultimate Entanglement 동안 Serperior의 SP.DEF와 P.DEF 합계의 70%에 해당하는 대상의 HP를 흡수합니다(이 DMG는 True DMG입니다). 자신의 HP가 이미 가득 찬 경우, HP가 가장 낮은 아군에게 넘치는 힐링을 전달합니다.",
		describe_en = "Serperior makes a firm vine prison, which later explodes to damage all enemies. Inflicts (#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#and buries an ivy seed beneath every enemy, which [Coils] them for 1 round after they move",
		zawakeEffectDesc_id = "Efek ekstra: Selama Keterikatan Ultimate, menyerap HP dari target yang setara dengan 70% dari jumlah SP.DEF dan P.DEF Serperior (DMG ini adalah True DMG); Jika HPnya sudah penuh, transfer Healing yang melimpah ke sekutu dengan HP terendah",
		describe_id = "Serperior membuat penjara tanaman merambat yang kokoh, yang kemudian meledak untuk memberikan damage pada semua musuh. Menimbulkan (#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#dan mengubur benih ivy di bawah setiap musuh, yang [Coils] mereka selama 1 ronde setelah mereka bergerak",
		simDesc_en = "Serperior makes a firm vine prison, which later explodes to damage all enemies and coils them after their next move",
		simDesc_vn = "Serperior faz uma prisão de videira firme, que mais tarde explode para danificar todos os inimigos e os enrola após seu próximo movimento",
		describe_kr = "세르페리어는 견고한 덩굴 감옥을 만들고, 나중에 폭발하여 모든 적에게 피해를 줍니다. (#C0x3D8A99#160% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$)#C0xF13B54#SP.DMG#C0x5B545B#를 가하고 모든 적 아래에 담쟁이덩굴 씨앗을 묻어 이동 후 1라운드 동안 [Coils]합니다.",
		simDesc_th = "Serperior สร้างคุกเถาวัลย์ที่มั่นคง ซึ่งต่อมาจะระเบิดเพื่อสร้างความเสียหายให้กับศัตรูทั้งหมด และม้วนขดพวกเขาหลังจากการเคลื่อนไหวครั้งถัดไป",
		zawakeEffectDesc_es = "Efecto adicional: Durante Ultimate Entanglement, absorbe HP del objetivo que es igual al 70% de la suma de SP.DEF y P.DEF de Serperior (este DMG es True DMG); Si ya está lleno de HP, transfiere la curación desbordada al aliado con menor HP.",
		starEffectDesc_kr = "추가 효과 : Ultimate Entanglement 시, Serperior의 SP.DEF와 P.DEF 합산의 60%에 해당하는 대상의 HP를 흡수합니다. (이 DMG는 True DMG입니다.)",
		zawakeEffectDesc_en = "Extra effect: During Ultimate Entanglement, absorbs HP from the target which is equal to 70% of the sum of Serperior's SP.DEF and P.DEF (this DMG is True DMG); If itself is alredady full of HP, transfer the overflowed Healing to the ally with lowest HP",
		simDesc_kr = "Serperior는 단단한 덩굴 감옥을 만들고 나중에 폭발하여 모든 적에게 피해를 입히고 다음 움직임 후에 그들을 감습니다.",
		zawakeSimpleDesc_th = "ดูดซับ HP เพิ่มขึ้นเป็น 70%; หากตัวเองมี HP เต็มแล้ว ให้โอนการรักษาที่มากเกินไปไปยังพันธมิตรที่มี HP ต่ำที่สุด",
		zawakeSimpleDesc_kr = "HP 증가량을 70%까지 흡수합니다. 자신의 HP가 이미 가득 찬 경우, HP가 가장 낮은 아군에게 넘치는 힐링을 전달합니다.",
		starEffectDesc_en = "Extra effect: During Ultimate Entanglement, absorbs HP from the target which is equal to 60% of the sum of Serperior's SP.DEF and P.DEF (this DMG is True DMG)",
		zawakeSimpleDesc_vn = "absorve aumento de HP para 70%; Se já estiver cheio de HP, transfira a cura transbordada para o aliado com menor HP",
