	[25913] = {
		describe_th = "Roggenrola เก็บพลังงานไว้ในปากเพื่อสร้างปืนใหญ่แม่เหล็กไฟฟ้ารูปเสาเพื่อโจมตีศัตรูติดต่อกันเพื่อสร้างความเสียหาย#C0xE69900#230%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B# ความเสียหายของตัวเองได้รับเพิ่มขึ้น 10% ในการต่อสู้ สูงสุด 5 ครั้ง หลังจากทักษะขั้นสูงสุด เนื่องจากสูญเสียการควบคุม จะโจมตีโปเกมอนเพื่อนหนึ่งครั้งอย่างแน่นอน",
		zawakeEffectDesc_vn = "Roggenrola armazena energia na boca para formar um canhão eletromagnético em forma de pilar para bombardear inimigos em sequência para lidar com #C0xE69900#240%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, dano próprio sofrido aumentado em 10% na batalha, até 5 vezes.",
		simDesc_es = "Roggenrola almacena energía en su boca para formar Zap Cannon, bombardeando enemigos en fila. Siempre que aumente la cantidad total de daño que recibe, su daño máximo también aumentará. Atacará a sus aliados una vez después de perder el control.",
		describe_es = "Roggenrola almacena energía en la boca para formar un cañón electromagnético en forma de pilar para bombardear a los enemigos seguidos y tratar#C0xE69900#230%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, el daño propio recibido aumenta en 10% en la batalla, hasta 5 veces. Después de las habilidades definitivas, debido a la pérdida de controles, seguramente atacará a los Pokémon amigos una vez.",
		zawakeEffectDesc_th = "Roggenrola เก็บพลังงานไว้ในปากเพื่อสร้างปืนใหญ่แม่เหล็กไฟฟ้ารูปเสาเพื่อโจมตีศัตรูติดต่อกันเพื่อสร้างความเสียหาย#C0xE69900#240%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B# ความเสียหายของตัวเองได้รับเพิ่มขึ้น 10% ในการต่อสู้ สูงสุด 5 ครั้ง",
		starEffectDesc_id = "Peningkatan efek: Meningkatkan kerusakan gerakan Ultimate sebesar 20% setiap kali diserang",
		starEffectDesc_es = "Aumento de efecto: aumenta el daño de su movimiento definitivo en un 20% cada vez que es atacado.",
		zawakeSimpleDesc_en = "DMG ratio increase to 240%, and will not lose control",
		describe_vn = "Roggenrola armazena energia na boca para formar um canhão eletromagnético em forma de pilar para bombardear inimigos em sequência para lidar com#C0xE69900#230%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, dano próprio sofrido aumentado em 10% na batalha, até 5 vezes. Após as habilidades Ultimate, por perder os controles, certamente atacará Pokémon amigos uma vez",
		starEffectDesc_th = "Effect boost: เพิ่มความเสียหายของท่า Ultimate 20% ทุกครั้งที่ถูกโจมตี",
		starEffectDesc_vn = "Aumento de efeito: Aumenta o dano de seu movimento Ultimate em 20% cada vez que é atacado",
		zawakeEffectDesc_kr = "로겐롤라는 입에 에너지를 저장해 기둥 모양의 전자기포를 형성해 적에게 연속 포격을 가해 공격을 가합니다#C0xE69900#240%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, 자신이 받는 데미지가 증가합니다. 전투시 10%, 최대 5회.",
		describe_en = "Roggenrola stores energy in mouth to form a pillar-shaped electromagnetic cannon to bombard enemies in a row to deal#C0xE69900#230%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, own damage taken increasedby 10% in the battle, up to 5 times. After the Ultimate skills, because of losing controls, certainly will attack friend Pokémon once",
		zawakeEffectDesc_id = "Roggenrola menyimpan energi di mulutnya untuk membentuk meriam elektromagnetik berbentuk pilar untuk membombardir musuh berturut-turut untuk menghasilkan#C0xE69900#240%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, kerusakan yang diterima sendiri meningkat sebesar 10% dalam pertempuran, hingga 5 kali.",
		describe_id = "Roggenrola menyimpan energi di mulutnya untuk membentuk meriam elektromagnetik berbentuk pilar untuk membombardir musuh berturut-turut untuk menghasilkan#C0xE69900#230%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, kerusakan yang diterima sendiri meningkat sebesar 10% dalam pertempuran, hingga 5 kali. Setelah skill Ultimate, karena kehilangan kendali, dipastikan akan menyerang Pokémon teman satu kali",
		simDesc_en = "Roggenrola stores energy in its mouth to form Zap Cannon, bombarding enemies in a row. Whenever the total amount of damage it receives increases, its Ultimate damage will also increase. It will attack its allies once after losing control.",
		simDesc_vn = "Roggenrola armazena energia em sua boca para formar Zap Cannon, bombardeando inimigos em sequência. Sempre que a quantidade total de dano recebido aumenta, seu dano final também aumentará. Ele atacará seus aliados uma vez após perder o controle.",
		describe_kr = "로겐롤라는 입에 에너지를 저장해 기둥 모양의 전자포를 형성해 적에게 연속 포격을 가해 공격을 가합니다#C0xE69900#230%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, 자신이 받는 데미지가 증가합니다. 전투시 10%, 최대 5회. 궁극기 스킬 이후에는 컨트롤을 잃기 때문에 반드시 친구 포켓몬을 한 번 공격합니다.",
		simDesc_th = "Roggenrola เก็บพลังงานไว้ในปากเพื่อสร้าง Zap Cannon โจมตีศัตรูเป็นแถว เมื่อใดก็ตามที่จำนวนความเสียหายทั้งหมดที่ได้รับเพิ่มขึ้น ความเสียหายขั้นสูงสุดก็จะเพิ่มขึ้นเช่นกัน มันจะโจมตีพันธมิตรทันทีหลังจากสูญเสียการควบคุม",
		zawakeEffectDesc_es = "Roggenrola almacena energía en la boca para formar un cañón electromagnético en forma de pilar para bombardear enemigos seguidos y causar #C0xE69900#240%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, el daño propio recibido aumenta en 10% en la batalla, hasta 5 veces.",
		starEffectDesc_kr = "효과 부스트 : 공격을 받을 때마다 궁극기 데미지가 20% 증가합니다.",
		zawakeEffectDesc_en = "Roggenrola stores energy in mouth to form a pillar-shaped electromagnetic cannon to bombard enemies in a row to deal#C0xE69900#240%P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#, own damage taken increasedby 10% in the battle, up to 5 times.",
		simDesc_kr = "로겐롤라는 입에 에너지를 저장하여 기압 대포를 형성하여 적에게 연속으로 폭격을 가합니다. 받는 총 피해량이 증가할 때마다 궁극기 피해량도 증가합니다. 통제력을 잃은 후 아군을 한 번 공격합니다.",
		zawakeSimpleDesc_th = "อัตราความเสียหายเพิ่มขึ้นเป็น 240% และจะไม่สูญเสียการควบคุม",
		zawakeSimpleDesc_kr = "DMG 비율이 240%로 증가하고 통제력을 잃지 않습니다.",
		starEffectDesc_en = "Effect boost: Increases the damage of its Ultimate move by 20% each time it is attacked",
		zawakeSimpleDesc_vn = "A proporção de DMG aumenta para 240% e não perderá o controle",
		zawakeSimpleDesc_id = "Rasio DMG meningkat menjadi 240%, dan tidak akan kehilangan kendali",
		id = 25913,
		zawakeSimpleDesc_es = "La proporción de daño aumenta al 240% y no perderá el control.",
		simDesc_id = "Roggenrola menyimpan energi di mulutnya untuk membentuk Zap Cannon, membombardir musuh secara berturut-turut. Setiap kali jumlah total damage yang diterimanya meningkat, damage Ultimate-nya juga akan meningkat. Ia akan menyerang sekutunya satu kali setelah kehilangan kendali."
	},
