	[29913] = {
		describe_th = "ลิตวิคเรียก Will-O-Wisps จำนวนมากที่อยู่รอบๆ ตัวมันเอง ก่อนที่จะเหวี่ยงมันไปยังเป้าหมายของศัตรูติดต่อกัน สร้างความเสียหาย#C0x3D8A99#220% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความเดือดดาลให้กับเป้าหมายอีกต่อไป และสร้างเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนการเคลื่อนไหวครั้งต่อไป",
		zawakeEffectDesc_vn = "Litwick invoca um grande número de Will-O-Wisps cercando-se antes de arremessá-los contra os alvos inimigos em sequência, distribuindo#C0x3D8A99#220% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. O dano deste movimento não criará mais raiva para o alvo e infligirá efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento; Reduz a velocidade de recuperação de raiva dos inimigos em 30% por 2 rodadas",
		simDesc_es = "Litwick convoca una gran cantidad de Will-O-Wisps que se rodean antes de arrojarlos a los enemigos. El daño de este movimiento no generará ira para los enemigos e inflige el efecto 【Will-O-Wisp】",
		describe_es = "Litwick invoca una gran cantidad de Will-O-Wisps que se rodean antes de lanzarlos hacia objetivos enemigos en fila, causando#C0x3D8A99#220% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. El daño de este movimiento no creará más ira en el objetivo e inflige el efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira instantáneamente y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeEffectDesc_th = "ลิตวิคเรียก Will-O-Wisps จำนวนมากที่อยู่รอบๆ ตัวมันเอง ก่อนที่จะเหวี่ยงมันไปยังเป้าหมายของศัตรูติดต่อกัน สร้างความเสียหาย#C0x3D8A99#220% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความเดือดดาลให้กับเป้าหมายอีกต่อไป และสร้างเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนการเคลื่อนไหวครั้งถัดไป ลดความเร็วในการฟื้นฟู Rage ของศัตรูลง 30% เป็นเวลา 2 รอบ",
		starEffectDesc_id = "Unit yang mengenai musuh dengan Will-O-Wisp akan meningkatkan kritiknya sebesar 20% pada gerakan Ultimate berikutnya",
		starEffectDesc_es = "Las unidades que hayan golpeado al enemigo con Will-O-Wisp aumentarán su crítico en un 20% en su próximo movimiento definitivo.",
		zawakeSimpleDesc_en = "Additional effect: Reduce enemies Rage recover Speed by 30% for 2 rounds",
		describe_vn = "Litwick invoca um grande número de Will-O-Wisps cercando-se antes de arremessá-los contra os alvos inimigos em sequência, distribuindo#C0x3D8A99#220% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. O dano deste movimento não criará mais raiva para o alvo e infligirá efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		starEffectDesc_th = "หน่วยที่โจมตีศัตรูด้วย Will-O-Wisp จะเพิ่มคริติคอล 20% ในท่าไม้ตายครั้งต่อไป",
