	[29916] = {
		describe_id = "Will-O-Wisp tetap berada di medan perang saat pertama kali dilumpuhkan, dan sebelum ronde besar dimulai, ia bangkit kembali sebagai Roh Pendendam dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Roh Pendendam tidak bisa diserang oleh P.ATK) yang menghilang di akhir ronde besar",
		zawakeEffectDesc_vn = "Um Will-O-Wisp permanece no campo de batalha na primeira vez que é nocauteado e, antes do início da grande rodada, ele revive como um Espírito Vingativo com #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (o Espírito Vingativo não pode ser atacado por P.ATK) que desaparece no final da próxima grande rodada",
		describe_vn = "Um Will-O-Wisp permanece no campo de batalha na primeira vez que é nocauteado e, antes do início da grande rodada, ele revive como um Espírito Vingativo com #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (o Espírito Vingativo não pode ser atacado por P.ATK) que desaparece no final da grande rodada",
		starEffectDesc_id = "Ketika bentuk Vengeful Spirit dihidupkan kembali, rage pulih sepenuhnya, sementara SP.ATK dan crit meningkat sebesar 30%",
		zawakeEffectDesc_th = "Will-O-Wisp ยังคงอยู่ในสนามรบในครั้งแรกที่ถูกทำให้ล้มลง และก่อนเริ่มรอบใหญ่ มันจะฟื้นคืนชีพขึ้นมาเป็น Vengeful Spirit ด้วย #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit ไม่สามารถ จะถูกโจมตีด้วย P.ATK) ซึ่งจะหายไปเมื่อสิ้นสุดรอบใหญ่ครั้งต่อไป",
		starEffectDesc_kr = "원혼형 부활 시 분노가 완전히 회복되며, SP.ATK와 크리티컬이 30% 증가합니다.",
		describe_es = "Un Will-O-Wisp permanece en el campo de batalla la primera vez que es noqueado y, antes del inicio de la gran ronda, revive como un espíritu vengativo con #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (el espíritu vengativo no puede ser atacado por P.ATK) que desaparece al final de la gran ronda",
		zawakeSimpleDesc_en = "disappears at the end of the next  big round",
		starEffectDesc_es = "Cuando la forma de Espíritu Vengativo revive, la ira se recupera por completo, mientras que SP.ATK y crítico aumentan en un 30%.",
		starEffectDesc_th = "เมื่อรูปแบบ Vengeful Spirit ฟื้นคืน ความโกรธจะฟื้นคืนเต็ม ในขณะที่ SP.ATK และคริติคอลเพิ่มขึ้น 30%",
		zawakeEffectDesc_id = "Will-O-Wisp tetap berada di medan perang saat pertama kali dilumpuhkan, dan sebelum ronde besar dimulai, ia bangkit kembali sebagai Roh Pendendam dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Roh Pendendam tidak bisa diserang oleh P.ATK) yang menghilang di akhir ronde besar berikutnya",
		zawakeEffectDesc_es = "Un Will-O-Wisp permanece en el campo de batalla la primera vez que es eliminado, y antes del comienzo de la gran ronda, revive como un espíritu vengativo con #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (el espíritu vengativo no puede ser atacado por P.ATK) que desaparece al final de la siguiente gran ronda",
		describe_en = "A Will-O-Wisp remains on the battlefield the first time it is being knocked out, and before the start of the big round, it revives as a Vengeful Spirit with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit cannot be attacked by P.ATK) which disappears at the end of the big round",
		zawakeSimpleDesc_th = "จะหายไปเมื่อสิ้นสุดรอบใหญ่ครั้งต่อไป",
		zawakeEffectDesc_kr = "Will-O-Wisp는 처음 쓰러졌을 때 전장에 남아 있다가 큰 라운드가 시작되기 전에 #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP로 복수 혼령으로 부활합니다. 다음 빅 라운드가 끝나면 사라지는 P.ATK)의 공격을 받습니다.",
		zawakeSimpleDesc_kr = "다음 큰 라운드가 끝나면 사라집니다.",
		zawakeEffectDesc_en = "A Will-O-Wisp remains on the battlefield the first time it is being knocked out, and before the start of the big round, it revives as a Vengeful Spirit with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit cannot be attacked by P.ATK) which disappears at the end of the next  big round",
		describe_kr = "Will-O-Wisp는 처음 쓰러졌을 때 전장에 남아 있다가 큰 라운드가 시작되기 전에 #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP로 복수 혼령으로 부활합니다. 빅 라운드가 끝나면 사라지는 P.ATK)의 공격을 받습니다.",
		zawakeSimpleDesc_vn = "desaparece no final da próxima grande rodada",
		zawakeSimpleDesc_id = "menghilang di akhir putaran besar berikutnya",
		starEffectDesc_vn = "Quando a forma Vengeful Spirit revive, a raiva se recupera totalmente, enquanto SP.ATK e crítico aumentam em 30%",
		zawakeSimpleDesc_es = "desaparece al final de la siguiente gran ronda",
		describe_th = "Will-O-Wisp ยังคงอยู่ในสนามรบในครั้งแรกที่ถูกทำให้ล้มลง และก่อนเริ่มรอบใหญ่ มันจะฟื้นคืนชีพขึ้นมาเป็น Vengeful Spirit ด้วย #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit ไม่สามารถ จะถูกโจมตีด้วย P.ATK) ซึ่งจะหายไปเมื่อสิ้นสุดรอบใหญ่",
		starEffectDesc_en = "When the Vengeful Spirit form revives, rage fully recovers, while SP.ATK and crit increases by 30%",
		id = 29916
	},
	[29921] = {
		zawakeEffectDesc_es = "Lampent se mueve al frente del único objetivo enemigo y lo ataca cortándolo con su mano, causando#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, y aumenta su SP. .ATK en un 30% durante 2 rondas.",
		zawakeEffectDesc_vn = "Lampent se move para a frente do único alvo inimigo e o ataca cortando-o com a mão, distribuindo#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumenta seu SP. .ATK em 30% por 2 rodadas.",
		describe_th = "แลมเพนท์เคลื่อนที่ไปด้านหน้าของศัตรูเป้าหมายเดียวและโจมตีมันด้วยการฟันด้วยมือของมัน สร้างความเสียหาย#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SP ของมัน .ATK 20% เป็นเวลา 2 รอบ",
		zawakeEffectDesc_kr = "램펜트는 단일 적 대상 앞으로 이동하여 손으로 베며 공격하며#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리하고 SP를 증가시킵니다. .2라운드 동안 ATK가 30% 증가합니다.",
		zawakeEffectDesc_th = "แลมป์เคลื่อนที่ไปด้านหน้าของศัตรูเป้าหมายเดียวและโจมตีมันด้วยการฟันด้วยมือของมัน สร้างความเสียหาย#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SP ของมัน .ATK 30% เป็นเวลา 2 รอบ",
		describe_en = "Lampent moves to the front of the single enemy target and attacks it by slashing it with its hand, dealing#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and increases its SP.ATK by 20% for 2 rounds.",
		describe_es = "Lampent se mueve al frente del único objetivo enemigo y lo ataca cortándolo con su mano, causando#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, y aumenta su SP. .ATK en un 20% durante 2 rondas.",
		zawakeSimpleDesc_en = "increases its SP.ATK by 20% for 2 rounds\n#F20#\n#F40##C0x5c9970#→increases its SP.ATK by 30% for 2 rounds",
		describe_vn = "Lampent se move para a frente do único alvo inimigo e o ataca cortando-o com a mão, distribuindo#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumenta seu SP. .ATK em 20% por 2 rodadas.",
		zawakeEffectDesc_en = "Lampent moves to the front of the single enemy target and attacks it by slashing it with its hand, dealing#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and increases its SP.ATK by 30% for 2 rounds.",
		zawakeSimpleDesc_vn = "aumenta seu SP.ATK em 20% por 2 rodadas\n#F20#\n#F40##C0x5c9970#→aumenta seu SP.ATK em 30% por 2 rodadas",
		zawakeSimpleDesc_id = "meningkatkan SP.ATK-nya sebesar 20% selama 2 ronde\n#F20#\n#F40##C0x5c9970#→meningkatkan SP.ATK-nya sebesar 30% selama 2 ronde",
		zawakeSimpleDesc_es = "aumenta su SP.ATK en un 20 % durante 2 rondas\n#F20#\n#F40##C0x5c9970#→aumenta su SP.ATK en un 30 % durante 2 rondas",
		describe_id = "Lampent bergerak ke depan satu target musuh dan menyerangnya dengan menebasnya menggunakan tangannya, menimbulkan#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan meningkatkan SP-nya .ATK sebesar 20% selama 2 putaran.",
		zawakeSimpleDesc_kr = "2라운드 동안 SP.ATK 20% 증가\n#F20#\n#F40##C0x5c9970#→2라운드 동안 SP.ATK 30% 증가",
		zawakeEffectDesc_id = "Lampent bergerak ke depan satu target musuh dan menyerangnya dengan menebasnya menggunakan tangannya, menimbulkan#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan meningkatkan SP-nya .ATK sebesar 30% selama 2 putaran.",
		describe_kr = "램펜트는 단일 적 대상 앞으로 이동하여 손으로 베며 공격하며#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리하고 SP를 증가시킵니다. .2라운드 동안 ATK가 20% 증가합니다.",
		zawakeSimpleDesc_th = "เพิ่ม SP.ATK ของมัน 20% เป็นเวลา 2 รอบ\n#F20#\n#F40##C0x5c9970#→เพิ่ม SP.ATK ของมัน 30% เป็นเวลา 2 รอบ",
		id = 29921
	},
	[29922] = {
		zawakeEffectDesc_es = "Lampent se teletransporta para golpear al enemigo antes de saltar para asestar un fuerte golpe a un solo objetivo enemigo, causando#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige al objetivo. con efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira al instante y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeEffectDesc_vn = "Lampent se teletransporta para atingir o inimigo antes de pular para acertar um golpe forte em um único alvo inimigo, distribuindo#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige o alvo com efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		describe_th = "เทเลพอร์ตลำแสงเพื่อฟาดศัตรูก่อนที่จะกระโดดขึ้นไปโจมตีศัตรูเป้าหมายเดียวอย่างรุนแรง สร้างความเสียหาย#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# และสร้างความเสียหายให้กับเป้าหมาย ด้วยเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 100 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนเริ่มการเคลื่อนไหวครั้งต่อไป",
		zawakeEffectDesc_kr = "Lampent는 순간이동하여 적을 강타한 후 점프하여 단일 적 대상에게 큰 타격을 가하고#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리하고 대상에게 피해를 입힙니다. [Will-O-Wisp] 효과로.\n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 공격 전에 동일한 양의 분노가 감소합니다.",
		zawakeEffectDesc_th = "เทเลพอร์ตลำแสงเพื่อฟาดศัตรูก่อนที่จะกระโดดขึ้นไปโจมตีศัตรูเป้าหมายเดียวอย่างรุนแรง สร้างความเสียหาย#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# และสร้างความเสียหายให้กับเป้าหมาย ด้วยเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนการเคลื่อนไหวครั้งต่อไป",
		describe_en = "Lampent teleports to slam the enemy before jumping up to land a heaby blow on a single enemy target, dealing#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicts the target with [Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 100 rage points instantly and reduces the same amount of rage before the next move",
		describe_es = "Lampent se teletransporta para golpear al enemigo antes de saltar para asestar un fuerte golpe a un solo objetivo enemigo, causando#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige al objetivo. con efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 100 puntos de ira al instante y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeSimpleDesc_en = "[Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same amount of rage before the next move",
		describe_vn = "Lampent se teletransporta para atingir o inimigo antes de pular para acertar um golpe forte em um único alvo inimigo, distribuindo#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige o alvo com efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 100 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		zawakeEffectDesc_en = "Lampent teleports to slam the enemy before jumping up to land a heaby blow on a single enemy target, dealing#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicts the target with [Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same amount of rage before the next move",
		zawakeSimpleDesc_vn = "[Will-O-Wisp] efeito.\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		zawakeSimpleDesc_id = "[Will-O-Wisp] efek.\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum langkah selanjutnya",
		zawakeSimpleDesc_es = "Efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira al instante y reduce la misma cantidad de ira antes del siguiente movimiento.",
		describe_id = "Teleportasi lampent untuk membanting musuh sebelum melompat untuk mendaratkan pukulan keras pada satu target musuh, menimbulkan#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, dan memberikan damage ke target dengan efek [Will-O-Wisp].\n[Will-O-Wisp]: Mengurangi 100 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum langkah selanjutnya",
		zawakeSimpleDesc_kr = "[Will-O-Wisp] 효과.\n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 공격 전에 동일한 양의 분노가 감소합니다.",
		zawakeEffectDesc_id = "Teleportasi lampent untuk membanting musuh sebelum melompat untuk mendaratkan pukulan keras pada satu target musuh, menimbulkan#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, dan memberikan damage ke target dengan efek [Will-O-Wisp].\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum langkah selanjutnya",
		describe_kr = "Lampent는 순간이동하여 적을 강타한 후 점프하여 단일 적 대상에게 큰 타격을 가하고#C0x3D8A99#170% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리하고 대상에게 피해를 입힙니다. [Will-O-Wisp] 효과로.\n[Will-O-Wisp]: 분노 포인트가 즉시 100 감소하고 다음 공격 전에 동일한 양의 분노가 감소합니다.",
		zawakeSimpleDesc_th = "[Will-O-Wisp] effect.\n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนเริ่มการเคลื่อนไหวครั้งต่อไป",
		id = 29922
	},
	[29923] = {
		describe_th = "แลมเพนท์เรียกวิล-โอ-วิสป์ที่ทรงพลังอย่างยิ่ง และเหวี่ยงมันไปยังเป้าหมายศัตรูติดต่อกัน สร้างความเสียหาย#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความเดือดดาลให้กับเป้าหมายอีกต่อไป และสร้างเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดความเดือดเท่าเดิมก่อนการเคลื่อนไหวครั้งถัดไป",
		zawakeEffectDesc_vn = "Lampent invoca Will-O-Wisp extremamente poderoso e o arremessa em direção aos alvos inimigos em sequência, distribuindo#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. O dano deste movimento não criará mais raiva para o alvo e inflige efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento.Reduz a velocidade de recuperação de raiva dos inimigos em 30 % por 2 rodadas",
		simDesc_es = "Lampent invoca Will-O-Wisp extremadamente poderosos y los arroja a los enemigos en columna. El daño de este movimiento no generará ira para los enemigos e inflige el efecto 【Will-O-Wisp】",
		describe_es = "Lampent invoca un Will-O-Wisp extremadamente poderoso y lo lanza hacia objetivos enemigos seguidos, causando#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. El daño de este movimiento no creará más ira para el objetivo e inflige el efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira instantáneamente y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeEffectDesc_th = "แลมเพนท์เรียกวิล-โอ-วิสป์ที่ทรงพลังอย่างยิ่ง และเหวี่ยงมันไปยังเป้าหมายศัตรูติดต่อกัน สร้างความเสียหาย#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความโกรธให้กับเป้าหมายอีกต่อไป และสร้างเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดความโกรธเท่าเดิมก่อนการเคลื่อนไหวครั้งต่อไป ลดความเร็วการกู้คืนความโกรธของศัตรูลง 30 % จำนวน 2 รอบ",
		starEffectDesc_id = "Unit yang mengenai musuh dengan Will-O-Wisp akan meningkatkan kritiknya sebesar 20% pada gerakan Ultimate berikutnya",
		starEffectDesc_es = "Las unidades que hayan golpeado al enemigo con Will-O-Wisp aumentarán su crítico en un 20% en su próximo movimiento definitivo.",
		zawakeSimpleDesc_en = "Additional effect: Reduce enemies Rage recover Speed by 30% for 2 rounds",
		describe_vn = "Lampent invoca Will-O-Wisp extremamente poderoso e o arremessa em direção aos alvos inimigos em sequência, distribuindo#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. O dano deste movimento não criará mais raiva para o alvo e infligirá efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		starEffectDesc_th = "หน่วยที่โจมตีศัตรูด้วย Will-O-Wisp จะเพิ่มคริติคอล 20% ในท่าไม้ตายครั้งต่อไป",
		starEffectDesc_vn = "Unidades que atingiram o inimigo com Will-O-Wisp aumentarão seu crítico em 20% em seu próximo movimento Ultimate",
		zawakeEffectDesc_kr = "Lampent는 매우 강력한 Will-O-Wisp를 소환하여 적 대상을 향해 연속적으로 던져#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리합니다. 이 이동의 피해는 대상에게 더 많은 분노를 생성하지 않으며 [Will-O-Wisp] 효과를 적용합니다.\n[Will-O-Wisp]: 즉시 분노 포인트가 150 감소하고 다음 이동 전에 동일한 분노 포인트가 감소합니다. 적의 분노 회복 속도가 30 감소합니다. 2라운드에 대한 %",
		describe_en = "Lampent summons extremely powerful Will-O-Wisp and hurls it towards enemy targets in a row, dealing#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. The damage of this move will not create more rage for the target and inflicts [Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same about of rage before the next move",
		zawakeEffectDesc_id = "Lampent memanggil Will-O-Wisp yang sangat kuat dan melemparkannya ke arah target musuh berturut-turut, menimbulkan#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. Kerusakan gerakan ini tidak akan menimbulkan lebih banyak kemarahan pada target dan menimbulkan efek [Will-O-Wisp].\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum gerakan berikutnya. Mengurangi Kecepatan Pemulihan Kemarahan musuh sebanyak 30 % untuk 2 putaran",
		describe_id = "Lampent memanggil Will-O-Wisp yang sangat kuat dan melemparkannya ke arah target musuh berturut-turut, menimbulkan#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. Kerusakan dari gerakan ini tidak akan menimbulkan lebih banyak kemarahan pada target dan menimbulkan efek [Will-O-Wisp].\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum gerakan berikutnya",
		simDesc_en = "Lampent summons extremely powerful Will-O-Wisp and hurls them at enemies in a column. DMG of this move will not generate rage for the enemies and inflicts 【Will-O-Wisp】 effect",
		simDesc_vn = "Lampent invoca Will-O-Wisp extremamente poderoso e os arremessa contra os inimigos em uma coluna. O DMG deste movimento não gerará raiva para os inimigos e infligirá o efeito 【Will-O-Wisp】",
		describe_kr = "Lampent는 매우 강력한 Will-O-Wisp를 소환하여 적 대상을 향해 연속적으로 던져#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리합니다. 이 이동의 피해는 대상에게 더 많은 분노를 생성하지 않으며 [Will-O-Wisp] 효과를 적용합니다.\n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 이동 전에 동일한 분노가 감소합니다.",
		simDesc_th = "Lampent เรียก Will-O-Wisp ที่ทรงพลังอย่างยิ่ง และขว้างพวกมันใส่ศัตรูที่อยู่ในแนวเดียวกัน ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความโกรธแค้นให้กับศัตรูและสร้างเอฟเฟกต์ 【Will-O-Wisp】",
		zawakeEffectDesc_es = "Lampent invoca un Will-O-Wisp extremadamente poderoso y lo lanza hacia objetivos enemigos seguidos, causando#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. El daño de este movimiento no creará más ira en el objetivo e inflige el efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira instantáneamente y reduce la misma cantidad de ira antes del siguiente movimiento. Reduce la velocidad de recuperación de ira de los enemigos en 30 % para 2 rondas",
		starEffectDesc_kr = "Will-O-Wisp로 적을 공격한 유닛은 다음 궁극기에서 치명타가 20% 증가합니다.",
		zawakeEffectDesc_en = "Lampent summons extremely powerful Will-O-Wisp and hurls it towards enemy targets in a row, dealing#C0x3D8A99#230% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#. The damage of this move will not create more rage for the target and inflicts [Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same about of rage before the next move.Reduce enemies Rage recover Speed by 30% for 2 rounds",
		simDesc_kr = "Lampent는 매우 강력한 Will-O-Wisp를 소환하여 기둥에 있는 적에게 던집니다. 이 기술의 데미지는 적에게 분노를 생성하지 않고 【Will-O-Wisp】 효과를 줍니다.",
		zawakeSimpleDesc_th = "ผลกระทบเพิ่มเติม: ลดความเร็วในการฟื้นฟู Rage ของศัตรู 30% เป็นเวลา 2 รอบ",
		zawakeSimpleDesc_kr = "추가 효과: 2라운드 동안 적의 분노 회복 속도를 30% 감소시킵니다.",
		starEffectDesc_en = "Units that have hit the enemy with Will-O-Wisp will increase its crit by 20% in its next Ultimate move",
		zawakeSimpleDesc_vn = "Efeito adicional: Reduz a velocidade de recuperação de raiva dos inimigos em 30% por 2 rodadas",
		zawakeSimpleDesc_id = "Efek tambahan: Mengurangi Kecepatan Pemulihan Kemarahan musuh sebesar 30% selama 2 putaran",
		id = 29923,
		zawakeSimpleDesc_es = "Efecto adicional: Reduce la velocidad de recuperación de ira de los enemigos en un 30 % durante 2 rondas.",
		simDesc_id = "Lampent memanggil Will-O-Wisp yang sangat kuat dan melemparkannya ke arah musuh dalam satu kolom. DMG gerakan ini tidak akan menimbulkan kemarahan pada musuh dan menimbulkan efek 【Will-O-Wisp】"
	},
	[29926] = {
		describe_id = "Will-O-Wisp tetap berada di medan perang saat pertama kali dilumpuhkan, dan sebelum ronde besar dimulai, ia bangkit kembali sebagai Roh Pendendam dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Roh Pendendam tidak bisa diserang oleh P.ATK) yang menghilang di akhir ronde besar",
		zawakeEffectDesc_vn = "Um Will-O-Wisp permanece no campo de batalha na primeira vez que é nocauteado e, antes do início da grande rodada, ele revive como um Espírito Vingativo com #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (o Espírito Vingativo não pode ser atacado por P.ATK) que desaparece no final da próxima grande rodada",
		describe_vn = "Um Will-O-Wisp permanece no campo de batalha na primeira vez que é nocauteado e, antes do início da grande rodada, ele revive como um Espírito Vingativo com #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (o Espírito Vingativo não pode ser atacado por P.ATK) que desaparece no final da grande rodada",
		starEffectDesc_id = "Ketika bentuk Vengeful Spirit dihidupkan kembali, rage pulih sepenuhnya, sementara SP.ATK dan crit meningkat sebesar 30%",
		zawakeEffectDesc_th = "Will-O-Wisp ยังคงอยู่ในสนามรบในครั้งแรกที่ถูกทำให้ล้มลง และก่อนเริ่มรอบใหญ่ มันจะฟื้นคืนชีพขึ้นมาเป็น Vengeful Spirit ด้วย #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit ไม่สามารถ จะถูกโจมตีด้วย P.ATK) ซึ่งจะหายไปเมื่อสิ้นสุดรอบใหญ่ครั้งต่อไป",
		starEffectDesc_kr = "원혼형 부활 시 분노가 완전히 회복되며, SP.ATK와 크리티컬이 30% 증가합니다.",
		describe_es = "Un Will-O-Wisp permanece en el campo de batalla la primera vez que es noqueado y, antes del inicio de la gran ronda, revive como un espíritu vengativo con #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (el espíritu vengativo no puede ser atacado por P.ATK) que desaparece al final de la gran ronda",
		zawakeSimpleDesc_en = "disappears at the end of the next  big round",
		starEffectDesc_es = "Cuando la forma de Espíritu Vengativo revive, la ira se recupera por completo, mientras que SP.ATK y crítico aumentan en un 30%.",
		starEffectDesc_th = "เมื่อรูปแบบ Vengeful Spirit ฟื้นคืน ความโกรธจะฟื้นคืนเต็ม ในขณะที่ SP.ATK และคริติคอลเพิ่มขึ้น 30%",
		zawakeEffectDesc_id = "Will-O-Wisp tetap berada di medan perang saat pertama kali dilumpuhkan, dan sebelum ronde besar dimulai, ia bangkit kembali sebagai Roh Pendendam dengan #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Roh Pendendam tidak bisa diserang oleh P.ATK) yang menghilang di akhir ronde besar berikutnya",
		zawakeEffectDesc_es = "Un Will-O-Wisp permanece en el campo de batalla la primera vez que es eliminado, y antes del comienzo de la gran ronda, revive como un espíritu vengativo con #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (el espíritu vengativo no puede ser atacado por P.ATK) que desaparece al final de la siguiente gran ronda",
		describe_en = "A Will-O-Wisp remains on the battlefield the first time it is being knocked out, and before the start of the big round, it revives as a Vengeful Spirit with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit cannot be attacked by P.ATK) which disappears at the end of the big round",
		zawakeSimpleDesc_th = "จะหายไปเมื่อสิ้นสุดรอบใหญ่ครั้งต่อไป",
		zawakeEffectDesc_kr = "Will-O-Wisp는 처음 쓰러졌을 때 전장에 남아 있다가 큰 라운드가 시작되기 전에 #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP로 복수 혼령으로 부활합니다. 다음 빅 라운드가 끝나면 사라지는 P.ATK)의 공격을 받습니다.",
		zawakeSimpleDesc_kr = "다음 큰 라운드가 끝나면 사라집니다.",
		zawakeEffectDesc_en = "A Will-O-Wisp remains on the battlefield the first time it is being knocked out, and before the start of the big round, it revives as a Vengeful Spirit with #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit cannot be attacked by P.ATK) which disappears at the end of the next  big round",
		describe_kr = "Will-O-Wisp는 처음 쓰러졌을 때 전장에 남아 있다가 큰 라운드가 시작되기 전에 #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP로 복수 혼령으로 부활합니다. 빅 라운드가 끝나면 사라지는 P.ATK)의 공격을 받습니다.",
		zawakeSimpleDesc_vn = "desaparece no final da próxima grande rodada",
		zawakeSimpleDesc_id = "menghilang di akhir putaran besar berikutnya",
		starEffectDesc_vn = "Quando a forma Vengeful Spirit revive, a raiva se recupera totalmente, enquanto SP.ATK e crítico aumentam em 30%",
		zawakeSimpleDesc_es = "desaparece al final de la siguiente gran ronda",
		describe_th = "Will-O-Wisp ยังคงอยู่ในสนามรบในครั้งแรกที่ถูกทำให้ล้มลง และก่อนเริ่มรอบใหญ่ มันจะฟื้นคืนชีพขึ้นมาเป็น Vengeful Spirit ด้วย #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# HP (Vengeful Spirit ไม่สามารถ จะถูกโจมตีด้วย P.ATK) ซึ่งจะหายไปเมื่อสิ้นสุดรอบใหญ่",
		starEffectDesc_en = "When the Vengeful Spirit form revives, rage fully recovers, while SP.ATK and crit increases by 30%",
