	[29931] = {
		zawakeEffectDesc_es = "Chandelure usa su llama para atacar a un solo enemigo consecutivamente, causando#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, y aumenta su SP.ATK en un 30% durante 2 rondas.",
		zawakeEffectDesc_vn = "Chandelure usa sua chama para atacar um único inimigo consecutivamente, distribuindo#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumenta seu SP.ATK em 30% por 2 rodadas.",
		describe_th = "แชนเดลัวร์ใช้เปลวไฟโจมตีศัตรูตัวเดียวติดต่อกัน สร้าง#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SP.ATK ขึ้น 20% เป็นเวลา 2 รอบ",
		zawakeEffectDesc_kr = "샹델루어는 화염을 이용해 단일 적에게 연속 공격을 가해#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 입히고 2라운드 동안 SP.ATK를 30% 증가시킵니다.",
		zawakeEffectDesc_th = "แชนเดลัวร์ใช้เปลวไฟโจมตีศัตรูตัวเดียวติดต่อกัน สร้าง#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SP.ATK ขึ้น 30% เป็นเวลา 2 รอบ",
		describe_en = "Chandelure uses its flame to attack a single enemy consecutively, dealing#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and increases its SP.ATK by 20% for 2 rounds.",
