	[29932] = {
		zawakeEffectDesc_es = "Chandelure usa cuatro de sus llamas para invocar una bola de energía para atacar objetivos enemigos seguidos, causando#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# e inflige [Will-O-Wisp] efecto en los objetivos.\n[Will-O-Wisp]: Reduce 150 puntos de ira al instante y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeEffectDesc_vn = "Chandelure usa quatro de suas chamas para invocar uma bola de energia para atacar alvos inimigos em sequência, distribuindo #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige [Will-O-Wisp] efeito nos alvos.\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		describe_th = "แชนเดอลูร์ใช้เปลวไฟสี่ดวงเพื่อเรียกลูกบอลพลังงานมาโจมตีศัตรูเป้าหมายติดต่อกัน สร้างความเสียหาย#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# และสร้างความเสียหาย [Will-O-Wisp] ส่งผลต่อเป้าหมาย\n[Will-O-Wisp]: ลด 100 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนเริ่มการเคลื่อนไหวครั้งต่อไป",
		zawakeEffectDesc_kr = "샹델루어는 화염 4개를 이용해 에너지볼을 소환해 적 대상을 연속 공격하며#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 입히고 [Will-O-Wisp]를 입힙니다. \n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 이동 전에 동일한 양의 분노가 감소합니다.",
		zawakeEffectDesc_th = "แชนเดอลูร์ใช้เปลวไฟสี่ดวงเพื่อเรียกลูกบอลพลังงานมาโจมตีศัตรูเป้าหมายติดต่อกัน สร้างความเสียหาย#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# และสร้างความเสียหาย [Will-O-Wisp] ส่งผลต่อเป้าหมาย\n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนเริ่มการเคลื่อนไหวครั้งต่อไป",
		describe_en = "Chandelure uses four of its flame to summon an energy ball to attack enemy targets in a row, dealing#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicts [Will-O-Wisp] effect on the targets.\n[Will-O-Wisp]: Reduces 100 rage points instantly and reduces the same amount of rage before the next move",
		describe_es = "Chandelure usa cuatro de sus llamas para convocar una bola de energía para atacar objetivos enemigos seguidos, causando#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# e inflige [Will-O-Wisp] efecto en los objetivos.\n[Will-O-Wisp]: Reduce 100 puntos de ira al instante y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeSimpleDesc_en = "[Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same amount of rage before the next move",
		describe_vn = "Chandelure usa quatro de suas chamas para invocar uma bola de energia para atacar alvos inimigos em sequência, distribuindo #C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige [Will-O-Wisp] efeito nos alvos.\n[Will-O-Wisp]: Reduz 100 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		zawakeEffectDesc_en = "Chandelure uses four of its flame to summon an energy ball to attack enemy targets in a row, dealing#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicts [Will-O-Wisp] effect on the targets.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same amount of rage before the next move",
		zawakeSimpleDesc_vn = "[Will-O-Wisp] efeito.\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		zawakeSimpleDesc_id = "[Will-O-Wisp] efek.\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum langkah selanjutnya",
		zawakeSimpleDesc_es = "Efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira al instante y reduce la misma cantidad de ira antes del siguiente movimiento.",
		describe_id = "Chandelure menggunakan empat apinya untuk memanggil bola energi untuk menyerang target musuh secara berturut-turut, menimbulkan#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, dan menimbulkan [Will-O-Wisp] berpengaruh pada target.\n[Will-O-Wisp]: Mengurangi 100 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum langkah selanjutnya",
		zawakeSimpleDesc_kr = "[Will-O-Wisp] 효과.\n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 공격 전에 동일한 양의 분노가 감소합니다.",
		zawakeEffectDesc_id = "Chandelure menggunakan empat apinya untuk memanggil bola energi untuk menyerang target musuh secara berturut-turut, menimbulkan#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, dan menimbulkan [Will-O-Wisp] berpengaruh pada target.\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum langkah selanjutnya",
		describe_kr = "샹델루어는 화염 4개를 이용해 에너지볼을 소환해 적 대상을 연속 공격하며#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 입히고 [Will-O-Wisp]를 입힙니다. \n[Will-O-Wisp]: 분노 포인트가 즉시 100 감소하고 다음 이동 전에 동일한 양의 분노가 감소합니다.",
		zawakeSimpleDesc_th = "[Will-O-Wisp] effect.\n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนเริ่มการเคลื่อนไหวครั้งต่อไป",
		id = 29932
	},
	[29933] = {
		describe_th = "Chandelure กะพริบไปยังด้านหน้าของศัตรูเป็นแถว ก่อนที่จะเรียกห้อง Fire Formation ขนาดใหญ่และบินขึ้นไปบนท้องฟ้า จากนั้นมันก็ทำการโจมตีอย่างกะทันหันต่อหน้าศัตรู สร้าง#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#ไปยังเป้าหมาย ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความเดือดดาลให้กับเป้าหมายอีกต่อไป และสร้างเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนการเคลื่อนไหวครั้งต่อไป",
		zawakeEffectDesc_vn = "Chandelure pisca na frente dos inimigos seguidos, antes de invocar uma enorme sala de Formação de Fogo e voar para o céu. Em seguida, ele faz um ataque repentino na frente dos inimigos, distribuindo#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#aos alvos. O dano deste movimento não criará mais raiva para o alvo e infligirá efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento.E reduz a velocidade de recuperação de raiva dos inimigos em 30% para 2 rodadas",
		simDesc_es = "Chandelure parpadea hacia el frente de los enemigos en una columna, antes de convocar a la enorme Formación Espíritu de Fuego. Luego vuela hacia el cielo y realiza un ataque repentino. El daño de este movimiento no creará más ira en el objetivo e inflige el efecto 【Will-O-Wisp】.",
		describe_es = "Chandelure parpadea hacia el frente de los enemigos en fila, antes de convocar una enorme sala de Formación de Fuego y volar hacia el cielo. Luego realiza un ataque repentino frente a los enemigos, causando#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#a los objetivos. El daño de este movimiento no creará más ira en el objetivo e inflige el efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira instantáneamente y reduce la misma cantidad de ira antes del siguiente movimiento.",
		zawakeEffectDesc_th = "Chandelure กะพริบไปยังด้านหน้าของศัตรูเป็นแถว ก่อนที่จะเรียกห้อง Fire Formation ขนาดใหญ่และบินขึ้นไปบนท้องฟ้า จากนั้นมันก็ทำการโจมตีอย่างกะทันหันต่อหน้าศัตรู สร้าง#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#ไปยังเป้าหมาย ความเสียหายของการเคลื่อนไหวนี้จะไม่สร้างความเดือดดาลให้กับเป้าหมายอีกต่อไป และสร้างเอฟเฟกต์ [Will-O-Wisp] \n[Will-O-Wisp]: ลด 150 คะแนนความโกรธทันที และลดปริมาณความโกรธเท่าเดิมก่อนการเคลื่อนไหวครั้งต่อไป และลดศัตรู ฟื้นฟูความเร็วด้วย 30% สำหรับ 2 รอบ",
		starEffectDesc_id = "Unit yang mengenai musuh dengan Will-O-Wisp akan meningkatkan kritiknya sebesar 20% pada gerakan Ultimate berikutnya",
		starEffectDesc_es = "Las unidades que hayan golpeado al enemigo con Will-O-Wisp aumentarán su crítico en un 20% en su próximo movimiento definitivo.",
		zawakeSimpleDesc_en = "Additional effect: Reduce enemies Rage recover Speed by 30% for 2 rounds",
		describe_vn = "Chandelure pisca na frente dos inimigos seguidos, antes de invocar uma enorme sala de Formação de Fogo e voar para o céu. Em seguida, ele faz um ataque repentino na frente dos inimigos, distribuindo#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#aos alvos. O dano deste movimento não criará mais raiva para o alvo e infligirá efeito [Will-O-Wisp].\n[Will-O-Wisp]: Reduz 150 pontos de raiva instantaneamente e reduz a mesma quantidade de raiva antes do próximo movimento",
		starEffectDesc_th = "หน่วยที่โจมตีศัตรูด้วย Will-O-Wisp จะเพิ่มคริติคอล 20% ในท่าไม้ตายครั้งต่อไป",
		starEffectDesc_vn = "Unidades que atingiram o inimigo com Will-O-Wisp aumentarão seu crítico em 20% em seu próximo movimento Ultimate",
		zawakeEffectDesc_kr = "샹델루어는 적의 정면을 향해 연속으로 섬광을 뿜어낸 뒤, 거대한 불진형 방을 소환해 하늘로 날아오른다. 그런 다음 적들 앞에서 기습 공격을 가해 대상에게#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 줍니다. 이 이동의 피해는 대상에게 더 많은 분노를 생성하지 않으며 [Will-O-Wisp] 효과를 적용합니다.\n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 이동 전에 동일한 양의 분노가 감소합니다. 그리고 적의 분노 회복 속도가 감소합니다. 2라운드 동안 30%",
		describe_en = "Chandelure flashes to the front of the enemies in a row, before summoning a huge Fire Formation room and flies to the sky. It then makes a sudden attack in front of the enemies, dealing#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#to the targets. The damage of this move will not create more rage for the target and inflicts [Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same amount of rage before the next move",
		zawakeEffectDesc_id = "Chandelure berkedip ke depan musuh berturut-turut, sebelum memanggil ruang Formasi Api yang besar dan terbang ke langit. Ia kemudian melakukan serangan mendadak di depan musuh, memberikan#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#ke target. Kerusakan gerakan ini tidak akan menimbulkan lebih banyak kemarahan pada target dan menimbulkan efek [Will-O-Wisp].\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum gerakan berikutnya. Dan mengurangi Kecepatan Pemulihan Kemarahan musuh sebesar 30% untuk 2 putaran",
		describe_id = "Chandelure berkedip ke depan musuh berturut-turut, sebelum memanggil ruang Formasi Api yang besar dan terbang ke langit. Ia kemudian melakukan serangan mendadak di depan musuh, memberikan#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#ke target. Kerusakan dari gerakan ini tidak akan menimbulkan lebih banyak kemarahan pada target dan menimbulkan efek [Will-O-Wisp].\n[Will-O-Wisp]: Mengurangi 150 poin kemarahan secara instan dan mengurangi jumlah kemarahan yang sama sebelum gerakan berikutnya",
		simDesc_en = "Chandelure flashes to the front of the enemies in a column, before summoning the huge Fire Spirit Formation. It then flies to the sky and makes a sudden attack. The damage of this move will not create more rage for the target and inflicts 【Will-O-Wisp】 effect.",
		simDesc_vn = "Chandelure aparece na frente dos inimigos em uma coluna, antes de invocar a enorme Formação Espiritual do Fogo. Em seguida, voa para o céu e faz um ataque repentino. O dano deste movimento não criará mais raiva para o alvo e infligirá o efeito 【Will-O-Wisp】.",
		describe_kr = "샹델루어는 적의 정면을 향해 연속으로 섬광을 뿜어낸 뒤, 거대한 불진형 방을 소환해 하늘로 날아오른다. 그런 다음 적들 앞에서 기습 공격을 가해 대상에게#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#를 줍니다. 이 동작의 피해는 대상에게 더 많은 분노를 생성하지 않으며 [Will-O-Wisp] 효과를 적용합니다.\n[Will-O-Wisp]: 분노 포인트가 즉시 150 감소하고 다음 동작 전에 동일한 양의 분노가 감소합니다.",
		simDesc_th = "Chandelure วาบไปที่ด้านหน้าของศัตรูเป็นแถว ก่อนที่จะเรียกรูปแบบ Fire Spirit ขนาดมหึมา จากนั้นมันก็บินขึ้นไปบนฟ้าและโจมตีอย่างกะทันหัน ความเสียหายของท่านี้จะไม่สร้างความโกรธให้กับเป้าหมายอีกต่อไป และทำให้เกิดเอฟเฟกต์ 【Will-O-Wisp】",
		zawakeEffectDesc_es = "Chandelure parpadea hacia el frente de los enemigos en fila, antes de convocar una enorme sala de Formación de Fuego y volar hacia el cielo. Luego realiza un ataque repentino frente a los enemigos, causando#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#a los objetivos. El daño de este movimiento no creará más ira para el objetivo e inflige el efecto [Will-O-Wisp].\n[Will-O-Wisp]: Reduce 150 puntos de ira instantáneamente y reduce la misma cantidad de ira antes del siguiente movimiento. Y reduce la velocidad de recuperación de ira de los enemigos en 30% por 2 rondas",
		starEffectDesc_kr = "Will-O-Wisp로 적을 공격한 유닛은 다음 궁극기에서 치명타가 20% 증가합니다.",
		zawakeEffectDesc_en = "Chandelure flashes to the front of the enemies in a row, before summoning a huge Fire Formation room and flies to the sky. It then makes a sudden attack in front of the enemies, dealing#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#to the targets. The damage of this move will not create more rage for the target and inflicts [Will-O-Wisp] effect.\n[Will-O-Wisp]: Reduces 150 rage points instantly and reduces the same amount of rage before the next move.And reduce enemies Rage recover Speed by 30% for 2 rounds",
		simDesc_kr = "Chandelure는 거대한 Fire Spirit Formation을 소환하기 전에 기둥의 적 앞쪽으로 번쩍입니다. 그러다가 하늘로 날아가서 갑자기 공격을 가합니다. 이 공격의 피해는 대상에게 더 많은 분노를 생성하지 않으며 【Will-O-Wisp】 효과를 적용합니다.",
		zawakeSimpleDesc_th = "ผลกระทบเพิ่มเติม: ลดความเร็วในการฟื้นฟู Rage ของศัตรู 30% เป็นเวลา 2 รอบ",
		zawakeSimpleDesc_kr = "추가 효과: 2라운드 동안 적의 분노 회복 속도를 30% 감소시킵니다.",
		starEffectDesc_en = "Units that have hit the enemy with Will-O-Wisp will increase its crit by 20% in its next Ultimate move",
		zawakeSimpleDesc_vn = "Efeito adicional: Reduz a velocidade de recuperação de raiva dos inimigos em 30% por 2 rodadas",
