	[31512] = {
		zawakeEffectDesc_es = "Larvesta se envuelve en fuego y golpea a un solo enemigo, infligiendo (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Da [Sun Cloak] al aliado de primera línea con el HP máximo más alto durante 3 rondas. Hay un 50 % de posibilidades de darle [Sun Cloak] al otro aliado de primera línea con el HP máximo más alto durante 3 rondas (Capa solar: la mejora, cuando es atacada, inflige daño de fuego equivalente al 120 % del SP.ATK de Volcarona. Posee el sol Capa elimina el efecto Bobina)",
		zawakeEffectDesc_vn = "Larvesta se cobre de fogo e se choca contra um único inimigo, infligindo (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Dá [Sun Cloak] ao aliado da linha de frente com o HP máximo mais alto por 3 rodadas. Há 50% de chance de dar [Sun Cloak] para outro aliado da linha de frente com o maior HP máximo por 3 rodadas (Sun Cloak: Buff, quando atacado, inflige dano de Fogo igual a 120% do SP.ATK de Volcarona. Possuir Sun Cloak remove o efeito Coil)",
		describe_th = "ลูกน้ำปิดบังตัวเองด้วยไฟและฟาดใส่ศัตรูตัวเดียว สร้างความเสียหาย (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# มอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าที่มี HP สูงสุดสูงสุดเป็นเวลา 3 รอบ (ผ้าคลุมอาทิตย์: บัฟ เมื่อถูกโจมตี จะสร้างความเสียหายทางไฟเท่ากับ 120% ของ SP.ATK ของ Volcarona การเป็นเจ้าของ Sun Cloak จะลบเอฟเฟกต์คอยล์ออก)",
		zawakeEffectDesc_kr = "라베스타는 불 속에 몸을 숨기고 적 한 명을 강타해 (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 3라운드 동안 최대 HP가 가장 높은 최전선 아군에게 [Sun Cloak]를 제공합니다. 50% 확률로 3라운드 동안 최대 HP가 가장 높은 다른 최전선 아군에게 [Sun Cloak] 부여(태양 망토: 버프 공격 시 볼카로나 SP.ATK의 120%만큼 화염 피해를 줍니다. 태양을 소유 망토는 코일 효과를 제거합니다)",
		zawakeEffectDesc_th = "ลูกน้ำปิดบังตัวเองด้วยไฟและฟาดใส่ศัตรูตัวเดียว สร้างความเสียหาย (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# มอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าที่มี HP สูงสุดสูงสุดเป็นเวลา 3 รอบ มีโอกาส 50% ที่จะมอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าอีกคนที่มี HP สูงสุดสูงสุดเป็นเวลา 3 รอบ (ผ้าคลุมอาทิตย์: บัฟเมื่อถูกโจมตีจะสร้างความเสียหายทางไฟเท่ากับ 120% ของ SP.ATK ของ Volcarona เป็นเจ้าของ Sun Cloak จะลบเอฟเฟกต์คอยล์)",
		describe_en = "Larvesta cloaks itself in fire and slams into a single enemy, inflicting (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Gives [Sun Cloak] to the front-line ally with the highest max HP for 3 rounds (Sun Cloak: Buff, when attacked, inflicts Fire damage equal to 120% of Volcarona's SP.ATK. Owning Sun Cloak removes the Coil effect)",
		describe_es = "Larvesta se envuelve en fuego y golpea a un solo enemigo, infligiendo (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Da [Sun Cloak] al aliado de primera línea con el HP máximo más alto durante 3 rondas (Capa solar: la mejora, cuando es atacada, inflige daño de Fuego equivalente al 120 % del SP.ATK de Volcarona. Poseer Capa solar elimina el efecto de bobina)",
		zawakeSimpleDesc_en = "#C0x5c9970#There is a 50% chance to give [Sun Cloak] to the another front-line ally with the highest max HP for 3 rounds",
		describe_vn = "Larvesta se cobre de fogo e se choca contra um único inimigo, infligindo (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Dá [Sun Cloak] ao aliado da linha de frente com o maior HP máximo por 3 rodadas (Sun Cloak: Buff, quando atacado, inflige dano de Fogo igual a 120% do SP.ATK de Volcarona. Possuir Sun Cloak remove o efeito Coil)",
		zawakeEffectDesc_en = "Larvesta cloaks itself in fire and slams into a single enemy, inflicting (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Gives [Sun Cloak] to the front-line ally with the highest max HP for 3 rounds. There is a 50% chance to give [Sun Cloak] to the another front-line ally with the highest max HP for 3 rounds(Sun Cloak: Buff, when attacked, inflicts Fire damage equal to 120% of Volcarona's SP.ATK. Owning Sun Cloak removes the Coil effect)",
		zawakeSimpleDesc_vn = "#C0x5c9970#Há 50% de chance de dar [Sun Cloak] para outro aliado da linha de frente com o HP máximo mais alto por 3 rodadas",
		zawakeSimpleDesc_id = "#C0x5c9970#Ada peluang 50% untuk memberikan [Sun Cloak] kepada sekutu garis depan lainnya dengan HP maksimal tertinggi selama 3 ronde",
		zawakeSimpleDesc_es = "#C0x5c9970#Hay un 50 % de posibilidades de darle [Sun Cloak] al otro aliado de primera línea con el HP máximo más alto durante 3 rondas.",
		describe_id = "Larvesta menyamarkan dirinya dalam api dan menghantam satu musuh, menimbulkan (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Memberikan [Sun Cloak] kepada sekutu garis depan dengan HP maksimal tertinggi selama 3 putaran (Sun Cloak: Buff, ketika diserang, menimbulkan damage Api setara dengan 120% SP.ATK Volcarona. Memiliki Sun Cloak menghilangkan efek Coil)",
		zawakeSimpleDesc_kr = "#C0x5c9970#3라운드 동안 최대 HP가 가장 높은 다른 최전방 아군에게 [Sun Cloak]을 줄 확률이 50%입니다.",
		zawakeEffectDesc_id = "Larvesta menyamarkan dirinya dalam api dan menghantam satu musuh, menimbulkan (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Memberikan [Sun Cloak] kepada sekutu garis depan dengan HP maksimal tertinggi selama 3 ronde. Ada peluang 50% untuk memberikan [Sun Cloak] kepada sekutu garis depan lain yang memiliki HP maksimal tertinggi selama 3 ronde (Sun Cloak: Buff, ketika diserang, menimbulkan damage Api setara dengan 120% SP.ATK Volcarona. Memiliki Sun Jubah menghilangkan efek Coil)",
		describe_kr = "라베스타는 불 속에 몸을 숨기고 적 한 명을 강타해 (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 최대 HP가 가장 높은 최전선 아군에게 3라운드 동안 [Sun Cloak] 부여 (태양 망토: 버프 공격 시 볼카로나 SP.ATK의 120%만큼 화염 피해를 입힙니다. 태양 망토를 소유하면 코일 효과가 제거됩니다)",
		zawakeSimpleDesc_th = "#C0x5c9970#มีโอกาส 50% ที่จะมอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าอีกคนที่มี HP สูงสุดสูงสุดเป็นเวลา 3 รอบ",
		id = 31512
