	[31522] = {
		zawakeEffectDesc_es = "Volcarona esparce una nube de polvo irritante sobre un solo enemigo para prenderle fuego, infligiéndole (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Da [Sun Cloak] al aliado de primera línea con el HP máximo más alto durante 3 rondas. Hay un 50% de probabilidad de darle [Sun Cloak] al otro aliado de primera línea con el HP máximo más alto durante 3 rondas. (Capa solar: la mejora, cuando es atacada, inflige daño de fuego equivalente al 120% del SP.ATK de Volcarona. Poseer Capa solar elimina el efecto de bobina)",
		zawakeEffectDesc_vn = "Volcarona espalha uma nuvem de pólvora irritante em um único inimigo para incendiá-lo, infligindo (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Dá [Sun Cloak] ao aliado da linha de frente com o HP máximo mais alto por 3 rodadas. Há 50% de chance de dar [Sun Cloak] ao outro aliado da linha de frente com o HP máximo mais alto por 3 rodadas. (Sun Cloak: Buff, quando atacado, inflige dano de Fogo igual a 120% do SP.ATK de Volcarona. Possuir Sun Cloak remove o efeito Coil)",
		describe_th = "Volcarona โปรยเมฆผงระคายเคืองใส่ศัตรูตัวเดียวเพื่อจุดไฟ ทำให้ศัตรูติดไฟ (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# มอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าที่มี HP สูงสุดสูงสุดเป็นเวลา 3 รอบ (ผ้าคลุมอาทิตย์: บัฟ เมื่อถูกโจมตี จะสร้างความเสียหายทางไฟเท่ากับ 120% ของ SP.ATK ของ Volcarona การเป็นเจ้าของ Sun Cloak จะลบเอฟเฟกต์คอยล์ออก)",
		zawakeEffectDesc_kr = "볼카로나는 적 한 명에게 자극적인 가루 구름을 뿌려 불을 붙이며 (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 3라운드 동안 최대 HP가 가장 높은 최전선 아군에게 [Sun Cloak]를 줍니다. 3라운드 동안 최대 HP가 가장 높은 다른 최전선 아군에게 [Sun Cloak]를 줄 확률이 50%입니다. (태양 망토 : 버프 공격 시 볼카로나 SP.ATK의 120%만큼 화염 피해를 입힙니다. 태양 망토를 소유하면 코일 효과가 제거됩니다.)",
		zawakeEffectDesc_th = "Volcarona โปรยเมฆผงระคายเคืองใส่ศัตรูตัวเดียวเพื่อจุดไฟ ทำให้ศัตรูติดไฟ (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# มอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าที่มีค่า HP สูงสุดสูงสุดเป็นเวลา 3 รอบ มีโอกาส 50% ที่จะมอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าอีกคนที่มีค่า HP สูงสุดสูงสุดเป็นเวลา 3 รอบ (Sun Cloak: บัฟเมื่อถูกโจมตีจะสร้างความเสียหายทางไฟเท่ากับ 120% ของ SP.ATK ของ Volcarona การเป็นเจ้าของ Sun Cloak จะลบเอฟเฟกต์คอยล์)",
		describe_en = "Volcarona scatters a cloud of irritating powder on a single enemy to set it on fire, inflicting (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Gives [Sun Cloak] to the front-line ally with the highest max HP for 3 rounds (Sun Cloak: Buff, when attacked, inflicts Fire damage equal to 120% of Volcarona's SP.ATK. Owning Sun Cloak removes the Coil effect)",
		describe_es = "Volcarona esparce una nube de polvo irritante sobre un solo enemigo para prenderle fuego, infligiéndole (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Da [Sun Cloak] al aliado de primera línea con el HP máximo más alto durante 3 rondas (Capa solar: la mejora, cuando es atacada, inflige daño de Fuego equivalente al 120 % del SP.ATK de Volcarona. Poseer Capa solar elimina el efecto de bobina)",
		zawakeSimpleDesc_en = "#C0x5c9970#There is a 50% chance to give [Sun Cloak] to the another front-line ally with the highest max HP for 3 rounds",
		describe_vn = "Volcarona espalha uma nuvem de pólvora irritante em um único inimigo para incendiá-lo, infligindo (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Dá [Sun Cloak] ao aliado da linha de frente com o maior HP máximo por 3 rodadas (Sun Cloak: Buff, quando atacado, inflige dano de Fogo igual a 120% do SP.ATK de Volcarona. Possuir Sun Cloak remove o efeito Coil)",
		zawakeEffectDesc_en = "Volcarona scatters a cloud of irritating powder on a single enemy to set it on fire, inflicting (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Gives [Sun Cloak] to the front-line ally with the highest max HP for 3 rounds.There is a 50% chance to give [Sun Cloak] to the another front-line ally with the highest max HP for 3 rounds. (Sun Cloak: Buff, when attacked, inflicts Fire damage equal to 120% of Volcarona's SP.ATK. Owning Sun Cloak removes the Coil effect)",
		zawakeSimpleDesc_vn = "#C0x5c9970#Há 50% de chance de dar [Sun Cloak] para outro aliado da linha de frente com o HP máximo mais alto por 3 rodadas",
		zawakeSimpleDesc_id = "#C0x5c9970#Ada peluang 50% untuk memberikan [Sun Cloak] kepada sekutu garis depan lainnya dengan HP maksimal tertinggi selama 3 ronde",
		zawakeSimpleDesc_es = "#C0x5c9970#Hay un 50 % de posibilidades de darle [Sun Cloak] al otro aliado de primera línea con el HP máximo más alto durante 3 rondas.",
		describe_id = "Volcarona menyebarkan awan bubuk yang mengiritasi ke satu musuh dan membakarnya, menimbulkan (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Memberikan [Sun Cloak] kepada sekutu garis depan dengan HP maksimal tertinggi selama 3 putaran (Sun Cloak: Buff, ketika diserang, menimbulkan damage Api setara dengan 120% SP.ATK Volcarona. Memiliki Sun Cloak menghilangkan efek Coil)",
		zawakeSimpleDesc_kr = "#C0x5c9970#3라운드 동안 최대 HP가 가장 높은 다른 최전방 아군에게 [Sun Cloak]을 줄 확률이 50%입니다.",
		zawakeEffectDesc_id = "Volcarona menyebarkan awan bubuk yang mengiritasi ke satu musuh dan membakarnya, menyebabkan (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Memberikan [Sun Cloak] kepada sekutu garis depan dengan HP maksimal tertinggi selama 3 ronde. Ada peluang 50% untuk memberikan [Sun Cloak] kepada sekutu lini depan lainnya dengan HP maksimal tertinggi selama 3 ronde. (Sun Cloak: Buff, ketika diserang, menimbulkan Fire damage setara dengan 120% SP.ATK Volcarona. Memiliki Sun Cloak menghilangkan efek Coil)",
		describe_kr = "볼카로나는 적 한 명에게 자극적인 가루 구름을 뿌려 불을 붙이며 (#C0x3D8A99#150% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 최대 HP가 가장 높은 최전선 아군에게 3라운드 동안 [Sun Cloak] 부여 (태양 망토: 버프 공격 시 볼카로나 SP.ATK의 120%만큼 화염 피해를 입힙니다. 태양 망토를 소유하면 코일 효과가 제거됩니다)",
		zawakeSimpleDesc_th = "#C0x5c9970#มีโอกาส 50% ที่จะมอบ [Sun Cloak] ให้กับพันธมิตรแนวหน้าอีกคนที่มี HP สูงสุดสูงสุดเป็นเวลา 3 รอบ",
		id = 31522
	},
	[31523] = {
		describe_th = "Volcarona เข้าไปในรังไหมที่ปกคลุมไปด้วยไฟ และเมื่อออกมาจะมีฝนตกลงมาเป็นไฟ สร้างความเสียหาย (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. เพิ่มความเสี่ยง 20% กับศัตรูหลักเป็นเวลา 1 รอบ เพิ่มโอกาสเป็น [Invite] 20% สามารถเชิญพันธมิตร 3 คนมาโจมตีศัตรูได้",
		zawakeEffectDesc_vn = "Volcarona entra no casulo coberto de fogo e faz chover fogo de cima quando sai. Inflige (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aplica 20% de Vulnerabilidade ao inimigo principal por 1 rodada. Aumenta a chance para [Invite] em 20%. Pode convidar 4 aliados para atacar o inimigo",
		simDesc_es = "Volcarona entra al capullo cubierto de fuego y hace llover fuego desde arriba cuando sale. Aplica vulnerabilidad al enemigo principal y aumenta la posibilidad de [Invite].",
		describe_es = "Volcarona entra al capullo cubierto de fuego y hace llover fuego desde arriba cuando sale. Inflige (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aplica un 20% de vulnerabilidad al enemigo principal durante 1 ronda. Aumenta la posibilidad de [Invite] en un 20%. Puede invitar a 3 aliados para atacar al enemigo.",
		zawakeEffectDesc_th = "Volcarona เข้าไปในรังไหมที่ปกคลุมไปด้วยไฟ และเมื่อออกมาจะมีฝนตกลงมาเป็นไฟ สร้างความเสียหาย (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. เพิ่มความเสี่ยง 20% กับศัตรูหลักเป็นเวลา 1 รอบ เพิ่มโอกาสเป็น [Invite] 20% สามารถเชิญพันธมิตรได้สูงสุด 4 คนเพื่อโจมตีศัตรู",
		starEffectDesc_id = "Efek ekstra: Menimbulkan 15% Kerentanan Bug pada target selama 2 putaran",
		starEffectDesc_es = "Efecto adicional: inflige un 15 % de vulnerabilidad a los errores a los objetivos durante 2 rondas.",
		zawakeSimpleDesc_en = "Can invite up 3 allies to attack the enemy\n#F20#\n#F40##C0x5c9970#→Can invite up 4 allies to attack the enemy",
		describe_vn = "Volcarona entra no casulo coberto de fogo e faz chover fogo de cima quando sai. Inflige (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aplica 20% de Vulnerabilidade ao inimigo principal por 1 rodada. Aumenta a chance para [Invite] em 20%. Pode convidar até 3 aliados para atacar o inimigo",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: สร้างช่องโหว่ Bug 15% ต่อเป้าหมายเป็นเวลา 2 รอบ",
		starEffectDesc_vn = "Efeito extra: Inflige 15% de vulnerabilidade a bugs aos alvos por 2 rodadas",
		zawakeEffectDesc_kr = "볼카로나는 불로 뒤덮인 누에고치 안으로 들어가고, 나오면 위에서부터 불을 쏟아낸다. (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. 1라운드 동안 주 적에게 20%의 취약성을 적용합니다. [Invite] 확률이 20% 증가합니다. 적을 공격하기 위해 아군 4명을 초대할 수 있습니다.",
		describe_en = "Volcarona enters the cocoon covered in fire, and rains fire down from above when it comes out. Inflicts (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Applies 20% Vulnerability to the main enemy for 1 round. Increases the chance to [Invite] by 20%. Can invite up 3 allies to attack the enemy",
		zawakeEffectDesc_id = "Gunung berapi memasuki kepompong yang tertutup api, dan menghujani api dari atas saat keluar. Dampak (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Menerapkan 20% Kerentanan pada musuh utama selama 1 putaran. Meningkatkan peluang menjadi [Invite] sebesar 20%. Dapat mengundang hingga 4 sekutu untuk menyerang musuh",
		describe_id = "Gunung berapi memasuki kepompong yang tertutup api, dan menghujani api dari atas saat keluar. Dampak (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Menerapkan 20% Kerentanan pada musuh utama selama 1 putaran. Meningkatkan peluang menjadi [Invite] sebesar 20%. Dapat mengundang hingga 3 sekutu untuk menyerang musuh",
		simDesc_en = "Volcarona enters the cocoon covered in fire, and rains fire down from above when it comes out. Applies Vulnerability to the main enemy and increases the chance to [Invite].",
		simDesc_vn = "Volcarona entra no casulo coberto de fogo e faz chover fogo de cima quando sai. Aplica Vulnerabilidade ao inimigo principal e aumenta a chance para [Invite].",
		describe_kr = "볼카로나는 불로 뒤덮인 누에고치 안으로 들어가고, 나오면 위에서부터 불을 쏟아낸다. (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. 1라운드 동안 주 적에게 20%의 취약성을 적용합니다. [Invite] 확률이 20% 증가합니다. 아군 3명을 초대하여 적을 공격할 수 있습니다.",
		simDesc_th = "Volcarona เข้าไปในรังไหมที่ปกคลุมไปด้วยไฟ และเมื่อออกมาจะมีฝนตกลงมาเป็นไฟ ใช้ช่องโหว่กับศัตรูหลักและเพิ่มโอกาสเป็น [Invite]",
		zawakeEffectDesc_es = "Volcarona entra al capullo cubierto de fuego y hace llover fuego desde arriba cuando sale. Inflige (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aplica un 20% de vulnerabilidad al enemigo principal durante 1 ronda. Aumenta la posibilidad de [Invite] en un 20%. Puede invitar hasta 4 aliados para atacar al enemigo.",
		starEffectDesc_kr = "추가 효과: 2라운드 동안 대상에게 15%의 버그 취약성을 부여합니다.",
		zawakeEffectDesc_en = "Volcarona enters the cocoon covered in fire, and rains fire down from above when it comes out. Inflicts (#C0x3D8A99#250% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Applies 20% Vulnerability to the main enemy for 1 round. Increases the chance to [Invite] by 20%. Can invite up 4 allies to attack the enemy",
		simDesc_kr = "볼카로나는 불로 뒤덮인 누에고치 안으로 들어가고, 나오면 위에서부터 불을 쏟아낸다. 주 적에게 취약성을 적용하고 확률을 [Invite]으로 증가시킵니다.",
		zawakeSimpleDesc_th = "สามารถเชิญพันธมิตรได้สูงสุด 3 คนเพื่อโจมตีศัตรู\n#F20#\n#F40##C0x5c9970#→สามารถเชิญพันธมิตรสูงสุด 4 คนเพื่อโจมตีศัตรูได้",
		zawakeSimpleDesc_kr = "적을 공격하기 위해 아군 3명을 초대할 수 있습니다\n#F20#\n#F40##C0x5c9970#→아군 4명을 초대하여 적을 공격할 수 있습니다",
		starEffectDesc_en = "Extra effect: Inflicts 15% Bug Vulnerability to targets for 2 rounds",
		zawakeSimpleDesc_vn = "Pode convidar até 3 aliados para atacar o inimigo\n#F20#\n#F40##C0x5c9970#→Pode convidar até 4 aliados para atacar o inimigo",
		zawakeSimpleDesc_id = "Dapat mengundang hingga 3 sekutu untuk menyerang musuh\n#F20#\n#F40##C0x5c9970#→Dapat mengundang hingga 4 sekutu untuk menyerang musuh",
		id = 31523,
		zawakeSimpleDesc_es = "Puede invitar a 3 aliados para atacar al enemigo\n#F20#\n#F40##C0x5c9970#→Puede invitar a 4 aliados para atacar al enemigo",
		simDesc_id = "Gunung berapi memasuki kepompong yang tertutup api, dan menghujani api dari atas saat keluar. Menerapkan Kerentanan pada musuh utama dan meningkatkan peluang menjadi [Invite]."
	},
	[31526] = {
		describe_id = "Saat menyerang, [Invite] 1 reli acak (Invite: Reli yang diundang akan menyerang musuh secara basic). Memiliki peluang #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# untuk mengundang sekutu, yang meningkat hingga 40% jika target memiliki persentase HP rendah.\nLebih lanjut meningkatkan peluang sebesar 40% jika musuh bertipe Bug (tidak bisa dihilangkan)",
		zawakeEffectDesc_vn = "Quando atacar, [Invite] 1 rally aleatório (Convite: O rally convidado irá atacar básico o inimigo). Tem uma#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#chance de convidar um aliado, que aumenta até 40% se o alvo tiver uma porcentagem baixa de HP.\nAumenta ainda mais a chance em 40% se o inimigo for do tipo Bug (não pode ser dissipado)",
		describe_vn = "Quando atacar, [Invite] 1 rally aleatório (Convite: O rally convidado irá atacar básico o inimigo). Tem uma#C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#chance de convidar um aliado, que aumenta até 40% se o alvo tiver uma porcentagem baixa de HP.\nAumenta ainda mais a chance em 40% se o inimigo for do tipo Bug (não pode ser dissipado)",
		starEffectDesc_id = "Efek tambahan: +15% DMG pada sekutu yang diundang menyerang",
		zawakeEffectDesc_th = "เมื่อโจมตี [Invite] สุ่มแรลลี่ 1 ครั้ง (เชิญ: แรลลี่ที่ได้รับเชิญจะโจมตีศัตรูพื้นฐาน) มีโอกาสเชิญพันธมิตร #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ซึ่งจะเพิ่มขึ้นถึง 40% หากเป้าหมายมีเปอร์เซ็นต์ HP ต่ำ \n เพิ่มโอกาสอีก 40% หากศัตรูเป็นประเภทแมลง (ไม่สามารถ ถูกไล่ออก)",
		starEffectDesc_kr = "추가 효과: 공격에 초대된 아군에 대한 데미지 +15%",
		describe_es = "Cuando ataca, [Invite] 1 manifestación aleatoria (Invitación: la manifestación invitada atacará de forma básica al enemigo). Tiene una#C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B#posibilidad de invitar a un aliado, que aumenta hasta un 40% si el objetivo tiene un porcentaje de HP bajo.\nAumenta aún más la probabilidad en un 40% si el enemigo es de tipo Bug (no puede ser disipado)",
		zawakeSimpleDesc_en = "the invite chance is increased by10%",
		starEffectDesc_es = "Efecto extra: +15% de daño para los aliados invitados a atacar.",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: +15% DMG สำหรับพันธมิตรที่ได้รับเชิญให้โจมตี",
