	[32421] = {
		describe_vn = "#C0xB15BFF#<Servidor Beta>#C0x5B545B#, Kyurem inflige (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#ao inimigo (no modo de batalha automática, sempre selecione primeiro o alvo restrito, independentemente de sua localização, se houver). Aumenta 20% SP.ATK e 20% P.ATK por 2 rodadas. Se Kyurem tiver 0 Floco de Neve, ganha um.",
		describe_kr = "#C0xB15BFF#<베타 서버>#C0x5B545B# 큐레무는 적에게 (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#를 줍니다. (자동전투 모드에서는, 위치에 관계없이 항상 제한된 대상을 먼저 선택하십시오(있는 경우). 2라운드 동안 SP.ATK가 20%, P.ATK가 20% 증가합니다. 큐레무에 눈송이가 0개 있으면 1개를 얻습니다.",
		describe_en = "#C0xB15BFF#<Beta Server>#C0x5B545B#, Kyurem inflicts (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#to the enemy (In the auto-battle mode, always select the restricted target first despite its location if there is one). Increases 20% SP.ATK and 20% P.ATK for 2 rounds. If Kyurem has 0 Snowflake, gains one.",
		describe_id = "#C0xB15BFF#<Server Beta>#C0x5B545B#, Kyurem memberikan (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#kepada musuh (Dalam mode pertarungan otomatis, selalu pilih target yang dibatasi terlebih dahulu meskipun lokasinya jika ada). Meningkatkan 20% SP.ATK dan 20% P.ATK selama 2 putaran. Jika Kyurem memiliki 0 Snowflake, dapatkan satu.",
