	[32641] = {
		zawakeEffectDesc_es = "#L10#Forma de pirueta:#L0#Meloetta baila para atacar objetivos enemigos, inflige#C0xE69900#80%P.ATK#C0x5B545B#+$(skillLevel*4*24)$ de#C0xF13B54#P.DMG#C0x5B545B# y aumenta la reducción de DAÑO en un 18%. de Meloetta gemela durante 3 rondas \n#F10#\n#F40##L10#Aria Forme:#L0#Meloetta canta para atacar a cualquier objetivo enemigo, reparte#C0x3D8A99#100% SP. ATK#C0x5B545B#+$(skillLevel*4*24)$ de#C0xF13B54#SP. DMG#C0x5B545B# y aumenta la bonificación de ATK en un 18% de Meloetta twin durante 3 rondas",
		zawakeEffectDesc_vn = "#L10#Forma de pirueta:#L0#Meloetta dança para atacar alvos inimigos, distribui#C0xE69900#80%P.ATK#C0x5B545B#+$(skillLevel*4*24)$ de#C0xF13B54#P.DMG#C0x5B545B# e aumenta a redução de DMG em 18% de Meloetta gêmea por 3 rodadas \n#F10#\n#F40##L10#Aria Forme:#L0#Meloetta canta para atacar qualquer alvo inimigo, acertos#C0x3D8A99#100%SP. ATK#C0x5B545B#+$(skillLevel*4*24)$ de#C0xF13B54#SP. DMG#C0x5B545B#, e aumenta o bônus de ATK em 18% do gêmeo Meloetta por 3 rodadas",
