	[32716] = {
		describe_id = [[
#L10#Unduh:#L0#Sebelum menyerang, bandingkan P.DEF dan SP.DEF target dan gunakan yang lebih rendah untuk menyesuaikan jenis serangannya dan tingkatkan#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#ATK yang dipilih (P. atau Sp.); Untuk mendapatkan setiap sekutu Pokemon Tipe Bug atau Baja, tingkatkan bonus DMG dan tingkat Kekebalan Kontrol sebesar 10%
#F20#
#F40##L10#Penyimpanan Energi:#L0#Kemarahan yang Meluap akan disimpan sebagai Energi , hingga 300, ubah menjadi Kemarahan sebelum bertindak, prioritaskan untuk menyimpan Energi selama status Pengisian
#F20#
#F40##L10#Legion:#L0#mulai dengan 1 [Soldier] (maks 2), saat memanggil Prajurit , menyembuhkan dirinya sendiri dengan 20% HP yang hilang, pertama kali tanpa Prajurit akan memanggil 2 Prajurit
#F20#
#F40##L10#Penghancuran Diri:#L0#Saat HP menjadi nol, masuk ke mode Penghancuran Diri, hitung mundur selama 3 putaran, tidak dapat bergerak selama hitungan mundur, meledak setelah melakukan tiga serangan aktif atau hitungan mundur berakhir, memberikan 400% SP.DMG dasar kepada semua musuh, untuk setiap putaran yang lalu, rasio meningkat sebesar 100%]],
		zawakeEffectDesc_vn = "Aumento do efeito: o número inicial de soldados +1. armazenamento total de energia ao entrar no campo de batalha; Quando soidiers [sacrifices], um adicional de 20% do próprio HP perdido será reparado; Quando o soldado estiver em campo, aumente em 10% a taxa de controle imunológico e o DMG dos aliados do tipo Bug/Steel; Após a primeira vez sem soldado e convocando um soldado por 3 rodadas, se Genesect entrar novamente no estado sem soldados, ele poderá convocar 2 soldados; Quando o efeito [Self-destruction] é acionado, os soldados se autodestruirão com Genesect, a autodestruição de cada soldado causará 150% de DMG de ATK a todos os inimigos",
		describe_vn = [[
#L10#Baixar:#L0#Antes de atacar, compare o P.DEF e SP.DEF do alvo e use o inferior para ajustar seu próprio tipo de ataque e aumentar#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#o ATK selecionado (P. ou Esp.); Por ter cada aliado Pokémon do tipo Bug ou do tipo Steel, aumente seu bônus DMG e taxa de controle imunológico em 10%
#F20#
#F40##L10#Armazenamento de energia:#L0#Overflow Anger será armazenado como energia , até 300, converte em Raiva antes da ação, prioridade para armazenar energia durante o estado de carregamento
#F20#
#F40##L10#Legião:#L0#comece com 1 [Soldier] (máx. 2), ao invocar o Soldado , cura-se com 20% de HP perdido, na primeira vez sem soldados invocará 2 soldados
#F20#
#F40##L10#Autodestruição:#L0#Quando o HP chegar a zero, entre no modo Autodestruição, contagem regressiva para 3 rodadas, incapaz de se mover durante a contagem regressiva, explode após receber três ataques ativos ou a contagem regressiva termina, o básico causa 400% SP.DMG para todos os inimigos, para cada rodada passada, aumento de proporção em 100%]],
		starEffectDesc_id = "Peningkatan efek: jumlah prajurit awal +1. penyimpanan energi penuh saat memasuki medan perang; Saat Genesect berada di lapangan, tingkatkan kerusakan ledakan diri unit sekutu sebesar 20%",
		zawakeEffectDesc_th = "เอฟเฟกต์เสริม: จำนวนทหารเริ่มต้น +1 การจัดเก็บพลังงานเต็มเมื่อเข้าสู่สนามรบ เมื่อซอยเดียร์ [sacrifices] HP ที่เสียไปเพิ่มอีก 20% จะได้รับการซ่อมแซม เมื่อทหารอยู่ในสนาม เพิ่มอัตราการควบคุมภูมิคุ้มกัน 10% และสร้างความเสียหายให้กับพันธมิตรที่เป็นแมลง/เหล็ก หลังจากครั้งแรกโดยไม่มีทหารและเรียกทหารออกมา 3 รอบ หากเจเนเซ็กต์เข้าสู่สภาวะไม่มีทหารอีกครั้ง จะสามารถเรียกทหารออกมาได้ 2 คน เมื่อเอฟเฟกต์ [Self-destruction] ทำงาน นักดินจะทำลายตัวเองด้วย Genesect การทำลายตัวเองของนักดินแต่ละคนจะสร้างความเสียหาย 150% ATK DMG ให้กับศัตรูทั้งหมด",
		starEffectDesc_kr = "효과 강화 : 초기 병사 수 +1. 전장에 들어갈 때 완전한 에너지 저장; 제네섹트가 필드에 있을 때 아군 유닛의 자폭 피해가 20% 증가합니다.",
		describe_es = [[
#L10#Descargar:#L0#Antes de atacar, compara el P.DEF y SP.DEF del objetivo y usa el inferior para ajustar su propio tipo de ataque y aumentar#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#el ATK seleccionado (P. o sp.); Por tener cada Pokémon de tipo Bicho o Tipo Acero como aliado, aumenta su bonificación de daño y su tasa de inmunidad de control en un 10 %
#F20#
#F40##L10#Almacenamiento de energía:#L0#Overflow Anger se almacenará como energía , hasta 300, se convierte en ira antes de la acción, prioridad para almacenar energía durante el estado de carga
#F20#
#F40##L10#Legión:#L0#comienza con 1 [Soldier] (máximo 2), al convocar a un soldado , se cura a sí mismo con un 20% de HP perdido, la primera vez sin soldados convocará a 2 soldados
#F20#
#F40##L10#Autodestrucción:#L0#Cuando HP se vuelve cero, ingresa al modo de autodestrucción, cuenta regresiva para 3 rondas, no puede moverse durante la cuenta regresiva, explota después de recibir tres ataques activos o finaliza la cuenta regresiva, el daño básico inflige 400% SP.DMG a todos los enemigos, por cada ronda pasada, la proporción aumenta en un 100%]],
		zawakeSimpleDesc_en = "#C0x5c9970#When soidiers [sacrifices], an additional 20% of own lost HP will be repaired; When the soldier is on the field, increase 10% immune control rate and DMG of Bug/Steel Type allies; After the first time without a soldier and summoning a soldier for 3 rounds, if Genesect enter again the state of no soldiers, it can summon 2 soidier; When the [Self-destruction] effect is triggered, the soildiers will self-destruct with Genesect, each soildier's self-destruction will cause 150% ATK DMG to all enemies#C0x5B545B#",
		starEffectDesc_es = "Mejora del efecto: el número inicial de soldados +1. almacenamiento total de energía al entrar en el campo de batalla; Cuando Genesect está en el campo, aumenta el daño de autoexplosión de las unidades aliadas en un 20%",
		starEffectDesc_th = "เอฟเฟกต์เสริม: จำนวนทหารเริ่มต้น +1 การจัดเก็บพลังงานเต็มเมื่อเข้าสู่สนามรบ เมื่อ Genesect อยู่บนสนาม เพิ่มความเสียหายจากการระเบิดตัวเองของยูนิตพันธมิตร 20%",
		zawakeEffectDesc_id = "Peningkatan efek: jumlah prajurit awal +1. penyimpanan energi penuh saat memasuki medan perang; Saat soidiers [sacrifices], tambahan 20% HP miliknya yang hilang akan diperbaiki; Saat prajurit berada di lapangan, tingkatkan 10% tingkat kontrol kekebalan dan DMG sekutu Tipe Bug/Baja; Setelah pertama kali tanpa prajurit dan memanggil prajurit selama 3 ronde, jika Genesect kembali masuk ke status tanpa prajurit, ia dapat memanggil 2 prajurit; Ketika efek [Self-destruction] terpicu, soildier akan menghancurkan dirinya sendiri dengan Genesect, setiap penghancuran diri soildier akan menyebabkan 150% ATK DMG ke semua musuh",
		zawakeEffectDesc_es = "Mejora del efecto: el número inicial de soldados +1. almacenamiento total de energía al entrar en el campo de batalla; Cuando los soldados [sacrifices], se reparará un 20% adicional de HP perdido; Cuando el soldado está en el campo, aumenta un 10% la tasa de control inmunológico y el DAÑO de los aliados tipo Insecto/Acero; Después de la primera vez sin soldado y convocando a un soldado durante 3 rondas, si Genesect vuelve a entrar en estado sin soldados, puede convocar a 2 soldados; Cuando se activa el efecto [Self-destruction], los soldados se autodestruirán con Genesect, la autodestrucción de cada soldado causará 150% ATK DAÑO a todos los enemigos.",
		describe_en = [[
#L10#Download:#L0#Before attacking, compare target's P.DEFand SP.DEF and use the lower one to adjust its own type of attack and increase#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#the selected ATK(P. or Sp.); For having each Bug-type or Steel-type Pokemon ally, increase its DMG bonus and Control Immune rate by 10%
#F20#
#F40##L10#Energy Storage:#L0#Overflow Anger will be stored as Energy, up to 300, convert into Anger before action, priority to store Energy during Charging state
#F20#
