	[33041] = {
		zawakeEffectDesc_es = "#C0xC0C0C0#¡Como el agua, invisible y poderoso!#C0x5B545B#\n#F10#\n#F40#El Greninja de Ash condensa un pequeño shuriken de agua y lo lanza rápidamente al único objetivo del enemigo (la velocidad de ataque prioritaria es la más lenta), causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, roba el 10% de velocidad y SP.ATK del objetivo e inflige un 10% de vulnerabilidad al agua (se puede acumular 3 veces), dura 3 rondas .",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Como água, invisível e poderoso!#C0x5B545B#\n#F10#\n#F40#O Greninja de Ash condensa uma pequena shuriken de água e rapidamente a lança no único alvo do inimigo (a velocidade de ataque prioritário é a mais lenta), causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, rouba 10% de velocidade e SP.ATK do alvo e inflige 10% de vulnerabilidade à água (pode ser acumulado 3 vezes), dura 3 rodadas .",
		describe_th = "#C0xC0C0C0#เหมือนน้ำ ที่มองไม่เห็นและทรงพลัง!#C0x5B545B#\n#F10#\n#F40#Greninja ของ Ash ควบแน่นชูริเคนน้ำขนาดเล็ก และขว้างมันไปที่เป้าหมายเดียวของศัตรูอย่างรวดเร็ว (ความเร็วการโจมตีสำคัญจะช้าที่สุด) ทำให้ #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# ขโมยความเร็วของเป้าหมาย 10% และสร้างความเสียหายต่อธาตุน้ำ 10% (สามารถซ้อนได้ 3 ครั้ง) มีผล 2 รอบ",
		zawakeEffectDesc_kr = "#C0xC0C0C0#물처럼 보이지 않고 강력합니다!#C0x5B545B#\n#F10#\n#F40#애쉬의 그레닌자는 작은 물 수리검을 응축하여 적의 단일 대상에게 빠르게 던집니다(우선 공격 속도가 가장 느립니다). #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 대상의 속도 및 SP.ATK를 10% 훔치고 물 취약성을 10% 부여합니다(3회 중첩 가능). 3라운드 동안 지속됩니다. .",
		zawakeEffectDesc_th = "#C0xC0C0C0#เหมือนน้ำ ที่มองไม่เห็นและทรงพลัง!#C0x5B545B#\n#F10#\n#F40#Greninja ของ Ash ควบแน่นชูริเคนน้ำขนาดเล็ก และขว้างมันไปที่เป้าหมายเดียวของศัตรูอย่างรวดเร็ว (ความเร็วการโจมตีสำคัญจะช้าที่สุด) ทำให้ #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# ขโมยความเร็ว&SP.ATK ของเป้าหมาย 10% และสร้างความเสียหายต่อธาตุน้ำ 10% (สามารถซ้อนทับได้ 3 ครั้ง) ใช้งานได้ 3 รอบ .",
		describe_en = "#C0xC0C0C0#Like water,invisible and powerful!#C0x5B545B#\n#F10#\n#F40#Ash's Greninja condenses a small water shuriken, and quickly throws it at the enemy's single target(priority attack speed is the slowest), causing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, steals target's 10% Speed and inflicts 10% Water Vulnerability(can be stacked 3 times), last for 2 rounds.",
		describe_es = "#C0xC0C0C0#¡Como el agua, invisible y poderoso!#C0x5B545B#\n#F10#\n#F40#El Greninja de Ash condensa un pequeño shuriken de agua y lo lanza rápidamente al único objetivo del enemigo (la velocidad de ataque prioritaria es la más lenta), causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, roba el 10% de velocidad del objetivo e inflige un 10% de vulnerabilidad al agua (se puede acumular 3 veces), dura 2 rondas.",
		zawakeSimpleDesc_en = "steals target's 10% Speed and inflicts 10% Water Vulnerability(can be stacked 3 times), last for 2 rounds\n#F10#\n#F40##C0x5c9970#→steals target's 10% Speed&SP.ATK and inflicts 10% Water Vulnerability(can be stacked 3 times), last for 3 rounds",
		describe_vn = "#C0xC0C0C0#Como água, invisível e poderoso!#C0x5B545B#\n#F10#\n#F40#O Greninja de Ash condensa uma pequena shuriken de água e rapidamente a lança no único alvo do inimigo (a velocidade de ataque prioritário é a mais lenta), causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, rouba 10% de velocidade do alvo e inflige 10% de vulnerabilidade à água (pode ser acumulado 3 vezes), dura 2 rodadas.",
		zawakeEffectDesc_en = "#C0xC0C0C0#Like water,invisible and powerful!#C0x5B545B#\n#F10#\n#F40#Ash's Greninja condenses a small water shuriken, and quickly throws it at the enemy's single target(priority attack speed is the slowest), causing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, steals target's 10% Speed&SP.ATK and inflict 10% Water Vulnerability(can be stacked 3 times), last for 3 rounds.",
		zawakeSimpleDesc_vn = "rouba 10% de velocidade do alvo e inflige 10% de vulnerabilidade à água (pode ser acumulado 3 vezes), dura 2 rodadas\n#F10#\n#F40##C0x5c9970#→rouba 10% de velocidade e SP.ATK do alvo e inflige 10% de vulnerabilidade à água (pode ser empilhado 3 vezes), dura 3 rodadas",
		zawakeSimpleDesc_id = "mencuri 10% Kecepatan target dan menimbulkan 10% Kerentanan Air (dapat ditumpuk 3 kali), bertahan selama 2 ronde\n#F10#\n#F40##C0x5c9970#→mencuri 10% Kecepatan&SP.ATK target dan menimbulkan 10% Kerentanan Air (bisa di stack 3 kali), bertahan selama 3 putaran",
		zawakeSimpleDesc_es = "roba el 10% de velocidad del objetivo e inflige un 10% de vulnerabilidad al agua (se puede acumular 3 veces), dura 2 rondas\n#F10#\n#F40##C0x5c9970#→roba el 10% de velocidad y SP.ATK del objetivo e inflige un 10% de vulnerabilidad al agua (se puede acumular 3 veces), dura 3 rondas",
		describe_id = "#C0xC0C0C0#Seperti air, tidak terlihat dan kuat!#C0x5B545B#\n#F10#\n#F40#Greninja Ash mengembunkan shuriken air kecil, dan dengan cepat melemparkannya ke satu target musuh (kecepatan serangan prioritas paling lambat), menyebabkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, mencuri 10% Kecepatan target dan menimbulkan 10% Kerentanan Air (dapat ditumpuk 3 kali), bertahan selama 2 ronde.",
		zawakeSimpleDesc_kr = "대상의 속도 10%를 훔치고 물 취약성 10% 부여(3회 중첩 가능), 2라운드 동안 지속\n#F10#\n#F40##C0x5c9970#→대상의 속도&SP.ATK 10%를 빼앗고 물 취약성 10% 부여 (3회 중첩 가능), 3라운드 동안 지속됩니다.",
		zawakeEffectDesc_id = "#C0xC0C0C0#Seperti air, tidak terlihat dan kuat!#C0x5B545B#\n#F10#\n#F40#Greninja Ash mengembunkan shuriken air kecil, dan dengan cepat melemparkannya ke satu target musuh (kecepatan serangan prioritas paling lambat), menyebabkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, mencuri 10% Kecepatan&SP.ATK target dan menimbulkan 10% Kerentanan Air (dapat ditumpuk 3 kali), bertahan selama 3 ronde .",
		describe_kr = "#C0xC0C0C0#물처럼 보이지 않고 강력합니다!#C0x5B545B#\n#F10#\n#F40#애쉬의 그레닌자는 작은 물 수리검을 응축하여 적의 단일 대상에게 빠르게 던집니다(우선 공격 속도가 가장 느립니다). #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 대상의 속도를 10% 훔치고 물 취약성을 10% 부여합니다(3회 중첩 가능). 2라운드 동안 지속됩니다.",
		zawakeSimpleDesc_th = "ขโมยความเร็ว 10% ของเป้าหมาย และสร้างความเสียหายทางน้ำ 10% (สามารถซ้อนกันได้ 3 ครั้ง) คงอยู่ 2 รอบ\n#F10#\n#F40##C0x5c9970# → ขโมยความเร็ว&SP.ATK ของเป้าหมาย 10% และสร้างความเสียหายทางน้ำ 10% (สามารถซ้อนได้ 3 ครั้ง) ใช้ได้ 3 รอบ",
		id = 33041
