	[35612] = {
		simDesc_vn = "Phantump penetra seus chifres em um único alvo inimigo para absorver seus nutrientes",
		describe_es = "Phantump penetra su cuerno de madera para absorber nutrientes de un solo enemigo para tratar#C0xE69900#110%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# y absorber el 8% de la corriente del objetivo (hasta el 10% del HP máximo del usuario).",
