	[36313] = {
		describe_th = [[
#C0xC0C0C0#ฉันแน่ใจว่าฉันสามารถสร้างเพชรแท้ได้!#C0x5B545B#
#F10#
#F40#Diancie เรียกคริสตัลขนาดใหญ่เพื่อผนึกศัตรูเป้าหมายเดียว สร้างความเสียหาย #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# และใช้ [Diamond Seal] กับเป้าหมาย 1 รอบ (ผนึกเพชร: เอฟเฟกต์ควบคุม ไม่สามารถปัดเป่า ขยับไม่ได้) และสร้าง [Diamond Wall] ไว้ด้านหน้า พันธมิตรทั้งหมด
#F20#
#F40##L10#กำแพงเพชร:#L0#ป้องกันพันธมิตรทั้งหมดและดูดซับความเสียหายเท่ากับผลรวมของ P.&Sp.DEF ของ Diancie 200% สำหรับพันธมิตรประเภท Rock/Fairy แต่ละตัว เพิ่มโบนัส DEF นี้ 100% (ซ้อนทับได้สูงสุด 400%) เมื่อกำแพงเพชรพัง จะรักษาพันธมิตรทั้งหมดเท่ากับผลรวมของ P.&Sp.DEF ของ Diancie 250% (เปลี่ยนการรักษาส่วนเกินให้เป็นโล่) และลด P.&Sp.ATK ของศัตรูทั้งหมด 20% เป็นเวลา 1 รอบ]],
		zawakeEffectDesc_vn = [[
#C0xC0C0C0#Tenho certeza que -- eu poderia fazer um diamante de verdade!#C0x5B545B#
#F10#
#F40#Diancie invoca um enorme cristal, cercando um único alvo inimigo, distribuindo #C0x3D8A99#500% SP. ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#, atacando o alvo [Diamond Seal] por 1 rodada (Selo de Diamante: efeito de controle, incapaz de dissipar, incapaz de se mover), e construa um [Diamond Wall] na frente de todos os aliados
#F20#
#F40##L10#Diamond Wall: #L0#Escudo de todas as unidades, com o HP igual ao total de 200% P.&SP.DEF de Diancie. Para cada aliado do tipo Rock/Fairy, aumente 100% do bônus P.&SP.DEF (máximo até 400%). Quando Diamond Wall é quebrada, todos os aliados recuperam HP igual ao total de 250% do P.&SP.DEF de Diancie (a cura excessiva se transformará em escudo) e reduz 30% de P.&SP.ATK para todos os inimigos por 1 rodada, e causa 1 alvo inimigo aleatório para ficar preso em [Diamond Seal] por 1 rodada]],
		simDesc_es = "Diancie invoca un cristal enorme que rodea a un único objetivo enemigo y lo bloquea dentro. Crea un muro de cristal frente a todos sus aliados que recupera parte del HP de los aliados cuando el muro se rompe y reduce el SP.ATK y P.ATK de todos los enemigos.",
		describe_es = [[
#C0xC0C0C0#¡Estoy seguro de que puedo crear diamantes reales!#C0x5B545B#
#F10#
#F40#Diancie invoca un cristal enorme para sellar un solo objetivo enemigo, causando #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# y aplica [Diamond Seal] al objetivo durante 1 ronda (Sello de Diamante: efecto de control, no se puede disipar, no se puede mover), y construye un [Diamond Wall] delante de todos los aliados
#F20#
#F40##L10#Muro de Diamante:#L0#Protege a todos los aliados y absorbe daño igual a la suma del 200% P.&Sp.DEF de Diancie. Por cada aliado de tipo Roca/Hada aumenta esta bonificación de DEF en un 100% (se acumula hasta un 400%). Cuando Diamond Wall se rompe, cura a todos los aliados igual a la suma del 250 % del P.&Sp.DEF de Diancie (convierte el exceso de curación en un escudo) y reduce el P.&Sp.ATK de todos los enemigos en un 20 % durante 1 ronda.]],
		zawakeEffectDesc_th = [[
#C0xC0C0C0#ฉันแน่ใจว่า -- ฉันสามารถสร้างเพชรได้จริงๆ!#C0x5B545B#
#F10#
#F40#Diancie เรียกคริสตัลขนาดใหญ่มาล้อมรอบเป้าหมายศัตรูเพียงตัวเดียว สร้างความเสียหาย #C0x3D8A99#500% SP ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B# สร้างเป้าหมาย [Diamond Seal] สำหรับ 1 รอบ(ตราเพชร: เอฟเฟกต์ควบคุม ไม่สามารถปัดเป่า ไม่สามารถเคลื่อนที่ได้) และสร้าง [Diamond Wall] ไว้ด้านหน้า ของพันธมิตรทั้งหมด
#F20#
#F40##L10#กำแพงเพชร: #L0#โล่ยูนิตทั้งหมด โดยมี HP เท่ากับผลรวมของ P.&SP.DEF ของ Diancie 200% สำหรับพันธมิตรประเภทร็อค/แฟรี่แต่ละตัว โบนัส P.&SP.DEF เพิ่มขึ้น 100% (สูงสุดถึง 400%) เมื่อกำแพงเพชรพัง พันธมิตรทั้งหมดจะฟื้นฟู HP เท่ากับค่า P.&SP.DEF ของ Diancie รวม 250% (การรักษามากเกินไปจะกลายเป็นโล่) และลด P.&SP.ATK 30% ให้กับศัตรูทั้งหมดเป็นเวลา 1 รอบ และทำให้ 1 สุ่มศัตรูเป้าหมายให้ติดอยู่ใน [Diamond Seal] เป็นเวลา 1 รอบ]],
		starEffectDesc_id = "Efek tambahan: Ketika Diamond Wall ada, itu mencerminkan efek negatif. Ketika Diamond Wall ditembus, durasi pengurangan P.ATK&SP.ATK diperpanjang menjadi 2 ronde.",
		starEffectDesc_es = "Efecto adicional: cuando existe Diamond Wall, refleja efectos negativos. Cuando se rompe Diamond Wall, la duración de la reducción de P.ATK y SP.ATK se extiende a 2 rondas.",
		zawakeSimpleDesc_en = "#C0x5c9970#[Diamond Wall] When Diamond Wall broken, causes 1 random enemy target to be trapped in [Diamond Seal] for 1 round, and reduce 30% P.&Sp.ATK to all enemies",
		describe_vn = [[
#C0xC0C0C0#Tenho certeza que posso criar diamantes de verdade!#C0x5B545B#
#F10#
#F40#Diancie invoca um enorme cristal para selar um único alvo inimigo, distribuindo #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# e aplicando [Diamond Seal] ao alvo por 1 rodada (Selo de Diamante: efeito de controle, incapaz de dissipar, incapaz de se mover), e construir um [Diamond Wall] na frente de todos os aliados
#F20#
#F40##L10#Muralha de Diamante:#L0#Protege todos os aliados e absorve dano igual à soma de 200% P.&Sp.DEF de Diancie. Para cada aliado do tipo Pedra/Fada, aumente esse bônus de DEF em 100% (acumulando até 400%). Quando Diamond Wall é quebrada, cura todos os aliados igual à soma de 250% do P.&Sp.DEF de Diancie (converte o excesso de cura em um escudo) e reduz o P.&Sp.ATK de todos os inimigos em 20% por 1 rodada.]],
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: เมื่อมีกำแพงเพชร มันจะสะท้อนผลกระทบด้านลบ เมื่อกำแพงเพชรพัง ระยะเวลาการลด P.ATK&SP.ATK จะเพิ่มขึ้นเป็น 2 รอบ",
		starEffectDesc_vn = "Efeito adicional: Quando existe Diamond Wall, ela reflete efeitos negativos. Quando a Diamond Wall é quebrada, a duração da redução de P.ATK e SP.ATK é estendida para 2 rodadas.",
		zawakeEffectDesc_kr = [[
#C0xC0C0C0#확신해요 -- 진짜 다이아몬드를 만들 수 있어요!#C0x5B545B#
#F10#
#F40#디안시는 거대한 수정을 소환해 적 대상 하나를 둘러싸고 #C0x3D8A99#500% SP를 줍니다. ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#, 1라운드 동안 딜링 대상 [Diamond Seal](다이아몬드 봉인: 제어 효과, 해제 불가, 이동 불가), 전방에 [Diamond Wall] 구축 of all allies
#F20#
#F40##L10#다이아몬드 벽: #L0#모든 유닛 쉴드, HP는 Diancie의 200% P.&SP.DEF의 합계와 같습니다. 바위/요정 유형 아군 하나당 P.&SP.DEF 보너스가 100% 증가합니다(최대 400%). 다이아몬드 월이 무너지면 모든 아군은 디안시의 P.&SP.DEF 합계 250%만큼 HP를 회복하고(오버힐은 실드로 전환), 1라운드 동안 적 전체의 P.&SP.ATK를 30% 감소시키고 1회 발동시킵니다. 무작위 적 대상이 [Diamond Seal]에 1라운드 동안 갇히게 됩니다.]],
		describe_en = [[
#C0xC0C0C0#I'm sure that I can create real diamonds!#C0x5B545B#
#F10#
#F40#Diancie summons a huge crystal to seal a single enemy target, dealing #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# and applying [Diamond Seal] to the target for 1 round (Diamond Seal: Control effect, unable to dispel, unable to move), and build a [Diamond Wall] in front of all allies
#F20#
#F40##L10#Diamond Wall:#L0#Shields all allies and absorbs damage equal to the sum of Diancie's 200% P.&Sp.DEF. For each Rock/Fairy-type ally increase this DEF bonus by 100% (stacking up to 400%). When Diamond Wall broken, heals all allies equal to the sum of 250% Diancie's P.&Sp.DEF (converts excess healing into a shield) and reduces P.&Sp.ATK of all enemies by 20% for 1 round.]],
		zawakeEffectDesc_id = [[
#C0xC0C0C0#Aku yakin -- Aku bisa membuat berlian sungguhan!#C0x5B545B#
#F10#
#F40#Diancie memanggil kristal besar, mengelilingi satu target musuh, menimbulkan #C0x3D8A99#500% SP. ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#, memberikan target [Diamond Seal] selama 1 putaran (Segel Berlian: efek kontrol, tidak dapat menghalau, tidak dapat bergerak), dan membangun [Diamond Wall] di depan dari semua sekutu
#F20#
#F40##L10#Diamond Wall: #L0#Semua perisai unit, dengan HP setara dengan total 200% P.&SP.DEF Diancie. Untuk setiap sekutu tipe Batu/Peri meningkatkan 100% bonus P.&SP.DEF (Tertinggi hingga 400%). Saat Diamond Wall rusak, semua sekutu memulihkan HP setara dengan total 250% P.&SP.DEF Diancie (Penyembuhan berlebih akan berubah menjadi perisai), dan mengurangi 30% P.&SP.ATK ke semua musuh selama 1 putaran, dan menyebabkan 1 target musuh acak yang akan terjebak di [Diamond Seal] selama 1 putaran]],
		describe_id = [[
#C0xC0C0C0#Aku yakin bisa membuat berlian sungguhan!#C0x5B545B#
#F10#
#F40#Diancie memanggil kristal besar untuk menyegel satu target musuh, menghasilkan #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# dan menerapkan [Diamond Seal] ke target selama 1 putaran (Segel Berlian: Efek kontrol, tidak dapat menghalau, tidak dapat bergerak), dan membangun [Diamond Wall] di depan semua sekutu
#F20#
#F40##L10#Diamond Wall:#L0#Melindungi semua sekutu dan menyerap kerusakan setara dengan jumlah 200% P.&Sp.DEF Diancie. Untuk setiap sekutu bertipe Rock/Fairy, tingkatkan bonus DEF ini sebesar 100% (ditumpuk hingga 400%). Saat Tembok Berlian rusak, menyembuhkan semua sekutu setara dengan jumlah 250% P.&Sp.DEF Diancie (mengubah kelebihan penyembuhan menjadi perisai) dan mengurangi P.&Sp.ATK semua musuh sebesar 20% selama 1 putaran.]],
		simDesc_en = "Diancie summons a huge crystal, surrounding a single enemy target, while locking it within. It creates one crystal wall in front of all its allies which recovers some of the allies' HP when the wall is broken, and reduces the SP.ATK and P.ATK of all enemies",
		simDesc_vn = "Diancie invoca um enorme cristal, cercando um único alvo inimigo, enquanto o prende dentro dele. Ele cria uma parede de cristal na frente de todos os seus aliados que recupera parte do HP dos aliados quando a parede é quebrada e reduz o SP.ATK e P.ATK de todos os inimigos",
		describe_kr = [[
#C0xC0C0C0#I'm sure that I can create real diamonds!#C0x5B545B#
#F10#
#F40#Diancie summons a huge crystal to seal a single enemy target, dealing #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# and applying [Diamond Seal] to the target for 1 round (Diamond Seal: Control effect, unable to dispel, unable to move), and build a [Diamond Wall] in front of all allies
#F20#
#F40##L10#Diamond Wall:#L0#Shields all allies and absorbs damage equal to the sum of Diancie's 200% P.&Sp.DEF. For each Rock/Fairy-type ally increase this DEF bonus by 100% (stacking up to 400%). When Diamond Wall broken, heals all allies equal to the sum of 250% Diancie's P.&Sp.DEF (converts excess healing into a shield) and reduces P.&Sp.ATK of all enemies by 20% for 1 round.]],
		simDesc_th = "Diancie เรียกคริสตัลขนาดใหญ่ออกมาล้อมรอบเป้าหมายศัตรูตัวเดียว พร้อมทั้งกักขังมันไว้ภายใน สร้างกำแพงคริสตัลขึ้นมาด้านหน้าพันธมิตรทั้งหมด ซึ่งจะฟื้นฟู HP ของพันธมิตรบางส่วนเมื่อกำแพงพัง และลด SP.ATK และ P.ATK ของศัตรูทั้งหมด",
		zawakeEffectDesc_es = [[
#C0xC0C0C0#Estoy seguro de que... ¡podría hacer un diamante real! #C0x5B545B#
#F10#
#F40#Diancie invoca un cristal enorme que rodea a un único objetivo enemigo y le inflige #C0x3D8A99#500% SP. ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#, ataca al objetivo [Diamond Seal] durante 1 ronda (Sello de diamante: efecto de control, no se puede disipar, no se puede mover) y construye un [Diamond Wall] al frente de todos los aliados
#F20#
#F40##L10#Muro de Diamante: #L0#Todo el escudo de la unidad, con el HP igual al total del 200% P.&SP.DEF de Diancie. Por cada aliado de tipo Roca/Hada aumenta el 100% de bonificación P.&SP.DEF (la más alta hasta 400%). Cuando Diamond Wall se rompe, todos los aliados recuperan HP equivalente al total del 250% del P.&SP.DEF de Diancie (la curación excesiva se convertirá en escudo) y reduce el 30% P.&SP.ATK a todos los enemigos durante 1 ronda, y causa 1 objetivo enemigo aleatorio en el que quedará atrapado [Diamond Seal] durante 1 ronda]],
		starEffectDesc_kr = "추가 효과 : 다이아몬드 월이 존재하면 부정적인 효과를 반영합니다. 다이아몬드 월이 파괴되면 P.ATK&SP.ATK 감소 지속시간이 2라운드로 연장됩니다.",
		zawakeEffectDesc_en = [[
#C0xC0C0C0#I'm sure that -- I could make a real diamond!#C0x5B545B#
#F10#
#F40#Diancie summons a huge crystal, surrounding a single enemy target, dealing #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#, dealing target [Diamond Seal] for 1 round(Diamond Seal: control effect, unable to dispel, unable to move), and build a [Diamond Wall] in front of all allies
#F20#
#F40##L10#Diamond Wall: #L0#All unit shield, with the HP equals to the total of Diancie's 200% P.&SP.DEF. For each Rock-/Fairy-type ally increase 100% P.&SP.DEF bonus(Highest up to 400%). When Diamond Wall broken, all allies recovers HP equals to the total of 250% Diancie's P.&SP.DEF(Over heal will turn into shield), and reduce 30% P.&SP.ATK to all enemies for 1 round, and causes 1 random enemy target to be trapped in [Diamond Seal] for 1 round]],
		simDesc_kr = "디안시가 거대한 수정을 소환하여 적 대상 하나를 둘러싸고 그 안에 가두어 놓습니다. 아군 전체 앞에 하나의 수정벽을 생성해 벽이 무너지면 아군의 HP를 일부 회복하고, 적 전체의 SP.ATK, P.ATK를 감소시킵니다.",
		zawakeSimpleDesc_th = "#C0x5c9970#[Diamond Wall] เมื่อกำแพงเพชรแตก สุ่มศัตรู 1 เป้าหมายติดอยู่ใน [Diamond Seal] เป็นเวลา 1 รอบ และลด P.&Sp.ATK 30% ให้กับศัตรูทั้งหมด",
		zawakeSimpleDesc_kr = "#C0x5c9970#[Diamond Wall] 다이아몬드 벽이 파괴되면 무작위 적 대상 1명이 [Diamond Seal]에 1라운드 동안 갇히게 되고 모든 적의 P.&Sp.ATK가 30% 감소합니다.",
		starEffectDesc_en = "Additional effect: When Diamond Wall exists, it reflects negative effects. When Diamond Wall is broken, the duration of P.ATK&SP.ATK reduction is extended to 2 rounds.",
		zawakeSimpleDesc_vn = "#C0x5c9970#[Diamond Wall] Quando Diamond Wall é quebrada, faz com que 1 alvo inimigo aleatório fique preso em [Diamond Seal] por 1 rodada e reduz 30% de P.&Sp.ATK para todos os inimigos",
		zawakeSimpleDesc_id = "#C0x5c9970#[Diamond Wall] Saat Diamond Wall pecah, menyebabkan 1 target musuh acak terjebak dalam [Diamond Seal] selama 1 putaran, dan mengurangi 30% P.&Sp.ATK ke semua musuh",
		id = 36313,
		zawakeSimpleDesc_es = "#C0x5c9970#[Diamond Wall] Cuando Diamond Wall se rompe, causa que 1 objetivo enemigo aleatorio quede atrapado en [Diamond Seal] durante 1 ronda y reduce el 30% P.&Sp.ATK a todos los enemigos.",
		simDesc_id = "Diancie memanggil kristal besar, mengelilingi satu target musuh, sambil menguncinya di dalam. Ini menciptakan satu dinding kristal di depan semua sekutunya yang memulihkan sebagian HP sekutu ketika tembok itu rusak, dan mengurangi SP.ATK dan P.ATK semua musuh"
	},
	[36314] = {
		id = 36314
	},
	[36315] = {
		id = 36315
	},
	[36316] = {
		describe_id = [[
#C0xC0C0C0#Aku mengizinkanmu, untuk menjadi sekeras, cemerlang, dan abadi seperti berlian!#C0x5B545B##F10#

#F40##L10#Princess Incoming:#L0# Diancie membangun [Diamond Wall] dengan perisai kekuatan yang setara dengan 500% P.&Sp.DEF miliknya di awal pertempuran.#F10#

#F40##L10#Pembiasan Berlian:#L0# Di akhir setiap putaran besar, salin tiga secara acak efek negatif dari sekutu dan menerapkannya pada musuh dengan ATK tertinggi. Untuk setiap salinan yang berhasil, sembuhkan sekutu Tipe Peri dan dirinya sendiri setara dengan #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# dari jumlah P.&Sp.DEF.]],
		zawakeEffectDesc_vn = [[
#C0xC0C0C0#Eu permito que você seja forte, brilhe e eterno como o diamante!#C0x5B545B##F10#

#F40##L10#Princesa Chegando: #L0#Diancie constrói um [Diamond Wall] no início da batalha #F10#

#F40##L10#Diamond Power: #L0#Para cada aliado, o HP da Diamond Wall invocado por Diancie aumenta em 15%; quando há um escudo de todas as unidades ou um escudo próprio no campo, aumenta a redução de DMG em 25%#F10#

#F40##L10#Fração de diamante: #L0#No final de cada grande rodada, copie 3 efeitos negativos aleatórios do aliado para o inimigo com maior ATK, para cada copiado, recupera HP igual a #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# do P.&Sp.DEF total dele mesmo e de um aliado do tipo Fairy.]],
		describe_vn = [[
#C0xC0C0C0#Eu permito que você seja tão duro, brilhante e eterno quanto um diamante!#C0x5B545B##F10#

#F40##L10#Princesa Chegando:#L0# Diancie constrói um [Diamond Wall] com o escudo força igual a 500% de seu próprio P.&Sp.DEF no início da batalha.#F10#

#F40##L10#Refração de diamante:#L0# No final de cada grande rodada, copie aleatoriamente três efeitos negativos dos aliados e aplique-os ao inimigo com o maior ATK. Para cada cópia bem-sucedida, cure um aliado do Tipo Fada e ele mesmo igual a #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# da soma de P.&Sp.DEF.]],
		starEffectDesc_id = "Efek tambahan:#L10#Mystery Guardian:#L0#Pertama kali HP Diancie lebih rendah dari 40%, memanggil [Diamond Wall]",
		zawakeEffectDesc_th = [[
#C0xC0C0C0#ฉันอนุญาตให้คุณแข็งแกร่ง เปล่งประกายและเป็นนิรันดร์เหมือนเพชร!#C0x5B545B##F10#

#F40##L10#เจ้าหญิงเข้ามา: #L0#Diancie สร้าง [Diamond Wall] เมื่อเริ่มการต่อสู้ #F10#

#F40##L10#พลังเพชร: #L0#สำหรับพันธมิตรแต่ละคน HP ของกำแพงเพชรที่เดียนซีเรียกมาเพิ่มขึ้น 15%; เมื่อมีโล่ยูนิตทั้งหมดหรือโล่ของตัวเองบนสนาม เพิ่มการลดความเสียหาย 25%#F10#

#F40##L10#เศษเพชร: #L0#เมื่อสิ้นสุดรอบใหญ่แต่ละรอบ ให้คัดลอก เอฟเฟกต์ด้านลบแบบสุ่มของพันธมิตร 3 แบบต่อศัตรูที่มี ATK สูงสุด สำหรับการคัดลอกแต่ละครั้ง จะฟื้นฟู HP เท่ากับ #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ของ P.&Sp.DEF ทั้งหมดของตัวเองและพันธมิตรประเภทนางฟ้า]],
		starEffectDesc_kr = "추가 효과:#L10#미스터리 가디언:#L0#처음 디안시의 HP가 40% 미만일 때, [Diamond Wall]를 소환합니다.",
		describe_es = [[
#C0xC0C0C0#¡Te permito ser tan duro, brillante y eterno como un diamante!#C0x5B545B##F10#

#F40##L10#Princesa entrante:#L0# Diancie construye un [Diamond Wall] con el escudo fuerza igual al 500% de su propio P.&Sp.DEF al comienzo de la batalla.#F10#

#F40##L10#Refracción del diamante:#L0# Al final de cada ronda grande, copia aleatoriamente tres efectos negativos de los aliados y aplicarlos al enemigo con el ATK más alto. Por cada copia exitosa, cura a un aliado tipo Hada y a sí mismo igual a #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# de la suma de P.&Sp.DEF.]],
		zawakeSimpleDesc_en = "#C0x5c9970#Additional effect:#L10#Diamond Power:#L0#: For each ally, the HP of the Diamond Wall summoned by Diancie increases by 15%; when there is an all unit shield or a shield of own on the field, increases  Damage Reduction by 25%",
		starEffectDesc_es = "Efecto adicional: #L10# Mystery Guardian: #L0# La primera vez que el HP de Diancie es inferior al 40%, invoca un [Diamond Wall]",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม:#L10#ผู้พิทักษ์ลึกลับ:#L0#ครั้งแรก HP ของ Diancie ต่ำกว่า 40% เรียก [Diamond Wall]",
		zawakeEffectDesc_id = [[
#C0xC0C0C0#Aku mengizinkanmu, untuk menjadi kuat, bersinar dan abadi seperti berlian!#C0x5B545B##F10#

#F40##L10#Putri Masuk: #L0#Diancie membangun [Diamond Wall] di awal pertempuran #F10#

#F40##L10#Kekuatan Berlian: #L0#Untuk setiap sekutu, HP Tembok Berlian yang dipanggil oleh Diancie meningkat sebesar 15%; ketika ada perisai semua unit atau perisai milik sendiri di lapangan, tingkatkan Pengurangan DMG sebesar 25%#F10#

#F40##L10#Pecahan Berlian: #L0#Di akhir setiap putaran besar, salin 3 sekutu memberikan efek negatif acak kepada musuh dengan ATK tertinggi, untuk setiap salinan, memulihkan HP setara dengan #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# dari total P.&Sp.DEF dirinya dan sekutu tipe Peri.]],
		zawakeEffectDesc_es = [[
#C0xC0C0C0#¡Te permito ser fuerte, brillar y eterno como el diamante! #C0x5B545B##F10#

#F40##L10#Princesa entrante: #L0#Diancie construye un [Diamond Wall] al comienzo de la batalla. #F10#

#F40##L10#Diamond Power: #L0#Para cada aliado, el HP del Diamond Wall convocado por Diancie aumenta en un 15%; cuando hay un escudo de todas las unidades o un escudo propio en el campo, aumenta la reducción de daño en un 25%#F10#

#F40##L10#Fracción de diamante: #L0#Al final de cada ronda grande, copia 3 efectos negativos aleatorios de aliados para el enemigo con mayor ATK, por cada copiado, recuperar HP equivale a #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# del P.&Sp.DEF total de sí mismo y de un aliado tipo Hada.]],
		describe_en = [[
#C0xC0C0C0#I allow you, to be as hard, brilliant and eternal like a diamond!#C0x5B545B##F10#

#F40##L10#Princess Incoming:#L0# Diancie builds a [Diamond Wall] with the shield strength equal to 500% of its own P.&Sp.DEF at the start of the battle.#F10#

#F40##L10#Diamond Refraction:#L0# At the end of each big round, randomly copy three negative effects from allies and apply them to the enemy with the highest ATK. For each successful copy, heal a Fairy-Type ally and itself equal to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# of the sum of P.&Sp.DEF.]],
		zawakeSimpleDesc_th = "#C0x5c9970#เอฟเฟกต์เพิ่มเติม:#L10#พลังเพชร:#L0#: สำหรับพันธมิตรแต่ละคน HP ของกำแพงเพชรที่เดียนซีเรียกมาจะเพิ่มขึ้น 15%; เมื่อมีโล่ยูนิตทั้งหมดหรือโล่ของตัวเองในสนาม เพิ่มการลดความเสียหาย 25%",
		zawakeEffectDesc_kr = [[
#C0xC0C0C0#나는 당신이 다이아몬드처럼 강하고 빛나고 영원할 수 있도록 허락합니다!#C0x5B545B##F10#

#F40##L10#공주 인커밍: #L0#디안시는 전투 시작 시 [Diamond Wall]를 만듭니다. #F10#

#F40##L10#다이아몬드 파워: #L0#아군 1명당 디안시가 소환한 다이아몬드 월의 HP가 15% 증가합니다. 필드에 전체 유닛 쉴드 또는 자신의 쉴드가 있을 때 DMG 감소가 25% 증가#F10#

#F40##L10#다이아몬드 비율: #L0#각 빅 라운드가 끝날 때 복사 공격력이 가장 높은 적에게 아군 무작위 부정적인 효과 3개를 복사할 때마다 자신과 요정형 아군 전체 P.&Sp.DEF의 #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#만큼 HP를 회복합니다.]],
		zawakeSimpleDesc_kr = "#C0x5c9970#추가 효과:#L10#다이아몬드 파워:#L0#: 아군 한 명당 디안시가 소환하는 다이아몬드 월의 HP가 15% 증가합니다. 필드에 전체 유닛 쉴드 또는 자신의 쉴드가 있을 때 데미지 감소 25% 증가",
		zawakeEffectDesc_en = [[
#C0xC0C0C0#I allow you, to be strong, shine and eternal like diamond!#C0x5B545B##F10#

#F40##L10#Princess Incoming: #L0#Diancie build a [Diamond Wall] at the start of battle#F10#

#F40##L10#Diamond Power: #L0#For each ally, the HP of the Diamond Wall summoned by Diancie increases by 15%; when there is an all unit shield or a shield of own on the field, increases DMG Reduction by 25%#F10#

#F40##L10#Diamond Fraction: #L0#At the end of each big round, copy 3 ally random negative effects to enemy with highest ATK, for each copied, recover HP equals to #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# of total P.&Sp.DEF of itself and a Fairy-type ally.]],
		describe_kr = [[
#C0xC0C0C0#당신을 다이아몬드처럼 단단하고 찬란하고 영원하게 허락합니다!#C0x5B545B##F10#

#F40##L10#공주 인커밍:#L0# 디안시는 방패로 [Diamond Wall]를 만듭니다. 전투 시작 시 자신의 P.&Sp.DEF의 500%와 동일한 강도#F10#

#F40##L10#다이아몬드 굴절:#L0# 각 큰 라운드가 끝나면 무작위로 3개를 복사합니다. 아군으로부터 부정적인 효과를 받아 공격력이 가장 높은 적에게 적용됩니다. 성공적인 복사마다 P.&Sp.DEF 합계의 #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#에 해당하는 요정 유형 아군과 자신을 치유합니다.]],
		zawakeSimpleDesc_vn = "#C0x5c9970#Efeito adicional:#L10#Poder Diamante:#L0#: Para cada aliado, o HP da Parede de Diamante invocado por Diancie aumenta em 15%; quando há um escudo de todas as unidades ou um escudo próprio no campo, aumenta a Redução de Dano em 25%",
		zawakeSimpleDesc_id = "#C0x5c9970#Efek tambahan:#L10#Kekuatan Berlian:#L0#: Untuk setiap sekutu, HP Tembok Berlian yang dipanggil oleh Diancie meningkat sebesar 15%; ketika ada perisai semua unit atau perisai milik sendiri di lapangan, meningkatkan Pengurangan Kerusakan sebesar 25%",
		starEffectDesc_vn = "Efeito adicional:#L10#Guardião Misterioso:#L0#HP da Diancie pela primeira vez abaixo de 40%, invoca um [Diamond Wall]",
		zawakeSimpleDesc_es = "#C0x5c9970#Efecto adicional:#L10#Diamond Power:#L0#: Para cada aliado, el HP del Diamond Wall convocado por Diancie aumenta en un 15%; cuando hay un escudo para toda la unidad o un escudo propio en el campo, aumenta la reducción de daño en un 25%",
		describe_th = [[
#C0xC0C0C0#ฉันอนุญาตให้คุณแข็งแกร่ง สุกใสและเป็นนิรันดร์เหมือนเพชร!#C0x5B545B##F10#

#F40##L10#เจ้าหญิงที่เข้ามา:#L0# Diancie สร้าง [Diamond Wall] พร้อมโล่ ความแข็งแกร่งเท่ากับ 500% ของ P.&Sp.DEF ของตัวเองเมื่อเริ่มการต่อสู้#F10#

#F40##L10#การหักเหของเพชร:#L0# เมื่อสิ้นสุดแต่ละรอบใหญ่ สุ่มคัดลอกสาม เอฟเฟกต์ด้านลบจากพันธมิตรและนำไปใช้กับศัตรูที่มีพลังโจมตีสูงสุด สำหรับแต่ละสำเนาที่ประสบความสำเร็จ ให้รักษาพันธมิตรประเภทนางฟ้าและตัวมันเองเท่ากับ #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ของผลรวมของ P.&Sp.DEF]],
		starEffectDesc_en = "Additional effect:#L10#Mystery Guardian:#L0#First time Diancie's HP lower than 40%, summons a [Diamond Wall]",
		id = 36316
	},
	[36321] = {
		zawakeEffectDesc_kr = "#C0xC0C0C0#얼음 결정이 반짝반짝~#C0x5B545B#\n#F10#\n#F40#디안시가 수정바위를 소환해 적 1명을 공격해 딜을 시킵니다 #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP .DMG#C0x5B545B#, 2라운드 동안 자신의 P.&SP.DEF가 80% 증가하고 DMG 감소가 20% 증가합니다.",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Cristal de Gelo Brilhante~#C0x5B545B#\n#F10#\n#F40#Diancie invoca pedras de cristal para atacar um único inimigo e lidar com #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP .DMG#C0x5B545B#, aumentando o próprio P.&SP.DEF em 80% e a redução de DMG em 20% por 2 rodadas",
		simDesc_es = "Diancie invoca rocas de cristal para atacar a un solo enemigo.",
		describe_en = "#C0xC0C0C0#Shining Ice Crystals~#C0x5B545B#\n#F10#\n#F40#Diancie summons ice crystals to attack a single enemy, dealing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B# and gaining bonus 80% P.DEF and SP.DEF for 2 rounds",
		zawakeEffectDesc_th = "#C0xC0C0C0#คริสตัลน้ำแข็งระยิบระยับ~#C0x5B545B#\n#F10#\n#F40#Diancie เรียกหินคริสตัลมาโจมตีศัตรูตัวเดียวเพื่อสร้างความเสียหาย #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP .DMG#C0x5B545B# เพิ่ม P.&SP.DEF ของตัวเอง 80% และลดความเสียหาย 20% เป็นเวลา 2 รอบ",
		describe_es = "#C0xC0C0C0#Shining Ice Crystals~#C0x5B545B#\n#F10#\n#F40#Diancie invoca cristales de hielo para atacar a un solo enemigo, causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP .DMG#C0x5B545B# y obteniendo una bonificación del 80% P.DEF y SP.DEF durante 2 rondas",
		simDesc_vn = "Diancie invoca pedras de cristal para atacar um único inimigo",
		zawakeSimpleDesc_en = "and increase own 80% P.DEF and SP.DEF\n#F20#\n#F40##C0x5c9970#→increases own P.DEF and SP.DEF by 80% and DMG reduction by 20%",
		describe_vn = "#C0xC0C0C0#Cristais de Gelo Brilhantes~#C0x5B545B#\n#F10#\n#F40#Diancie invoca cristais de gelo para atacar um único inimigo, distribuindo #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP .DMG#C0x5B545B# e ganhando bônus de 80% P.DEF e SP.DEF por 2 rodadas",
		zawakeEffectDesc_id = "#C0xC0C0C0#Ice Crystal Glittering~#C0x5B545B#\n#F10#\n#F40#Diancie memanggil batu kristal untuk menyerang satu musuh untuk menangani #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP .DMG#C0x5B545B#, meningkatkan P.&SP.DEF sendiri sebesar 80% dan pengurangan DMG sebesar 20% selama 2 putaran",
		zawakeEffectDesc_es = "#C0xC0C0C0#Brillo de cristal de hielo~#C0x5B545B#\n#F10#\n#F40#Diancie invoca rocas de cristal para atacar a un solo enemigo y enfrentar #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP .DMG#C0x5B545B#, aumentando el P.&SP.DEF propio en un 80% y la reducción de DAÑO en un 20% durante 2 rondas",
		describe_th = "#C0xC0C0C0#ผลึกน้ำแข็งส่องแสง~#C0x5B545B#\n#F10#\n#F40#Diancie เรียกผลึกน้ำแข็งมาโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP .DMG#C0x5B545B# และได้รับโบนัส P.DEF และ SP.DEF 80% เป็นเวลา 2 รอบ",
		zawakeSimpleDesc_th = "และเพิ่ม P.DEF และ SP.DEF ของตัวเอง 80% \n#F20#\n#F40##C0x5c9970# →เพิ่ม P.DEF และ SP.DEF ของตัวเอง 80% และลด DMG 20%",
		zawakeSimpleDesc_kr = "그리고 자신의 P.DEF, SP.DEF 80% 증가\n#F20#\n#F40##C0x5c9970#→자신의 P.DEF, SP.DEF 80% 증가 및 DMG 감소 20%",
		describe_id = "#C0xC0C0C0#Kristal Es Cemerlang~#C0x5B545B#\n#F10#\n#F40#Diancie memanggil kristal es untuk menyerang satu musuh, menghasilkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP .DMG#C0x5B545B# dan mendapatkan bonus 80% P.DEF dan SP.DEF selama 2 putaran",
		simDesc_en = "Diancie summons crystal rocks to attack a single enemy",
		zawakeEffectDesc_en = "#C0xC0C0C0#Ice Crystal Glittering~#C0x5B545B#\n#F10#\n#F40#Diancie summons crystal rocks to attack a single enemy to deal #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, increasing own P.&SP.DEF by 80% and DMG reduction by 20% for 2 rounds",
		describe_kr = "#C0xC0C0C0#빛나는 얼음 결정~#C0x5B545B#\n#F10#\n#F40#디안시가 얼음 결정을 소환하여 적 1명을 공격하며 #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP .DMG#C0x5B545B# 2라운드 동안 P.DEF 및 SP.DEF 80% 보너스를 얻습니다.",
		simDesc_th = "Diancie เรียกหินคริสตัลออกมาโจมตีศัตรูตัวเดียว",
		zawakeSimpleDesc_vn = "e aumentar 80% P.DEF e SP.DEF próprios\n#F20#\n#F40##C0x5c9970#→aumenta P.DEF e SP.DEF próprios em 80% e redução de DMG em 20%",
		zawakeSimpleDesc_id = "dan meningkatkan P.DEF dan SP.DEF miliknya sebesar 80%\n#F20#\n#F40##C0x5c9970#→meningkatkan P.DEF dan SP.DEF miliknya sebesar 80% dan pengurangan DMG sebesar 20%",
		zawakeSimpleDesc_es = "y aumenta el 80% P.DEF y SP.DEF propio\n#F20#\n#F40##C0x5c9970#→aumenta el P.DEF y SP.DEF propio en un 80% y la reducción de DAÑO en un 20%",
		simDesc_kr = "디안시는 수정바위를 소환하여 적 1명을 공격합니다.",
		id = 36321,
		simDesc_id = "Diancie memanggil batu kristal untuk menyerang satu musuh"
	},
	[36322] = {
		zawakeEffectDesc_kr = "#C0xC0C0C0#Such glow, is it snowing?#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on the head to attack single enemy, dealing #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicting a 2-round power gem shield that can absorb 400% of the sum of Diancie's P.&SP.DMG to self and an allied Pokémon with the highest ATK(takes max. P.&SP.ATK). At the same time, deals a 2-round power gem shield to another random Rock-/Fairy-type Pokémon. Temporary increase 20% of P.&Sp.ATK to ally with this shield before attacking(Power Gem can not be stack). When Fairy-type Pokémon is added, increases healing rate by 15%; when Rock-type Pokémon is added, increases DMG Reduction by 10%; when the power gem shield is broken, it also reduces the caster's P.&Sp.ATK by 15% for 2 rounds(can stack 2 times)",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Que brilho, está nevando?#C0x5B545B#\n#F10#\n#F40#Diancie libera uma luz forte da gema na cabeça para atacar um único inimigo, distribuindo #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e infligindo um escudo de gema de poder de 2 rodadas que pode absorver 400% da soma do P.&SP.DMG de Diancie para si mesmo e um Pokémon aliado com o ATK mais alto ( leva no máximo P.&SP.ATK). Ao mesmo tempo, concede um escudo de power gem de 2 rodadas a outro Pokémon aleatório do tipo Rock/Fairy. Aumento temporário de 20% de P.&Sp.ATK para se aliar a este escudo antes de atacar (Power Gem não pode ser empilhado). Quando Pokémon do tipo Fada são adicionados, aumenta a taxa de cura em 15%; quando Pokémon do tipo Rock é adicionado, aumenta a redução de DMG em 10%; quando o escudo da gema de poder é quebrado, ele também reduz o P.&Sp.ATK do lançador em 15% por 2 rodadas (pode acumular 2 vezes)",
		simDesc_es = "Diancie libera una luz deslumbrante de la gema en su cabeza para curar a todos los aliados.",
		describe_en = "#C0xC0C0C0#The light, is it snowing?#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on its head to attack a single enemy, dealing #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B#, grants itself and the ally with the highest ATK a power gem shield for 2 rounds, which can absorb damage equal to 300% of the sum of Diancie's SP.DEF and P.DEF, and grants another random Rock/Fairy-type ally a power gem shield for 2 rounds. The ally holds power gem shield temporarily increases 10% P.&Sp.ATK before attacking (Power Gems are not stackable). Fairy-Type ally with Power Gem increases 15% Healing Rate; Rock-Type ally with Power Gem increases 10% DMG Reduction.",
		zawakeEffectDesc_th = "#C0xC0C0C0#แสงเจิดจ้าขนาดนี้ หิมะตกหรือเปล่า?#C0x5B545B#\n#F10#\n#F40#Diancie ปล่อยแสงอันแรงกล้าจากอัญมณีบนหัวเพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และสร้างโล่อัญมณีพลัง 2 รอบที่สามารถดูดซับ 400% ของผลรวมของพลังโจมตีและ SP.DMG ของ Diancie ให้กับตนเองและโปเกมอนพันธมิตรที่มี ATK สูงสุด( รับพลังโจมตีและพลังโจมตีสูงสุด) ในเวลาเดียวกัน สร้างเกราะอัญมณีพลัง 2 รอบให้กับโปเกมอนประเภทร็อค/แฟรี่แบบสุ่มตัวอื่น เพิ่ม P.&Sp.ATK 20% ชั่วคราวให้กับพันธมิตรด้วยโล่นี้ก่อนโจมตี (Power Gem ไม่สามารถทับซ้อนกันได้) เมื่อเพิ่มโปเกมอนประเภทนางฟ้า เพิ่มอัตราการรักษา 15% เมื่อเพิ่มโปเกมอนประเภทร็อค เพิ่มการลดความเสียหาย 10% เมื่อโล่อัญมณีพลังถูกทำลาย จะลด P.&Sp.ATK ของผู้ร่ายลง 15% เป็นเวลา 2 รอบ (สามารถซ้อนทับได้ 2 ครั้ง)",
		describe_es = "#C0xC0C0C0#La luz, ¿está nevando?#C0x5B545B#\n#F10#\n#F40#Diancie libera una luz fuerte de la gema en su cabeza para atacar a un solo enemigo, causando #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B#, se otorga a sí mismo y al aliado con mayor ATK un escudo de gemas de poder durante 2 rondas, que puede absorber daño equivalente al 300% de la suma de SP.DEF y de Diancie. P.DEF, y otorga a otro aliado aleatorio de tipo Roca/Hada un escudo de gemas de poder durante 2 rondas. El aliado que tiene un escudo de gemas de poder aumenta temporalmente un 10% P.&Sp.ATK antes de atacar (las gemas de poder no son acumulables). El aliado tipo Hada con Power Gem aumenta un 15% la tasa de curación; El aliado tipo roca con Power Gem aumenta un 10% la reducción de daño.",
		simDesc_vn = "Diancie libera uma luz ofuscante da gema em sua cabeça para curar todos os aliados",
		zawakeSimpleDesc_en = "#C0x5c9970#The shield value of the power gem shield is increased to 400%, and the temporarily increased P. & Sp. ATK before the shield attacks is increased to 20%; when the power gem shield is broken, it also reduces the caster's P. & Sp. ATK by 15% for 2 rounds (can stack 2 times)",
		describe_vn = "#C0xC0C0C0#A luz, está nevando?#C0x5B545B#\n#F10#\n#F40#Diancie libera uma luz forte da gema em sua cabeça para atacar um único inimigo, distribuindo #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B#, concede a si mesmo e ao aliado com o maior ATK um escudo de gema de poder por 2 rodadas, que pode absorver dano igual a 300% da soma do SP.DEF de Diancie e P.DEF, e concede a outro aliado aleatório do tipo Pedra/Fada um escudo de gema de poder por 2 rodadas. O aliado detém o escudo da gema de poder e aumenta temporariamente 10% de P.&Sp.ATK antes de atacar (as gemas de poder não são acumuláveis). Aliado Fairy-Type com Power Gem aumenta 15% da Taxa de Cura; Aliado Rock-Type com Power Gem aumenta 10% de redução de DMG.",
		zawakeEffectDesc_id = "#C0xC0C0C0#Cahaya seperti itu, apakah sedang turun salju?#C0x5B545B#\n#F10#\n#F40#Diancie melepaskan cahaya kuat dari permata di kepala untuk menyerang satu musuh, menghasilkan #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan memberikan perisai permata kekuatan 2 putaran yang dapat menyerap 400% jumlah P.&SP.DMG Diancie kepada diri sendiri dan Pokémon sekutu dengan ATK tertinggi( membutuhkan maks.P.&SP.ATK). Pada saat yang sama, memberikan perisai permata kekuatan 2 putaran ke Pokémon tipe Batu/Peri acak lainnya. Peningkatan sementara 20% P.&Sp.ATK ke sekutu dengan perisai ini sebelum menyerang (Permata Kekuatan tidak dapat ditumpuk). Saat Pokémon tipe Peri ditambahkan, meningkatkan tingkat penyembuhan sebesar 15%; ketika Pokémon tipe Rock ditambahkan, meningkatkan Pengurangan DMG sebesar 10%; ketika perisai permata kekuatan rusak, itu juga mengurangi P.&Sp.ATK kastor sebesar 15% selama 2 putaran (dapat ditumpuk 2 kali)",
		zawakeEffectDesc_es = "#C0xC0C0C0#Qué brillo, ¿está nevando? #C0x5B545B#\n#F10#\n#F40#Diancie libera una luz fuerte de la gema en la cabeza para atacar a un solo enemigo, causando #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige un escudo de gemas de poder de 2 rondas que puede absorber el 400% de la suma del P.&SP.DMG de Diancie a sí mismo y a un Pokémon aliado con el ATK más alto ( toma P.&SP.ATK máx.). Al mismo tiempo, otorga un escudo de gemas de poder de 2 rondas a otro Pokémon aleatorio de tipo Roca/Hada. Aumento temporal del 20% de P.&Sp.ATK para aliarse con este escudo antes de atacar (Power Gem no se puede acumular). Cuando se agrega Pokémon de tipo Hada, aumenta la tasa de curación en un 15%; cuando se agrega Pokémon de tipo Roca, aumenta la reducción de daño en un 10%; Cuando el escudo de la gema de poder se rompe, también reduce el P.&Sp.ATK del lanzador en un 15% durante 2 rondas (se puede acumular 2 veces).",
		describe_th = "#C0xC0C0C0#แสง หิมะตกหรือเปล่า?#C0x5B545B#\n#F10#\n#F40#Diancie ปล่อยแสงอันแรงกล้าจากอัญมณีบนหัวเพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B# มอบโล่อัญมณีพลังให้ตัวเองและพันธมิตรที่มี ATK สูงสุดเป็นเวลา 2 รอบ ซึ่งสามารถดูดซับความเสียหายได้เท่ากับ 300% ของผลรวม SP.DEF ของ Diancie และ ป้องกันการโจมตี และมอบโล่อัญมณีพลังให้พันธมิตรประเภทร็อค/แฟรี่แบบสุ่มอีกตัวเป็นเวลา 2 รอบ พันธมิตรที่ถือโล่อัญมณีพลังจะเพิ่ม P.&Sp.ATK 10% ชั่วคราวก่อนโจมตี (อัญมณีพลังไม่สามารถซ้อนกันได้) พันธมิตรประเภทนางฟ้าที่มี Power Gem จะเพิ่มอัตราการรักษา 15%; พันธมิตรประเภทร็อคที่มี Power Gem จะเพิ่มการลด DMG 10%",
		zawakeSimpleDesc_th = "#C0x5c9970#ค่าโล่ของโล่อัญมณีพลังเพิ่มขึ้นเป็น 400% และค่า P. & Sp. เพิ่มขึ้นชั่วคราว ATK ก่อนการโจมตีด้วยโล่เพิ่มขึ้นเป็น 20%; เมื่อโล่อัญมณีพลังถูกทำลาย มันจะลด P. & Sp ของผู้ร่ายด้วย ATK 15% เป็นเวลา 2 รอบ (สามารถซ้อนได้ 2 ครั้ง)",
		zawakeSimpleDesc_kr = "#C0x5c9970#파워젬 실드의 실드값이 400%로 증가되며, 일시적으로 P.&Sp가 증가합니다. 방패 공격 전 공격력이 20%로 증가됩니다. 파워 젬 쉴드가 깨지면 시전자의 P. & Sp도 감소합니다. 2라운드 동안 공격력 15% 증가(2회 중첩 가능)",
		describe_id = "#C0xC0C0C0#Cahaya, apakah turun salju?#C0x5B545B#\n#F10#\n#F40#Diancie melepaskan cahaya kuat dari permata di kepalanya untuk menyerang satu musuh, menimbulkan #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B#, memberikan dirinya sendiri dan sekutu dengan ATK tertinggi sebuah perisai permata kekuatan selama 2 putaran, yang dapat menyerap kerusakan sebesar 300% dari jumlah SP.DEF Diancie dan P.DEF, dan memberi sekutu acak tipe Batu/Peri lainnya sebuah perisai permata kekuatan selama 2 putaran. Sekutu yang memegang perisai permata kekuatan untuk sementara meningkatkan 10% P.&Sp.ATK sebelum menyerang (Permata Kekuatan tidak dapat ditumpuk). Sekutu Tipe Peri dengan Permata Kekuatan meningkatkan 15% Tingkat Penyembuhan; Sekutu Tipe Batu dengan Permata Kekuatan meningkatkan 10% Pengurangan DMG.",
		simDesc_en = "Diancie releases a dazzling light from the gem on its head to heal all allies",
		zawakeEffectDesc_en = "#C0xC0C0C0#Such glow, is it snowing?#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on the head to attack single enemy, dealing #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicting a 2-round power gem shield that can absorb 400% of the sum of Diancie's P.&SP.DMG to self and an allied Pokémon with the highest ATK(takes max. P.&SP.ATK). At the same time, deals a 2-round power gem shield to another random Rock-/Fairy-type Pokémon. Temporary increase 20% of P.&Sp.ATK to ally with this shield before attacking(Power Gem can not be stack). When Fairy-type Pokémon is added, increases healing rate by 15%; when Rock-type Pokémon is added, increases DMG Reduction by 10%; when the power gem shield is broken, it also reduces the caster's P.&Sp.ATK by 15% for 2 rounds(can stack 2 times)",
		describe_kr = "#C0xC0C0C0#The light, is it snowing?#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on its head to attack a single enemy, dealing #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#SP.DMG#C0x5B545B#, grants itself and the ally with the highest ATK a power gem shield for 2 rounds, which can absorb damage equal to 300% of the sum of Diancie's SP.DEF and P.DEF, and grants another random Rock/Fairy-type ally a power gem shield for 2 rounds. The ally holds power gem shield temporarily increases 10% P.&Sp.ATK before attacking (Power Gems are not stackable). Fairy-Type ally with Power Gem increases 15% Healing Rate; Rock-Type ally with Power Gem increases 10% DMG Reduction.",
		simDesc_th = "Diancie ปล่อยแสงเจิดจ้าจากอัญมณีบนหัวเพื่อรักษาเพื่อนร่วมทีมทั้งหมด",
		zawakeSimpleDesc_vn = "#C0x5c9970#O valor do escudo da gema de poder foi aumentado para 400%, e o P. & Sp. O ATK antes dos ataques do escudo é aumentado para 20%; quando o escudo da gema de poder é quebrado, ele também reduz o P. e Sp do lançador. ATK em 15% por 2 rodadas (pode acumular 2 vezes)",
		zawakeSimpleDesc_id = "#C0x5c9970#Nilai perisai dari perisai permata kekuatan ditingkatkan menjadi 400%, dan P. & Sp meningkat sementara. ATK sebelum serangan perisai ditingkatkan menjadi 20%; ketika perisai permata kekuatan rusak, itu juga mengurangi P. & Sp kastor. ATK sebesar 15% selama 2 ronde (bisa di stack 2 kali)",
		zawakeSimpleDesc_es = "#C0x5c9970#El valor del escudo de la gema de poder aumenta al 400%, y el P. & Sp. aumentado temporalmente. El ATK antes de los ataques del escudo aumenta al 20%; Cuando el escudo de la gema de poder se rompe, también reduce la P. y Sp del lanzador. ATK en un 15 % durante 2 rondas (se puede acumular 2 veces)",
		simDesc_kr = "디안시가 머리에 있는 보석에서 눈부신 빛을 발산하여 아군 전체를 치유합니다.",
		id = 36322,
		simDesc_id = "Diancie melepaskan cahaya menyilaukan dari permata di kepalanya untuk menyembuhkan semua sekutu"
	},
	[36323] = {
		describe_th = [[
#C0xC0C0C0#ลานตาน้ำแข็ง!#C0x5B545B#
#F10#
#F40#Diancie เรียกคริสตัลขนาดใหญ่เพื่อผนึกศัตรูเป้าหมายเดียว สร้างความเสียหาย #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# SP.DMG#C0x5B545B# และใช้ [Diamond Seal] กับเป้าหมาย 1 รอบ (ผนึกเพชร: เอฟเฟกต์ควบคุม ไม่สามารถลบล้างได้ ไม่สามารถเคลื่อนที่ได้) และสร้าง [Diamond Wall] ต่อหน้าพันธมิตรทั้งหมด
#F20#
#F40##L10#กำแพงเพชร:#L0#ป้องกันพันธมิตรทั้งหมดและดูดซับความเสียหายเท่ากับผลรวมของ P.&Sp.DEF ของ Diancie 200% สำหรับพันธมิตรประเภท Rock/Fairy แต่ละตัว เพิ่มโบนัส DEF นี้ 100% (ซ้อนทับได้สูงสุด 400%) เมื่อกำแพงเพชรพัง จะรักษาพันธมิตรทั้งหมดเท่ากับผลรวมของ P.&Sp.DEF ของ Diancie 250% (เปลี่ยนการรักษาส่วนเกินให้เป็นโล่) และลด P.&Sp.ATK ของศัตรูทั้งหมด 20% เป็นเวลา 1 รอบ]],
		zawakeEffectDesc_vn = [[
#C0xC0C0C0#Caleidoscópio de gelo e neve!#C0x5B545B#
#F10#
#F40#Diancie invoca um enorme cristal, cercando um único alvo inimigo, distribuindo #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B#, atacando o alvo [Diamond Seal] por 1 rodada (Selo de Diamante: efeito de controle, incapaz de dissipar, incapaz de se mover) e construir um [Diamond Wall] na frente de todos os aliados
#F20# 
#F40##L10#Diamond Wall: #L0#Escudo de todas as unidades, com o HP igual ao total de 200% P.&SP.DEF de Diancie. Para cada aliado do tipo Rock/Fairy, aumente 100% do bônus P.&SP.DEF (máximo até 400%). Quando Diamond Wall é quebrada, todos os aliados recuperam HP igual ao total de 250% do P.&SP.DEF de Diancie (a cura excessiva se transformará em escudo) e reduz 30% de P.&SP.ATK para todos os inimigos por 1 rodada, e causa 1 alvo inimigo aleatório para ficar preso em [Diamond Seal] por 1 rodada]],
		simDesc_es = "Diancie invoca un cristal enorme que rodea a un único objetivo enemigo y lo bloquea dentro. Crea un muro de cristal frente a todos sus aliados que recupera parte del HP de los aliados cuando el muro se rompe y reduce el SP.ATK y P.ATK de todos los enemigos.",
		describe_es = [[
#C0xC0C0C0#¡Caleidoscopio de hielo!#C0x5B545B#
#F10#
#F40#Diancie invoca un cristal enorme para sellar un solo objetivo enemigo, causando #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# SP.DMG#C0x5B545B# y aplicando [Diamond Seal] al objetivo durante 1 ronda (Sello de Diamante: efecto de control, no se puede disipar, no se puede mover) y construye un [Diamond Wall] frente a todos los aliados
#F20#
#F40##L10#Muro de Diamante:#L0#Protege a todos los aliados y absorbe daño igual a la suma del 200% P.&Sp.DEF de Diancie. Por cada aliado de tipo Roca/Hada aumenta esta bonificación de DEF en un 100% (se acumula hasta un 400%). Cuando Diamond Wall se rompe, cura a todos los aliados igual a la suma del 250 % del P.&Sp.DEF de Diancie (convierte el exceso de curación en un escudo) y reduce el P.&Sp.ATK de todos los enemigos en un 20 % durante 1 ronda.]],
		zawakeEffectDesc_th = [[
#C0xC0C0C0#ภาพลานตาของน้ำแข็งและหิมะ!#C0x5B545B#
#F10#
#F40#Diancie เรียกคริสตัลขนาดใหญ่มาล้อมรอบเป้าหมายศัตรูเพียงตัวเดียว สร้างความเสียหาย #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# จัดการเป้าหมาย [Diamond Seal] เป็นเวลา 1 รอบ(ผนึกเพชร: เอฟเฟกต์ควบคุม ไม่สามารถลบล้างได้ ไม่สามารถเคลื่อนที่ได้) และสร้าง [Diamond Wall] ต่อหน้าพันธมิตรทั้งหมด
#F20# 
#F40##L10#กำแพงเพชร: #L0#โล่ยูนิตทั้งหมด โดยมี HP เท่ากับผลรวมของ P.&SP.DEF ของ Diancie 200% สำหรับพันธมิตรประเภทร็อค/แฟรี่แต่ละตัว โบนัส P.&SP.DEF เพิ่มขึ้น 100% (สูงสุดถึง 400%) เมื่อกำแพงเพชรพัง พันธมิตรทั้งหมดจะฟื้นฟู HP เท่ากับค่า P.&SP.DEF ของ Diancie รวม 250% (การรักษามากเกินไปจะกลายเป็นโล่) และลด P.&SP.ATK 30% ให้กับศัตรูทั้งหมดเป็นเวลา 1 รอบ และทำให้ 1 สุ่มศัตรูเป้าหมายให้ติดอยู่ใน [Diamond Seal] เป็นเวลา 1 รอบ]],
		starEffectDesc_id = "Efek tambahan: Ketika Diamond Wall ada, itu mencerminkan efek negatif. Ketika Diamond Wall ditembus, durasi pengurangan P.ATK&SP.ATK diperpanjang menjadi 2 ronde.",
		starEffectDesc_es = "Efecto adicional: cuando existe Diamond Wall, refleja efectos negativos. Cuando se rompe Diamond Wall, la duración de la reducción de P.ATK y SP.ATK se extiende a 2 rondas.",
		zawakeSimpleDesc_en = "#C0x5c9970#[Diamond Wall] When Diamond Wall broken, causes 1 random enemy target to be trapped in [Diamond Seal] for 1 round, and reduce 30% P.&Sp.ATK to all enemies",
		describe_vn = [[
#C0xC0C0C0#Caleidoscópio de Gelo!#C0x5B545B#
#F10#
#F40#Diancie invoca um enorme cristal para selar um único alvo inimigo, distribuindo #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# SP.DMG#C0x5B545B# e aplicando [Diamond Seal] ao alvo por 1 rodada (Selo de Diamante: efeito de controle, incapaz de dissipar, incapaz de se mover), e construir um [Diamond Wall] na frente de todos os aliados
#F20#
#F40##L10#Muralha de Diamante:#L0#Protege todos os aliados e absorve dano igual à soma dos 200% P.&Sp.DEF de Diancie. Para cada aliado do tipo Pedra/Fada, aumente esse bônus de DEF em 100% (acumulando até 400%). Quando Diamond Wall é quebrada, cura todos os aliados igual à soma de 250% do P.&Sp.DEF de Diancie (converte o excesso de cura em um escudo) e reduz o P.&Sp.ATK de todos os inimigos em 20% por 1 rodada.]],
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: เมื่อมีกำแพงเพชร มันจะสะท้อนผลกระทบด้านลบ เมื่อกำแพงเพชรพัง ระยะเวลาการลด P.ATK&SP.ATK จะเพิ่มขึ้นเป็น 2 รอบ",
		starEffectDesc_vn = "Efeito adicional: Quando existe Diamond Wall, ela reflete efeitos negativos. Quando a Diamond Wall é quebrada, a duração da redução de P.ATK e SP.ATK é estendida para 2 rodadas.",
		zawakeEffectDesc_kr = [[
#C0xC0C0C0#얼음과 눈의 만화경!#C0x5B545B#
#F10#
#F40#디안시가 거대한 수정을 소환해 단일 적 대상을 둘러싸고 #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B#, 1라운드 동안 대상 [Diamond Seal](다이아몬드 봉인: 제어 효과, 해제 불가, 이동 불가)을 처리하고 모든 아군 앞에 [Diamond Wall]을 구축합니다
#F20# 
#F40##L10#다이아몬드 벽: #L0#모든 유닛의 방어막, HP는 Diancie의 200% P.&SP.DEF의 합계와 같습니다. 바위/요정 유형 아군 하나당 P.&SP.DEF 보너스가 100% 증가합니다(최대 400%). 다이아몬드 월이 무너지면 모든 아군은 디안시의 P.&SP.DEF 합계 250%만큼 HP를 회복하고(오버힐은 실드로 전환), 1라운드 동안 적 전체의 P.&SP.ATK를 30% 감소시키고 1회 발동시킵니다. 무작위 적 대상이 [Diamond Seal]에 1라운드 동안 갇히게 됩니다.]],
		describe_en = [[
#C0xC0C0C0#Ice Kaleidoscope!#C0x5B545B#
#F10#
#F40#Diancie summons a huge crystal to seal a single enemy target, dealing #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B# and applying [Diamond Seal] to the target for 1 round (Diamond Seal: Control effect, unable to dispel, unable to move), and build a [Diamond Wall] in front of all allies
#F20#
#F40##L10#Diamond Wall:#L0#Shields all allies and absorbs damage equal to the sum of Diancie's 200% P.&Sp.DEF. For each Rock/Fairy-type ally increase this DEF bonus by 100% (stacking up to 400%). When Diamond Wall broken, heals all allies equal to the sum of 250% Diancie's P.&Sp.DEF (converts excess healing into a shield) and reduces P.&Sp.ATK of all enemies by 20% for 1 round.]],
		zawakeEffectDesc_id = [[
#C0xC0C0C0#Kaleidoskop es dan salju!#C0x5B545B#
#F10#
#F40#Diancie memanggil kristal besar, mengelilingi satu target musuh, menghasilkan #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B#, menangani target [Diamond Seal] selama 1 putaran (Segel Berlian: efek kontrol, tidak dapat menghilangkan, tidak dapat bergerak), dan membangun [Diamond Wall] di depan semua sekutu
#F20# 
#F40##L10#Diamond Wall: #L0#Semua perisai unit, dengan HP setara dengan total 200% P.&SP.DEF Diancie. Untuk setiap sekutu tipe Batu/Peri meningkatkan 100% bonus P.&SP.DEF (Tertinggi hingga 400%). Saat Diamond Wall rusak, semua sekutu memulihkan HP setara dengan total 250% P.&SP.DEF Diancie (Penyembuhan berlebih akan berubah menjadi perisai), dan mengurangi 30% P.&SP.ATK ke semua musuh selama 1 putaran, dan menyebabkan 1 target musuh acak yang akan terjebak di [Diamond Seal] selama 1 putaran]],
		describe_id = [[
#C0xC0C0C0#Kaleidoskop Es!#C0x5B545B#
#F10#
#F40#Diancie memanggil kristal besar untuk menyegel satu target musuh, menghasilkan #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# SP.DMG#C0x5B545B# dan menerapkan [Diamond Seal] pada target selama 1 putaran (Segel Berlian: Efek kontrol, tidak dapat menghilangkan, tidak dapat bergerak), dan membangun [Diamond Wall] di depan semua sekutu
#F20#
#F40##L10#Tembok Berlian:#L0#Melindungi semua sekutu dan menyerap kerusakan setara dengan jumlah 200% P.&Sp.DEF Diancie. Untuk setiap sekutu bertipe Rock/Fairy, tingkatkan bonus DEF ini sebesar 100% (ditumpuk hingga 400%). Saat Tembok Berlian rusak, menyembuhkan semua sekutu setara dengan jumlah 250% P.&Sp.DEF Diancie (mengubah kelebihan penyembuhan menjadi perisai) dan mengurangi P.&Sp.ATK semua musuh sebesar 20% selama 1 putaran.]],
		simDesc_en = "Diancie summons a huge crystal, surrounding a single enemy target, while locking it within. It creates one crystal wall in front of all its allies which recovers some of the allies' HP when the wall is broken, and reduces the SP.ATK and P.ATK of all enemies",
		simDesc_vn = "Diancie invoca um enorme cristal, cercando um único alvo inimigo, enquanto o prende dentro dele. Ele cria uma parede de cristal na frente de todos os seus aliados que recupera parte do HP dos aliados quando a parede é quebrada e reduz o SP.ATK e P.ATK de todos os inimigos",
		describe_kr = [[
#C0xC0C0C0#얼음 만화경!#C0x5B545B#
#F10#
#F40#디안시가 거대한 수정을 소환하여 단일 적 대상을 봉인하고 #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54# SP.DMG#C0x5B545B# 그리고 1라운드 동안 대상에 [Diamond Seal]를 적용하고(다이아몬드 봉인: 제어 효과, 해제 불가, 이동 불가) 모든 아군 앞에 [Diamond Wall]을 생성합니다
#F20#
#F40##L10#다이아몬드 벽:#L0#모든 아군을 보호하고 디안시의 200% P.&Sp.DEF 합만큼 피해를 흡수합니다. 바위/요정 유형 아군 하나당 DEF 보너스가 100% 증가합니다(최대 400%까지 누적). 다이아몬드 월이 파괴되면 디안시의 P.&Sp.DEF의 250% 합만큼 모든 아군을 치유하고(초과 치유량을 방패로 전환) 1라운드 동안 모든 적의 P.&Sp.ATK를 20% 감소시킵니다.]],
		simDesc_th = "Diancie เรียกคริสตัลขนาดใหญ่ออกมาล้อมรอบเป้าหมายศัตรูตัวเดียว พร้อมทั้งกักขังมันไว้ภายใน สร้างกำแพงคริสตัลขึ้นมาด้านหน้าพันธมิตรทั้งหมด ซึ่งจะฟื้นฟู HP ของพันธมิตรบางส่วนเมื่อกำแพงพัง และลด SP.ATK และ P.ATK ของศัตรูทั้งหมด",
		zawakeEffectDesc_es = [[
#C0xC0C0C0#¡Caleidoscopio de hielo y nieve!#C0x5B545B#
#F10#
#F40#Diancie invoca un cristal enorme que rodea a un solo objetivo enemigo y le inflige #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$ #C0xF13B54#SP.DMG#C0x5B545B#, ataca al objetivo [Diamond Seal] durante 1 ronda (Sello de diamante: efecto de control, no se puede disipar, no se puede mover) y construye un [Diamond Wall] frente a todos los aliados
#F20# 
#F40##L10#Muro de Diamante: #L0#Todo el escudo de la unidad, con el HP igual al total del 200% P.&SP.DEF de Diancie. Por cada aliado de tipo Roca/Hada aumenta el 100% de bonificación P.&SP.DEF (la más alta hasta 400%). Cuando Diamond Wall se rompe, todos los aliados recuperan HP equivalente al total del 250% del P.&SP.DEF de Diancie (la curación excesiva se convertirá en escudo) y reduce el 30% P.&SP.ATK a todos los enemigos durante 1 ronda, y causa 1 objetivo enemigo aleatorio en el que quedará atrapado [Diamond Seal] durante 1 ronda]],
		starEffectDesc_kr = "추가 효과 : 다이아몬드 월이 존재하면 부정적인 효과를 반영합니다. 다이아몬드 월이 파괴되면 P.ATK&SP.ATK 감소 지속시간이 2라운드로 연장됩니다.",
		zawakeEffectDesc_en = [[
#C0xC0C0C0#Kaleidoscope of ice and snow!#C0x5B545B#
#F10#
#F40#Diancie summons a huge crystal, surrounding a single enemy target, dealing #C0x3D8A99#500% SP.ATK#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54#SP.DMG#C0x5B545B#, dealing target [Diamond Seal] for 1 round(Diamond Seal: control effect, unable to dispel, unable to move), and build a [Diamond Wall] in front of all allies
#F20#
