	},
	[36636] = {
		describe_id = "Dapat menyerang musuh di garis belakang secara langsung;\nMenghancurkan musuh akan memberikan $(400+skillLevel*3-3)$ Kemarahan",
		zawakeEffectDesc_vn = "Pode atacar diretamente um inimigo da linha de retaguarda;\nNocautear o inimigo concede $(400+skillLevel*3-3)$ Fúria. Se não matar o alvo, aumente o próprio DMG letal em 10% por 2 rodadas (não pode ser acumulado)",
		describe_vn = "Pode atacar um inimigo da linha de retaguarda diretamente;\nNocautear o inimigo concede $(400+skillLevel*3-3)$ Raiva",
		starEffectDesc_id = "Efek tambahan: secara otomatis masuk ke status [Stealth] setelah Kemarahan penuh, dan meningkatkan tingkat Kekebalan Kontrol sebesar 20% selama sembunyi-sembunyi",
		zawakeEffectDesc_th = "สามารถโจมตีศัตรูแนวหลังได้โดยตรง \n การน็อคศัตรูจะได้รับ $(400+skillLevel*3-3)$ ความเดือดดาล หากไม่สังหารเป้าหมาย เพิ่ม Lethal DMG ของตนเองขึ้น 10% เป็นเวลา 2 รอบ (ไม่สามารถซ้อนทับได้)",
		starEffectDesc_kr = "추가 효과 : 분노가 가득 차면 자동으로 [Stealth] 상태가 되며, 은신 중 제어 면역률이 20% 증가합니다.",
		describe_es = "Puede atacar a un enemigo de retaguardia directamente;\nNoquear al enemigo otorga $(400+skillLevel*3-3)$ Rabia",
		zawakeSimpleDesc_en = "#C0x5c9970#If not killing the target, increase own Lethal DMG by 10% for 2 rounds(cannot be stacked)",
		starEffectDesc_es = "Efecto adicional: ingresa automáticamente al estado [Stealth] después de que la ira esté llena y aumenta la tasa de control inmunológico en un 20% durante el sigilo.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เข้าสู่สถานะ [Stealth] โดยอัตโนมัติหลังจากความโกรธเต็ม และเพิ่มอัตราภูมิคุ้มกันควบคุม 20% ระหว่างการซ่อนตัว",
		zawakeEffectDesc_id = "Dapat menyerang musuh di garis belakang secara langsung;\nMenghancurkan musuh akan memberikan $(400+skillLevel*3-3)$ Kemarahan. Jika tidak membunuh target, meningkatkan Lethal DMG miliknya sebesar 10% selama 2 ronde (tidak dapat ditumpuk)",
		zawakeEffectDesc_es = "Puede atacar a un enemigo de retaguardia directamente;\nNoquear al enemigo otorga $(400+skillLevel*3-3)$ Rabia. Si no matas al objetivo, aumenta el daño letal propio en un 10% durante 2 rondas (no se puede acumular)",
		describe_en = "Can attack a rear-line enemy directly;\nKnocking out the enemy grants $(400+skillLevel*3-3)$ Rage",
		zawakeSimpleDesc_th = "#C0x5c9970#หากไม่ฆ่าเป้าหมาย เพิ่มความเสียหายร้ายแรงของตัวเอง 10% เป็นเวลา 2 รอบ(ไม่สามารถซ้อนทับได้)",
		zawakeEffectDesc_kr = "후방의 적을 직접 공격할 수 있습니다.\n 적을 쓰러뜨리면 $(400+skillLevel*3-3)$ 분노가 부여됩니다. 대상을 죽이지 못한 경우 2라운드 동안 자신의 치명적인 피해가 10% 증가합니다(중첩할 수 없음).",
		zawakeSimpleDesc_kr = "#C0x5c9970#대상을 죽이지 못한 경우 2라운드 동안 자신의 치명적인 피해량이 10% 증가합니다(중첩할 수 없음).",
		zawakeEffectDesc_en = "Can attack a rear-line enemy directly;\nKnocking out the enemy grants $(400+skillLevel*3-3)$ Rage. If not killing the target, increase own Lethal DMG by 10% for 2 rounds(cannot be stacked)",
		describe_kr = "후방의 적을 직접 공격할 수 있습니다;\n 적을 쓰러뜨리면 획득 $(400+skillLevel*3-3)$ 분노",
		zawakeSimpleDesc_vn = "#C0x5c9970#Se não matar o alvo, aumente o próprio DMG Letal em 10% por 2 rodadas (não pode ser empilhado)",
		zawakeSimpleDesc_id = "#C0x5c9970#Jika tidak membunuh target, meningkatkan Lethal DMG miliknya sebesar 10% selama 2 putaran (tidak dapat ditumpuk)",
		starEffectDesc_vn = "Efeito adicional: entra automaticamente no estado [Stealth] após a raiva completa e aumenta a taxa de controle imunológico em 20% durante a furtividade",
		zawakeSimpleDesc_es = "#C0x5c9970#Si no matas al objetivo, aumenta el daño letal propio en un 10 % durante 2 rondas (no se puede acumular)",
		describe_th = "สามารถโจมตีศัตรูแนวหลังได้โดยตรง \n การน็อคศัตรูจะได้รับ $(400+skillLevel*3-3)$ ความเดือดดาล",
		starEffectDesc_en = "Additional effect: automatically enter the [Stealth] state after Anger full, and increase Control Immune rate by 20% during stealth",
		id = 36636
