	[36723] = {
		describe_id = "Torracat berubah menjadi pita api untuk menyerang musuh di barisan belakang dengan HP terendah, menimbulkan#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, dan memasuki kondisi menyala selama 2 ronde , dan memulihkan 30% dari maks. HP pada saat yang sama (Pokémon tipe Api sekutu lainnya memulihkan 15% dari HP maksimal), kondisi menyala:#C0xF13B54#Selama Festival Musim Semi Tahun Macan, menimbulkan kerusakan ganda pada musuh kelas non-pemain#C0x5B545B#, meningkatkan tingkat lifesteal dan bonus ATK sebesar 30%; setelah skill Ultimate berakhir, 2 lapis Fighting Intent dikonsumsi",
		zawakeEffectDesc_vn = "Torracat se transforma em uma serpentina de chamas para atacar os inimigos da última fileira com o HP mais baixo, infligindo#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, entra em estado de chamas por 2 rodadas, recupera aliados próprios e do tipo Fogo 30% do máximo. HP ao mesmo tempo (outros Pokémon aliados, mas não do tipo Fogo, recuperam 15% do HP máximo), estado flamejante:#C0xF13B54#Durante o Festival da Primavera do Ano do Tigre, inflige dano duplo a inimigos da classe não-jogador#C0x5B545B#, aumentando a taxa de roubo de vida e bônus de ATK em 30%, e aumentando ignorar P.DEF em 30%; após o final da habilidade Ultimate, 2 camadas de Intenção de Combate são consumidas",
		describe_vn = "Torracat se transforma em uma serpentina de chamas para atacar os inimigos da última fileira com o HP mais baixo, infligindo#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, e entra em estado de chamas por 2 rodadas e recupera 30% do máximo. HP ao mesmo tempo (outros Pokémon aliados do tipo Fogo recuperam 15% do HP máximo), estado flamejante:#C0xF13B54#Durante o Festival da Primavera do Ano do Tigre, inflige dano duplo a inimigos da classe não-jogador#C0x5B545B#, aumentando a taxa de roubo de vida e o bônus de ATK em 30%; após o final da habilidade Ultimate, 2 camadas de Intenção de Combate são consumidas",
		starEffectDesc_id = "Efek tambahan: Saat dalam keadaan menyala, kekebalan terhadap kontrol meningkat sebesar 50%, dan saat menyerang, menambahkan Pembakaran dan 30% rentan terhadap target tipe api selama 2 putaran; setelah skill Ultimate berakhir, 1 lapisan niat bertarung dikonsumsi",
		zawakeEffectDesc_th = "ทอร์ราแคทแปลงร่างเป็นลำแสงเพลิงเพื่อโจมตีศัตรูแถวหลังที่มี HP ต่ำสุด สร้างความเสียหาย#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B# เข้าสู่สถานะเพลิงไหม้ 2 รอบ ฟื้นฟูพันธมิตรของตนเองและพันธมิตรประเภทไฟ 30% จากสูงสุด HP ในเวลาเดียวกัน (พันธมิตรอื่นๆ แต่ไม่ใช่โปเกมอนประเภทไฟจะฟื้นคืน 15% ของ HP สูงสุด) สถานะเพลิง:#C0xF13B54#ในช่วงเทศกาลฤดูใบไม้ผลิของปีเสือ สร้างความเสียหายสองเท่าให้กับศัตรูที่ไม่ใช่ผู้เล่นคลาส#C0x5B545B# เพิ่มอัตราการดูดพลังชีวิตและโบนัส ATK 30% และเพิ่มการเพิกเฉย P.DEF 30% หลังจากสิ้นสุดทักษะอัลติเมท เจตนาการต่อสู้ 2 ชั้นจะถูกใช้ไป",
		starEffectDesc_kr = "추가 효과 : 화염 상태일 때 제어 면역이 50% 증가하고, 공격 시 2라운드 동안 대상에게 화상 및 화염 속성 취약이 30% 추가됩니다. 궁극기 스킬 종료 후 전투의지 1층 소모",
		describe_es = "Torracat se transforma en una serpentina de llamas para atacar a los enemigos de la última fila con el HP más bajo, infligiendo#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, y entra en estado de llamas durante 2 rondas. , y recupera propio 30% del máximo. HP al mismo tiempo (otros Pokémon aliados de tipo Fuego recuperan el 15% del HP máximo), estado llameante:#C0xF13B54#Durante el Festival de Primavera del Año del Tigre, inflige el doble de daño a enemigos de clase que no son jugadores#C0x5B545B#, aumentar la tasa de robo de vida y la bonificación ATK en un 30%; Después del final de la habilidad definitiva, se consumen 2 capas de Fighting Intent.",
		zawakeSimpleDesc_en = "flaming state boost:#C0x5c9970#increasing  ignore P.DEF by 30%; recovers other Fire-type allies 30% of max. HP at the same time (other allied but not Fire-type Pokémons recover 15% of max. HP)",
		starEffectDesc_es = "Efecto adicional: cuando está en estado de llamas, la inmunidad al control aumenta en un 50%, y al atacar, agrega Ardor y un 30% de vulnerabilidad al tipo de fuego al objetivo durante 2 rondas; Después de finalizar la habilidad Definitiva, se consume 1 capa de intención de lucha.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เมื่ออยู่ในสถานะเพลิง ภูมิต้านทานในการควบคุมจะเพิ่มขึ้น 50% และเมื่อโจมตีจะเพิ่มประเภทเผาไหม้และประเภทไฟ 30% ที่เสี่ยงต่อเป้าหมายเป็นเวลา 2 รอบ; หลังจากสิ้นสุดทักษะอัลติเมท ความตั้งใจในการต่อสู้ 1 ชั้นจะถูกใช้ไป",
		zawakeEffectDesc_id = "Torracat berubah menjadi pita api untuk menyerang musuh di barisan belakang dengan HP terendah, menimbulkan#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, memasuki kondisi menyala selama 2 ronde, memulihkan sekutunya sendiri dan sekutu tipe Api 30% dari maks. HP pada saat yang sama (Pokémon sekutu lainnya tetapi bukan Pokémon bertipe Api memulihkan 15% dari HP maksimal), kondisi menyala:#C0xF13B54#Selama Festival Musim Semi Tahun Macan, menimbulkan kerusakan ganda pada musuh kelas non-pemain#C0x5B545B#, meningkatkan tingkat lifesteal dan bonus ATK sebesar 30%, dan meningkatkan pengabaian P.DEF sebesar 30%; setelah skill Ultimate berakhir, 2 lapis Fighting Intent dikonsumsi",
		zawakeEffectDesc_es = "Torracat se transforma en una serpentina de llamas para atacar a los enemigos de la última fila con el HP más bajo, infligiendo#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, entra en estado de llamas durante 2 rondas. Recupera a tus propios aliados y a los de tipo Fuego el 30% del máximo. HP al mismo tiempo (otros Pokémon aliados pero no de tipo Fuego recuperan el 15 % del HP máximo), estado de llamas:#C0xF13B54#Durante el Festival de Primavera del Año del Tigre, inflige el doble de daño a enemigos de clase que no son jugadores#C0x5B545B#, aumentando la tasa de robo de vida y la bonificación ATK en un 30 % y aumentando el P.DEF de ignorar en un 30 %; Después del final de la habilidad definitiva, se consumen 2 capas de Fighting Intent.",
		describe_en = "Torracat transforms into a flame streamer to attack the back row enemies with the lowest HP, inflicting#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, and enters flaming state for 2 rounds, and recovers own 30% of max. HP at the same time (other allied Fire-type Pokémon recover 15% of max. HP), flaming state:#C0xF13B54#During the Spring Festival of the Year of Tiger, inflicts double damage to non-player class enemies#C0x5B545B#, increasing lifesteal rate and ATK bonus by 30%; after the end of Ultimate skill, 2 layers of Fighting Intent are consumed",
		zawakeSimpleDesc_th = "เพิ่มสถานะเพลิง:#C0x5c9970#เพิ่มการเพิกเฉย P.DEF ขึ้น 30%; ฟื้นฟูพันธมิตรประเภทไฟอื่นๆ 30% จากสูงสุด HP ในเวลาเดียวกัน (โปเกมอนประเภทเดียวกันที่ไม่ใช่ไฟจะฟื้น 15% ของ HP สูงสุด)",
		zawakeEffectDesc_kr = "토라캣이 화염 깃발로 변신하여 HP가 가장 낮은 뒷줄의 적을 공격하며 #C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, 2라운드 동안 화염 상태에 진입하고, 자신과 불꽃형 아군 최대 30% 회복 동시에 HP(불꽃타입 포켓몬이 아닌 다른 아군 최대 HP의 15% 회복), 불타는 상태:#C0xF13B54#춘절 기간 동안 비플레이어 클래스 적에게 2배의 데미지를 줍니다#C0x5B545B# 생명력 흡수율과 ATK 보너스가 30% 증가하고 P.DEF 무시가 30% 증가합니다. 궁극기 스킬 종료 후 투지 2중 소모",
		zawakeSimpleDesc_kr = "불타는 상태 부스트:#C0x5c9970#P.DEF 무시가 30% 증가합니다. 다른 불꽃형 아군 최대 30% 회복 동시에 HP(불꽃타입 포켓몬이 아닌 다른 아군은 최대 HP의 15%를 회복)",
		zawakeEffectDesc_en = "Torracat transforms into a flame streamer to attack the back row enemies with the lowest HP, inflicting#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, enters flaming state for 2 rounds, recovers own and Fire-type allies 30% of max. HP at the same time (other allied but not Fire-type Pokémon recover 15% of max. HP), flaming state:#C0xF13B54#During the Spring Festival of the Year of Tiger, inflicts double damage to non-player class enemies#C0x5B545B#, increasing lifesteal rate and ATK bonus by 30%, and increasing  ignore P.DEF by 30%; after the end of Ultimate skill, 2 layers of Fighting Intent are consumed",
		describe_kr = "토라캣이 화염 깃발로 변신해 HP가 가장 낮은 뒷줄의 적들을 공격해 #C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#를 입히고 2라운드 동안 화염 상태가 됩니다. , 그리고 자신의 최대 30%를 회복합니다. 동시에 HP(다른 아군 불꽃형 포켓몬은 최대 HP의 15% 회복), 불타는 상태:#C0xF13B54#춘절 기간 동안 플레이어가 아닌 클래스의 적에게 2배의 피해를 줍니다#C0x5B545B#, 생명력 흡수율과 공격력 보너스가 30% 증가합니다. 궁극기 스킬 종료 후 투지 2중 소모",
		zawakeSimpleDesc_vn = "aumento de estado flamejante:#C0x5c9970#aumentando ignorar P.DEF em 30%; recupera outros aliados do tipo Fogo em 30% do máximo. HP ao mesmo tempo (outros Pokémons aliados, mas não do tipo Fogo, recuperam 15% do HP máximo)",
		zawakeSimpleDesc_id = "peningkatan status menyala:#C0x5c9970#meningkatkan pengabaian P.DEF sebesar 30%; memulihkan sekutu tipe Api lainnya 30% dari maks. HP pada saat yang sama (Pokémon sekutu lainnya tetapi bukan Pokémon tipe Api memulihkan 15% dari HP maksimal)",
		starEffectDesc_vn = "Efeito adicional: Quando em estado flamejante, a imunidade ao controle aumenta em 50%, e ao atacar, adiciona Queima e 30% do tipo fogo vulnerável ao alvo por 2 rodadas; após o término da habilidade Ultimate, 1 camada de intenção de luta é consumida",
		zawakeSimpleDesc_es = "impulso del estado de llamas: #C0x5c9970#aumentando el P.DEF de ignorar en un 30%; recupera a otros aliados de tipo Fuego el 30% del máximo. HP al mismo tiempo (otros Pokémon aliados pero no de tipo Fuego recuperan el 15% del HP máximo)",
		describe_th = "ทอร์ราแคทแปลงร่างเป็นลำแสงเพลิงเพื่อโจมตีศัตรูแถวหลังที่มี HP ต่ำสุด สร้างความเสียหาย#C0xE69900#440% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B# และเข้าสู่สถานะเพลิงไหม้ 2 รอบ และฟื้นฟูตัวเอง 30% จากสูงสุด HP ในเวลาเดียวกัน (โปเกมอนประเภทไฟพันธมิตรตัวอื่นฟื้น 15% ของ HP สูงสุด) สถานะเพลิง:#C0xF13B54#ในช่วงเทศกาลฤดูใบไม้ผลิของปีเสือ สร้างความเสียหายสองเท่าให้กับศัตรูที่ไม่ใช่ผู้เล่นคลาส#C0x5B545B#, เพิ่มอัตราการดูดพลังชีวิตและโบนัส ATK 30%; หลังจากสิ้นสุดทักษะอัลติเมท เจตนาการต่อสู้ 2 ชั้นจะถูกใช้ไป",
		starEffectDesc_en = "Additional effect: When in the flaming state, the immunity to control increases by 50%, and when attacking, adds Burning and 30% fire-type vulnerable to the target for 2 rounds; after the ends of Ultimate skill, 1 layer of fighting intent is consumed",
		id = 36723
	},
	[36726] = {
		describe_id = "Di akhir ronde, ada peluang 60% untuk mendapatkan lapisan Fighting Intent; saat diserang secara aktif, ada 25% kemungkinan mendapatkan lapisan Fighting Intent, ditumpuk hingga 4 lapisan; sebelum dimulainya setiap ronde besar, Torracat akan mencuri SP.ATK dan P.ATK dari 3 unit musuh dengan ATK tertinggi#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#dan akan mengembalikannya setelah ronde besar berakhir; langsung melepaskan skill Ultimate dan mendapatkan 2 lapis Fighting Intent ketika Pokémon tipe Api sekutu mati (dipicu satu kali di antara penonton)",
		zawakeEffectDesc_vn = "No início da batalha, ganha 1 camada de Intenção de Combate, ao final do round, há 60% de chance de ganhar uma camada de Intenção de Combate; ao ser atacado ativamente, há 40% de chance de ganhar uma camada de Intenção de Combate, acumulando até 4 camadas; antes do início de cada grande rodada, Torracat roubará SP.ATK e P.ATK de 3 unidades de inimigos com o maior ATK#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#e os devolverá após o término da grande rodada; libera instantaneamente habilidade Ultimate e ganha 2 camadas de Intenção de Luta quando Pokémon aliados do tipo Fogo morrem (acionado uma vez na audiência)",
		describe_vn = "Ao final da rodada, há 60% de chance de ganhar uma camada de Intenção de Combate; ao ser atacado ativamente, há 25% de chance de ganhar uma camada de Intenção de Combate, acumulando até 4 camadas; antes do início de cada grande rodada, Torracat roubará SP.ATK e P.ATK de 3 unidades de inimigos com o maior ATK#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#e os devolverá após o término da grande rodada; libera instantaneamente habilidade Ultimate e ganha 2 camadas de Intenção de Combate quando Pokémon aliados do tipo Fogo morrem (acionado uma vez na audiência)",
		starEffectDesc_id = "Efek tambahan: Ketika setiap unit musuh dikalahkan, mencuri 15% SP.ATK dan P.ATK target (dapat ditumpuk); semua Pokémon tipe Api dan tipe Gelap yang bersekutu mendapatkan 50% dari efek ini",
		zawakeEffectDesc_th = "เมื่อเริ่มการต่อสู้ ได้รับเจตจำนงการต่อสู้ 1 ชั้น เมื่อสิ้นสุดรอบ มีโอกาส 60% ที่จะได้รับเจตจำนงการต่อสู้ 1 ชั้น เมื่อถูกโจมตีอย่างแข็งขัน มีโอกาส 40% ที่จะได้รับชั้นเจตนาการต่อสู้ ซ้อนได้สูงสุด 4 ชั้น ก่อนเริ่มแต่ละรอบใหญ่ Torracat จะขโมย SP.ATK และ P.ATK ของศัตรู 3 หน่วยที่มี ATK สูงสุด#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# และจะคืนให้หลังจากรอบใหญ่สิ้นสุดลง ปล่อยทักษะขั้นสูงสุดทันทีและได้รับเจตจำนงการต่อสู้ 2 ชั้นเมื่อโปเกมอนประเภทไฟพันธมิตรตาย (ถูกกระตุ้นหนึ่งครั้งในกลุ่มผู้ชม)",
		starEffectDesc_kr = "추가 효과: 각 적 유닛이 패배할 때 대상의 SP.ATK 및 P.ATK를 15% 훔칩니다(중첩 가능). 아군 불꽃타입, 악타입 포켓몬 모두 이 효과를 50% 얻습니다.",
		describe_es = "Al final de la ronda, hay un 60% de posibilidades de obtener una capa de Intención de lucha; cuando se es atacado activamente, hay un 25 % de posibilidades de obtener una capa de Intención de lucha, acumulándose hasta 4 capas; antes del inicio de cada gran ronda, Torracat robará SP.ATK y P.ATK de 3 unidades de enemigos con el ATK más alto#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#y lo devolverá después de que finalice la gran ronda; Libera instantáneamente la habilidad definitiva y gana 2 capas de intención de lucha cuando un Pokémon aliado de tipo Fuego muere (se activa una vez en la audiencia).",
		zawakeSimpleDesc_en = "At the start of the battle, gains 1 layer of Fighting Intent; when being actively attacked, the chance of gaining Fighting Intent is increased to 40%",
		starEffectDesc_es = "Efecto adicional: cuando cada unidad enemiga es derrotada, roba el 15% SP.ATK y P.ATK del objetivo (se puede acumular); todos los Pokémon aliados de tipo Fuego y Tipo Oscuro obtienen el 50% de este efecto.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เมื่อศัตรูแต่ละยูนิตถูกกำจัด จะขโมย SP.ATK และ P.ATK ของเป้าหมาย 15% (สามารถซ้อนทับได้); โปเกมอนธาตุไฟและธาตุมืดพันธมิตรทั้งหมดจะได้รับเอฟเฟกต์นี้ 50%",
		zawakeEffectDesc_id = "Di awal pertarungan, memperoleh 1 lapis Fighting Intent, di akhir ronde, ada peluang 60% untuk mendapatkan satu lapis Fighting Intent; saat diserang secara aktif, ada peluang 40% untuk mendapatkan lapisan Fighting Intent, yang ditumpuk hingga 4 lapisan; sebelum dimulainya setiap ronde besar, Torracat akan mencuri SP.ATK dan P.ATK dari 3 unit musuh dengan ATK tertinggi#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#dan akan mengembalikannya setelah ronde besar berakhir; langsung melepaskan skill Ultimate dan mendapatkan 2 lapis Fighting Intent ketika Pokémon tipe Api sekutu mati (dipicu satu kali di antara penonton)",
		zawakeEffectDesc_es = "Al comienzo de la batalla, gana 1 capa de Fighting Intent, al final de la ronda, hay un 60% de posibilidades de ganar una capa de Fighting Intent; cuando se es atacado activamente, hay un 40 % de posibilidades de obtener una capa de Intención de lucha, acumulándose hasta 4 capas; antes del inicio de cada gran ronda, Torracat robará SP.ATK y P.ATK de 3 unidades de enemigos con el ATK más alto#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#y lo devolverá después de que finalice la gran ronda; Libera instantáneamente la habilidad definitiva y gana 2 capas de intención de lucha cuando un Pokémon aliado de tipo Fuego muere (se activa una vez en la audiencia).",
		describe_en = "At the end of the round, there is a 60% chance of gaining a layer of Fighting Intent; when being actively attacked, there is a 25% chance of gaining a layer of Fighting Intent, stacking up to 4 layers; before the start of each big round, Torracat will steal SP.ATK and P.ATK of 3 units of enemies with the highest ATK#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#and will return it after the big round ends; instantly releases Ultimate skill and gains 2 layers of Fighting Intent when allied Fire-type Pokémon dies(triggered once in the audience)",
		zawakeSimpleDesc_th = "เมื่อเริ่มการต่อสู้ ได้รับเจตจำนงการต่อสู้ 1 ชั้น เมื่อถูกโจมตีอย่างแข็งขัน โอกาสในการได้รับเจตจำนงการต่อสู้เพิ่มขึ้นเป็น 40%",
		zawakeEffectDesc_kr = "전투 시작 시 투지 1층을 획득하고, 라운드 종료 시 60% 확률로 투지 1층을 획득합니다. 적극적 공격을 받을 때 40% 확률로 투지 레이어를 획득하며 최대 4 레이어까지 중첩됩니다. 각 큰 라운드가 시작되기 전에 Torracat은 가장 높은 ATK#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#를 가진 적 3개의 SP.ATK 및 P.ATK를 훔치고 큰 라운드가 끝난 후 반환합니다. 아군 불꽃타입 포켓몬이 죽으면 즉시 궁극기를 발동하고 투지 2단계 획득(청중에게 1회 발동)",
		zawakeSimpleDesc_kr = "전투 시작 시 전투 의지 1단계를 얻습니다. 적극적 공격을 받을 때 전투 의지 획득 확률이 40%로 증가합니다.",
		zawakeEffectDesc_en = "At the start of the battle, gains 1 layer of Fighting Intent, at the end of the round, there is a 60% chance of gaining a layer of Fighting Intent; when being actively attacked, there is a 40% chance of gaining a layer of Fighting Intent, stacking up to 4 layers; before the start of each big round, Torracat will steal SP.ATK and P.ATK of 3 units of enemies with the highest ATK#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#and will return it after the big round ends; instantly releases Ultimate skill and gains 2 layers of Fighting Intent when allied Fire-type Pokémon dies(triggered once in the audience)",
		describe_kr = "라운드가 끝나면 60%의 확률로 전투 의도 레이어를 얻을 수 있습니다. 적극적으로 공격을 받을 때 25%의 확률로 투지 레이어를 획득하며 최대 4겹까지 중첩됩니다. 각 큰 라운드가 시작되기 전에 Torracat은 가장 높은 ATK#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B#를 가진 적 3개의 SP.ATK 및 P.ATK를 훔치고 큰 라운드가 끝난 후 반환합니다. 아군 불꽃타입 포켓몬이 죽으면 즉시 궁극기를 발동하고 투지 2단계 획득(청중에게 1회 발동)",
		zawakeSimpleDesc_vn = "No início da batalha, ganha 1 camada de Intenção de Combate; ao ser atacado ativamente, a chance de ganhar Intenção de Combate aumenta para 40%",
		zawakeSimpleDesc_id = "Di awal pertempuran, memperoleh 1 lapisan Fighting Intent; saat diserang secara aktif, peluang mendapatkan Fighting Intent meningkat menjadi 40%",
		starEffectDesc_vn = "Efeito adicional: Quando cada unidade inimiga é derrotada, rouba 15% de SP.ATK e P.ATK do alvo (pode ser empilhado); todos os Pokémon aliados do tipo Fire e Dark ganham 50% deste efeito",
		zawakeSimpleDesc_es = "Al comienzo de la batalla, gana 1 capa de Intención de lucha; Al ser atacado activamente, la probabilidad de obtener intención de lucha aumenta al 40%.",
		describe_th = "เมื่อสิ้นสุดรอบ มีโอกาส 60% ที่จะได้รับชั้นเจตนาการต่อสู้ เมื่อถูกโจมตีอย่างแข็งขัน มีโอกาส 25% ที่จะได้รับชั้นเจตนาการต่อสู้ ซ้อนได้สูงสุด 4 ชั้น ก่อนเริ่มแต่ละรอบใหญ่ Torracat จะขโมย SP.ATK และ P.ATK ของศัตรู 3 หน่วยที่มี ATK สูงสุด#C0x5c9970#$(10+skillLevel*0.05-0.05)$%#C0x5B545B# และจะคืนให้หลังจากรอบใหญ่สิ้นสุดลง ปล่อยทักษะขั้นสูงสุดทันทีและได้รับเจตจำนงการต่อสู้ 2 ชั้นเมื่อโปเกมอนประเภทไฟพันธมิตรตาย (ถูกกระตุ้นหนึ่งครั้งในกลุ่มผู้ชม)",
		starEffectDesc_en = "Additional effect: When each enemy unit is defeated, steals 15% SP.ATK and P.ATK of the target(can be stacked); all allied Fire-type and Dark-type Pokémon gain 50% of this effect",
		id = 36726
	},
	[36731] = {
