	[36812] = {
		zawakeEffectDesc_es = "Popplio infla un globo de agua para atacar a un solo objetivo enemigo, causando #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, usa el control de canto para lanzar un globo de agua a [Bound] la matriz objetivo (Bound: efecto de control, no puede usar ataques básicos), después de que el objetivo usa una habilidad pequeña o habilidad definitiva, el globo de agua explota y cancela Bound, causa 100% SP.ATK de daño de Popplio y activa el efecto pasivo de sonido húmedo.",
		zawakeEffectDesc_vn = "Popplio sopra um balão de água para atacar um único alvo inimigo, distribuindo #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, usa o controle de canto para liberar o balão de água para [Bound] o array alvo (Bound: efeito de controle, não pode usar ataques básicos), depois que o alvo usa uma pequena habilidade ou Ultimate Skill, o balão de água explode e cancela Bound, causa 100% de dano SP.ATK de Popplio e desencadeia o efeito passivo de som úmido",
		describe_th = "ป็อปลิโอเป่าลูกโป่งน้ำเพื่อโจมตีศัตรูเป้าหมายเดียว สร้างความเสียหาย #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B# และใช้การร้องเพลงเพื่อควบคุมการปล่อยลูกโป่งน้ำ [Confine] เป้าหมายติดต่อกัน (จำกัด: เอฟเฟกต์ควบคุม ไม่สามารถใช้การโจมตีพื้นฐานได้) หลังจากที่เป้าหมายใช้ทักษะขนาดเล็กหรือทักษะอัลติเมท ลูกโป่งน้ำจะระเบิดและการกักขังสิ้นสุดลง สร้างความเสียหายเท่ากับ SP.ATK 100% ของ Popplio",
		zawakeEffectDesc_kr = "포플리오가 물풍선을 날려 단일 적 대상을 공격하며 #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 노래 컨트롤을 사용해 물풍선을 [Bound]에게 발사합니다. 대상 배열(바운드: 제어 효과, 기본 공격 불가), 대상이 소형 스킬 또는 얼티밋 스킬 사용 후 물풍선이 폭발하여 바운드를 취소하고 포플리오의 SP.ATK 100% 데미지를 주며 패시브 촉촉한 음향 효과 발동",
		zawakeEffectDesc_th = "ป็อปลิโอเป่าลูกโป่งน้ำเพื่อโจมตีศัตรูเป้าหมายเดียว สร้างความเสียหาย#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# ใช้การควบคุมการร้องเพลงเพื่อปล่อยลูกโป่งน้ำไปที่ [Bound] อาเรย์เป้าหมาย (ถูกผูกไว้: เอฟเฟกต์ควบคุม ไม่สามารถใช้การโจมตีพื้นฐานได้) หลังจากที่เป้าหมายใช้ทักษะขนาดเล็กหรือทักษะขั้นสูงสุด บอลลูนน้ำจะระเบิดและยกเลิกการผูกมัด สร้างความเสียหาย SP.ATK 100% ของ Popplio และเรียกใช้เอฟเฟกต์เสียงชื้นแบบพาสซีฟ",
		describe_en = "Popplio blows out a water balloon to attack a single enemy target, dealing #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, and uses singing to control the release of water balloon to [Confine] the targets in a row (Confine: Control effect, cannot use basic attacks). After the target uses a small skill or Ult Skill, the water balloon explodes and the confinement ends, dealing DMG equals to Popplio's 100% SP.ATK",
		describe_es = "Popplio infla un globo de agua para atacar a un solo objetivo enemigo, causando #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, y usa el canto para controlar la liberación del globo de agua para [Confine] los objetivos seguidos (Confinar: efecto de control, no se pueden usar ataques básicos). Después de que el objetivo usa una habilidad pequeña o una habilidad definitiva, el globo de agua explota y el confinamiento termina, causando DAÑO igual al 100% SP.ATK de Popplio.",
		zawakeSimpleDesc_en = "When the water balloon explodes, triggers passive Moist Sound effect",
		describe_vn = "Popplio sopra um balão de água para atacar um único alvo inimigo, distribuindo #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, e usa o canto para controlar a liberação do balão de água para [Confine] os alvos seguidos (Confinar: efeito de controle, não pode usar ataques básicos). Depois que o alvo usa uma pequena habilidade ou Ult Skill, o balão de água explode e o confinamento termina, distribuindo DMG igual a 100% SP.ATK de Popplio",
		zawakeEffectDesc_en = "Popplio blows out a water balloon to attack a single enemy target, dealing#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, uses singing control to release water balloon to [Bound] the target array (Bound: Control effect, cannot use basic attacks), after the target uses a small skill or Ultimate Skill, the water balloon explodes and cancels Bound, deals 100% SP.ATK damage of Popplio, and triggers passive Moist Sound effect",
		zawakeSimpleDesc_vn = "Quando o balão de água explode, ativa o efeito passivo de som úmido",
		zawakeSimpleDesc_id = "Saat balon air meledak, memicu efek Suara Lembab pasif",
		zawakeSimpleDesc_es = "Cuando el globo de agua explota, se activa el efecto pasivo de sonido húmedo.",
		describe_id = "Popplio meniup balon air untuk menyerang satu target musuh, menimbulkan #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, dan menggunakan nyanyian untuk mengontrol pelepasan balon air ke [Confine] target berturut-turut (Batas: Efek kontrol, tidak bisa menggunakan serangan dasar). Setelah target menggunakan skill kecil atau Skill Ult, balon air meledak dan kurungan berakhir, menimbulkan DMG setara dengan 100% SP.ATK Popplio",
		zawakeSimpleDesc_kr = "물풍선이 터지면 패시브 촉촉한 소리 효과가 발동됩니다.",
		zawakeEffectDesc_id = "Popplio meniup balon air untuk menyerang satu target musuh, menimbulkan#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, menggunakan kontrol bernyanyi untuk melepaskan balon air ke [Bound] array target (Bound: Efek kontrol, tidak dapat menggunakan serangan dasar), setelah target menggunakan skill kecil atau Skill Ultimate, balon air meledak dan membatalkan Bound, menimbulkan 100% SP.ATK damage Popplio, dan memicu efek pasif Moist Sound",
		describe_kr = "포플리오는 물풍선을 날려 단일 적 대상을 공격해 #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#를 입히고, 노래로 물풍선의 방출을 제어하여 [Confine] 연속된 대상 (제한: 제어 효과, 기본 공격을 사용할 수 없음). 대상이 소형 스킬이나 궁극기 스킬을 사용한 후 물풍선이 터지며 감금이 종료되어 포플리오의 SP.ATK 100%만큼 데미지를 줍니다.",
		zawakeSimpleDesc_th = "เมื่อลูกโป่งน้ำระเบิด จะทำให้เกิดเอฟเฟกต์เสียงชื้น",
		id = 36812
	},
	[36813] = {
		describe_th = "Popplio ยิงกระแสน้ำอันทรงพลังใส่ศัตรูในแนวหน้า สร้าง #C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B# ลดความโกรธของเป้าหมายลง 200 แต้ม และลบล้างความเสียหาย [Burn] เอฟเฟกต์ของโปเกมอนทั้งหมดในการต่อสู้ ศัตรูที่ถูกขับไล่จะลดความโกรธลงอีก 600 แต้ม พันธมิตรที่ถูกขับไล่จะฟื้นฟู HP ของ SP.ATK ของ Popplio 100%",
		zawakeEffectDesc_vn = "Popplio usa Aqua Jet para atacar os inimigos na linha de frente, infligindo (#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#, reduz a Fúria do alvo em 300 pontos, reduz o velocidade de recuperação de raiva em 50% por 2 rodadas e dissipa o efeito de queima de todos os Pokémon no campo. Inimigos dissipados reduzem a raiva em 600 pontos adicionais, aliados dissipados recuperam HP de 100% SP.ATK de Popplio",
		simDesc_es = "Popplio dispara un poderoso chorro de agua a los enemigos en la línea del frente, reduce la ira del objetivo y disipa todos los efectos [Burn] en el campo de batalla.",
		describe_es = "Popplio dispara un poderoso chorro de agua a los enemigos en la línea del frente, causando #C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, reduce la ira del objetivo en 200 puntos y disipa el [Burn] efecto de todos los Pokémon en la batalla. Los enemigos disipados reducen la ira en 600 puntos adicionales, los aliados disipados recuperan HP del 100% SP.ATK de Popplio.",
		zawakeEffectDesc_th = "ป็อปลิโอใช้เจ็ทน้ำเพื่อโจมตีศัตรูในแนวหน้า สร้างความเสียหาย (#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# ลดความโกรธของเป้าหมายลง 300 คะแนน ลดพลังโจมตี ความเร็วการฟื้นฟูความโกรธ 50% เป็นเวลา 2 รอบ และลบล้างเอฟเฟกต์การเผาไหม้ของโปเกมอนทุกตัวบนสนาม ศัตรูที่ถูกขับไล่จะลดความโกรธลงอีก 600 แต้ม พันธมิตรที่ถูกขับไล่จะฟื้นฟู HP ของ SP.ATK ของ Popplio 100%",
		starEffectDesc_id = "Efek Tambahan: menghilangkan 2 Debuff dari semua sekutu",
		starEffectDesc_es = "Efecto adicional: disipa 2 desventajas de todos los aliados.",
		zawakeSimpleDesc_en = "Reduce the target's rage to 300 points; reduce the rage recovery speed by 50% for 2 rounds",
		describe_vn = "Popplio dispara um poderoso jato de água contra os inimigos na linha de frente, distribuindo #C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, reduz a Fúria do alvo em 200 pontos e dissipa o [Burn] efeito de todos os Pokémon na batalha. Inimigos dissipados reduzem a raiva em 600 pontos adicionais, aliados dissipados recuperam HP de 100% SP.ATK de Popplio",
		starEffectDesc_th = "ผลกระทบเพิ่มเติม: ลบล้างดีบัฟ 2 อันจากพันธมิตรทั้งหมด",
		starEffectDesc_vn = "Efeito Adicional: dissipa 2 Debilitações de todos os aliados",
		zawakeEffectDesc_kr = "포플리오는 아쿠아제트로 최전선의 적을 공격하여 (#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#, 대상의 분노를 300 감소시키고, 2라운드 동안 분노 회복 속도가 50% 증가하고 필드에 있는 모든 포켓몬의 화상 효과가 해제됩니다. 해제된 적의 분노가 추가로 600포인트 감소하고, 해제된 아군은 포플리오의 SP.ATK 100%만큼 HP를 회복합니다.",
		describe_en = "Popplio fires a powerful stream of water at enemies in the front line, dealing #C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, reduces the target's Rage by 200 points and dispels the [Burn] effect of all Pokemon in the battle. Enemies dispelled reduce rage by an additional 600 points, allies dispelled recovers HP of Popplio's 100% SP.ATK",
		zawakeEffectDesc_id = "Popplio menggunakan Aqua Jet untuk menyerang musuh di garis depan, menimbulkan (#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#, mengurangi Rage target sebanyak 300 poin, mengurangi kecepatan pemulihan kemarahan sebesar 50% selama 2 putaran, dan menghilangkan efek pembakaran semua Pokémon di lapangan. Musuh yang di-dispel mengurangi kemarahan sebanyak 600 poin tambahan, sekutu yang di-dispel memulihkan HP dari 100% SP.ATK Popplio",
		describe_id = "Popplio menembakkan aliran air yang kuat ke musuh di garis depan, menyebabkan #C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#, mengurangi Rage target sebanyak 200 poin dan menghalau [Burn] efek semua Pokemon dalam pertempuran. Musuh yang dihilangkan mengurangi kemarahan sebanyak 600 poin tambahan, sekutu yang dihilangkan memulihkan HP dari 100% SP.ATK Popplio",
		simDesc_en = "Popplio fires a powerful stream of water at enemies in the front line, reduces target's Rage, and dispels all [Burn] effect on the battlefield",
		simDesc_vn = "Popplio dispara um poderoso jato de água contra os inimigos na linha de frente, reduz a Fúria do alvo e dissipa todos os efeitos [Burn] no campo de batalha",
		describe_kr = "포플리오가 최전선의 적에게 강력한 물줄기를 발사하여 #C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# SP.DMG#C0x5B545B#를 처리하고 대상의 분노를 200포인트 감소시키고 [Burn] 전투에 참여하는 모든 포켓몬의 효과. 해제된 적의 분노가 추가로 600 감소하고, 해제된 아군은 포플리오의 SP.ATK 100% HP를 회복합니다.",
		simDesc_th = "Popplio ยิงกระแสน้ำอันทรงพลังใส่ศัตรูในแนวหน้า ลดความโกรธของเป้าหมาย และลบล้างเอฟเฟกต์ [Burn] ทั้งหมดบนสนามรบ",
		zawakeEffectDesc_es = "Popplio usa Aqua Jet para atacar a los enemigos en la línea del frente, infligiendo (#C0x3D8A99#240% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#, reduce la ira del objetivo en 300 puntos, reduce la Velocidad de recuperación de ira en un 50% durante 2 rondas y disipa el efecto de quema de todos los Pokémon en el campo. Los enemigos disipados reducen la ira en 600 puntos adicionales, los aliados disipados recuperan HP del 100% SP.ATK de Popplio.",
