	[36831] = {
		zawakeEffectDesc_es = "Primarina usa el poder de la marea para atacar a un solo objetivo enemigo para tratar#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#y luego aumenta su propio SP.DEF en un 30% y SP.ATK en un 10% durante 2 rondas, con un 50% de probabilidad de activar el efecto pasivo de sonido húmedo",
