	[51008] = {
		describe_vn = "Quando danificado por uma habilidade, tem $(40+(skillLevel-1)*2)$% de chance de remover 1-2 efeitos negativos para si mesmo. Aciona até 1 vez em 1 rodada grande e 3 vezes durante a batalha.",
		describe_kr = "스킬 피해 시 $(40+(skillLevel-1)*2)$% 확률로 자신에게 1~2개의 부정적인 효과를 제거합니다. 1개의 큰 라운드에 최대 1번, 전투에 걸쳐 3번까지 발동합니다.",
		describe_en = "When damage by a skill, has a $(40+(skillLevel-1)*2)$% chance to remove 1-2 negative effect for self. Triggers up to 1 time over 1 big round and 3 times over the battle.",
		describe_id = "Ketika terkena kerusakan oleh suatu keterampilan, mempunyai peluang $(40+(skillLevel-1)*2)$% untuk menghilangkan 1-2 efek negatif pada diri sendiri. Memicu hingga 1 kali dalam 1 putaran besar dan 3 kali dalam pertempuran.",
		id = 51008,
		describe_es = "Cuando se daña con una habilidad, tiene un $(40+(skillLevel-1)*2)$% de probabilidad de eliminar 1-2 efectos negativos para uno mismo. Se activa hasta 1 vez en 1 ronda grande y 3 veces durante la batalla.",
		describe_th = "เมื่อสร้างความเสียหายด้วยทักษะ มีโอกาส $(40+(skillLevel-1)*2)$% ที่จะลบเอฟเฟกต์ด้านลบ 1-2 ให้กับตนเอง เรียกใช้ได้สูงสุด 1 ครั้งใน 1 รอบใหญ่ และ 3 ครั้งในการต่อสู้"
	},
	[51009] = {
		describe_vn = "Durante a batalha, as habilidades ativas do transportador de itens causam $(14+(skillLevel-1)*1.5)$% mais dano ao alvo no estado de controle \nQuando [Ash’s Pikachu] carrega, a chance de paralisia aumenta em 5%",
		describe_kr = "전투 중 아이템 운반자의 액티브 스킬이 제어 상태의 대상에게 $(14+(skillLevel-1)*1.5)$% 추가 피해를 입힙니다 \n [Ash’s Pikachu] 운반 시 마비 확률 5% 증가",
		describe_en = "During the battle, active skills of item carrier deals $(14+(skillLevel-1)*1.5)$% more damage to target in control state \nWhen [Ash’s Pikachu] carries, chance of paralysis increase by 5%",
		describe_id = "Selama pertempuran, keterampilan aktif pembawa item menimbulkan $(14+(skillLevel-1)*1.5)$% lebih banyak kerusakan pada target dalam keadaan terkendali \nSaat [Ash’s Pikachu] dibawa, kemungkinan kelumpuhan meningkat sebesar 5%",
		id = 51009,
		describe_es = "Durante la batalla, las habilidades activas del portador de objetos causan un $(14+(skillLevel-1)*1.5)$ % más de daño al objetivo en estado de control \nCuando [Ash’s Pikachu] lleva, la probabilidad de parálisis aumenta en un 5 %",
		describe_th = "ในระหว่างการต่อสู้ ทักษะการใช้งานของผู้ขนส่งไอเท็มจะสร้างความเสียหายเพิ่มขึ้น $(14+(skillLevel-1)*1.5)$% ต่อเป้าหมายในสถานะควบคุม \nเมื่อ [Ash’s Pikachu] พกพา โอกาสที่จะเป็นอัมพาตเพิ่มขึ้น 5%"
	},
	[51010] = {
		describe_vn = "Durante a batalha, a taxa crítica do titular aumenta em $(8+(skillLevel-1)*1)$%, e o DMG crítico aumenta em $(10+(skillLevel-1)*1.5)$%; Ataques ativos que não causam acerto crítico aumentam permanentemente a taxa crítica e o DMG crítico em 5% (até 3 pilhas. Este bônus será removido após o acerto crítico)",
		describe_kr = "전투 중 홀더의 치명타율은 $(8+(skillLevel-1)*1)$% 증가하고, 치명타 피해량은 $(10+(skillLevel-1)*1.5)$% 증가합니다. 치명타가 아닌 활성 공격은 치명타율과 치명타 피해량을 5% 영구적으로 증가시킵니다. (최대 3중첩. 이 보너스는 치명타 후에 제거됩니다.)",
		describe_en = "During the battle, the holder's Crit rate increases by $(8+(skillLevel-1)*1)$%, and the Crit DMG increases by $(10+(skillLevel-1)*1.5)$%; Active attacks that does not Critical hit permanently increase Crit rate and Crit DMG by 5% (Up to 3 stacks. This bonus will be removed after Crit Hit)",
		describe_id = "Selama pertempuran, tingkat Kritik pemegangnya meningkat sebesar $(8+(skillLevel-1)*1)$%, dan DMG Kritikusnya meningkat sebesar $(10+(skillLevel-1)*1.5)$%; Serangan aktif yang tidak menimbulkan Critical hit secara permanen meningkatkan Crit rate dan Crit DMG sebesar 5% (Hingga 3 stack. Bonus ini akan dihapus setelah Crit Hit)",
		id = 51010,
		describe_es = "Durante la batalla, la tasa de críticos del poseedor aumenta en un $(8+(skillLevel-1)*1)$% y el daño crítico aumenta en un $(10+(skillLevel-1)*1.5)$%; Los ataques activos que no causan golpes críticos aumentan permanentemente la tasa de críticos y el daño crítico en un 5 % (hasta 3 acumulaciones. Esta bonificación se eliminará después del golpe crítico).",
		describe_th = "ในระหว่างการต่อสู้ อัตราคริติคอลของผู้ถือจะเพิ่มขึ้น $(8+(skillLevel-1)*1)$% และความเสียหายคริติคอลเพิ่มขึ้น $(10+(skillLevel-1)*1.5)$% การโจมตีแบบแอคทีฟที่ไม่โจมตีคริติคอลจะเพิ่มอัตราคริติคอลและความเสียหายคริติคอล 5% อย่างถาวร (สูงสุด 3 สแต็ค โบนัสนี้จะถูกลบออกหลังจากคริติคอล)"
	},
	[52001] = {
		describe_vn = "Nas batalhas, há 30% de chance de aumentar $(18+(skillLevel-1)*1)$% de ignorância do P.DEF ao atacar",
		describe_kr = "전투 중 공격 시 30% 확률로 $(18+(skillLevel-1)*1)$% P.DEF 무지 증가",
		describe_en = "In battles, there is 30% chance to increase $(18+(skillLevel-1)*1)$% P.DEF ignorance when attacking",
		describe_id = "Dalam pertempuran, ada 30% peluang untuk meningkatkan $(18+(skillLevel-1)*1)$% P.DEF ketidaktahuan saat menyerang",
		id = 52001,
		describe_es = "En las batallas, hay un 30% de posibilidades de aumentar $(18+(skillLevel-1)*1)$% P.DEF ignorancia al atacar",
		describe_th = "ในการต่อสู้ มีโอกาส 30% ที่จะเพิ่มความไม่รู้ P.DEF $(18+(skillLevel-1)*1)$% เมื่อโจมตี"
	},
	[52002] = {
		describe_vn = "Nas batalhas, ao receber dano, há 40% de chance de aumentar a redução de dano próprio em $(14+(skillLevel-1)*1)$% por 1 rodada, não pode ser acumulada",
		describe_kr = "전투에서 피해를 입을 때 40% 확률로 1라운드 동안 자신의 피해 감소량을 $(14+(skillLevel-1)*1)$% 증가, 중첩 불가",
		describe_en = "In battles, when receiving damage, there is 40% chance to increase own damage reduction by $(14+(skillLevel-1)*1)$% for 1 round, can't be stacked",
		describe_id = "Dalam pertempuran, saat menerima damage, ada 40% peluang untuk meningkatkan pengurangan damage sendiri sebesar $(14+(skillLevel-1)*1)$% selama 1 putaran, tidak bisa ditumpuk",
		id = 52002,
		describe_es = "En las batallas, al recibir daño, hay un 40% de probabilidad de aumentar la reducción de daño propio en un $(14+(skillLevel-1)*1)$% durante 1 ronda, no se puede acumular.",
		describe_th = "ในการต่อสู้เมื่อได้รับความเสียหาย มีโอกาส 40% ที่จะเพิ่มการลดความเสียหายของตัวเอง $(14+(skillLevel-1)*1)$% เป็นเวลา 1 รอบ ไม่สามารถซ้อนทับได้"
	},
	[52003] = {
		describe_vn = "Nas batalhas, há 30% de chance de aumentar $(18+(skillLevel-1)*1)$% de ignorância do SP.DEF ao atacar",
		describe_kr = "전투 시 공격 시 30% 확률로 $(18+(skillLevel-1)*1)$% SP.DEF 무지 증가",
		describe_en = "In battles, there is 30% chance to increase $(18+(skillLevel-1)*1)$% SP.DEF ignorance when attacking",
		describe_id = "Dalam pertempuran, ada 30% peluang untuk meningkatkan $(18+(skillLevel-1)*1)$% ketidaktahuan SP.DEF saat menyerang",
		id = 52003,
		describe_es = "En las batallas, hay un 30% de posibilidades de aumentar $(18+(skillLevel-1)*1)$% ignorancia de SP.DEF al atacar.",
		describe_th = "ในการต่อสู้ มีโอกาส 30% ที่จะเพิ่มความไม่รู้ SP.DEF $(18+(skillLevel-1)*1)$% เมื่อทำการโจมตี"
	},
	[52004] = {
		describe_vn = "Nas quatro primeiras quatro grandes rodadas da batalha, o aumento de VEL e de DMG são cada um aumentados em $(16+(skillLevel-1)*2)$%, ao atacar um inimigo cujo HP acima de 50% causará dano extra $(15+(skillLevel-1)*1.5)$% (acumula durante a batalha no modo Solo ). \n#F10#\n#F40##L10# Imortal  Lenda: #L0# aumenta 5% P.ATK, SP.ATK e 5% de taxa crítica por 2 rodadas antes de cada ação, que pode ser acumulada 2 vezes; Este efeito será desencadeado continuamente na mesma grande rodada (habilidades extras podem ser desencadeadas, consulte o manual de batalha), aumentando 15% extras de P.ATK, SP.ATK e 15% taxa de crit para 2 rodadas, que não podem ser acumuladas.",
		describe_kr = "전투의 첫 4라운드에서는 SPD 및 DMG 부스트가 각각 $(16+(skillLevel-1)*2)$%씩 증가하며, HP가 50%를 초과하는 적을 공격하면 추가 $(15+(skillLevel-1)*1.5)$% 피해를 입힐 수 있습니다(솔로 모드에서는 전투 전반에 걸쳐 중첩됩니다). \n#F10#\n#F40##L10# 불멸의 전설: #L0# 각 행동 전 2라운드 동안 P.ATK, SP.ATK 및 치명타율 5%가 증가하며, 이는 2회 중첩 가능합니다. 이 효과는 동일한 큰 라운드 내에서 지속적으로 발생하며(추가 스킬은 발동될 수 있음, 전투 매뉴얼 참조) 2라운드 동안 P.ATK, SP.ATK 및 치명타율이 15% 증가하며 중첩될 수 없습니다.",
		describe_en = "In the first 4 big rounds of the battle, SPD and DMG boost are each increased by $(16+(skillLevel-1)*2)$%, when attacking enemy whose HP over 50% will cause extra $(15+(skillLevel-1)*1.5)$% damage(Stacks across the battle in Solo Mode). \n#F10#\n#F40##L10# Immortal  Legend: #L0# increase 5% P.ATK, SP.ATK and 5%  crit rate for 2 round before each action, which can be stacked 2 times; This effect will be triggered continuously within the same big round (extra skills can be triggered, see the battle manual), increase extra 15% P.ATK, SP.ATK and 15% crit rate for 2 rounds, which can not be stacked.",
		describe_id = "In the first 4 big rounds of the battle, SPD and DMG boost are each increased by $(16+(skillLevel-1)*2)$%, when attacking enemy whose HP over 50% will cause extra $(15+(skillLevel-1)*1.5)$% damage(Stacks across the battle in Solo Mode). \n#F10#\n#F40##L10# Immortal  Legend: #L0# increase 5% P.ATK, SP.ATK and 5%  crit rate for 2 round before each action, which can be stacked 2 times; This effect will be triggered continuously within the same big round (extra skills can be triggered, see the battle manual), increase extra 15% P.ATK, SP.ATK and 15% crit rate for 2 rounds, which can not be stacked.",
		id = 52004,
		describe_es = "In the first 4 big rounds of the battle, SPD and DMG boost are each increased by $(16+(skillLevel-1)*2)$%, when attacking enemy whose HP over 50% will cause extra $(15+(skillLevel-1)*1.5)$% damage(Stacks across the battle in Solo Mode). \n#F10#\n#F40##L10# Immortal  Legend: #L0# increase 5% P.ATK, SP.ATK and 5%  crit rate for 2 round before each action, which can be stacked 2 times; This effect will be triggered continuously within the same big round (extra skills can be triggered, see the battle manual), increase extra 15% P.ATK, SP.ATK and 15% crit rate for 2 rounds, which can not be stacked.",
		describe_th = "ใน 4 รอบใหญ่ แรกของการต่อสู้ SPD และ DMG บูสต์ จะเพิ่มขึ้น $(16+(skillLevel-1)*2)$% เมื่อ โจมตี ศัตรูซึ่งมี HP มากกว่า 50% จะสร้างความเสียหายเพิ่มเติม $(15+(skillLevel-1)*1.5)$% (สแต็คข้ามการต่อสู้ในโหมดโซโล) \n#F10#\n#F40##L10# อมตะ  ตำนาน: #L0# เพิ่ม 5% P.ATK, SP.ATK และ อัตราคริติคอล 5% สำหรับ 2 รอบ ก่อน แต่ละ การกระทำ ซึ่งสามารถ ซ้อนได้ 2 ครั้ง; เอฟเฟกต์นี้จะถูกกระตุ้นอย่างต่อเนื่องภายในรอบใหญ่เดียวกัน (สามารถเรียกใช้ทักษะพิเศษได้ โปรดดูคู่มือการต่อสู้) เพิ่ม P.ATK, SP.ATK พิเศษ 15% และอัตราคริติคอล 15% สำหรับ 2 รอบ ซึ่งไม่สามารถซ้อนกันได้"
	},
	[52005] = {
		describe_vn = "Nas batalhas, ao ser atacado, se o próprio HP for inferior a 35%, recupere imediatamente $(15+(skillLevel-1)*1.5)$% do HP máximo, pode ser acionado 3 vezes em uma batalha (acumula durante a batalha no modo Solo)\n#F10#\n #F40##L10#Efeito Imortal:#L0#Quando o HP for inferior a 5% pela primeira vez, recupere seus 60% de HP (Efeito Imortal ignora proibição de cura, efeito de redução de cura, quando Efeito Imortal tem múltiplos portadores, aciona apenas dois deles)",
		describe_kr = "전투 중 공격당할 때 자신의 HP가 35% 미만일 경우 즉시 자신의 최대 HP를 $(15+(skillLevel-1)*1.5)$%만큼 회복하고 전투에서 3번 발동 가능합니다(솔로 모드에서는 전투 전체에 걸쳐 중첩됩니다)\n#F10#\n #F40##L10#불멸 효과:#L0#처음 HP가 5% 미만일 때 HP 60% 회복(불멸 효과는 치유 금지 무시, 치유 감소 효과, 불멸 효과에 캐리어가 여러 개 있을 경우 2개만 발동)",
		describe_en = "In battles, when being attacked, if own HP is lower than 35%, immediately recover own $(15+(skillLevel-1)*1.5)$% max HP, can be trigger 3 times in a battle (Stacks across the battle in Solo Mode)\n#F10#\n#F40##L10#Immortal Effect:#L0#When HP first time lower than 5%, recover its 60% HP(Immortal effect ignore heal ban, heal reduce effect, when Immortal Effect have multiple carrier, only trigger two of them)",
		describe_id = "Dalam pertempuran, ketika diserang, jika HP milik sendiri kurang dari 35%, segera memulihkan $(15+(skillLevel-1)*1.5)$% HP maks miliknya, dapat dipicu 3 kali dalam pertempuran (Stacks di seluruh pertempuran dalam Mode Solo)\n#F10#\n #F40##L10#Efek Abadi:#L0#Ketika HP pertama kali lebih rendah dari 5%, pulihkan 60% HP-nya (Efek abadi abaikan pelarangan penyembuhan, efek pengurangan penyembuhan, ketika Efek Abadi memiliki banyak pembawa, hanya memicu dua di antaranya)",
		id = 52005,
		describe_es = "En las batallas, al ser atacado, si su HP es inferior al 35%, recupera inmediatamente su propio $(15+(skillLevel-1)*1.5)$% de HP máximo, se puede activar 3 veces en una batalla (se acumula a lo largo de la batalla en modo Solo)\n#F10#\n #F40##L10#Efecto inmortal:#L0#Cuando HP por primera vez es inferior al 5%, recupera su 60% de HP (el efecto inmortal ignora la prohibición de curación, reduce el efecto de curación, cuando el efecto inmortal tiene múltiples portadores, solo activa dos de ellos)",
		describe_th = "ในการต่อสู้ เมื่อถูกโจมตี หาก HP ของตัวเองต่ำกว่า 35% จะฟื้นฟู HP สูงสุดของตนเองทันที $(15+(skillLevel-1)*1.5)$% HP สูงสุด สามารถทริกเกอร์ได้ 3 ครั้งในการต่อสู้ (สแต็คข้ามการต่อสู้ในโหมดเดี่ยว)\n#F10#\n #F40##L10#เอฟเฟกต์อมตะ:#L0#เมื่อ HP ครั้งแรกต่ำกว่า 5% จะฟื้นฟู HP 60% (เอฟเฟกต์อมตะเพิกเฉยต่อการห้ามการรักษา ลดเอฟเฟกต์การรักษา เมื่อเอฟเฟกต์อมตะมีพาหะหลายตัว ทริกเกอร์เพียงสองตัวเท่านั้น)"
	},
	[52006] = {
		describe_vn = "Nas primeiras 2 rodadas das batalhas, recupere a própria $(90+(skillLevel-1)*15)$ Fúria antes da própria rodada, ignorando $(6+(skillLevel-1)*1.5)$% de redução de dano (acumula durante a batalha no modo Solo)",
		describe_kr = "전투의 첫 2라운드에서 자신의 회복 $(90+(skillLevel-1)*15)$ 자신의 라운드 전 분노, $(6+(skillLevel-1)*1.5)$% 피해 감소 무시(솔로 모드에서 전투 전반에 걸쳐 중첩)",
		describe_en = "At the first 2 rounds in battles, recover own $(90+(skillLevel-1)*15)$ Rage before own round, ignoring $(6+(skillLevel-1)*1.5)$% damage reduction (Stacks across the battle in Solo Mode)",
		describe_id = "Pada 2 ronde pertama pertempuran, pulihkan $(90+(skillLevel-1)*15)$ Kemarahan sebelum ronde sendiri, abaikan $(6+(skillLevel-1)*1.5)$% pengurangan kerusakan (Menumpuk di seluruh pertarungan dalam Mode Solo)",
		id = 52006,
		describe_es = "En las primeras 2 rondas de las batallas, recupera tu propia $(90+(skillLevel-1)*15)$ ira antes de tu propia ronda, ignorando $(6+(skillLevel-1)*1.5)$% de reducción de daño (se acumula a lo largo de la batalla en modo Solo)",
		describe_th = "ใน 2 รอบแรกของการต่อสู้ ฟื้นฟู $(90+(skillLevel-1)*15)$ ความเดือดดาลของตัวเองก่อนรอบของตัวเอง โดยไม่สนใจการลดความเสียหาย $(6+(skillLevel-1)*1.5)$% (สแต็คข้ามการต่อสู้ในโหมดเดี่ยว)"
	},
	[52007] = {
		describe_vn = "Nas batalhas, seu ataque reduz o efeito de cura do alvo com maior ATK (maior valor de P.ATK e SP.ATK) em $(40+(skillLevel-1)*2)$% e a taxa de recuperação de raiva em $(20+(skillLevel-1)*2)$% por 2 rodadas.",
		describe_kr = "전투 시 2라운드 동안 공격력이 가장 높은 대상(P.ATK 및 SP.ATK 값이 높음)의 치유 효과를 $(40+(skillLevel-1)*2)$%, 분노 회복 속도를 $(20+(skillLevel-1)*2)$% 감소시킵니다.",
		describe_en = "In battles, its attack reduces the healing effect of the target with the highest ATK (higher P.ATK and SP.ATK value) by $(40+(skillLevel-1)*2)$% and rage recovery rate by $(20+(skillLevel-1)*2)$% for 2 rounds.",
		describe_id = "Dalam pertempuran, serangannya mengurangi efek penyembuhan target dengan ATK tertinggi (nilai P.ATK dan SP.ATK lebih tinggi) sebesar $(40+(skillLevel-1)*2)$% dan tingkat pemulihan kemarahan sebesar $(20+(skillLevel-1)*2)$% selama 2 ronde.",
		id = 52007,
		describe_es = "En las batallas, su ataque reduce el efecto curativo del objetivo con el ATK más alto (mayor valor P.ATK y SP.ATK) en un $(40+(skillLevel-1)*2)$% y la tasa de recuperación de ira en un $(20+(skillLevel-1)*2)$% durante 2 rondas.",
		describe_th = "ในการต่อสู้ การโจมตีจะลดผลการรักษาของเป้าหมายที่มี ATK สูงสุด (ค่า P.ATK และ SP.ATK ที่สูงขึ้น) ลง $(40+(skillLevel-1)*2)$% และอัตราการฟื้นฟูความโกรธลง $(20+(skillLevel-1)*2)$% เป็นเวลา 2 รอบ"
	},
	[52008] = {
		describe_vn = "Nas batalhas, o ataque ativo do porta-aviões causa efeito de queimadura no alvo principal (distribuindo P.DMG de seu P.ATK de 80%, dura 3 rodadas, acumula 5 vezes mais), quando tem estado de queimadura inimigo no alcance de ataque, aumenta temporariamente $(12+(skillLevel-1)*1.5)$% Taxa crítica e $(8+(skillLevel-1)*1)$% Roubo de vida antes do ataque\n#F10# \n#F40#HP na primeira vez inferior a 40%, aumenta com 12% de bônus de DMG e 5% de taxa crítica, dura 3 rodadas",
		describe_kr = "전투에서 캐리어의 액티브 공격은 주 대상에게 화상 효과를 줍니다(P.ATK의 80% P.DMG 처리, 3라운드 지속, 최대 5회 중첩). 공격 범위에 화상 상태의 적이 있으면 일시적으로 자체 증가 $(12+(skillLevel-1)*1.5)$% 치명타율 및 $(8+(skillLevel-1)*1)$% 공격 전 라이프 스틸\n#F10# \n#F40#처음 HP가 40% 미만, 12% DMG 보너스 및 5% 치명타율로 자체 증가, 3라운드 지속",
		describe_en = "In battles, carrier's active attack deals burn effect to the main target(dealing P.DMG of its 80% P.ATK, last for 3 rounds, stack up 5 times most), when have burn state enemy in attack range, temporary increase itself $(12+(skillLevel-1)*1.5)$% Crit rate and $(8+(skillLevel-1)*1)$% Life Steal before attack\n#F10# \n#F40#First time HP lower than 40%, increase itself with 12% DMG bonus and 5% crit rate, last for 3 rounds",
		describe_id = "Dalam pertempuran, serangan aktif pembawa menimbulkan efek luka bakar ke target utama (menimbulkan P.DMG dari 80% P.ATK-nya, bertahan selama 3 ronde, ditumpuk 5 kali paling banyak), ketika musuh dalam keadaan terbakar dalam jangkauan serangan, peningkatan sementara itu sendiri $(12+(skillLevel-1)*1.5)$% Crit rate dan $(8+(skillLevel-1)*1)$% Life Steal sebelum menyerang\n#F10# \n#F40#Pertama kali HP di bawah 40%, meningkat dengan bonus DMG 12% dan 5% crit rate, bertahan selama 3 ronde",
		id = 52008,
		describe_es = "En las batallas, el ataque activo del portaaviones causa un efecto de quemadura al objetivo principal (causando P.DMG de su 80% P.ATK, dura 3 rondas, se acumula 5 veces más), cuando tiene al enemigo en estado de quemadura en el rango de ataque, aumenta temporalmente. $(12+(skillLevel-1)*1.5)$% Tasa de crítico y $(8+(skillLevel-1)*1)$% Robo de vida antes del ataque\n#F10# \n#F40#La primera vez HP es inferior al 40%, aumenta con una bonificación de DAÑO del 12% y una tasa de crítico del 5%, dura 3 rondas",
		describe_th = "ในการรบ การโจมตีที่ใช้งานของเรือบรรทุกจะสร้างเอฟเฟกต์เผาไหม้ไปยังเป้าหมายหลัก (สร้างความเสียหาย P.DMG ของ P.ATK 80% เป็นเวลา 3 รอบ ซ้อนทับได้มากที่สุด 5 เท่า) เมื่อศัตรูติดสถานะเผาไหม้ในระยะการโจมตี จะเพิ่มตัวเองชั่วคราว $(12+(skillLevel-1)*1.5)$% อัตราคริติคอล และ $(8+(skillLevel-1)*1)$% ดูดเลือดก่อนโจมตี\n#F10# \n#F40#HP ครั้งแรกต่ำกว่า 40% เพิ่มตัวเองด้วยโบนัส DMG 12% และอัตราคริติคอล 5% ใช้ได้ 3 รอบ"
	},
	[52009] = {
		describe_vn = "Nas batalhas, ao receber um ataque Ultimate, ele recupera instantaneamente HP igual a $(12+(skillLevel-1)*1.5)$% no máximo. HP (o excesso de HP será convertido em escudo) e $(60+(skillLevel-1)*15)$ Raiva, este efeito só pode ser acionado 3 vezes durante toda a batalha (acumula durante a batalha no modo Solo). Quando o transportador aciona 4 efeitos de movimento especial (assistência, contra-ataque, o convidado, eu primeiro), é capaz de obter 1 efeito básico de item retido adicional (acionar apenas uma vez).",
		describe_kr = "전투에서 궁극기 공격을 받으면 최대 $(12+(skillLevel-1)*1.5)$%만큼 HP를 즉시 회복합니다. HP(초과 HP는 보호막으로 전환됨) 및 $(60+(skillLevel-1)*15)$ 분노, 이 효과는 전체 전투에서 3번만 발동할 수 있습니다(솔로 모드에서는 전투 전체에 걸쳐 중첩됩니다). 캐리어가 4가지 필살기 효과(어시스트, 반격, 초대자, 나 먼저) 발동 시, 소지 아이템 기본 효과 1개를 추가로 획득할 수 있습니다(1회만 발동).",
		describe_en = "In battles, when it receives a Ultimate attack, it instantly recovers HP equals to $(12+(skillLevel-1)*1.5)$% max. HP (excess HP will convert into shield) and $(60+(skillLevel-1)*15)$ Anger, this effect can only trigger 3 times for whole battle (Stacks across the battle in Solo Mode). When carrier trigger 4 special move effect(assist,counter attack,the invited, me first ), able to get 1 additional held item basic effect(only trigger once).",
		describe_id = "Dalam pertempuran, ketika menerima serangan Ultimate, ia langsung memulihkan HP setara dengan $(12+(skillLevel-1)*1.5)$% maks. HP (kelebihan HP akan diubah menjadi perisai) dan $(60+(skillLevel-1)*15)$ Anger, efek ini hanya dapat terpicu 3 kali dalam keseluruhan pertarungan (Stacks di seluruh pertarungan dalam Mode Solo). Ketika operator memicu 4 efek gerakan khusus (bantuan, serangan balik, undangan, saya duluan), dapat memperoleh 1 efek dasar item tambahan yang ditahan (hanya memicu satu kali).",
		id = 52009,
		describe_es = "En las batallas, cuando recibe un ataque definitivo, recupera instantáneamente HP equivalente al $(12+(skillLevel-1)*1.5)$% máximo. HP (el exceso de HP se convertirá en escudo) y $(60+(skillLevel-1)*15)$ Ira, este efecto solo puede activarse 3 veces durante toda la batalla (se acumula a lo largo de la batalla en modo Solo). Cuando el portador activa 4 efectos de movimiento especiales (asistencia, contraataque, el invitado, yo primero), puedo obtener 1 efecto básico adicional del elemento retenido (solo se activa una vez).",
		describe_th = "ในการต่อสู้ เมื่อได้รับการโจมตีขั้นสุดยอด จะฟื้นฟู HP ทันทีเท่ากับสูงสุด $(12+(skillLevel-1)*1.5)$% HP (HP ส่วนเกินจะแปลงเป็นโล่) และ $(60+(skillLevel-1)*15)$ ความโกรธ เอฟเฟกต์นี้สามารถทริกเกอร์ได้ 3 ครั้งเท่านั้นตลอดการต่อสู้ (สแต็คข้ามการต่อสู้ในโหมดเดี่ยว) เมื่อผู้ให้บริการเรียกใช้เอฟเฟกต์การเคลื่อนไหวพิเศษ 4 แบบ (ช่วยเหลือ, โจมตีตอบโต้, ผู้ถูกเชิญ, ฉันก่อน) สามารถรับเอฟเฟกต์พื้นฐานของไอเท็มที่ถือเพิ่มเติมได้ 1 รายการ (ทริกเกอร์เพียงครั้งเดียว)"
	},
	[52010] = {
		describe_vn = "Nas batalhas, o portador de item aumenta temporariamente a redução de $(20+(skillLevel-1)*2)$% de DMG Ult ao receber os primeiros 4 danos de Ulti Skill\n#F10# \n#F40##L10#Efeito de ressonância: #L0#Nas primeiras 2 rodadas, quando ter 2 ou mais aliados do mesmo tipo do portador do item, reduz 20% do dano efetivo do tipo sofrido pelo portador do item, aliados com o mesmo tipo ganham 10% de redução de DMG Ult (ao ter vários portadores de ressonância, apenas um será efetivo)",
		describe_kr = "전투에서 아이템 캐리어는 처음 4개의 울티 스킬 데미지를 받을 때 일시적으로 $(20+(skillLevel-1)*2)$%의 Ult DMG 감소를 증가시킵니다\n#F10# \n#F40##L10#공명 효과: #L0#처음 2라운드에서, 아이템 캐리어와 같은 유형의 아군이 2명 이상인 경우, 아이템 캐리어가 받는 유형 유효 피해의 20% 감소, 같은 유형의 아군은 궁극기 데미지 10% 감소(공명 캐리어가 여러 개일 경우 하나만 유효)",
		describe_en = "In batles, item carrier temporary increase itself of $(20+(skillLevel-1)*2)$% Ult DMG reduction when receiving the first 4 Ulti Skill damage\n#F10# \n#F40##L10#Resonance effect: #L0#At the first 2 rounds, when having 2 or above allies are same type with item carrier, reduce 20% of type effective damage taken by item carrier, allies with same type gains 10% Ult DMG reduction(When having multiple Resonance carrier, only one will be effective)",
		describe_id = "Dalam pertarungan, pembawa item untuk sementara meningkatkan $(20+(skillLevel-1)*2)$% pengurangan Ult DMG ketika menerima 4 damage Skill Ulti pertama\n#F10# \n#F40##L10#Efek resonansi: #L0#Pada 2 ronde pertama, ketika memiliki 2 sekutu atau lebih yang bertipe sama dengan pembawa item, mengurangi 20% jenis kerusakan efektif yang diterima oleh pembawa item, sekutu dengan tipe yang sama memperoleh 10% pengurangan Ult DMG (Saat memiliki beberapa pembawa Resonansi, hanya satu yang akan efektif)",
		id = 52010,
		describe_es = "En las batallas, el portador de objetos aumenta temporalmente en un $(20+(skillLevel-1)*2)$% de reducción de daño definitivo al recibir los primeros 4 daños de habilidad definitiva\n#F10# \n#F40##L10#Efecto de resonancia: #L0#En las primeras 2 rondas, cuando tener 2 o más aliados del mismo tipo que el portador del artículo, reduce el 20 % del tipo de daño efectivo recibido por el portador del artículo, los aliados con el mismo tipo obtienen una reducción del 10 % de DAÑO definitivo (cuando se tienen múltiples portadores de resonancia, solo uno será efectivo)",
		describe_th = "ในการต่อสู้ ผู้ขนส่งไอเท็มจะเพิ่มขึ้นชั่วคราว $(20+(skillLevel-1)*2)$% การลดความเสียหายของ Ult DMG เมื่อได้รับความเสียหายจากทักษะ Ulti 4 ครั้งแรก\n#F10# \n#F40##L10#เอฟเฟกต์เสียงสะท้อน: #L0#ใน 2 รอบแรก เมื่อ การมีพันธมิตรตั้งแต่ 2 คนขึ้นไปเป็นประเภทเดียวกันกับผู้ขนส่งไอเทม ลดความเสียหายที่มีประสิทธิภาพประเภทที่ได้รับจากผู้ขนส่งไอเทม 20% พันธมิตรประเภทเดียวกันจะได้รับการลดความเสียหาย Ult DMG 10% (เมื่อมีพาหะ Resonance หลายตัว จะมีเพียงตัวเดียวเท่านั้นที่จะมีผล)"
	},
	[52011] = {
		describe_vn = "Nas batalhas, aumente $(12+(skillLevel-1)*1)$% SPD e $(12+(skillLevel-1)*1)$% Taxa de controle, e o bônus será liberado após liberar uma grande habilidade pela primeira vez",
