	[61001] = {
		describe_vn = "Nas batalhas, toda vez que um Pokémon é morto (amigos e inimigos), aumente 5% de P.ATK e SP.ATK para os Pokémon aliados restantes (até 4 vezes)",
		describe_kr = "전투에서 포켓몬이 죽을 때마다(친구와 적 모두), 남은 아군 포켓몬의 P.ATK 및 SP.ATK가 5% 증가합니다(최대 4회).",
		describe_en = "In battles, every time a Pokemon gets killed (both friends and enemies), increase 5% P.ATK and SP.ATK to remaining allied Pokemon (up to 4 times)",
		describe_id = "Dalam pertempuran, setiap kali Pokemon terbunuh (baik teman maupun musuh), tingkatkan 5% P.ATK dan SP.ATK ke Pokemon sekutu yang tersisa (hingga 4 kali lipat)",
		id = 61001,
		describe_es = "En las batallas, cada vez que matan a un Pokémon (tanto amigos como enemigos), aumenta un 5% P.ATK y SP.ATK a los Pokémon aliados restantes (hasta 4 veces).",
		describe_th = "ในการต่อสู้ ทุกครั้งที่โปเกมอนถูกฆ่า (ทั้งเพื่อนและศัตรู) เพิ่ม P.ATK และ SP.ATK 5% ให้กับโปเกมอนฝ่ายเดียวกันที่เหลืออยู่ (สูงสุด 4 ครั้ง)"
	},
