	[61003] = {
		describe_vn = "Nas batalhas, quando o HP de todos os Pokémon aliados for inferior a 50%, inflija um escudo compartilhado a todos os nossos Pokémon (igual a 20% do HP máximo do Pokémon com o HP mais alto). Pode ser acionado apenas uma vez em uma batalha",
		describe_kr = "전투에서 모든 아군 포켓몬의 HP가 50% 미만일 때 모든 포켓몬에게 공유 쉴드를 부여합니다(HP가 가장 높은 포켓몬의 최대 HP의 20%에 해당). 전투 중 한 번만 발동 가능",
		describe_en = "In battles, when all allied Pokemon's HP is lower than 50%, inflict a shared shield to all our Pokemon (equals to 20% max HP of the Pokemon with the highest HP). Can be triggered only once in a battle",
		describe_id = "Dalam pertempuran, ketika HP semua Pokemon sekutu kurang dari 50%, berikan perisai bersama ke semua Pokemon kita (setara dengan 20% HP maksimal Pokemon dengan HP tertinggi). Hanya dapat dipicu sekali dalam pertempuran",
		id = 61003,
		describe_es = "En las batallas, cuando el HP de todos los Pokémon aliados es inferior al 50%, inflige un escudo compartido a todos nuestros Pokémon (equivale al 20% del HP máximo del Pokémon con mayor HP). Solo se puede activar una vez en una batalla.",
		describe_th = "ในการต่อสู้ เมื่อ HP ของโปเกมอนพันธมิตรทั้งหมดต่ำกว่า 50% สร้างเกราะป้องกันให้กับโปเกมอนของเราทั้งหมด (เท่ากับ 20% HP สูงสุดของโปเกมอนที่มี HP สูงสุด) สามารถเปิดใช้งานได้เพียงครั้งเดียวในการต่อสู้"
	},
