	[61005] = {
		describe_vn = "Nas duas primeiras rodadas de batalhas, reduza o P.ATK/SP.ATK de todos os Pokémon inimigos em 10% e o SPD em 15%",
		describe_kr = "첫 2번의 전투에서 모든 적 포켓몬의 P.ATK/SP.ATK가 10%, SPD가 15% 감소합니다.",
		describe_en = "At the first two rounds of battles, reduce all enemy Pokemon's P.ATK/SP.ATK by 10% and SPD by 15%",
