	[66034] = {
		describe_vn = "Ao lançar Ult Skill, tem 8% de chance de causar efeito de controle aleatório (Atordoamento, Silêncio, Paralisia, Sono) aos alvos no alcance de ataque. Se a Ult Skill não for lançada na grande rodada, aumente a taxa de controle em 2% (acumulável), remova o impulso após lançar a Ult Skill",
		describe_kr = "궁극 스킬 시전 시, 공격 범위 내 대상에게 8% 확률로 무작위 제어 효과(스턴, 침묵, 마비, 수면)를 부여합니다. 빅 라운드에서 얼트 스킬이 시전되지 않은 경우 제어율 2% 증가(중첩 가능), 얼트 스킬 시전 후 부스트 제거",
		describe_en = "When casting Ult Skill, having a 8% chance to deal random control effect (Stun, Silent, Paralysis, Sleep) to targets in attack range. If the Ult Skill is not cast in the big round, boost 2% control rate (stackable), remove boost after casting Ult Skill",
		describe_id = "Saat mengeluarkan Skill Ult, mempunyai peluang 8% untuk memberikan efek kontrol acak (Stun, Silent, Paralysis, Sleep) ke target dalam jangkauan serangan. Jika Skill Ult tidak digunakan dalam ronde besar, boost 2% control rate (dapat ditumpuk), hilangkan boost setelah mengeluarkan Skill Ult",
		id = 66034,
		describe_es = "Al lanzar la habilidad definitiva, tienes un 8 % de probabilidad de aplicar un efecto de control aleatorio (aturdimiento, silencio, parálisis, sueño) a los objetivos en el rango de ataque. Si la habilidad definitiva no se lanza en la ronda grande, aumenta la tasa de control en un 2 % (apilable), elimina el impulso después de lanzar la habilidad definitiva",
		describe_th = "เมื่อร่ายสกิล Ult มีโอกาส 8% ที่จะสร้างเอฟเฟกต์การควบคุมแบบสุ่ม (Stun, Silent, Paralysis, Sleep) ไปยังเป้าหมายที่อยู่ในระยะการโจมตี หากไม่ได้ใช้ทักษะอัลท์ในรอบใหญ่ เพิ่มอัตราการควบคุม 2% (ซ้อนกันได้) ลบบูสต์ออกหลังจากใช้ทักษะอัลท์"
	},
	[66035] = {
		describe_vn = "Ao lançar Ult Skill, tem 10% de chance (25% de chance do alvo principal) de aplicar efeito de controle aleatório (Atordoamento, Silêncio, Paralisia, Sono) aos alvos no alcance de ataque. Se a Ult Skill não for lançada na grande rodada, aumente a taxa de controle em 3% (acumulável), remova o impulso após lançar a Ult Skill",
		describe_kr = "궁극기 스킬 시전 시 10% 확률(주 대상에게는 25% 확률)로 공격 범위 내 대상에게 무작위 제어 효과(스턴, 침묵, 마비, 수면)가 적용됩니다. 빅 라운드에서 얼트 스킬이 시전되지 않은 경우 제어율 3% 증가(중첩 가능), 얼트 스킬 시전 후 부스트 제거",
		describe_en = "When casting Ult Skill, having a 10% chance (25% chance to main target) to apply random control effect (Stun, Silent, Paralysis, Sleep) to targets in attack range. If the Ult Skill is not cast in the big round, boost 3% control rate (stackable), remove boost after casting Ult Skill",
		describe_id = "Saat mengeluarkan Skill Ult, mempunyai 10% peluang (25% peluang pada target utama) untuk menerapkan efek kontrol acak (Stun, Silent, Paralysis, Sleep) pada target dalam jangkauan serangan. Jika Skill Ult tidak digunakan dalam putaran besar, tingkatkan kontrol 3% (dapat ditumpuk), hilangkan boost setelah mengeluarkan Skill Ult",
		id = 66035,
		describe_es = "Al lanzar la habilidad definitiva, tienes un 10 % de probabilidad (25 % de probabilidad del objetivo principal) de aplicar un efecto de control aleatorio (aturdimiento, silencio, parálisis, sueño) a los objetivos en el rango de ataque. Si la habilidad definitiva no se lanza en la ronda grande, aumenta la tasa de control en un 3% (apilable), elimina el impulso después de lanzar la habilidad definitiva",
		describe_th = "เมื่อร่ายสกิล Ult มีโอกาส 10% (โอกาส 25% ไปยังเป้าหมายหลัก) เพื่อใช้เอฟเฟกต์การควบคุมแบบสุ่ม (Stun, Silent, Paralysis, Sleep) กับเป้าหมายที่อยู่ในระยะการโจมตี หากไม่ได้ใช้ทักษะอัลท์ในรอบใหญ่ เพิ่มอัตราการควบคุม 3% (ซ้อนกันได้) ลบบูสต์ออกหลังจากใช้ทักษะอัลท์"
	},
