	[80083] = {
		describe_vn = "[Fire Strength]: Cada vez que o lançador causa dano, reduz o SP.ATK e P.ATK do inimigo em 8%, até 10% do próprio SP.ATK e P.ATK ([Evil Strength] melhora ainda mais os efeitos)",
		describe_kr = "[Fire Strength]: 시전자가 피해를 입힐 때마다 적의 SP.ATK 및 P.ATK가 8% 감소하고, 자신의 SP.ATK 및 P.ATK가 최대 10% 감소합니다([Evil Strength] 효과가 더욱 향상됩니다).",
		describe_en = "[Fire Strength]: Each time the caster deals damage, reduces the enemy's SP.ATK and P.ATK by 8%, up to 10% of own SP.ATK and P.ATK ([Evil Strength] further improves the effects)",
		describe_id = "[Fire Strength]: Setiap kali pengguna memberikan damage, mengurangi SP.ATK dan P.ATK musuh sebesar 8%, hingga 10% dari SP.ATK dan P.ATK milik sendiri ([Evil Strength] meningkatkan efek lebih lanjut)",
		id = 80083,
		describe_es = "[Fire Strength]: Cada vez que el lanzador inflige daño, reduce el SP.ATK y P.ATK del enemigo en un 8%, hasta un 10% del propio SP.ATK y P.ATK ([Evil Strength] mejora aún más los efectos)",
		describe_th = "[Fire Strength]: ทุกครั้งที่ผู้ร่ายสร้างความเสียหาย จะลด SP.ATK และ P.ATK ของศัตรูลง 8% สูงสุด 10% ของ SP.ATK และ P.ATK ของตัวเอง ([Evil Strength] ปรับปรุงเอฟเฟกต์เพิ่มเติม)"
	},
