	[210311] = {
		simDesc_vn = "Giratina dá um tapa no chão para atacar um único inimigo com Ominous Wind, causando P.DMG e aumentando sua própria imunidade a danos. Ganha Sombra Fantasma",
		describe_es = "Giratina golpea el suelo para atacar a un solo enemigo con Ominous Wind, causando (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#y aumentando su propio SP.DEF y P.DEF. en un 50% durante 2 rondas. Gana 1 punto de Sombra Fantasma después de este ataque.",
		simDesc_th = "Giratina ตบพื้นเพื่อโจมตีศัตรูเดี่ยวด้วย Ominous Wind สร้าง P.DMG และเพิ่มภูมิคุ้มกันความเสียหายของตัวเอง ได้รับ Ghost Shadow",
		describe_kr = "기라티나가 불길한 바람으로 적 1명을 내리쳐 공격하고 (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B# 자신의 SP.DEF와 P.DEF를 증가시킵니다. 2라운드 동안 50% 감소합니다. 이 공격 후 유령 그림자 1포인트를 얻습니다.",
		simDesc_kr = "기라티나가 불길한 바람으로 단일 적에게 땅을 내리쳐 P.DMG를 입히고 자신의 피해 면역을 증가시킵니다. 유령 그림자 획득",
		describe_en = "Giratina slaps the ground to attack a single enemy with Ominous Wind, dealing (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#and increasing own SP.DEF and P.DEF by 50% for 2 rounds. Gains 1 point of Ghost Shadow after this attack",
		describe_th = "กิราติน่าตบพื้นเพื่อโจมตีศัตรูตัวเดียวด้วยลมร้าย สร้าง (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#และเพิ่ม SP.DEF และ P.DEF ของตัวเอง 50% เป็นเวลา 2 รอบ ได้รับ Ghost Shadow 1 แต้มหลังการโจมตีครั้งนี้",
		simDesc_id = "Giratina menampar tanah untuk menyerang satu musuh dengan Ominous Wind, menimbulkan P.DMG dan meningkatkan Imunitas Kerusakannya sendiri. Mendapatkan Bayangan Hantu",
		describe_vn = "Giratina dá um tapa no chão para atacar um único inimigo com Ominous Wind, distribuindo (#C0xE69900#100% P.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#P.DMG#C0x5B545B#e aumentando seu próprio SP.DEF e P.DEF em 50% por 2 rodadas. Ganha 1 ponto de Sombra Fantasma após este ataque",
