	[220041] = {
		zawakeEffectDesc_es = "Hoopa golpea a un solo enemigo con la mano fantasma, infligiendo (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aumenta el propio SP.ATK en un 15% y SP.DEF Ignorar en un 25% durante 3 rondas.",
		zawakeEffectDesc_vn = "Hoopa dá um soco em um único inimigo com a mão fantasma, infligindo (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aumenta o SP.ATK próprio em 15% e o SP.DEF Ignorar em 25% por 3 rodadas.",
		describe_th = "ฮูปาชกศัตรูหนึ่งตัวด้วยมือผี สร้างความเสียหาย (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# เพิ่ม SP.ATK ของตัวเอง 15% และ SP.DEF เพิกเฉย 20% เป็นเวลา 2 รอบ",
		zawakeEffectDesc_kr = "후파가 유령손으로 적 하나를 때려 (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 3라운드 동안 자신의 SP.ATK가 15% 증가하고 SP.DEF 무시가 25% 증가합니다.",
		zawakeEffectDesc_th = "ฮูปาชกศัตรูหนึ่งตัวด้วยมือผี สร้างความเสียหาย (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# เพิ่ม SP.ATK ของตัวเอง 15% และ SP.DEF เพิกเฉย 25% เป็นเวลา 3 รอบ",
		describe_en = "Hoopa punches a single enemy with the ghost hand, inflicting (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Increases own SP.ATK by 15% and SP.DEF Ignore by 20% for 2 rounds.",
		describe_es = "Hoopa golpea a un solo enemigo con la mano fantasma, infligiendo (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aumenta el propio SP.ATK en un 15% y SP.DEF Ignorar en un 20% durante 2 rondas.",
		zawakeSimpleDesc_en = "increases its own Sp.ATK by 15% and Sp.DEF Ignore by 25% for 2 rounds\n#F20#\n#F40##C0x5c9970#→increases its own SP.ATK by 15% and SP.DEF Ignore by 25% for 3 rounds",
		describe_vn = "Hoopa dá um soco em um único inimigo com a mão fantasma, infligindo (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Aumenta o SP.ATK próprio em 15% e o SP.DEF Ignorar em 20% por 2 rodadas.",
		zawakeEffectDesc_en = "Hoopa punches a single enemy with the ghost hand, inflicting (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Increases own SP.ATK by 15% and SP.DEF Ignore by 25% for 3 rounds.",
		zawakeSimpleDesc_vn = "aumenta seu próprio Sp.ATK em 15% e Sp.DEF Ignore em 25% por 2 rodadas\n#F20#\n#F40##C0x5c9970#→aumenta seu próprio SP.ATK em 15% e SP.DEF Ignore em 25 % por 3 rodadas",
		zawakeSimpleDesc_id = "meningkatkan Sp.ATK miliknya sebesar 15% dan Sp.DEF Ignore sebesar 25% selama 2 ronde\n#F20#\n#F40##C0x5c9970#→meningkatkan SP.ATK miliknya sebesar 15% dan SP.DEF Ignore sebesar 25 % untuk 3 putaran",
		zawakeSimpleDesc_es = "aumenta su propio Sp.ATK en un 15% y Sp.DEF Ignorar en un 25% durante 2 rondas\n#F20#\n#F40##C0x5c9970#→aumenta su propio SP.ATK en un 15% y SP.DEF Ignorar en 25 % para 3 rondas",
		describe_id = "Hoopa meninju satu musuh dengan tangan hantu, menimbulkan (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Meningkatkan SP.ATK sendiri sebesar 15% dan SP.DEF Ignore sebesar 20% selama 2 putaran.",
		zawakeSimpleDesc_kr = "2라운드 동안 자신의 Sp.ATK가 15% 증가하고 Sp.DEF 무시가 25% 증가\n#F20#\n#F40##C0x5c9970#→자신의 SP.ATK가 15% 증가하고 SP.DEF 무시가 25 증가합니다. 3라운드 동안 %",
		zawakeEffectDesc_id = "Hoopa meninju satu musuh dengan tangan hantu, menimbulkan (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#. Meningkatkan SP.ATK sendiri sebesar 15% dan SP.DEF Ignore sebesar 25% selama 3 putaran.",
		describe_kr = "후파가 유령손으로 적 하나를 때려 (#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 2라운드 동안 자신의 SP.ATK가 15% 증가하고 SP.DEF 무시가 20% 증가합니다.",
		zawakeSimpleDesc_th = "เพิ่ม Sp.ATK ของตัวเอง 15% และ Sp.DEF เพิกเฉย 25% เป็นเวลา 2 รอบ\n#F20#\n#F40##C0x5c9970#→เพิ่ม SP.ATK ของตัวเอง 15% และ SP.DEF เพิกเฉย 25 % เป็นเวลา 3 รอบ",
		id = 220041
	},
	[220042] = {
		zawakeEffectDesc_es = "0",
		zawakeEffectDesc_vn = "0",
		describe_th = "Hoopa ปล่อย Aura Sphere อันชั่วร้ายใส่ศัตรูตัวเดียวด้วยแหวนทองคำของมัน สร้างความเสียหาย (#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# และทำให้ศัตรูแนวหน้าได้รับความอ่อนแอ 25% และลดการรักษา 20% เป็นเวลา 3 รอบ",
		zawakeEffectDesc_kr = "0",
		zawakeEffectDesc_th = "0",
		describe_en = "Hoopa launches an evil Aura Sphere to a single enemy with its Golden Rings. Inflicts (#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#, and causes front-line enemies to suffer 25% Vulnerability and 20% Healing Reduction for 3 rounds.",
		describe_es = "Hoopa lanza una malvada Aura Sphere a un solo enemigo con sus Anillos Dorados. Inflige (#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# y hace que los enemigos de primera línea sufran un 25% de vulnerabilidad y un 20% de reducción de curación durante 3 rondas.",
		zawakeSimpleDesc_en = "0",
		describe_vn = "Hoopa lança uma Esfera de Aura maligna contra um único inimigo com seus Anéis de Ouro. Inflige (#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B# e faz com que os inimigos da linha de frente sofram 25% de vulnerabilidade e 20% de redução de cura por 3 rodadas.",
		zawakeEffectDesc_en = "0",
		zawakeSimpleDesc_vn = "0",
		zawakeSimpleDesc_id = "0",
		zawakeSimpleDesc_es = "0",
		describe_id = "Hoopa meluncurkan Aura Sphere jahat ke satu musuh dengan Cincin Emasnya. Menimbulkan (#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#, dan menyebabkan musuh di garis depan menderita 25% Kerentanan dan 20% Pengurangan Penyembuhan selama 3 ronde.",
		zawakeSimpleDesc_kr = "0",
		zawakeEffectDesc_id = "0",
		describe_kr = "후파는 황금 반지를 이용해 적 한 명에게 사악한 오라 스피어를 발사합니다. (#C0x3D8A99#180% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$)#C0xF13B54#SP.DMG#C0x5B545B#를 입히고, 최전선 적에게 3라운드 동안 25% 취약성과 20% 치유 감소를 유발합니다.",
		zawakeSimpleDesc_th = "0",
		id = 220042
	},
	[220043] = {
		describe_th = "มือผีทั้ง 6 ของ Hoopa เดินทางผ่านอวกาศด้วยความช่วยเหลือของ Golden Rings เพื่อโจมตีศัตรูแนวหน้า ลดการลดความเสียหายอย่างถาวร 15% (ซ้อนทับได้ ไม่สามารถลบล้างได้) เป้าหมายหลักได้รับความเสียหาย#C0x3D8A99#420% SP.ATK#C0x5B545B#(#C0x3D8A99#140% SP.ATK#C0x5B545B#สำหรับเป้าหมายแนวหน้าที่เหลือ)+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#แทน . เป้าหมายหลักจะอยู่ในหลุมจนกว่าฮูปาจะเคลื่อนที่ครั้งต่อไปเสร็จ บันทึก DMG ที่ทำกับศัตรูทั้งหมดตลอดการเข้าพัก เมื่อเป้าหมายออกจากหลุม ถ้า Hoopa ยังไม่หมดสติ จะสร้าง True DMG เท่ากับ 50% ของจำนวน DMG ที่บันทึกไว้ และ 100% P.ATK\n#F20#\n#F40##L10#เทเลพอร์ต:#L0#เอฟเฟกต์การควบคุม ไม่สามารถลบล้างได้ ไม่สามารถโจมตีหรือถูกโจมตีในช่วงเวลาดังกล่าวได้ แต่ฮูปายังสามารถโจมตีเป้าหมายได้",
		zawakeEffectDesc_vn = "0",
		simDesc_es = "Las 6 manos fantasmales de Hoopa viajan por el espacio con la ayuda de anillos dorados para atacar a los enemigos de primera línea. Reduce permanentemente su reducción de daño. Mantiene al objetivo principal en el agujero antes de teletransportarlo de regreso para lanzar Dimensional Strike.",
		describe_es = "Las 6 manos fantasmales de Hoopa viajan por el espacio con la ayuda de anillos dorados para atacar a los enemigos de primera línea. Reduce permanentemente su reducción de daño en un 15 % (apilable, no se puede disipar). El objetivo principal sufre#C0x3D8A99#420% SP.ATK#C0x5B545B#(#C0x3D8A99#140% SP.ATK#C0x5B545B#para el resto de objetivos de primera línea)+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#en su lugar . El objetivo principal permanece en el hoyo hasta que Hoopa finaliza su siguiente movimiento. Registros de DMG infligido a todos los enemigos durante la estancia. Cuando el objetivo sale del agujero, si Hoopa no se ha desmayado, inflige daño verdadero equivalente al 50 % de la cantidad de daño récord y 100 % P.ATK\n#F20#\n#F40##L10#Teletransporte:#L0#Efecto de control, no se puede disipar, no se puede atacar ni ser atacado durante el período, pero Hoopa aún puede atacar al objetivo.",
		zawakeEffectDesc_th = "0",
		starEffectDesc_id = "Peningkatan efek: Serangan Hyperspace menyebabkan True DMG tambahan sebesar 30% dari Max HP target",
		starEffectDesc_es = "Aumento del efecto: los ataques hiperespaciales causan daño verdadero adicional equivalente al 30 % del HP máximo del objetivo.",
		zawakeSimpleDesc_en = "0",
		describe_vn = "As 6 mãos fantasmas de Hoopa viajam pelo espaço com a ajuda de anéis de ouro para atacar os inimigos da linha de frente. Reduz permanentemente a redução de DMG em 15% (acumulável, não pode ser dissipado). O alvo principal sofre#C0x3D8A99#420% SP.ATK#C0x5B545B#(#C0x3D8A99#140% SP.ATK#C0x5B545B#para o resto dos alvos da linha de frente)+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#em vez disso . O alvo principal permanece no buraco até Hoopa terminar seu próximo movimento. Registra DMG causado a todos os inimigos durante a estadia. Quando o alvo sai do buraco, se Hoopa não tiver desmaiado, inflige True DMG igual a 50% da quantidade recorde de DMG e 100% P.ATK\n#F20#\n#F40##L10#Teleporte:#L0#Efeito de controle, não pode ser dissipado, não pode atacar ou ser atacado durante o período, mas Hoopa ainda pode atacar o alvo.",
		starEffectDesc_th = "เอฟเฟกต์เสริม: การโจมตีไฮเปอร์สเปซทำให้เกิด True DMG เพิ่มเติมเท่ากับ 30% ของ HP สูงสุดของเป้าหมาย",
		starEffectDesc_vn = "Aumento de efeito: Ataques no hiperespaço causam Dano Verdadeiro adicional igual a 30% do HP máximo do alvo",
		zawakeEffectDesc_kr = "0",
		describe_en = "Hoopa's 6 ghost hands travel through space with the help of Golden Rings to attack front-line enemies. Permanently reduces their DMG Reduction by 15% (Stackable, cannot be dispelled). The main target suffers#C0x3D8A99#420% SP.ATK#C0x5B545B#(#C0x3D8A99#140% SP.ATK#C0x5B545B#for the rest of front-line targets)+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#instead. The main target stays in the hole until Hoopa finishes its next move. Records DMG dealt to all enemies over the stay. When the target gets out of the hole, if Hoopa hasn't fainted, inflicts True DMG equal to 50% of record DMG amount and 100% P.ATK\n#F20#\n#F40##L10#Teleport:#L0#Control effect, cannot be dispelled, cannot attack or be attacked during the period, but Hoopa can still attack the target.",
		zawakeEffectDesc_id = "0",
		describe_id = "6 tangan hantu Hoopa melakukan perjalanan melintasi ruang angkasa dengan bantuan Cincin Emas untuk menyerang musuh garis depan. Mengurangi Pengurangan DMG sebesar 15% secara permanen (Dapat ditumpuk, tidak dapat dihilangkan). Target utama menderita#C0x3D8A99#420% SP.ATK#C0x5B545B#(#C0x3D8A99#140% SP.ATK#C0x5B545B#untuk target garis depan lainnya)+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#sebagai gantinya . Target utama tetap berada di dalam lubang sampai Hoopa menyelesaikan gerakan selanjutnya. Rekor DMG yang diberikan ke semua musuh selama menginap. Ketika target keluar dari lubang, jika Hoopa belum pingsan, menimbulkan True DMG setara dengan 50% dari jumlah rekor DMG dan 100% P.ATK\n#F20#\n#F40##L10#Teleportasi:#L0#Efek kontrol, tidak dapat dihilangkan, tidak dapat menyerang atau diserang selama periode tersebut, namun Hoopa tetap dapat menyerang target.",
		simDesc_en = "Hoopa's 6 ghost hands travel through space with the help of Golden Rings to attack front-line enemies. Permanently reduces their DMG Reduction. Keeps the main target in the hole before teleporting it back to launch Dimensional Strike.",
		simDesc_vn = "As 6 mãos fantasmas de Hoopa viajam pelo espaço com a ajuda de anéis de ouro para atacar os inimigos da linha de frente. Reduz permanentemente sua redução de DMG. Mantém o alvo principal no buraco antes de teletransportá-lo de volta para lançar o Dimensional Strike.",
		describe_kr = "후파의 6개 유령손은 황금반지의 도움으로 우주를 여행하며 최전선의 적을 공격합니다. 피해 감소를 영구적으로 15% 감소시킵니다(중첩 가능, 해제 불가). 주요 대상이 고통받습니다#C0x3D8A99#420% SP.ATK#C0x5B545B#(#C0x3D8A99#140% SP.ATK#C0x5B545B#나머지 최전선 대상)+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#대신 . 주 대상은 Hoopa가 다음 동작을 마칠 때까지 구멍에 남아 있습니다. 머무는 동안 모든 적에게 가해진 DMG를 기록합니다. 대상이 구멍 밖으로 나왔을 때 후파가 기절하지 않았다면 기록 피해량의 50% 및 P.ATK 100%에 해당하는 True 피해를 입힙니다.ATK\n#F20#\n#F40##L10#텔레포트:#L0#제어 효과는 해제할 수 없고, 해당 기간 동안 공격하거나 공격받을 수 없지만 후파는 여전히 대상을 공격할 수 있습니다.",
		simDesc_th = "มือผีทั้ง 6 ของ Hoopa เดินทางผ่านอวกาศด้วยความช่วยเหลือของ Golden Rings เพื่อโจมตีศัตรูแนวหน้า ลดการลดความเสียหายอย่างถาวร เก็บเป้าหมายหลักไว้ในหลุมก่อนที่จะเทเลพอร์ตกลับไปเพื่อยิง Dimensional Strike",
		zawakeEffectDesc_es = "0",
		starEffectDesc_kr = "효과 부스트: 초공간 공격은 대상 최대 HP의 30%에 해당하는 추가 True DMG를 유발합니다.",
		zawakeEffectDesc_en = "0",
		simDesc_kr = "후파의 6개 유령손은 황금반지의 도움으로 우주를 여행하며 최전선의 적을 공격합니다. DMG 감소를 영구적으로 감소시킵니다. 차원 타격을 시작하기 위해 다시 순간 이동하기 전에 주 대상을 구멍에 유지합니다.",
		zawakeSimpleDesc_th = "0",
		zawakeSimpleDesc_kr = "0",
		starEffectDesc_en = "Effect boost: Hyperspace attacks cause additional True DMG equal to 30% of target's Max HP",
		zawakeSimpleDesc_vn = "0",
		zawakeSimpleDesc_id = "0",
		id = 220043,
		zawakeSimpleDesc_es = "0",
		simDesc_id = "6 tangan hantu Hoopa melakukan perjalanan melintasi ruang angkasa dengan bantuan Cincin Emas untuk menyerang musuh garis depan. Mengurangi Pengurangan DMG mereka secara permanen. Pertahankan target utama di dalam lubang sebelum memindahkannya kembali untuk meluncurkan Dimensional Strike."
	},
	[220046] = {
		describe_id = [[
Sebelum setiap putaran besar, berikan 6 [Golden Rings] kepada musuh acak di garis depan dan dapatkan semua [Golden Rings] kembali sebelum Hoopa bergerak (Membuat mereka kembali seketika saat target pingsan)
#F20#
#F40##L10#Emas Cincin: #L0#Efek spesial, setiap Cincin Emas mengurangi nilai tertentu dari statistik dasar target yang sesuai. (Nilainya sama dengan 8% dari statistik Hoopa yang terkait. Dapat dihilangkan. Menumpuk hingga 3 kali pada satu target)
#F20#
#F40#Mengurangi DMG Akhir yang diterima Hoopa sebesar $(15+skillLevel*0.05-0.05)$% dan menghilangkan 150% DMG ke 1 musuh acak di garis depan. Pada saat yang sama, menimbulkan True DMG setara dengan 40% P.ATK pada musuh.]],
		zawakeEffectDesc_vn = "0",
		describe_vn = [[
Antes de cada grande rodada, dá 6 [Golden Rings] para inimigos aleatórios da linha de frente e recupera todos [Golden Rings] antes que Hoopa se mova (os recupera instantaneamente quando o alvo desmaia)
#F20#
#F40##L10#Dourado Anel:#L0#Efeito especial, cada Anel de Ouro reduz um certo valor das estatísticas base correspondentes do alvo. (O valor equivale a 8% das estatísticas correspondentes de Hoopa. Pode ser dissipado. Acumula até 3 vezes em um único alvo)
#F20#
#F40#Reduz o DMG final recebido por Hoopa em $(15+skillLevel*0.05-0.05)$% e remove 150% do DMG para 1 inimigo aleatório da linha de frente. Ao mesmo tempo, inflige True DMG igual a 40% de P.ATK ao inimigo.]],
		starEffectDesc_id = "Efek ekstra: Saat pertempuran dimulai, Hoopa mengulurkan Tangan Hantunya untuk mencuri 10% Pengurangan DMG dari target musuh di barisan depan (tidak dapat dilepas); Saat menyerang, 10% Pengurangan DMG ini akan diubah menjadi bonus DMG",
		zawakeEffectDesc_th = "0",
		starEffectDesc_kr = "추가 효과: 전투가 시작되면 후파는 고스트 핸드를 확장하여 앞줄에 있는 적 대상으로부터 10% 데미지 감소를 훔칩니다(제거 불가). 공격할 때 이 10% DMG 감소는 DMG 보너스로 전환됩니다.",
		describe_es = [[
Antes de cada gran ronda, otorga 6 [Golden Rings] a enemigos aleatorios de primera línea y recupera todos los [Golden Rings] antes de que Hoopa se mueva (los recupera instantáneamente cuando el objetivo se desmaya)
#F20#
#F40##L10#Dorado Anillo:#L0#Efecto especial, cada Anillo Dorado reduce un cierto valor de las estadísticas base correspondientes del objetivo. (El valor equivale al 8% de las estadísticas correspondientes de Hoopa. Puede disiparse. Se acumula hasta 3 veces en un solo objetivo)
#F20#
#F40#Reduce el daño final recibido por Hoopa en un $(15+skillLevel*0.05-0.05)$% y elimina un 150%. del DMG a 1 enemigo aleatorio de primera línea. Al mismo tiempo, inflige daño verdadero equivalente al 40% de P.ATK al enemigo.]],
		zawakeSimpleDesc_en = "0",
		starEffectDesc_es = "Efecto adicional: cuando comienza la batalla, Hoopa extiende sus Manos Fantasma para robar un 10 % de reducción de daño de los objetivos enemigos en la primera fila (no extraíble); Cuando ataca, esta reducción de daño del 10% se convertirá en bonificación de daño.",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: เมื่อการต่อสู้เริ่มต้น Hoopa ขยาย Ghost Hands เพื่อขโมยการลดความเสียหาย 10% จากเป้าหมายศัตรูในแถวหน้า (ไม่สามารถถอดออกได้); เมื่อโจมตี การลดความเสียหาย 10% เหล่านี้จะถูกแปลงเป็นโบนัสความเสียหาย",
		zawakeEffectDesc_id = "0",
		zawakeEffectDesc_es = "0",
		describe_en = [[
Before each big round, gives 6 [Golden Rings] to random front-line enemies and gets all [Golden Rings] back before Hoopa moves (Gets them back instantly when the target faints)
#F20#
#F40##L10#Golden Ring:#L0#Special effect, each Golden Ring reduces a certain value of the target's corresponding base stats. (The value equals 8% of Hoopa's corresponding stats. Can be dispelled. Stacks up to 3 times on a single target)
#F20#
#F40#Reduces Final DMG taken by Hoopa by $(15+skillLevel*0.05-0.05)$% and removes 150% of the DMG to 1 random front-line enemy. At the same time, inflicts True DMG equal to own 40% P.ATK to the enemy.]],
		zawakeSimpleDesc_th = "0",
		zawakeEffectDesc_kr = "0",
		zawakeSimpleDesc_kr = "0",
		zawakeEffectDesc_en = "0",
		describe_kr = [[
각 큰 라운드 전에 임의의 최전선 적에게 6 [Golden Rings]를 주고 후파가 움직이기 전에 [Golden Rings]를 모두 돌려받습니다. (대상이 기절하면 즉시 돌려받습니다)
#F20#
#F40##L10#Golden 반지:#L0#특수 효과, 각 황금 반지는 대상의 해당 기본 능력치의 특정 값을 감소시킵니다. (값은 후파 해당 능력치의 8%입니다. 해제 가능합니다. 단일 대상에 최대 3번까지 중첩됩니다.)
#F20#
#F40#후파가 받는 최종 데미지가 $(15+skillLevel*0.05-0.05)$% 감소하고 150% 제거됩니다. 무작위 최전선 적 1명에게 피해를 입힙니다. 동시에 적에게 자신의 P.ATK 40%만큼 True DMG를 줍니다.]],
		zawakeSimpleDesc_vn = "0",
		zawakeSimpleDesc_id = "0",
		starEffectDesc_vn = "Efeito extra: Quando a batalha começa, Hoopa estende suas Mãos Fantasmas para roubar 10% de Redução de DANO dos alvos inimigos na primeira fila (não removível); Quando atacar, essa redução de 10% de DMG será convertida em bônus de DMG",
		zawakeSimpleDesc_es = "0",
		describe_th = [[
ก่อนรอบใหญ่แต่ละรอบ ให้ 6 [Golden Rings] สุ่มศัตรูแนวหน้า และรับทั้งหมด [Golden Rings] กลับก่อนที่ฮูปาจะเคลื่อนไหว (ได้รับพวกเขากลับมาทันทีเมื่อเป้าหมายเป็นลม)
#F20#
#F40##L10#Golden แหวน:#L0#เอฟเฟกต์พิเศษ แหวนทองคำแต่ละวงจะลดค่าสถานะพื้นฐานที่สอดคล้องกันของเป้าหมาย (ค่าเท่ากับ 8% ของสถิติที่สอดคล้องกันของ Hoopa สามารถลบล้างได้ ซ้อนได้สูงสุด 3 ครั้งในเป้าหมายเดียว)
#F20#
#F40#ลด DMG สุดท้ายที่ Hoopa ได้รับ $(15+skillLevel*0.05-0.05)$% และลบออก 150% ของความเสียหายต่อศัตรูแนวหน้าแบบสุ่ม 1 ตัว ในเวลาเดียวกัน สร้างความเสียหายจริงเท่ากับ 40% P.ATK แก่ศัตรู]],
		starEffectDesc_en = "Extra effect: When the battle begins, Hoopa extends its Ghost Hands to steal 10% DMG Reduction from the enemy targets in the front row (not removable); When it attacks, these 10% DMG Reduction will be converted into DMG bonus",
		id = 220046
	},
