	[230500] = {
		describe_th = "Slaking ปล่อยอัลติเมทโบลว์ กระแทกศัตรูเป้าหมายหนึ่งเป้าหมายและสร้างความเสียหาย #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B# โดยไม่สนใจพลังป้องกัน 30% ของเป้าหมายในเกมนี้ เคลื่อนไหว. หลังจากโจมตีจะหลับ 1 รอบ (ไม่สามารถปลุกพลังหรือลบล้างได้)",
		describe_en = "Slaking launches an Ultimate Blow, knocking up a single enemy target and dealing#C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, while disregarding the target's 30% P.DEF in this move. After attacking, it sleeps for 1 round (cannot be awakened or dispelled)",
		simDesc_es = "Slaking lanza un golpe definitivo que hace volar a un solo objetivo enemigo, sin tener en cuenta parte de su P.DEF. Se vuelve demasiado vago para moverse después de realizar el ataque.",
		describe_es = "Slaking lanza un Golpe Definitivo, derribando a un solo objetivo enemigo y causando#C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, sin tener en cuenta el 30% P.DEF del objetivo en este mover. Después de atacar, duerme durante 1 asalto (no se puede despertar ni disipar)",
		starEffectDesc_vn = "Aumento de efeito: Desconsidera 40% do P.DEF do alvo, e após estar acordado, aumenta 30% do seu dano Ultimate após 3 rodadas",
		starEffectDesc_id = "Peningkatan efek: Mengabaikan 40% P.DEF target, dan setelah bangun, meningkatkan 30% kerusakan Ultimate setelahnya selama 3 ronde",
		starEffectDesc_es = "Aumento del efecto: ignora el 40% del P.DEF del objetivo y, después de estar despierto, aumenta el 30% de su daño máximo durante 3 rondas.",
		describe_vn = "Slaking lança um golpe final, derrubando um único alvo inimigo e distribuindo#C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, enquanto desconsidera os 30% P.DEF do alvo neste mover. Após atacar, ele dorme por 1 rodada (não pode ser despertado ou dissipado)",
		starEffectDesc_th = "เอฟเฟกต์เสริม: โดยไม่สนใจ P.DEF ของเป้าหมาย 40% และหลังจากตื่นตัว จะเพิ่ม 30% ของความเสียหายขั้นสูงสุดหลังจากนั้นเป็นเวลา 3 รอบ",
		describe_id = "Slaking meluncurkan Serangan Pamungkas, menjatuhkan satu target musuh dan menyebabkan#C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#, sambil mengabaikan 30% P.DEF target dalam hal ini bergerak. Setelah menyerang, ia tertidur selama 1 putaran (tidak dapat dibangunkan atau dihilangkan)",
		simDesc_en = "Slaking lands an ultimate punch making a single enemy target fly, while disregarding some of its P.DEF. It becomes too lazy to move after making the attack.",
		simDesc_vn = "Slaking acerta um soco definitivo fazendo um único alvo inimigo voar, enquanto desconsidera parte de seu P.DEF. Fica com preguiça de se mover depois de fazer o ataque.",
		describe_kr = "슬레이킹은 궁극기를 발사해 단일 적 대상을 쓰러뜨리고 #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*75)$#C0xF13B54#P.DMG#C0x5B545B#를 처리하며 대상의 30% P.DEF를 무시합니다. 이동하다. 공격 후 1라운드 동안 수면 상태가 됩니다. (각성 및 해제 불가)",
		simDesc_th = "Slaking โจมตีด้วยหมัดขั้นสุดยอดทำให้เป้าหมายศัตรูตัวเดียวบินได้ โดยไม่สนใจ P.DEF บางส่วน มันขี้เกียจเกินไปที่จะเคลื่อนไหวหลังจากทำการโจมตี",
		starEffectDesc_kr = "효과 증폭 : 대상의 P.DEF를 40% 무시하고, 깨어난 후 3라운드 동안 궁극기 대미지의 30%를 증가시킵니다.",
		simDesc_kr = "Slaking은 P.DEF를 일부 무시하면서 단일 적 목표를 날아가게 만드는 궁극의 펀치를 날립니다. 공격을 한 후에는 움직이기가 너무 게으릅니다.",
		starEffectDesc_en = "Effect boost: Disregards 40% of the target's P.DEF, and after being awake, it increases 30% of its Ultimate damage after for 3 rounds",
		id = 230500,
		simDesc_id = "Slaking mendaratkan pukulan pamungkas yang membuat satu target musuh terbang, sambil mengabaikan sebagian P.DEF-nya. Menjadi terlalu malas untuk bergerak setelah melakukan serangan."
	},
