	[250021] = {
		describe_vn = "Jigglypuff canta suavemente e ataca um único alvo inimigo com sua voz, distribuindo#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		describe_kr = "Jigglypuff는 부드럽게 노래하며 목소리로 단일 적 대상을 공격하여#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리합니다.",
		describe_en = "Jigglypuff sings softly and attacks a single enemy target with its voice, dealing#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		describe_id = "Jigglypuff bernyanyi dengan lembut dan menyerang satu target musuh dengan suaranya, menimbulkan#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		id = 250021,
		describe_es = "Jigglypuff canta suavemente y ataca a un solo objetivo enemigo con su voz, causando#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		describe_th = "จิกกลีพัฟร้องเพลงเบาๆ และโจมตีศัตรูเป้าหมายเดียวด้วยเสียง สร้างความเสียหาย#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0xF13B54#SP.DMG#C0x5B545B#"
	},
	[250022] = {
		describe_vn = "Jigglypuff pula com raiva e ataca um único alvo inimigo, distribuindo#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*36)$#C0xF13B54#SP.DMG#C0x5B545B#, com 50% de chance de colocar o alvo para dormir por 1 redondo",
		describe_kr = "Jigglypuff가 화가 나서 뛰어올라 단일 적 대상을 공격하여 #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 공격하며, 50% 확률로 1 동안 대상을 잠들게 합니다. 둥근",
		describe_en = "Jigglypuff angrily jumps up and strikes at a single enemy target, dealing#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*36)$#C0xF13B54#SP.DMG#C0x5B545B#, with 50% chance of putting the target to sleep for 1 round",
		describe_id = "Jigglypuff dengan marah melompat dan menyerang satu target musuh, menimbulkan#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*36)$#C0xF13B54#SP.DMG#C0x5B545B#, dengan 50% kemungkinan membuat target tertidur selama 1 bulat",
		id = 250022,
		describe_es = "Jigglypuff salta enojado y ataca a un solo objetivo enemigo, causando#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*36)$#C0xF13B54#SP.DMG#C0x5B545B#, con un 50% de probabilidad de poner al objetivo a dormir durante 1 redondo",
		describe_th = "จิกกลีพัฟกระโดดขึ้นโจมตีศัตรูเป้าหมายเดียวด้วยความโกรธ สร้างความเสียหาย#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*36)$#C0xF13B54#SP.DMG#C0x5B545B# โดยมีโอกาส 50% ที่จะทำให้เป้าหมายหลับเป็นเวลา 1 วินาที กลม"
	},
	[250023] = {
		describe_vn = "Jigglypuff canta alegremente no palco, distribuindo#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*30)$#C0xF13B54#SP.DMG#C0x5B545B#para todos os inimigos, com 40% de chance de colocar 3 unidades inimigas para dormir por 1 rodada",
		describe_kr = "Jigglypuff는 무대에서 즐겁게 노래하며 #C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*30)$#C0xF13B54#SP.DMG#C0x5B545B#를 모든 적에게 처리하고 40% 확률로 3개의 적 유닛을 1라운드 동안 잠들게 합니다.",
		describe_en = "Jigglypuff happily sings on stage, dealing#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*30)$#C0xF13B54#SP.DMG#C0x5B545B#to all enemies, with 40% chance of putting 3 enemy units to sleep for 1 round",
		describe_id = "Jigglypuff dengan gembira bernyanyi di atas panggung, memberikan#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*30)$#C0xF13B54#SP.DMG#C0x5B545B#ke semua musuh, dengan 40% kemungkinan membuat 3 unit musuh tertidur selama 1 ronde",
		id = 250023,
		describe_es = "Jigglypuff canta felizmente en el escenario, causando#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*30)$#C0xF13B54#SP.DMG#C0x5B545B#a todos los enemigos, con un 40% de probabilidad de poner a dormir a 3 unidades enemigas durante 1 ronda.",
		describe_th = "จิกกลีพัฟร้องเพลงบนเวทีอย่างมีความสุข สร้างความเสียหาย#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*30)$#C0xF13B54#SP.DMG#C0x5B545B#ให้กับศัตรูทั้งหมด โดยมีโอกาส 40% ที่จะทำให้ยูนิตศัตรู 3 ตัวหลับเป็นเวลา 1 รอบ"
	},
	[250026] = {
		describe_vn = "Há $(20+skillLevel*0.1-0.1)$% de chance de colocar um inimigo que o ataca para dormir por 1 rodada",
		describe_kr = "$(20+skillLevel*0.1-0.1)$%의 확률로 자신을 공격하는 적을 1라운드 동안 잠들게 합니다.",
		describe_en = "There is a $(20+skillLevel*0.1-0.1)$% chance of putting an enemy that attacks it to sleep for 1 round",
		describe_id = "Ada peluang $(20+skillLevel*0.1-0.1)$% membuat musuh yang menyerangnya tertidur selama 1 ronde",
		id = 250026,
		describe_es = "Hay un $(20+skillLevel*0.1-0.1)$% de probabilidad de poner a dormir a un enemigo que lo ataca durante 1 ronda.",
		describe_th = "มีโอกาส $(20+skillLevel*0.1-0.1)$% ที่จะทำให้ศัตรูที่โจมตีเข้าสู่โหมดสลีปเป็นเวลา 1 รอบ"
	},
	[250100] = {
		id = 250100
	},
	[250121] = {
		describe_vn = "O antigo Jigglypuff canta alto, infligindo certos#C0xF13B54#SP.DMG#C0x5B545B#a 2 inimigos aleatórios. Ao mesmo tempo, tem 80-100% de chance de acalmá-los para [Sleep] por 2-3 rodadas (Sono: incapaz de se mover, acorda quando atacado) Quando Jigglypuff fica bravo, ataca mais 1 alvo",
		describe_kr = "고대 Jigglypuff가 큰 소리로 노래하며 무작위 2명의 적에게 특정#C0xF13B54#SP.DMG#C0x5B545B#를 입힙니다. 동시에 2~3라운드 동안 80~100%의 확률로 [Sleep]로 달래줍니다. (수면: 움직이지 못함, 공격당하면 깨어남) Jigglypuff가 화가 나면 대상 1명을 더 공격합니다.",
		describe_en = "Ancient Jigglypuff sings loudly, inflicting certain#C0xF13B54#SP.DMG#C0x5B545B#to random 2 enemies. At the same time, has an 80-100% chance to lull them to [Sleep] for 2-3 rounds (Sleep: unable to move, wakes up when attacked) When Jigglypuff gets mad, attacks 1 more target",
		describe_id = "Jigglypuff kuno bernyanyi dengan keras, menimbulkan#C0xF13B54#SP.DMG#C0x5B545B#tertentu kepada 2 musuh secara acak. Pada saat yang sama, mempunyai peluang 80-100% untuk menidurkan mereka ke [Sleep] selama 2-3 ronde (Tidur: tidak bisa bergerak, bangun saat diserang) Saat Jigglypuff marah, serang 1 target lagi",
		id = 250121,
		describe_es = "El antiguo Jigglypuff canta en voz alta e inflige ciertos#C0xF13B54#SP.DMG#C0x5B545B#a 2 enemigos al azar. Al mismo tiempo, tiene un 80-100% de posibilidades de adormecerlos hasta [Sleep] durante 2-3 rondas (Sueño: incapaz de moverse, se despierta cuando es atacado) Cuando Jigglypuff se enoja, ataca a 1 objetivo más",
		describe_th = "Jigglypuff โบราณร้องเพลงเสียงดัง สร้างความเสียหายแน่นอน#C0xF13B54#SP.DMG#C0x5B545B# สุ่มศัตรู 2 ตัว ขณะเดียวกันมีโอกาส 80-100% ที่จะกล่อมพวกมันให้ [Sleep] 2-3 รอบ (หลับ: ขยับไม่ได้, ตื่นเมื่อถูกโจมตี) เมื่อ Jigglypuff โกรธโจมตีอีก 1 เป้าหมาย"
	},
	[250122] = {
		describe_vn = "O Antigo Jigglypuff ataca um único inimigo com seu marcador. Inflige certo#C0xF13B54#SP.DMG#C0x5B545B#e 30% de DMG extra se o alvo estiver dormindo, reduz permanentemente seu DMG em 5% (não pode ser dissipado). À medida que mais inimigos adormecem, Jigglypuff punirá aqueles que dormiram por muito tempo.",
		describe_kr = "고대의 Jigglypuff는 마커 펜으로 적 한 명을 공격합니다. 특정#C0xF13B54#SP.DMG#C0x5B545B#을 가하고 대상이 수면 상태인 경우 30% 추가 피해를 주며 영구적으로 피해를 5% 감소시킵니다(해제 불가). 잠들어 있는 적들이 많아질수록, 오랫동안 잠을 자고 있는 적들을 징벌할 것입니다.",
		describe_en = "Ancient Jigglypuff attacks a single enemy with its marker pen. Inflicts certain#C0xF13B54#SP.DMG#C0x5B545B#and 30% extra DMG if the target is in sleep, permanently reduces its DMG by 5% (cannot be dispelled). As more enemies fall asleep, Jigglypuff will punish those that have slept for a long time.",
		describe_id = "Jigglypuff Kuno menyerang satu musuh dengan spidolnya. Menimbulkan#C0xF13B54#SP.DMG#C0x5B545B#tertentu dan 30% DMG ekstra jika target sedang tidur, mengurangi DMG target secara permanen sebesar 5% (tidak dapat dihilangkan). Semakin banyak musuh yang tertidur, Jigglypuff akan menghukum mereka yang sudah tertidur lama.",
		id = 250122,
		describe_es = "Ancient Jigglypuff ataca a un solo enemigo con su rotulador. Inflige cierto#C0xF13B54#SP.DMG#C0x5B545B#y un 30% de DAÑO adicional si el objetivo está dormido, reduce permanentemente su DAÑO en un 5% (no se puede disipar). A medida que más enemigos se duerman, Jigglypuff castigará a aquellos que hayan dormido durante mucho tiempo.",
		describe_th = "Jigglypuff โบราณโจมตีศัตรูตัวเดียวด้วยปากกามาร์กเกอร์ สร้างความเสียหายแน่นอน#C0xF13B54#SP.DMG#C0x5B545B#และความเสียหายพิเศษ 30% หากเป้าหมายอยู่ในโหมดสลีป จะลดความเสียหายอย่างถาวร 5% (ไม่สามารถลบล้างได้) เมื่อศัตรูหลับใหลมากขึ้น Jigglypuff จะลงโทษผู้ที่หลับใหลเป็นเวลานาน"
	},
	[250123] = {
		describe_vn = "A antiga Jigglypuff canta no centro do palco. Inflige certo#C0xF13B54#SP.DMG#C0x5B545B#a todos os inimigos e tem 80%-100% de chance de acalmá-los para [Sleep] por 2 rodadas. Hipnotiza o inimigo com maior ATK por 3 rodadas.",
		describe_kr = "고대 Jigglypuff가 무대 중앙에서 노래합니다. 모든 적에게 특정#C0xF13B54#SP.DMG#C0x5B545B#을 입히고 80%-100% 확률로 2라운드 동안 [Sleep]로 달래줍니다. 3라운드 동안 공격력이 가장 높은 적을 최면 상태로 만듭니다.",
		describe_en = "Ancient Jigglypuff sings at the center of the stage. Inflicts certain#C0xF13B54#SP.DMG#C0x5B545B#to all enemies and has a 80%-100% chance to lull them to [Sleep] for 2 rounds. Hypnotizes the enemy with the highest ATK for 3 rounds.",
		describe_id = "Jigglypuff kuno bernyanyi di tengah panggung. Menimbulkan#C0xF13B54#SP.DMG#C0x5B545B#tertentu kepada semua musuh dan berpeluang 80%-100% untuk membuai mereka hingga [Sleep] selama 2 ronde. Menghipnotis musuh dengan ATK tertinggi selama 3 ronde.",
		id = 250123,
		describe_es = "El antiguo Jigglypuff canta en el centro del escenario. Inflige cierto#C0xF13B54#SP.DMG#C0x5B545B#a todos los enemigos y tiene un 80%-100% de posibilidades de adormecerlos hasta [Sleep] durante 2 rondas. Hipnotiza al enemigo con mayor ATK durante 3 rondas.",
		describe_th = "Ancient Jigglypuff ร้องเพลงอยู่กลางเวที สร้างความเสียหาย#C0xF13B54#SP.DMG#C0x5B545B#ให้กับศัตรูทั้งหมด และมีโอกาส 80%-100% ที่จะกล่อมพวกเขาให้ [Sleep] เป็นเวลา 2 รอบ สะกดจิตศัตรูด้วย ATK สูงสุดเป็นเวลา 3 รอบ"
	},
	[250126] = {
		describe_vn = [[
[Status Condition Immunity]: Primal Jigglypuff é imune a condições de status.
[Special Sleep]: Atacar Pokémons adormecidos não o despertará. Depois que Jigglypuff coloca o alvo para dormir, se o efeito estiver sendo dissipado, ele desperta de um ataque, aumenta a raiva do alvo em 400 pontos. Se o alvo acordar sozinho, ele perderá 200 pontos de raiva.
[Move Boost]: Quando Primal Jigglypuff libera 2 movimentos Ultimate, ele ataca todos os alvos adormecidos sempre que faz o movimento Scribble.
[Ability Boost]: Primal Jigglypuff gradualmente aumenta suas próprias habilidades e ATK com base na quantidade de dano que recebe, e também entrará em Fúria após um certo número de rodadas]],
		describe_kr = [[
[Status Condition Immunity]: 원시 Jigglypuff는 상태이상에 면역입니다.
[Special Sleep]: 잠자는 포켓몬을 공격해도 깨어나지 않습니다. Jigglypuff가 대상을 잠들게 한 후, 효과가 해제되어 공격에서 깨어나면 대상의 분노가 400 포인트 증가합니다. 대상이 스스로 깨어나면 대상은 대신 분노 포인트 200을 잃습니다.
[Move Boost]: 원시 Jigglypuff가 궁극기 2개를 방출하면 Scribble 동작을 할 때마다 잠자는 모든 대상을 공격합니다.
[Ability Boost]: 원시 Jigglypuff가 점차적으로 공격합니다. 받는 피해량에 따라 자신의 능력과 공격력이 증가하며, 일정 라운드가 지나면 분노 상태로 전환됩니다.]],
		describe_en = [[
[Status Condition Immunity]: Primal Jigglypuff is immune to status conditions.
[Special Sleep]: Attacking sleeping Pokémons will not awaken it. After Jigglypuff puts the target to sleep, if the effect is being dispelled of it awakens from an attack, it increases the target's rage by 400 points. If the target awakes up itself, the target loses 200 rage points instead.
[Move Boost]: When Primal Jigglypuff releases 2 Ultimate moves, it attacks all sleeping targets whenever it makes the Scribble move.
[Ability Boost]: Primal Jigglypuff gradually increases its own abilities and ATK based on the amount of damage it receives, and will also enter Rage after a certain number of rounds]],
		describe_id = [[
[Status Condition Immunity]: Primal Jigglypuff kebal terhadap kondisi status.
[Special Sleep]: Menyerang Pokémon yang sedang tidur tidak akan membangunkannya. Setelah Jigglypuff menidurkan target, jika efeknya dihilangkan saat ia terbangun dari serangan, maka kemarahan target akan meningkat sebesar 400 poin. Jika target terbangun sendiri, target akan kehilangan 200 rage point.
[Move Boost]: Saat Primal Jigglypuff mengeluarkan 2 jurus Ultimate, ia akan menyerang semua target yang tertidur setiap kali ia melakukan gerakan Scribble.
[Ability Boost]: Primal Jigglypuff secara bertahap meningkatkan kemampuan dan ATKnya sendiri berdasarkan jumlah kerusakan yang diterimanya, dan juga akan memasuki Rage setelah beberapa putaran tertentu]],
		id = 250126,
		describe_es = [[
[Status Condition Immunity]: Primal Jigglypuff es inmune a las condiciones de estado.
[Special Sleep]: Atacar a Pokémon dormidos no lo despertará. Después de que Jigglypuff pone a dormir al objetivo, si el efecto se disipa cuando se despierta de un ataque, aumenta la ira del objetivo en 400 puntos. Si el objetivo se despierta solo, pierde 200 puntos de ira.
[Move Boost]: Cuando Primal Jigglypuff lanza 2 movimientos definitivos, ataca a todos los objetivos dormidos cada vez que realiza el movimiento Scribble.
[Ability Boost]: Primal Jigglypuff gradualmente aumenta sus propias habilidades y ATK según la cantidad de daño que recibe, y también entrará en ira después de una cierta cantidad de rondas]],
		describe_th = [[
[Status Condition Immunity]: Primal Jigglypuff มีภูมิคุ้มกันต่อสภาวะสถานะ
[Special Sleep]: การโจมตีโปเกมอนที่หลับอยู่จะไม่ปลุกมัน หลังจากที่ Jigglypuff ทำให้เป้าหมายเข้าสู่โหมดสลีป หากเอฟเฟกต์ถูกลบล้างออกไป มันจะตื่นขึ้นจากการโจมตี ความโกรธของเป้าหมายจะเพิ่มขึ้น 400 หน่วย หากเป้าหมายตื่นขึ้นมา เป้าหมายจะสูญเสียคะแนนความโกรธ 200 คะแนนแทน 
[Move Boost]: เมื่อ Primal Jigglypuff ปล่อยท่าอัลติเมท 2 ครั้ง มันจะโจมตีเป้าหมายที่หลับอยู่ทั้งหมดเมื่อใดก็ตามที่มันทำให้ Scribble เคลื่อนไหว
[Ability Boost]: Primal Jigglypuff ค่อยๆ เพิ่มความสามารถและ ATK ของตัวเองตามจำนวนความเสียหายที่ได้รับ และจะเข้าสู่ Rage หลังจากผ่านไปตามจำนวนรอบที่กำหนด]]
	},
	[251011] = {
		describe_vn = "Primal Gengar invoca Spirit Ambush para 2-3 alvos aleatórios, causando uma certa quantidade de #C0xF13B54#SP.DMG#C0x5B545B#enquanto adiciona uma pilha de [Poison] (Veneno: o alvo perde dano verdadeiro igual a 1% do HP máximo de Primal Gengar. no início de cada rodada por 5 rodadas. O efeito pode ser dissipado. Quando o efeito atinge 10 pilhas, ele causa instantaneamente dano verdadeiro igual a 80% do HP máximo do alvo). Se o alvo já estiver envenenado, sua pilha de veneno dobra.",
		describe_kr = "원시 Gengar는 2-3명의 무작위 대상에게 Spirit Ambush를 소환하여 일정량의#C0xF13B54#SP.DMG#C0x5B545B#를 입히고 [Poison]의 스택을 추가합니다. (독: 대상은 원시 Gengar의 최대 HP 1%에 해당하는 실제 피해를 잃습니다. 5라운드 동안 매 라운드 시작 시 효과는 해제될 수 있으며, 효과가 10중첩에 도달하면 즉시 대상 최대 HP의 80%에 해당하는 고정 피해를 입힙니다. 대상이 이미 중독된 경우에는 독 스택이 두 배가 됩니다.",
		describe_en = "Primal Gengar summons Spirit Ambush to 2-3 random targets, dealing a certain amount of#C0xF13B54#SP.DMG#C0x5B545B#while added a stack of [Poison] (Poison: Target loses true damage equals to Primal Gengar's 1% max. HP at the beginning of each round for 5 rounds. The effect can be dispelled. When the effect reaches 10 stacks, it instantly deals true damage equals to 80% of the target's max HP). If the target is already poisoned, its poison stack doubles.",
		describe_id = "Primal Gengar memanggil Spirit Ambush ke 2-3 target acak, menimbulkan #C0xF13B54#SP.DMG#C0x5B545B# dalam jumlah tertentu sambil menambahkan setumpuk [Poison] (Racun: Target kehilangan kerusakan sebenarnya setara dengan 1% HP maksimal Primal Gengar di awal setiap ronde selama 5 ronde. Efeknya dapat dihilangkan. Jika efek mencapai 10 tumpukan, maka akan langsung menimbulkan true damage setara dengan 80% dari max HP target). Jika target sudah terkena racun, tumpukan racunnya akan berlipat ganda.",
		id = 251011,
		describe_es = "Primal Gengar invoca Spirit Ambush a 2-3 objetivos aleatorios, causando una cierta cantidad de #C0xF13B54#SP.DMG#C0x5B545B# mientras agrega una acumulación de [Poison] (Veneno: el objetivo pierde daño verdadero equivalente al 1% de HP máximo de Primal Gengar al comienzo de cada ronda durante 5 rondas. El efecto se puede disipar. Cuando el efecto alcanza 10 acumulaciones, inflige instantáneamente un daño verdadero equivalente al 80% del HP máximo del objetivo). Si el objetivo ya está envenenado, su acumulación de veneno se duplica.",
		describe_th = "Primal Gengar เรียก Spirit Ambush ไปยังเป้าหมายแบบสุ่ม 2-3 เป้าหมาย สร้างความเสียหายจำนวนหนึ่ง #C0xF13B54#SP.DMG#C0x5B545B# พร้อมทั้งเพิ่มสแตค [Poison] (พิษ: เป้าหมายสูญเสียความเสียหายจริงเท่ากับ HP สูงสุดของ Primal Gengar 1% เมื่อเริ่มแต่ละรอบ 5 รอบ เอฟเฟกต์สามารถลบล้างได้ เมื่อเอฟเฟกต์ถึง 10 สแต็ค จะสร้างความเสียหายจริงทันทีเท่ากับ 80% ของ HP สูงสุดของเป้าหมาย) หากเป้าหมายติดพิษอยู่แล้ว พิษของมันจะสะสมเป็นสองเท่า"
	},
	[251012] = {
		describe_vn = "Primal Gengar libera o poder das trevas para consumir aleatoriamente 300 pontos de raiva de 2 alvos, causando uma certa quantidade de #C0xF13B54#SP.DMG#C0x5B545B#e aumenta seu próprio crítico em 40% por 2 rodadas. Após algumas rodadas, a absorção de raiva será eficaz para todos os alvos em [Fear]",
		describe_kr = "원시 젠가는 어둠의 힘을 방출하여 2명의 대상의 분노 포인트 300을 무작위로 소모하여 일정량#C0xF13B54#SP.DMG#C0x5B545B#을 처리하고 2라운드 동안 자신의 치명타를 40% 증가시킵니다. 몇 라운드가 지나면 [Fear]의 모든 대상에게 분노 흡수가 적용됩니다.",
		describe_en = "Primal Gengar releases the power of darkness to randomly consume 300 rage points of 2 targets, dealing a certain amount of#C0xF13B54#SP.DMG#C0x5B545B#and increases its own crit by 40% for 2 rounds. After a few rounds, rage absorption will be effective to all targets in [Fear]",
		describe_id = "Primal Gengar melepaskan kekuatan kegelapan untuk secara acak mengkonsumsi 300 poin kemarahan dari 2 target, menimbulkan sejumlah#C0xF13B54#SP.DMG#C0x5B545B# tertentu dan meningkatkan kritiknya sendiri sebesar 40% selama 2 putaran. Setelah beberapa ronde, penyerapan kemarahan akan efektif pada semua target di [Fear]",
		id = 251012,
		describe_es = "Primal Gengar libera el poder de la oscuridad para consumir aleatoriamente 300 puntos de ira de 2 objetivos, causando una cierta cantidad de#C0xF13B54#SP.DMG#C0x5B545B#y aumenta su propio crítico en un 40% durante 2 rondas. Después de algunas rondas, la absorción de ira será efectiva para todos los objetivos en [Fear]",
		describe_th = "ไพรมอลเก็นการ์ปลดปล่อยพลังแห่งความมืดเพื่อสุ่มใช้แต้มความโกรธ 300 แต้มจาก 2 เป้าหมาย สร้างความเสียหายจำนวนหนึ่ง #C0xF13B54#SP.DMG#C0x5B545B# และเพิ่มคริติคอลของตัวเอง 40% เป็นเวลา 2 รอบ หลังจากผ่านไปไม่กี่รอบ การดูดซึมความโกรธจะมีผลกับเป้าหมายทั้งหมดใน [Fear]"
	},
	[251013] = {
		describe_vn = "Primal Gengar libera o poder das trevas para consumir todos os alvos inimigos, causando #C0xF13B54#SP.DMG#C0x5B545B# massivo, com 30-70% de chance de infligir [Fear] por 3 rodadas (Medo: Reduz o ATK do alvo para o mesmo nível como sua DEF, quanto menor o ATK, maior a taxa de medo, com 30% extras ao infligir inimigos na linha de trás. O medo pode ser dissipado, e se o nível de raiva estiver cheio antes do turno do alvo, ele será dissipado automaticamente). Sempre que Primal Gengar faz 2 movimentos Ultimate, cada movimento Ultimate adiciona 1 pilha de [Poison] a todos os inimigos",
		describe_kr = "원시 젠가가 어둠의 힘을 방출하여 모든 적 대상을 소비하여 엄청난 #C0xF13B54#SP.DMG#C0x5B545B#을 가하고 30~70% 확률로 3라운드 동안 [Fear]를 입힙니다(공포: 대상의 공격력을 같은 수준으로 감소) 방어력은 ATK가 낮을수록 공포율이 높아지며, 후방의 적을 공격할 경우 30% 추가 공포는 해제될 수 있으며, 대상의 턴 전에 분노 레벨이 가득 차면 자동으로 해제됩니다. Primal Gengar가 2번의 궁극기 이동을 할 때마다 각 궁극기 이동은 모든 적에게 [Poison]의 1 스택을 추가합니다.",
		describe_en = "Primal Gengar releases the power of darkness to consume all enemy targets, dealing massive#C0xF13B54#SP.DMG#C0x5B545B#, with 30-70% chance of inflicting [Fear] for 3 rounds (Fear: Reduces the target's ATK to the same level as its DEF, the lower the ATK the higher the Fear rate, with extra 30% when inflicting enemies in the back line. Fear can be dispelled, and if the rage level is full before the target's turn, it will be dispelled automatically). Whenever Primal Gengar makes 2 Ultimate moves, each Ultimate move adds 1 stack of [Poison] to all enemies",
		describe_id = "Primal Gengar melepaskan kekuatan kegelapan untuk memakan semua target musuh, menimbulkan#C0xF13B54#SP.DMG#C0x5B545B# besar-besaran, dengan peluang 30-70% menimbulkan [Fear] selama 3 ronde (Fear: Mengurangi ATK target ke level yang sama sebagai DEF-nya, semakin rendah ATKnya, semakin tinggi tingkat Ketakutannya, dengan tambahan 30% ketika menyerang musuh di lini belakang. Ketakutan dapat dihilangkan, dan jika level kemarahan sudah penuh sebelum giliran target, maka akan dihilangkan secara otomatis). Setiap kali Primal Gengar melakukan 2 gerakan Ultimate, setiap gerakan Ultimate menambahkan 1 tumpukan [Poison] ke semua musuh",
		id = 251013,
		describe_es = "Primal Gengar libera el poder de la oscuridad para consumir todos los objetivos enemigos, causando un enorme #C0xF13B54#SP.DMG#C0x5B545B#, con un 30-70 % de probabilidad de infligir [Fear] durante 3 rondas (Miedo: reduce el ATK del objetivo al mismo nivel (como su DEF, cuanto menor sea el ATK, mayor será la tasa de miedo, con un 30% adicional cuando inflige enemigos en la línea de fondo. El miedo se puede disipar, y si el nivel de ira está lleno antes del turno del objetivo, se disipará automáticamente). Siempre que Primal Gengar realiza 2 movimientos definitivos, cada movimiento definitivo añade 1 acumulación de [Poison] a todos los enemigos.",
		describe_th = "ไพรมอลเก็นการ์ปลดปล่อยพลังแห่งความมืดกลืนกินเป้าหมายศัตรูทั้งหมด สร้างความเสียหายมหาศาล#C0xF13B54#SP.DMG#C0x5B545B# โดยมีโอกาส 30-70% ที่จะสร้างความเสียหาย [Fear] เป็นเวลา 3 รอบ (ความกลัว: ลด ATK ของเป้าหมายให้อยู่ในระดับเดียวกัน) เนื่องจาก DEF ยิ่ง ATK ต่ำ อัตราความกลัวก็จะยิ่งสูงขึ้น โดยจะเพิ่ม 30% เมื่อสร้างความเสียหายให้ศัตรูในแนวหลัง ความกลัวสามารถลบล้างได้ และหากระดับความโกรธเต็มก่อนถึงเทิร์นของเป้าหมาย มันจะถูกลบล้างโดยอัตโนมัติ) เมื่อใดก็ตามที่ Primal Gengar ทำท่าไม้ตาย 2 ครั้ง แต่ละท่าท่าไม้ตายจะเพิ่ม 1 กอง [Poison] ให้กับศัตรูทั้งหมด"
	},
	[251015] = {
		id = 251015
	},
	[251016] = {
		describe_vn = [[
[Immunity Body]: Imune ao efeito de Controle e Veneno 
[Negative Maker]: Cada ataque aplica 2 efeitos negativos aleatórios (Redução de SP.ATK, SP.DEF, P.ATK, P.DEF; Veneno, Redução de Cura) por 5 rodadas. Pode ser dissipado
[Deep Fear]: Quando um alvo entrar em [fear] novamente, ele obterá o status [Deep Fear], o que reduz sua Regeneração de Fúria em 50% e evita que esse status seja dissipado.
[Evil Curse]: A partir da 8ª rodada, Ancient Gengar observa o alvo com maior ATK a cada 2 rodadas e aplica [Curse] por 2 rodadas (Maldição: Aumenta 50% de DMG e mantém a Fúria cheia. Quando o Ultimate é usado, seu próprio leva o dobro DMG lidou com Ultimate.
[Ability UP]: Ancient Gengar ganha gradualmente estatísticas e aumentos de ataque à medida que requer mais DMG.]],
		describe_kr = [[
[Immunity Body]: 제어 및 독 효과에 면역
[Negative Maker]: 각 공격은 5라운드 동안 무작위로 2개의 부정적인 효과(SP.ATK, SP.DEF, P.ATK, P.DEF 감소; 독, 치유 감소)를 적용합니다. 해제 가능
[Deep Fear]: 대상이 다시 [fear] 상태가 되면 [Deep Fear] 상태가 되어 분노 재생이 50% 감소하고 이 상태가 해제되는 것을 방지합니다.
[Evil Curse]: 8라운드부터 고대 젠가는 2라운드마다 공격력이 가장 높은 대상을 관찰하여 2라운드 동안 [Curse]를 적용합니다. (저주: 데미지가 50% 증가하고 분노가 가득 차게 됩니다. 궁극기가 사용 적중 시 자신의 데미지가 2배가 됩니다. DMG는 Ultimate를 처리했습니다.
[Ability UP]: 고대 Gengar는 더 많은 DMG가 필요함에 따라 점차적으로 능력치와 공격 부스트를 얻습니다.]],
		describe_en = [[
[Immunity Body]: Immune to Control and Poison effect
[Negative Maker]: Each attack applies random 2 negative effect (Reducing SP.ATK, SP.DEF, P.ATK, P.DEF; Poison, Heal Reduction) for 5 rounds. Can be dispelled
[Deep Fear]: When a target becomes in [fear] again, it will get the [Deep Fear] status, which reduces its Rage Regen by 50% and prevents this status from being dispelled.
[Evil Curse]: Starting from the 8th round, Ancient Gengar observes the target with the highest ATK every 2 rounds and applies [Curse] for 2 rounds (Curse: Increases 50% DMG and keeps Rage full. When the Ultimate is used-hit, its own takes double DMG dealt with Ultimate.
[Ability UP]: Ancient Gengar gradually gains stats and attack boosts as it takes more DMG.]],
		describe_id = [[
[Immunity Body]: Kebal terhadap Kontrol dan efek Racun
[Negative Maker]: Setiap serangan menerapkan 2 efek negatif acak (Pengurangan SP.ATK, SP.DEF, P.ATK, P.DEF; Racun, Pengurangan Pemulihan) selama 5 putaran. Dapat dihilangkan
[Deep Fear]: Ketika target berada dalam [fear] lagi, ia akan mendapatkan status [Deep Fear], yang mengurangi Rage Regen sebesar 50% dan mencegah status ini dihilangkan.
[Evil Curse]: Mulai ronde ke 8, Ancient Gengar mengamati target dengan ATK tertinggi setiap 2 ronde dan menerapkan [Curse] selama 2 ronde (Kutukan: Meningkatkan 50% DMG dan membuat Rage tetap penuh. Saat Ultimate digunakan dan dipukul, efeknya akan berlipat ganda DMG ditangani dengan Ultimate.
[Ability UP]: Gengar Kuno secara bertahap memperoleh statistik dan peningkatan serangan seiring dengan menerima lebih banyak DMG.]],
		id = 251016,
		describe_es = [[
[Immunity Body]: Inmune al control y efecto de veneno
[Negative Maker]: Cada ataque aplica 2 efectos negativos aleatorios (Reducción de SP.ATK, SP.DEF, P.ATK, P.DEF; Veneno, Reducción de curación) durante 5 rondas. Se puede disipar
[Deep Fear]: cuando un objetivo vuelve a entrar en [fear], obtendrá el estado [Deep Fear], que reduce su regeneración de ira en un 50 % y evita que este estado se disipe.
[Evil Curse]: A partir de la octava ronda, Ancient Gengar observa el objetivo con el ATK más alto cada 2 rondas y aplica [Curse] durante 2 rondas (Maldición: aumenta el 50% de DAÑO y mantiene la ira llena. Cuando se usa el golpe definitivo, el suyo recibe el doble El DAÑO se ocupa de Ultimate.
[Ability UP]: Ancient Gengar gana gradualmente estadísticas y mejoras de ataque a medida que recibe más DAÑO.]],
		describe_th = [[
[Immunity Body]: ภูมิคุ้มกันต่อการควบคุมและเอฟเฟกต์พิษ
[Negative Maker]: การโจมตีแต่ละครั้งจะสร้างเอฟเฟกต์ด้านลบ 2 แบบแบบสุ่ม (ลด SP.ATK, SP.DEF, P.ATK, P.DEF; พิษ, ลดการรักษา) เป็นเวลา 5 รอบ สามารถลบล้างได้
[Deep Fear]: เมื่อเป้าหมายเข้าสู่ [fear] อีกครั้ง มันจะได้รับสถานะ [Deep Fear] ซึ่งจะลดอัตราฟื้นฟูความโกรธลง 50% และป้องกันไม่ให้สถานะนี้ถูกลบล้าง
[Evil Curse]: เริ่มตั้งแต่รอบที่ 8 Ancient Gengar จะสังเกตเป้าหมายที่มี ATK สูงสุดทุกๆ 2 รอบ และใช้งาน [Curse] เป็นเวลา 2 รอบ (คำสาป: เพิ่ม DMG 50% และทำให้ Rage เต็ม เมื่อใช้ Ultimate การโจมตีของมันเองจะใช้เวลาสองเท่า สร้างความเสียหายด้วยอัลติเมท
[Ability UP]: เก็นการ์โบราณจะค่อยๆ ได้รับสถิติและบูสต์การโจมตีเมื่อได้รับความเสียหายมากขึ้น]]
	},
