	[252011] = {
		describe_vn = "O Antigo Alakazam bate nas colheres para criar uma luz, dobrando SP.ATK e SP.DEF para 1 sombra por 3 rodadas\n#C0xFF9900#Ataque Básico de Equipe Dupla:#C0x5B545B#Inflige certos#C0xF13B54#SP.DMG#C0x5B545B#e aplica 40% de vulnerabilidade ao alvo (não pode ser dissipado) por 1 rodada. Acumula até 5 vezes",
		describe_kr = "고대 알라카잠은 숟가락을 두드려 빛을 만들고 3라운드 동안 1개의 그림자에 대해 SP.ATK 및 SP.DEF를 두 배로 늘립니다\n#C0xFF9900#더블 팀 기본 공격:#C0x5B545B#특정한 영향#C0xF13B54#SP.DMG#C0x5B545B#을 적용하고 적용합니다. 1 라운드 동안 대상에 대한 40% 취약성(해제 불가) 최대 5회까지 중첩됩니다.",
		describe_en = "Ancient Alakazam knocks the spoons to create a light, doubling SP.ATK and SP.DEF for 1 shadow for 3 rounds\n#C0xFF9900#Double Team Basic Attack:#C0x5B545B#Inflicts certain#C0xF13B54#SP.DMG#C0x5B545B#and applies 40% Vulnerability to the target (cannot be dispelled) for 1 round. Stacks up to 5 times",
		describe_id = "Alakazam kuno mengetuk sendok untuk menciptakan SP.ATK dan SP.DEF yang ringan, menggandakan SP.ATK dan SP.DEF untuk 1 bayangan selama 3 ronde\n#C0xFF9900#Serangan Dasar Tim Ganda:#C0x5B545B#Menimbulkan efek tertentu#C0xF13B54#SP.DMG#C0x5B545B#dan berlaku 40% Kerentanan terhadap target (tidak dapat dihilangkan) selama 1 putaran. Menumpuk hingga 5 kali",
		id = 252011,
		describe_es = "El antiguo Alakazam golpea las cucharas para crear una luz, duplicando SP.ATK y SP.DEF para 1 sombra durante 3 rondas\n#C0xFF9900#Ataque básico de equipo doble:#C0x5B545B#Inflige ciertos#C0xF13B54#SP.DMG#C0x5B545B#y aplica 40% de vulnerabilidad al objetivo (no se puede disipar) durante 1 ronda. Se acumula hasta 5 veces",
		describe_th = "อลาคาซัมโบราณเคาะช้อนเพื่อสร้างแสง เพิ่ม SP.ATK และ SP.DEF เป็นสองเท่าเป็นเวลา 1 เงาเป็นเวลา 3 รอบ\n#C0xFF9900#การโจมตีปกติแบบทีมคู่:#C0x5B545B#สร้างความเสียหายแน่นอน#C0xF13B54#SP.DMG#C0x5B545B#และใช้ ความอ่อนแอต่อเป้าหมาย 40% (ไม่สามารถลบล้างได้) เป็นเวลา 1 รอบ ซ้อนได้ถึง 5 ครั้ง"
	},
	[252012] = {
		describe_vn = "O antigo Alakazam fica no ar para concentrar sua força de vontade. Cura todas as sombras até o ponto em que elas tenham o mesmo HP que a sombra com o HP mais alto. (Se houver apenas 1 sombra, restaura 100% do HP dela.) Dá uma sombra aleatória [Reflect] por 3 rodadas (Refletir: aumenta 30% de redução de DMG e 100% de taxa de reflexão)\n#C0xFF9900#Double Team Small Move: #C0x5B545B#Inflige certos#C0xF13B54#SP.DMG#C0x5B545B#e reduz 25% de Precisão por 2 rodadas (Acumula até 2 vezes)",
		describe_kr = "고대 알라카잠은 의지력을 집중하기 위해 공중에 떠있습니다. 모든 그림자의 HP가 가장 높은 그림자와 같은 HP가 되도록 치유합니다. (그림자가 1개만 있으면 HP가 100% 회복됩니다.) 3라운드 동안 무작위 그림자 [Reflect] 제공 (반사: 데미지 감소 30% 및 반사율 100% 증가)\n#C0xFF9900#더블 팀 소형 이동: #C0x5B545B#특정 피해를 입히고#C0xF13B54#SP.DMG#C0x5B545B#2라운드 동안 정확도 25% 감소(최대 2회 중첩)",
		describe_en = "Ancient Alakazam sits in the air to focus its willpower. Heals all shadows to the point they have the same HP as the shadow with the highest HP. (If there is only 1 shadow, restores 100% HP for it.) Gives a random shadow [Reflect] for 3 rounds (Reflect: Increases 30% DMG Reduction and 100% Reflection Rate)\n#C0xFF9900#Double Team Small Move:#C0x5B545B#Inflicts certain#C0xF13B54#SP.DMG#C0x5B545B#and reduces 25% Accuracy for 2 rounds (Stacks up to 2 times)",
		describe_id = "Alakazam kuno berada di udara untuk memfokuskan tekadnya. Menyembuhkan semua bayangan hingga mereka memiliki HP yang sama dengan bayangan dengan HP tertinggi. (Jika hanya ada 1 bayangan, memulihkan 100% HPnya.) Memberikan bayangan acak [Reflect] selama 3 ronde (Refleksi: Meningkatkan 30% Pengurangan DMG dan 100% Tingkat Refleksi)\n#C0xFF9900#Gerakan Kecil Tim Ganda: #C0x5B545B#Menimbulkan#C0xF13B54#SP.DMG#C0x5B545B#tertentu dan mengurangi 25% Akurasi selama 2 ronde (Stack hingga 2 kali)",
		id = 252012,
		describe_es = "El antiguo Alakazam se sienta en el aire para concentrar su fuerza de voluntad. Cura todas las sombras hasta el punto de que tienen el mismo HP que la sombra con mayor HP. (Si solo hay 1 sombra, restaura el 100% de HP). Da una sombra aleatoria [Reflect] durante 3 rondas (Reflejo: aumenta el 30% de reducción de daño y el 100% de tasa de reflexión)\n#C0xFF9900#Movimiento pequeño de equipo doble: #C0x5B545B#Inflige ciertos#C0xF13B54#SP.DMG#C0x5B545B#y reduce el 25% de precisión durante 2 rondas (se acumula hasta 2 veces)",
		describe_th = "Alakazam โบราณนั่งอยู่ในอากาศเพื่อมุ่งความสนใจไปที่พลังจิตของตน รักษาเงาทั้งหมดจนถึงจุดที่มี HP เท่ากันกับเงาที่มี HP สูงสุด (หากมีเงาเพียง 1 อัน จะฟื้นฟู HP 100% ให้กับมัน) ให้เงาแบบสุ่ม [Reflect] เป็นเวลา 3 รอบ (สะท้อนกลับ: เพิ่มการลด DMG 30% และอัตราการสะท้อน 100%) \n#C0xFF9900#Double Team Small Move: #C0x5B545B#สร้างความเสียหายแน่นอน#C0xF13B54#SP.DMG#C0x5B545B#และลดความแม่นยำ 25% เป็นเวลา 2 รอบ (ซ้อนทับได้สูงสุด 2 ครั้ง)"
	},
	[252013] = {
		describe_vn = "O antigo Alakazam ataca todos os inimigos com intenso poder psíquico, infligindo massivo#C0xF13B54#SP.DMG#C0x5B545B#. Solicita que todas as sombras desferam ataque básico ao inimigo. Se um inimigo for nocauteado, cura instantaneamente todos os aliados de acordo com o HP máximo do inimigo. Depois de lançar Ultimate pela 2ª vez, se houver mais inimigos do que aliados, Ancient Alakazam aumenta temporariamente a Taxa Crítica de 60% para todos os aliados por 1 rodada. No status Anger, Ancient Alakazam silencia todos os inimigos por 2 rodadas",
		describe_kr = "고대 알라카잠은 강렬한 정신력으로 적 전체를 공격해 엄청난 피해를 입힙니다#C0xF13B54#SP.DMG#C0x5B545B#. 모든 그림자에게 적에게 기본 공격을 가하도록 요청합니다. 적이 쓰러지면 적의 최대 HP만큼 아군 전체를 즉시 회복시킵니다. 궁극기 2회 시전 후 아군보다 적이 많을 경우 고대 알라카잠이 1라운드 동안 아군 전체의 치명타율을 일시적으로 60% 증가시킵니다. 분노 상태에서 고대 알라카잠은 2라운드 동안 모든 적을 침묵시킵니다.",
		describe_en = "Ancient Alakazam attacks all enemies with intense psychic power, inflicting massive#C0xF13B54#SP.DMG#C0x5B545B#. Requests all shadows to deal basic attack to the enemy. If an enemy is knocked out, instantly heals all allies by the max HP of the enemy. After casting Ultimate for the 2nd time, if there are more enemies than allies, Ancient Alakazam temporarily increases 60% Crit Rate for all allies for 1 round. In the Anger status, Ancient Alakazam silences all enemies for 2 rounds",
		describe_id = "Alakazam kuno menyerang semua musuh dengan kekuatan psikis yang kuat, menimbulkan#C0xF13B54#SP.DMG#C0x5B545B# secara besar-besaran. Meminta semua bayangan untuk memberikan serangan dasar ke musuh. Jika musuh tersingkir, langsung menyembuhkan semua sekutu sebanyak HP maksimum musuh. Setelah mengeluarkan Ultimate untuk kedua kalinya, jika jumlah musuh lebih banyak dari sekutu, Alakazam Kuno untuk sementara meningkatkan 60% Crit Rate untuk semua sekutu selama 1 ronde. Dalam status Anger, Alakazam Kuno membungkam semua musuh selama 2 ronde",
		id = 252013,
		describe_es = "El antiguo Alakazam ataca a todos los enemigos con un intenso poder psíquico, infligiendo un masivo#C0xF13B54#SP.DMG#C0x5B545B#. Solicita a todas las sombras que realicen un ataque básico al enemigo. Si un enemigo es noqueado, cura instantáneamente a todos los aliados con el HP máximo del enemigo. Después de lanzar Ultimate por segunda vez, si hay más enemigos que aliados, Ancient Alakazam aumenta temporalmente un 60 % de índice de críticos para todos los aliados durante 1 ronda. En el estado de ira, el antiguo Alakazam silencia a todos los enemigos durante 2 rondas.",
		describe_th = "อลาคาซัมโบราณโจมตีศัตรูทั้งหมดด้วยพลังจิตอันเข้มข้น สร้างความเสียหายมหาศาล#C0xF13B54#SP.DMG#C0x5B545B# ร้องขอเงาทั้งหมดเพื่อสร้างการโจมตีพื้นฐานให้กับศัตรู หากศัตรูถูกทำให้ล้ม จะรักษาพันธมิตรทั้งหมดทันทีตาม HP สูงสุดของศัตรู หลังจากร่ายท่าไม้ตายเป็นครั้งที่ 2 หากมีศัตรูมากกว่าพันธมิตร Ancient Alakazam จะเพิ่มอัตราคริติคอล 60% ให้กับพันธมิตรทั้งหมดชั่วคราวเป็นเวลา 1 รอบ ในสถานะความโกรธ อาลาคาซัมโบราณจะปิดเสียงศัตรูทั้งหมดเป็นเวลา 2 รอบ"
	},
