	[260011] = {
		describe_vn = "O Robô Meowth atinge um único alvo com seu corpo, causando #C0xF13B54#dano físico#C0x5B545B#, e tem 50% de chance de adicionar [Greedy] por 4 rodadas",
		describe_kr = "로봇 나옹은 몸으로 단일 대상을 공격하여 #C0xF13B54#물리 피해#C0x5B545B#를 입히고 4라운드 동안 50% 확률로 [Greedy]를 추가합니다.",
		describe_en = "The Robot Meowth hits a single target with its body, causing #C0xF13B54#physical damage#C0x5B545B#, and has a 50% chance to add [Greedy] for 4 rounds",
		describe_id = "Robot Meowth mengenai satu target dengan tubuhnya, menyebabkan #C0xF13B54#kerusakan fisik#C0x5B545B#, dan berpeluang 50% menambah [Greedy] selama 4 ronde",
		id = 260011,
		describe_es = "El Robot Meowth golpea un solo objetivo con su cuerpo, causando #C0xF13B54#daño físico#C0x5B545B#, y tiene un 50 % de posibilidades de sumar [Greedy] durante 4 rondas.",
		describe_th = "หุ่นยนต์เหมียวโจมตีเป้าหมายเดียวด้วยร่างกาย ทำให้เกิด #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# และมีโอกาส 50% ที่จะเพิ่ม [Greedy] เป็นเวลา 4 รอบ"
