	[260012] = {
		describe_vn = "O Robô Meowth lança raios de dinheiro dos óculos mecânicos para atacar o alvo, causando muitos #C0xF13B54#danos físicos#C0x5B545B#, e adicionando 1 camada de【Ganancioso】\n【#L10#Ganancioso#L0#】: Não pode ser dissipado,【Ganancioso】 O dano recebido pelo alvo é aumentado em 20%, e antes do início da rodada de ação, 3% do HP máximo do alvo será perdido (pode ser sobreposto a 5 camadas)",
		describe_kr = "로봇야옹은 기계안경에서 돈광선을 발사해 대상을 공격해 #C0xF13B54#물리적 데미지#C0x5B545B#를 많이 입히고,【욕심】\n【#L10#욕심#L0#】을 1겹 추가: 불가능 디스펠,【탐욕】 대상이 받는 피해가 20% 증가하고, 액션 라운드 시작 전 대상의 최대 HP가 3% 감소합니다. (5겹 중첩 가능)",
		describe_en = "The Robot Meowth launches money rays from the mechanical glasses to attack the target, causing a lot of #C0xF13B54#physical damage#C0x5B545B#, and adding 1 layer of【Greedy】\n【#L10#Greedy#L0#】: Cannot be dispelled,【 Greedy】 The damage taken by the target is increased by 20%, and before the start of the action round, 3% of the target's maximum HP will be lost (can be superimposed to 5 layers)",
		describe_id = "Robot Meowth meluncurkan sinar uang dari kacamata mekanis untuk menyerang target, menyebabkan banyak #C0xF13B54#kerusakan fisik#C0x5B545B#, dan menambahkan 1 lapisan 【Serakah】\n【#L10#Serakah#L0#】: Tidak bisa dihilangkan, 【 Serakah】 Kerusakan yang diterima target meningkat sebesar 20%, dan sebelum ronde aksi dimulai, 3% dari HP maksimum target akan hilang (dapat ditumpangkan hingga 5 lapisan)",
		id = 260012,
		describe_es = "El Robot Meowth lanza rayos de dinero desde las gafas mecánicas para atacar al objetivo, causando muchos #C0xF13B54#daños físicos#C0x5B545B# y agregando 1 capa de 【Codicioso】\n【#L10#Codicioso#L0#】: No puede ser disipado, 【Codicioso】 El daño recibido por el objetivo aumenta en un 20%, y antes del inicio de la ronda de acción, se perderá el 3% del HP máximo del objetivo (se puede superponer en 5 capas)",
		describe_th = "หุ่นยนต์เหมียวปล่อยรังสีเงินจากแว่นตากลเข้าโจมตีเป้าหมาย ทำให้เกิด #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# จำนวนมาก และเพิ่ม【โลภ】\n【#L10#โลภ#L0#】 1 ชั้น: ไม่สามารถ หายไป,【 ความโลภ】 ความเสียหายที่ได้รับโดยเป้าหมายเพิ่มขึ้น 20% และก่อนเริ่มรอบแอ็คชั่น 3% ของ HP สูงสุดของเป้าหมายจะหายไป (สามารถซ้อนทับได้ถึง 5 ชั้น)"
	},
	[260013] = {
		describe_vn = "O Robô Meowth lança moedas de ouro de seus braços para atacar todos os alvos inimigos, causando excesso de #C0xF13B54#dano físico#C0x5B545B#, e tem certa probabilidade de adicionar 1 a 2 rodadas【Suborno】\n【#L10#Suborno#L0# 】: Pode ser dissipado, controle unidades inimigas para atacar elfos amigos",
		describe_kr = "로봇야옹은 팔에서 금화를 발사해 모든 적 대상을 공격해 #C0xF13B54#과잉 물리 피해#C0x5B545B#를 입히고, 일정 확률로 1~2발의 【뇌물】\n【#L10#뇌물#L0#을 추가합니다. ] : 해제 가능, 적 유닛을 조종하여 아군 엘프를 공격",
		describe_en = "The Robot Meowth launches gold coins from its arms to attack all enemy targets, causing excess #C0xF13B54#physical damage#C0x5B545B#, and has a certain probability of adding 1 to 2 rounds【Bribery】\n【#L10#Bribery#L0#】 : Can be dispelled, control enemy units to attack friendly elves",
		describe_id = "Robot Meowth meluncurkan koin emas dari lengannya untuk menyerang semua target musuh, menyebabkan #C0xF13B54#kerusakan fisik#C0x5B545B# berlebih, dan memiliki kemungkinan tertentu untuk menambahkan 1 hingga 2 putaran 【Suap】\n【#L10#Suap#L0# 】 : Dapat dihilangkan, kendalikan unit musuh untuk menyerang elf teman",
		id = 260013,
		describe_es = "El Robot Meowth lanza monedas de oro desde sus brazos para atacar a todos los objetivos enemigos, causando un exceso de #C0xF13B54#daño físico#C0x5B545B#, y tiene cierta probabilidad de sumar de 1 a 2 rondas【Soborno】\n【#L10#Soborno#L0# 】 : Puede ser disipado, controla las unidades enemigas para atacar a los elfos amigos.",
		describe_th = "หุ่นยนต์เหมียวปล่อยเหรียญทองจากแขนเพื่อโจมตีเป้าหมายศัตรูทั้งหมด ทำให้เกิดความเสียหายเกิน #C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# และมีความเป็นไปได้ที่จะเพิ่ม 1 ถึง 2 รอบ【การติดสินบน】\n【#L10#การติดสินบน#L0# ] : สามารถปัดเป่าได้ ควบคุมยูนิตศัตรูเพื่อโจมตีเอลฟ์ฝ่ายเดียวกัน"
	},
	[260014] = {
		describe_vn = "O Robô Meowth dispara raios de dinheiro dos óculos mecânicos para atacar o alvo, causando muitos #C0xF13B54#danos físicos#C0x5B545B#, e adicionando 1 camada de【Ganancioso】\n【#L10#Ganancioso#L0#】: Não pode ser dissipado,【Ganancioso]】O dano recebido pelo alvo é aumentado em 30% (até 10 camadas)",
		describe_kr = "로봇야옹은 기계안경에서 돈광선을 쏘아 대상을 공격하여 #C0xF13B54#물리적 데미지#C0x5B545B#를 많이 주고, 【탐욕】\n【#L10#탐욕#L0#】을 1겹 추가: 불가능 디스펠됨,【탐욕]】대상이 받는 피해가 30% 증가합니다. (최대 10겹)",
		describe_en = "The Robot Meowth shoots money rays from the mechanical glasses to attack the target, causing a lot of #C0xF13B54#physical damage#C0x5B545B#, and adding 1 layer of【Greedy】\n【#L10#Greedy#L0#】: Cannot be dispelled,【 Greedy]】The damage taken by the target is increased by 30% (up to 10 layers)",
		describe_id = "Robot Meowth menembakkan sinar uang dari kacamata mekanis untuk menyerang target, menyebabkan banyak #C0xF13B54#kerusakan fisik#C0x5B545B#, dan menambahkan 1 lapis 【Serakah】\n【#L10#Serakah#L0#】: Tidak bisa dihilangkan, 【Serakah]】 Kerusakan yang diterima target meningkat 30% (hingga 10 lapisan)",
		id = 260014,
