	[260026] = {
		describe_vn = [[
#L10#Corpo de aço: #L0# é imune a qualquer controle; ignora 50% da defesa dupla do alvo
#F20#
#F40##L10#Vontade de Ferro: #L0#O primeiro volume de sangue é inferior a 80%, 60%, 40%, 20%, e entra [Iron Will] por 1 rodada, [Iron Will] obtém 30% de redução de dano final e, quando atacado, usa ataques normais ou pequenas habilidades para contra-atacar o inimigo
#F20#
#F40## L10#A Força do Aço: #L0# Para cada 1% de perda de vida, o bônus de dano será aumentado em 1%, até 50%; quando atacado, há 30% de chance de usar o ataque normal para contra-atacar o inimigo]],
		describe_kr = [[
#L10#강철 몸체: #L0# 어떤 제어에도 면역입니다. 대상의 이중방어 50% 무시
#F20#
#F40##L10#철의 의지: #L0# 첫 번째 혈액량이 80%, 60%, 40%, 20% 미만이고 입력 [Iron Will] 1라운드 동안 [Iron Will] 최종 피해량이 30% 감소하고 공격을 받으면 일반 공격이나 소형 스킬을 사용하여 적을 반격합니다
#F20#
#F40## L10#강철의 힘: #L0# 생명력 손실이 1% 증가할 때마다 피해 보너스는 1%씩 최대 50%까지 증가합니다. 공격을 받으면 30% 확률로 일반 공격을 사용하여 적에게 반격합니다.]],
		describe_en = [[
#L10#Steel Body: #L0# is immune to any control; ignores 50% of the target's double defense
#F20#
#F40##L10#Iron Will: #L0#The first blood volume is lower than 80%, 60%, 40%, 20%, and enter [Iron Will] for 1 round, [Iron Will] gets 30% final damage reduction, and when attacked, use normal attacks or small skills to counterattack the enemy
#F20#
#F40## L10#The Strength of Steel: #L0# For every 1% loss of lost life, the damage bonus will be increased by 1%, up to 50%; when attacked, there is a 30% chance to use normal attack to counter the enemy]],
		describe_id = [[
#L10#Badan Baja: #L0# kebal terhadap kendali apa pun; mengabaikan 50% pertahanan ganda target
#F20#
#F40##L10#Iron Will: #L0#Volume darah pertama lebih rendah dari 80%, 60%, 40%, 20%, dan masuk [Iron Will] selama 1 ronde, [Iron Will] mendapat pengurangan damage akhir sebesar 30%, dan ketika diserang, gunakan serangan normal atau skill kecil untuk menyerang balik musuh
#F20#
#F40## L10#Kekuatan Baja: #L0# Untuk setiap 1% hilangnya nyawa, bonus kerusakan akan meningkat sebesar 1%, hingga 50%; ketika diserang, ada 30% kemungkinan menggunakan serangan normal untuk melawan musuh]],
		id = 260026,
		describe_es = [[
#L10#Cuerpo de Acero: #L0# es inmune a cualquier control; ignora el 50% de la doble defensa del objetivo
#F20#
#F40##L10#Voluntad de hierro: #L0#El primer volumen de sangre es inferior al 80%, 60%, 40%, 20% y entra [Iron Will] durante 1 ronda, [Iron Will] obtiene un 30% de reducción de daño final y, cuando es atacado, usa ataques normales o pequeñas habilidades para contraatacar al enemigo
#F20#
#F40## L10#La fuerza del acero: #L0# Por cada 1% de pérdida de vidas perdidas, la bonificación de daño se incrementará en un 1%, hasta un 50%; cuando es atacado, hay un 30% de posibilidades de usar un ataque normal para contrarrestar al enemigo]],
		describe_th = [[
#L10#ตัวเหล็ก: #L0# มีภูมิคุ้มกันต่อการควบคุมใดๆ ละเว้นการป้องกันสองเท่าของเป้าหมาย 50%
#F20#
#F40##L10#เจตจำนงเหล็ก: #L0#ปริมาตรเลือดแรกต่ำกว่า 80%, 60%, 40%, 20% และป้อน [Iron Will] สำหรับ 1 รอบ [Iron Will] ได้รับการลดความเสียหายสุดท้าย 30% และเมื่อถูกโจมตี ให้ใช้การโจมตีปกติหรือทักษะขนาดเล็กเพื่อตอบโต้ศัตรู
#F20#
#F40## L10#ความแข็งแกร่งของเหล็ก: #L0# ทุกๆ 1% ของการสูญเสียชีวิต โบนัสความเสียหายจะเพิ่มขึ้น 1% สูงสุด 50% เมื่อถูกโจมตี มีโอกาส 30% ที่จะใช้การโจมตีปกติตอบโต้ศัตรู]]
	},
	[260031] = {
		describe_vn = "Tentacruel Mecânico usa Arraia Tóxica para atacar um único inimigo, distribuindo #C0xF13B54# SP.ATK #C0x5B545B#, e tem 50% de chance de infligir [Badly Poison] por 3 rodadas.",
		describe_kr = "기계 텐타크루엘은 독성 가오리를 사용하여 적 한 명을 공격하여 #C0xF13B54# SP.ATK #C0x5B545B#를 입히고 3라운드 동안 50% 확률로 [Badly Poison]를 입힙니다.",
		describe_en = "Mechanical Tentacruel uses Toxic Stingray to attack a single enemy, dealing #C0xF13B54# SP.ATK #C0x5B545B#, and has a 50% chance to inflict [Badly Poison] for 3 rounds.",
		describe_id = "Tentacruel Mekanik menggunakan Toxic Stingray untuk menyerang satu musuh, menimbulkan #C0xF13B54# SP.ATK #C0x5B545B#, dan berpeluang 50% menimbulkan [Badly Poison] selama 3 ronde.",
		id = 260031,
		describe_es = "Mechanical Tentacruel usa Toxic Stingray para atacar a un solo enemigo, causando #C0xF13B54# SP.ATK #C0x5B545B# y tiene un 50 % de posibilidades de infligir [Badly Poison] durante 3 rondas.",
		describe_th = "หนวดหมึกจักรกลใช้ปลากระเบนพิษโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0xF13B54# SP.ATK #C0x5B545B# และมีโอกาส 50% ที่จะสร้างความเสียหาย [Badly Poison] เป็นเวลา 3 รอบ"
	},
	[260032] = {
		describe_vn = "Tentacruel Mecânico usa Entangling Strike para atacar um único inimigo, causando #C0xF13B54# SP.ATK#C0x5B545B# massivo, e tem 100% de chance de infligir [Badly Poison] por 3 rodadas (Envenenado é um efeito negativo que tem 40% de chance de impede o alvo de agir antes de cada rodada e causa dano verdadeiro adicional igual a 100% do bônus de dano de ataque especial do alvo. Pode acumular até 10 camadas). Além disso, há 50% de chance de invocar um Tentacool em um espaço vazio, que herda 10% da saúde máxima e 50% dos atributos do Tentacool (os ataques do Tentacool também infligem Envenenado)",
		describe_kr = "Mechanical Tentacruel은 Entangling Strike를 사용하여 적 한 명을 공격하여 엄청난 #C0xF13B54# SP.ATK#C0x5B545B#을 입히고 3라운드 동안 100% 확률로 [Badly Poison]를 입힙니다. (중독은 40% 확률로 부정적인 효과입니다. 각 라운드 전에 대상이 행동을 취하는 것을 방지하고 대상의 특수 공격 피해 보너스의 100%에 해당하는 추가 고정 피해를 입힙니다. 최대 10겹까지 쌓일 수 있습니다. 또한, 50% 확률로 빈 슬롯에 텐타쿨을 소환합니다. 이 텐타쿨은 최대 생명력의 10%와 텐타쿨의 속성을 50% 상속합니다. (텐타쿨의 공격에도 중독 효과가 적용됩니다.)",
		describe_en = "Mechanical Tentacruel uses Entangling Strike to attack a single enemy, dealing massive #C0xF13B54# SP.ATK#C0x5B545B#, and has a 100% chance to inflict [Badly Poison] for 3 rounds (Poisoned is a negative effect that has a 40% chance to prevent the target from taking action before each round, and causes additional true damage equal to 100% of the target's special attack damage bonus. It can stack up to 10 layers). Additionally, there is a 50% chance to summon an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned)",
		describe_id = "Tentacruel Mekanik menggunakan Entangling Strike untuk menyerang satu musuh, menimbulkan #C0xF13B54# SP.ATK#C0x5B545B# dalam jumlah besar, dan berpeluang 100% menimbulkan [Badly Poison] selama 3 ronde (Poisoned adalah efek negatif yang berpeluang 40% untuk menimbulkan undefined SP.ATKundefined mencegah target mengambil tindakan sebelum setiap putaran, dan menyebabkan kerusakan nyata tambahan sebesar 100% bonus kerusakan serangan khusus target. Dapat ditumpuk hingga 10 lapisan). Selain itu, ada peluang 50% untuk memanggil Tentacool di slot kosong, yang mewarisi 10% kesehatan maksimum dan 50% atribut Tentacool (serangan Tentacool juga menimbulkan Keracunan)",
		id = 260032,
		describe_es = "Mechanical Tentacruel usa Entangling Strike para atacar a un solo enemigo, causando un enorme #C0xF13B54# SP.ATK#C0x5B545B#, y tiene un 100 % de probabilidad de infligir [Badly Poison] durante 3 rondas (Envenenado es un efecto negativo que tiene un 40 % de probabilidad de evita que el objetivo actúe antes de cada ronda y causa daño verdadero adicional equivalente al 100% del bono de daño de ataque especial del objetivo. Puede acumularse hasta 10 capas). Además, existe un 50 % de posibilidades de invocar un Tentacool en un espacio vacío, que hereda el 10 % de la salud máxima y el 50 % de los atributos del Tentacool (los ataques de Tentacool también infligen envenenamiento).",
		describe_th = "หนวดเครื่องจักรจักรกลใช้ Entangling Strike เพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหายมหาศาล #C0xF13B54# SP.ATK#C0x5B545B# และมีโอกาส 100% ที่จะสร้างความเสียหาย [Badly Poison] เป็นเวลา 3 รอบ (พิษเป็นเอฟเฟกต์ด้านลบที่มีโอกาส 40% ที่จะสร้าง ป้องกันไม่ให้เป้าหมายดำเนินการก่อนแต่ละรอบและสร้างความเสียหายจริงเพิ่มเติมเท่ากับ 100% ของโบนัสความเสียหายจากการโจมตีพิเศษของเป้าหมาย สามารถซ้อนได้สูงสุด 10 ชั้น) นอกจากนี้ มีโอกาส 50% ที่จะเรียก Tentacool ในช่องว่าง ซึ่งจะได้รับ 10% ของพลังชีวิตสูงสุด และ 50% ของคุณสมบัติของ Tentacool (การโจมตีของ Tentacool จะทำให้ติดพิษด้วย)"
	},
	[260033] = {
		describe_vn = "Tentacruel Mecânico dispara Arraia Tóxica em todos os inimigos, causando #C0xF13B54# SP.ATK #C0x5B545B# massivo. Em seguida, ele comanda um Tentacool Mecânico aleatório para envolver um inimigo por 1 rodada, impedindo-o de agir. Quando qualquer unidade inimiga entra em ação, o inimigo envolvido causa dano verdadeiro massivo igual ao bônus SP.ATK do alvo. O alvo morrerá ou retornará à sua posição original após 1 rodada",
		describe_kr = "기계 텐타크루엘이 모든 적에게 독성 가오리를 발사해 막대한 피해를 입힙니다 #C0xF13B54# SP.ATK #C0x5B545B#. 그런 다음 무작위 기계식 텐타쿨을 명령하여 1라운드 동안 적을 감싸 행동을 취하지 못하게 합니다. 적 유닛이 행동을 취하면, 감싸인 적은 대상의 SP.ATK 보너스와 동일한 막대한 고정 피해를 입힙니다. 대상은 1라운드 후에 사망하거나 원래 위치로 돌아갑니다.",
		describe_en = "Mechanical Tentacruel fires Toxic Stingray at all enemies, dealing massive #C0xF13B54# SP.ATK #C0x5B545B#. It then commands a random Mechanical Tentacool to wrap around an enemy for 1 round, preventing it from taking action. When any enemy unit takes action, the wrapped enemy deals massive true damage equal to the target's SP.ATK bonus. The target will die or return to its original position after 1 round",
		describe_id = "Tentacruel Mekanik menembakkan Ikan Pari Beracun ke semua musuh, menghasilkan #C0xF13B54# SP.ATK #C0x5B545B# dalam jumlah besar. Ia kemudian memerintahkan Tentacool Mekanik acak untuk membungkus musuh selama 1 putaran, mencegahnya mengambil tindakan. Saat unit musuh mengambil tindakan, musuh yang terbungkus akan menimbulkan kerusakan nyata yang besar setara dengan bonus SP.ATK target. Target akan mati atau kembali ke posisi semula setelah 1 putaran",
		id = 260033,
		describe_es = "Mechanical Tentacruel dispara Toxic Stingray a todos los enemigos, causando un enorme #C0xF13B54# SP.ATK #C0x5B545B#. Luego ordena a un Tentacool mecánico aleatorio que envuelva a un enemigo durante 1 ronda, impidiéndole actuar. Cuando cualquier unidad enemiga entra en acción, el enemigo envuelto inflige un daño verdadero masivo igual al bono SP.ATK del objetivo. El objetivo morirá o volverá a su posición original después de 1 ronda.",
		describe_th = "หนวดจักรกลยิงปลากระเบนพิษใส่ศัตรูทั้งหมด สร้างความเสียหายมหาศาล #C0xF13B54# SP.ATK #C0x5B545B# จากนั้นจะสั่งให้เต็นท์กลไกแบบสุ่มพันรอบๆ ศัตรูเป็นเวลา 1 รอบ เพื่อป้องกันไม่ให้มีการดำเนินการ เมื่อยูนิตศัตรูออกคำสั่ง ศัตรูที่ถูกห่อไว้จะสร้างความเสียหายจริงมหาศาลเท่ากับโบนัส SP.ATK ของเป้าหมาย เป้าหมายจะตายหรือกลับสู่ตำแหน่งเดิมหลังจากผ่านไป 1 รอบ"
	},
	[260036] = {
		describe_vn = [[
L10#Charge, my minions!#L0#: The Mechanical Tentacruel is immune to any control effects. At the beginning of each round, it summons an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned). Damage received by the Tentacool is proportionally transferred to the Tentacruel
#F20#
#F40##L10#Explosão de Máquina:#L0# Quando o Tentacruel Mecânico morre, ele explode, causando 60% de dano de Veneno a todas as unidades inimigas e infligindo Envenenado por 2 rodadas
#F20#
#F40##L10#Corrosão Tóxica:#L0# Cada vez que o Tentacruel inflige [Badly Poison] a um inimigo, ele aumenta seu ataque duplo e redução de dano em 10%. Cada vez que um Tentacool é invocado, ele aumenta permanentemente sua redução de dano final em 10%.]],
		describe_kr = [[
L10#Charge, my minions!#L0#: The Mechanical Tentacruel is immune to any control effects. At the beginning of each round, it summons an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned). Damage received by the Tentacool is proportionally transferred to the Tentacruel
#F20#
#F40##L10#기계 폭발:#L0# 기계 텐타크루엘이 죽으면 폭발하여 모든 적 유닛에게 60%의 독 피해를 주고 2라운드 동안 중독 상태를 입힙니다
#F20#
#F40##L10#독성 부식:#L0# 텐타크루엘이 적에게 [Badly Poison]를 입힐 때마다 듀얼 공격력과 데미지 감소량이 10%씩 증가합니다. Tentacool이 소환될 때마다 최종 데미지 감소량이 10%씩 영구적으로 증가합니다.]],
		describe_en = [[
L10#Charge, my minions!#L0#: The Mechanical Tentacruel is immune to any control effects. At the beginning of each round, it summons an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned). Damage received by the Tentacool is proportionally transferred to the Tentacruel
#F20#
#F40##L10#Machine Explosion:#L0# When the Mechanical Tentacruel dies, it explodes, dealing 60% Poison damage to all enemy units and inflicting Poisoned for 2 rounds
#F20#
#F40##L10#Toxic Corrosion:#L0# Each time the Tentacruel inflicts [Badly Poison] on an enemy, it increases its dual attack and damage reduction by 10%. Each time an Tentacool is summoned, it permanently increases its final damage reduction by 10%.]],
		describe_id = [[
L10#Charge, my minions!#L0#: The Mechanical Tentacruel is immune to any control effects. At the beginning of each round, it summons an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned). Damage received by the Tentacool is proportionally transferred to the Tentacruel
#F20#
#F40##L10#Ledakan Mesin:#L0# Saat Tentacruel Mekanis mati, ia akan meledak, menimbulkan 60% kerusakan Racun ke semua unit musuh dan menimbulkan Keracunan selama 2 ronde
#F20#
#F40##L10# Korosi Beracun:#L0# Setiap kali Tentacruel memberikan [Badly Poison] pada musuh, serangan ganda dan pengurangan kerusakannya meningkat sebesar 10%. Setiap kali Tentacool dipanggil, pengurangan kerusakan terakhirnya secara permanen meningkat sebesar 10%.]],
		id = 260036,
		describe_es = [[
L10#Charge, my minions!#L0#: The Mechanical Tentacruel is immune to any control effects. At the beginning of each round, it summons an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned). Damage received by the Tentacool is proportionally transferred to the Tentacruel
#F20#
#F40##L10#Machine Explosion:#L0# When the Mechanical Tentacruel dies, it explodes, dealing 60% Poison damage to all enemy units and inflicting Poisoned for 2 rounds
#F20#
#F40##L10#Toxic Corrosion:#L0# Cada vez que el Tentacruel inflige [Badly Poison] sobre un enemigo, Aumenta su ataque dual y reducción de daño en un 10%. Cada vez que se invoca un Tentacool, aumenta permanentemente su reducción de daño final en un 10%.]],
		describe_th = [[
L10#Charge, my minions!#L0#: The Mechanical Tentacruel is immune to any control effects. At the beginning of each round, it summons an Tentacool in an empty slot, which inherits 10% of the maximum health and 50% of the attributes of the Tentacool (Tentacool's attacks also inflict Poisoned). Damage received by the Tentacool is proportionally transferred to the Tentacruel
#F20#
#F40##L10#เครื่องจักรระเบิด:#L0# เมื่อหนวดปลาหมึกตาย มันจะระเบิด สร้างความเสียหายพิษ 60% ให้กับยูนิตศัตรูทั้งหมด และทำให้ติดพิษเป็นเวลา 2 รอบ
#F20#
#F40##L10#การกัดกร่อนที่เป็นพิษ:#L0# แต่ละครั้งที่เทนทาครูลสร้างความเสียหายให้กับศัตรู [Badly Poison] จะเพิ่มการโจมตีคู่และลดความเสียหาย 10% ทุกครั้งที่เรียก Tentacool มันจะเพิ่มการลดความเสียหายสุดท้ายลง 10% อย่างถาวร]]
	},
