	[300051] = {
		describe_vn = "Coagule uma Hydro Bomb para atacar os inimigos com garras afiadas para lidar com#C0xE69900#100%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#.",
		describe_kr = "하이드로폭탄을 응고시켜 날카로운 발톱으로 적을 공격합니다#C0xE69900#100%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#.",
		describe_en = "Coagulate a Hydro Bomb to attack enemies with the sharp claws to deal#C0xE69900#100%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#.",
		describe_id = "Koagulasikan Hydro Bomb untuk menyerang musuh dengan cakar tajam untuk mengakibatkan#C0xE69900#100%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#.",
		id = 300051,
		describe_es = "Coagula una Hydro Bomb para atacar a los enemigos con las garras afiladas para tratar#C0xE69900#100%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#.",
		describe_th = "จับกลุ่มระเบิดพลังน้ำเพื่อโจมตีศัตรูด้วยกรงเล็บอันแหลมคมเพื่อสร้างความเสียหาย#C0xE69900#100%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#"
	},
	[300052] = {
		describe_vn = "Faça um Shuriken nas mãos e corra até os inimigos para lidar com#C0xE69900#200%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#. Se o HP do alvo for superior a 50%, esse dano aumenta em 30%",
		describe_kr = "손으로 수리검을 만들고 적에게 질주해 거래를 하세요#C0xE69900#200%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#. 대상의 HP가 50% 이상일 경우 피해량이 30% 증가합니다.",
		describe_en = "Make a Shuriken on hands and sprints to enemies to deal#C0xE69900#200%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#. If the target's HP is higher than 50%, this damage increased by 30%",
		describe_id = "Buat Shuriken di tangan dan lari ke musuh untuk menangani#C0xE69900#200%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#. Jika HP target lebih tinggi dari 50%, damage ini meningkat sebesar 30%.",
		id = 300052,
		describe_es = "Haz un Shuriken en las manos y corre hacia los enemigos para enfrentarlos#C0xE69900#200%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B#. Si el HP del objetivo es superior al 50%, este daño aumenta en un 30%.",
		describe_th = "สร้างชูริเคนในมือแล้ววิ่งไปหาศัตรูเพื่อสร้างความเสียหาย#C0xE69900#200%P.ATK#C0x5B545B#+$( skillLevel *24)$#C0xF13B54#P.DMG#C0x5B545B# หาก HP ของเป้าหมายสูงกว่า 50% ความเสียหายนี้จะเพิ่มขึ้น 30%"
	},
	[300053] = {
		describe_vn = "Greninja se divide em sombras de água e pula no ar e faz um Shuriken para lidar com os inimigos para lidar#C0xE69900#350%P.ATK#C0x5B545B#+$( skillLevel *36)$#C0xF13B54#P.DMG#C0x5B545B#. Este dano aumenta o crítico em 30% e o dano crítico em 20%",
		describe_kr = "그레닌자가 물그림자로 나뉘어 공중으로 뛰어올라 수리검을 만들어 적을 상대하도록 합니다#C0xE69900#350%P.ATK#C0x5B545B#+$( skillLevel *36)$#C0xF13B54#P.DMG#C0x5B545B#. 이 피해로 인해 치명타가 30% 증가하고 치명타 피해가 20% 증가합니다.",
