	[1000031] = {
		describe_vn = "Ataque os inimigos com um chicote de videira deal#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B# e converta 30% desse dano em seu próprio HP",
		describe_kr = "덩굴채찍딜로 적을 공격하고#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, 이 데미지의 30%를 자신의 HP로 전환",
		describe_en = "Attack enemies with a vine whip deal#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, and convert 30% of this damage to own HP for itself",
		describe_id = "Menyerang musuh dengan cambuk anggur#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, dan mengubah 30% kerusakan ini menjadi HP untuk dirinya sendiri",
		id = 1000031,
		describe_es = "Ataca a los enemigos con un látigo de vid#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B# y convierte el 30% de este daño en su propio HP.",
		describe_th = "โจมตีศัตรูด้วยแส้เถาวัลย์ #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B# และแปลง 30% ของความเสียหายนี้เป็น HP ของตัวเอง"
	},
	[1000032] = {
		describe_vn = "Atire folhas e corte inimigos para atacar para lidar com #C0x3D8A99#150%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, com 30% de chance de infligir efeito de veneno (o veneno pode ser acumulado até 5 vezes, e cada camada causa#C0x3D8A99#50%SP.ATK#C0x5B545B#dano verdadeiro por 2 rodadas); cure o companheiro de equipe com o HP mais baixo em#C0x3D8A99#100%SP.ATK#C0x5B545B#",
		describe_kr = "나뭇잎을 쏘고 적들을 베어 공격하여 딜을 합니다#C0x3D8A99#150%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, 30% 확률로 독 효과 부여 (독은 최대 5개까지 중첩 가능) 회, 각 레이어는 #C0x3D8A99#50%SP.ATK#C0x5B545B#2라운드 동안 실제 피해를 입힙니다); #C0x3D8A99#100%SP.ATK#C0x5B545B#로 HP가 가장 낮은 팀원을 치료하세요.",
		describe_en = "Shoot leaves and cut enemies to attack to deal#C0x3D8A99#150%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, with 30% chance to inflict Poison effect (Poison can be stacked up to 5 times, and each layer deals#C0x3D8A99#50%SP.ATK#C0x5B545B#true damage for 2 rounds); heal the teammate with the lowest HP by#C0x3D8A99#100%SP.ATK#C0x5B545B#",
		describe_id = "Tembak daun dan tebas musuh untuk menyerang untuk menimbulkan#C0x3D8A99#150%SP.ATK#C0x5B545B#+$(skillLevel*24)$#C0x8A5C99#SP.DMG#C0x5B545B#, dengan peluang 30% menimbulkan efek Racun (Racun dapat ditumpuk hingga 5 kali, dan setiap lapisan menimbulkan#C0x3D8A99#50%SP.ATK#C0x5B545B#kerusakan nyata selama 2 ronde); menyembuhkan rekan satu tim dengan HP terendah sebesar#C0x3D8A99#100%SP.ATK#C0x5B545B#",
