	[1019812] = {
		describe_vn = "Rayquaza voa em círculos e invoca um tornado para atacar um único alvo inimigo, distribuindo#C0xE69900#80% P.ATK#C0x5B545B#+#C0x3D8A99#80% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, que lança o alvo para o céu por 1 rodada (o alvo fica incapaz de atacar ou receber ataque). Quando o alvo pousa no chão, há 70% de chance de ele ficar atordoado por 1 rodada (a taxa de atordoamento aumenta quando o número de alvos próximos aumenta, até 100%)",
		describe_kr = "Rayquaza flies in circles and summons a tornado to attack single enemy target, dealing#C0xE69900#80% P.ATK#C0x5B545B#+#C0x3D8A99#80% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, which blows the target to the sky for 1 round (target is unable to attack or receive attack). When the target lands on the ground, there is a 70% chance that it will be stunned for 1 round (Stun rate increases when the number of nearby targets increase, up to 100%)",
		describe_en = "Rayquaza flies in circles and summons a tornado to attack single enemy target, dealing#C0xE69900#80% P.ATK#C0x5B545B#+#C0x3D8A99#80% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, which blows the target to the sky for 1 round (target is unable to attack or receive attack). When the target lands on the ground, there is a 70% chance that it will be stunned for 1 round (Stun rate increases when the number of nearby targets increase, up to 100%)",
		describe_id = "Rayquaza terbang berputar-putar dan memanggil tornado untuk menyerang satu target musuh, memberikan#C0xE69900#80% P.ATK#C0x5B545B#+#C0x3D8A99#80% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, yang melontarkan target ke langit selama 1 putaran (target tidak dapat menyerang atau menerima serangan). Saat target mendarat di tanah, terdapat 70% kemungkinan target akan terkena efek stun selama 1 putaran (Tingkat stun meningkat saat jumlah target di sekitar meningkat, hingga 100%)",
		id = 1019812,
		describe_es = "Rayquaza vuela en círculos y convoca un tornado para atacar a un solo objetivo enemigo, causando#C0xE69900#80% P.ATK#C0x5B545B#+#C0x3D8A99#80% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B#, que lanza al objetivo al cielo durante 1 ronda (el objetivo no puede atacar ni recibir ataques). Cuando el objetivo aterriza en el suelo, hay un 70 % de posibilidades de que quede aturdido durante 1 ronda (la tasa de aturdimiento aumenta cuando aumenta el número de objetivos cercanos, hasta un 100 %).",
		describe_th = "เรย์ควาซ่าบินเป็นวงกลมและเรียกพายุทอร์นาโดเข้าโจมตีศัตรูเป้าหมายเดียว สร้างความเสียหาย#C0xE69900#80% P.ATK#C0x5B545B#+#C0x3D8A99#80% SP.ATK#C0x5B545B#+$(skillLevel*4*48)$#C0xF13B54#SP.DMG#C0x5B545B# ซึ่งเป่าเป้าหมายขึ้นฟ้า 1 รอบ (เป้าหมายไม่สามารถโจมตีหรือรับการโจมตีได้) เมื่อเป้าหมายตกลงบนพื้น มีโอกาส 70% ที่จะติดสตัน 1 รอบ (อัตรา Stun เพิ่มขึ้นเมื่อจำนวนเป้าหมายใกล้เคียงเพิ่มขึ้น สูงสุด 100%)"
	},
	[1019813] = {
		describe_th = "Rayquaza บินขึ้นไปบนท้องฟ้าพร้อมกับนำศัตรูมาเรียงเป็นแถวก่อนจะปล่อยพลังอันมหาศาลออกมา สร้างความเสียหาย#C0xE69900#180% P.ATK#C0x5B545B#+#C0x3D8A99#180% SP พลังโจมตี#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#SP.DMG#C0x5B545B#. อีกทั้งยังสร้างสันติกับความก้าวร้าวของเป้าหมาย: ล็อคความโกรธของเป้าหมายไว้ 1 รอบ (ระดับความโกรธยังคงไม่เปลี่ยนแปลงเมื่อล็อคอิน)",
		describe_en = "Rayquaza flies to the sky while bringing its enemies in a row along, before releasing its massive power, dealing#C0xE69900#180% P.ATK#C0x5B545B#+#C0x3D8A99#180% SP. ATK#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#SP.DMG#C0x5B545B#. It also makes peace with the target's aggression: locking into the target's rage for 1 round (rage level remains unchanged when locked in)",
		simDesc_es = "Rayquaza vuela hacia el cielo mientras arrastra a sus enemigos en fila, antes de liberar su enorme poder y fijar el nivel de ira del objetivo.",
		describe_es = "Rayquaza vuela hacia el cielo mientras arrastra a sus enemigos en fila, antes de liberar su enorme poder, causando#C0xE69900#180% P.ATK#C0x5B545B#+#C0x3D8A99#180% SP. ATK#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#SP.DMG#C0x5B545B#. También hace las paces con la agresión del objetivo: bloquea la ira del objetivo durante 1 asalto (el nivel de ira permanece sin cambios cuando está bloqueado)",
		starEffectDesc_vn = "Causa dano verdadeiro adicional que é igual ao total de seu próprio P.ATK e SP.ATK (dano crítico pode ser causado e desconsidera a imunidade de SP.ATK e P.ATK)",
		starEffectDesc_id = "Menimbulkan tambahan true damage yang setara dengan total P.ATK dan SP.ATK miliknya (crit damage dapat diberikan dan mengabaikan imunitas SP.ATK dan P.ATK)",
		starEffectDesc_es = "Inflige daño verdadero adicional que es igual al total de su propio P.ATK y SP.ATK (se puede infligir daño crítico y no tiene en cuenta la inmunidad de SP.ATK y P.ATK)",
		describe_vn = "Rayquaza voa para o céu enquanto traz seus inimigos em uma fileira, antes de liberar seu enorme poder, distribuindo#C0xE69900#180% P.ATK#C0x5B545B#+#C0x3D8A99#180% SP. ATK#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#SP.DMG#C0x5B545B#. Também faz as pazes com a agressão do alvo: prendendo-se à raiva do alvo por 1 rodada (o nível de raiva permanece inalterado quando bloqueado)",
		starEffectDesc_th = "สร้างความเสียหายจริงเพิ่มเติมซึ่งเท่ากับผลรวมของ P.ATK และ SP.ATK ของตัวเอง (สามารถสร้างความเสียหายแบบคริติคอลได้ และไม่สนใจการป้องกัน SP.ATK และ P.ATK)",
		describe_id = "Rayquaza terbang ke langit sambil membawa musuh-musuhnya berturut-turut, sebelum melepaskan kekuatan besarnya, memberikan#C0xE69900#180% P.ATK#C0x5B545B#+#C0x3D8A99#180% SP. ATK#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#SP.DMG#C0x5B545B#. Ia juga berdamai dengan agresi target: mengunci kemarahan target selama 1 putaran (tingkat kemarahan tetap tidak berubah ketika terkunci)",
		simDesc_en = "Rayquaza flies to the sky while bringing its enemies in a row along, before releasing its massive power and locks into the target's rage level",
		simDesc_vn = "Rayquaza voa para o céu enquanto traz seus inimigos em uma fileira, antes de liberar seu enorme poder e travar no nível de raiva do alvo.",
		describe_kr = "레이콰자는 적을 일렬로 끌어들이며 하늘을 날아가며 엄청난 위력을 발산하며#C0xE69900#180% P.ATK#C0x5B545B#+#C0x3D8A99#180% SP를 줍니다. ATK#C0x5B545B#+$(skillLevel*4*80)$#C0xF13B54#SP.DMG#C0x5B545B#. 또한 대상의 공격성을 완화합니다. 1라운드 동안 대상의 분노를 고정합니다(고정되면 분노 수준은 변경되지 않습니다).",
		simDesc_th = "เรย์ควาซ่าบินขึ้นไปบนท้องฟ้าพร้อมกับนำศัตรูมาเรียงเป็นแถวก่อนจะปล่อยพลังอันมหาศาลออกมาและล็อกระดับความโกรธของเป้าหมาย",
		starEffectDesc_kr = "자신의 P.ATK와 SP.ATK의 합만큼 추가 고정 피해를 입힙니다. (치명타 피해도 입힐 수 있으며 SP.ATK와 P.ATK 면역은 무시됩니다.)",
		simDesc_kr = "레쿠아자가 하늘로 날아올라 적들을 일렬로 끌어들이고, 엄청난 힘을 방출해 대상의 분노 수준을 고정시킵니다.",
		starEffectDesc_en = "Deals additional true damage that is equal to the total of its own P.ATK and SP.ATK (crit damage can be dealt and disregards SP.ATK and P.ATK immunity)",
		id = 1019813,
		simDesc_id = "Rayquaza terbang ke langit sambil membawa musuh-musuhnya berturut-turut, sebelum melepaskan kekuatan besarnya dan mengunci tingkat kemarahan target."
	},
	[1022421] = {
		simDesc_vn = "Lucario avança antes de pular alto e dar um soco forte",
