	[1036312] = {
		zawakeSimpleDesc_kr = "#C0x5c9970#파워젬 실드의 실드값이 400%로 증가되며, 일시적으로 P.&Sp가 증가합니다. 방패 공격 전 공격력이 20%로 증가됩니다. 파워 젬 쉴드가 깨지면 시전자의 P. & Sp도 감소합니다. 2라운드 동안 공격력 15% 증가(2회 중첩 가능)",
		describe_th = "#C0xC0C0C0#แสงศักดิ์สิทธิ์ของเพชร โปรดโปรยลงมาให้เราหน่อย#C0x5B545B#\n#F10#\n#F40#Diancie ปล่อยแสงอันแรงกล้าจากอัญมณีบนหัวเพื่อโจมตีศัตรูตัวเดียว#C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#และสร้างโล่อัญมณีพลัง 2 รอบให้กับโปเกมอนฝ่ายเดียวกันที่มี P.ATK หรือ SP.ATK สูงสุด (สามารถรับความเสียหายได้ 300% รวม SP.DEF ของ Diancie และ ป้องกันภัย) สร้างโล่อัญมณีให้กับโปเกมอนประเภท Rock/Fairy แบบสุ่มอีกตัว นาน 2 รอบ เพิ่ม P.&Sp.ATK ชั่วคราว 10% ให้กับพันธมิตรด้วยโล่นี้ก่อนโจมตี (Power Gem ไม่สามารถทับซ้อนกันได้)",
		simDesc_es = "Diancie libera una luz deslumbrante de la gema en su cabeza para curar a todos los aliados.",
		describe_en = "#C0xC0C0C0#Holy light of Diamond, please rain on us#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on the head to attack single enemy#C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#and inflict a 2-round power gem shield to allied Pokémon with the highest P.ATK or SP.ATK (can absorb a damage of 300% sum Diancie's SP.DEF and P.DEF). Deals gem shield to another random Rock/Fairy type Pokémon, last for 2 rounds. Temporary increase 10% of P.&Sp.ATK to ally with this shield before attacking(Power Gem can not be stack)",
		simDesc_kr = "디안시가 머리에 있는 보석에서 눈부신 빛을 발산하여 아군 전체를 치유합니다.",
		describe_es = "#C0xC0C0C0#Santa luz de Diamante, por favor llueve sobre nosotros#C0x5B545B#\n#F10#\n#F40#Diancie libera una luz fuerte de la gema en la cabeza para atacar a un solo enemigo#C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#e inflige un escudo de gemas de poder de 2 rondas a los Pokémon aliados con el P.ATK o SP.ATK más alto (puede absorber un daño del 300 % sumando el SP.DEF de Diancie y P.DEF). Otorga un escudo de gemas a otro Pokémon aleatorio de tipo Roca/Hada y dura 2 rondas. Aumento temporal del 10% de P.&Sp.ATK para aliarse con este escudo antes de atacar (Power Gem no se puede acumular)",
		zawakeSimpleDesc_vn = "#C0x5c9970#O valor do escudo da gema de poder foi aumentado para 400%, e o P. & Sp. O ATK antes dos ataques do escudo é aumentado para 20%; quando o escudo da gema de poder é quebrado, ele também reduz o P. e Sp do lançador. ATK em 15% por 2 rodadas (pode acumular 2 vezes)",
		zawakeSimpleDesc_en = "#C0x5c9970#The shield value of the power gem shield is increased to 400%, and the temporarily increased P. & Sp. ATK before the shield attacks is increased to 20%; when the power gem shield is broken, it also reduces the caster's P. & Sp. ATK by 15% for 2 rounds (can stack 2 times)",
		describe_vn = "#C0xC0C0C0#Santa luz do Diamante, por favor chova sobre nós#C0x5B545B#\n#F10#\n#F40#Diancie libera uma luz forte da gema na cabeça para atacar um único inimigo#C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#e inflija um escudo de power gem de 2 rodadas a Pokémon aliados com o maior P.ATK ou SP.ATK (pode absorver um dano de 300% da soma do SP.DEF de Diancie e P.DEF). Oferece escudo de gema a outro Pokémon aleatório do tipo Pedra/Fada, durando 2 rodadas. Aumento temporário de 10% de P.&Sp.ATK para se aliar a este escudo antes de atacar (Power Gem não pode ser empilhado)",
		zawakeSimpleDesc_id = "#C0x5c9970#Nilai perisai dari perisai permata kekuatan ditingkatkan menjadi 400%, dan P. & Sp meningkat sementara. ATK sebelum serangan perisai ditingkatkan menjadi 20%; ketika perisai permata kekuatan rusak, itu juga mengurangi P. & Sp kastor. ATK sebesar 15% selama 2 ronde (bisa di stack 2 kali)",
		zawakeSimpleDesc_es = "#C0x5c9970#El valor del escudo de la gema de poder aumenta al 400%, y el P. & Sp. aumentado temporalmente. El ATK antes de los ataques del escudo aumenta al 20%; Cuando el escudo de la gema de poder se rompe, también reduce la P. y Sp del lanzador. ATK en un 15 % durante 2 rondas (se puede acumular 2 veces)",
		describe_id = "#C0xC0C0C0#Cahaya Suci Berlian, tolong hujani kami#C0x5B545B#\n#F10#\n#F40#Diancie melepaskan cahaya kuat dari permata di kepala untuk menyerang musuh tunggal#C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#dan memberikan perisai permata kekuatan 2 putaran kepada Pokémon sekutu dengan P.ATK atau SP.ATK tertinggi (dapat menyerap kerusakan sebesar 300% jumlah SP.DEF Diancie dan P.DEF). Memberikan perisai permata ke Pokémon tipe Batu/Peri acak lainnya, berlangsung selama 2 putaran. Peningkatan sementara 10% P.&Sp.ATK ke sekutu dengan perisai ini sebelum menyerang (Permata Kekuatan tidak dapat ditumpuk)",
		simDesc_en = "Diancie releases a dazzling light from the gem on its head to heal all allies",
		simDesc_vn = "Diancie libera uma luz ofuscante da gema em sua cabeça para curar todos os aliados",
		describe_kr = "#C0xC0C0C0#다이아몬드의 성스러운 빛, 비를 내려주세요#C0x5B545B#\n#F10#\n#F40#디안시는 머리에 있는 보석에서 강력한 빛을 발산하여 적 하나를 공격합니다#C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# P.ATK 또는 SP.ATK가 가장 높은 아군 포켓몬에게 2라운드 파워 보석 보호막을 적용합니다(Diancie의 SP.DEF 합계의 300% 피해를 흡수할 수 있으며 P.DEF). 2라운드 동안 지속되는 다른 무작위 바위/요정 유형 포켓몬에게 보석 보호막을 줍니다. 공격 전 이 쉴드를 사용하는 아군의 P.&Sp.ATK가 일시적으로 10% 증가합니다(파워 젬 중첩 불가)",
		simDesc_th = "Diancie ปล่อยแสงเจิดจ้าจากอัญมณีบนหัวเพื่อรักษาเพื่อนร่วมทีมทั้งหมด",
		zawakeSimpleDesc_th = "#C0x5c9970#ค่าโล่ของโล่อัญมณีพลังเพิ่มขึ้นเป็น 400% และค่า P. & Sp. เพิ่มขึ้นชั่วคราว ATK ก่อนการโจมตีด้วยโล่เพิ่มขึ้นเป็น 20%; เมื่อโล่อัญมณีพลังถูกทำลาย มันจะลด P. & Sp ของผู้ร่ายด้วย ATK 15% เป็นเวลา 2 รอบ (สามารถซ้อนได้ 2 ครั้ง)",
		id = 1036312,
		simDesc_id = "Diancie melepaskan cahaya menyilaukan dari permata di kepalanya untuk menyembuhkan semua sekutu"
	},
