	[2600804] = {
		starEffectDesc_es = "Efecto adicional: Steelix se venga realizando un contraataque cada vez que un aliado (excluido él mismo) con el HP más bajo recibe un ataque.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: Steelix แก้แค้นด้วยการโจมตีตอบโต้ทุกครั้งที่พันธมิตร (ไม่รวมตัวมันเอง) ที่มี HP ต่ำที่สุดได้รับการโจมตี",
		id = 2600804,
		starEffectDesc_vn = "Efeito adicional: Steelix se vinga fazendo um contra-ataque sempre que um aliado (excluindo ele mesmo) com o HP mais baixo recebe um ataque",
		starEffectDesc_kr = "추가 효과 : 스틸릭스는 HP가 가장 낮은 아군(자신 제외)이 공격을 받을 때마다 반격을 가해 복수한다.",
		starEffectDesc_id = "Efek tambahan: Steelix membalas dendam dengan melakukan serangan balik setiap kali sekutu (tidak termasuk dirinya sendiri) dengan HP terendah menerima serangan",
		starEffectDesc_en = "Additional effect: Steelix takes revenge by making a counter-attack whenever an ally (excluding itself) with the lowest HP receives an attack"
	},
	[2600814] = {
		describe_vn = "Ativa ao desmaiar, se houver ==1 aliado sobrevivente, dissipa o buff invencível de Steelix",
		describe_kr = "기절 시 발동, 살아남은 아군이 ==1인 경우 스틸릭스의 무적 버프를 해제합니다.",
		describe_en = "Triggers upon faint, if there is ==1 surviving ally, dispels the invincible buff from Steelix",
