	[3004313] = {
		describe_th = "Onix เขย่าอากาศและพื้นเพื่อโจมตีศัตรูทั้งหมดเพื่อสร้างความเสียหาย #C0xE69900#160%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B# ช่องว่างที่ใหญ่ขึ้นระหว่าง SPD ของตัวเองกับเป้าหมาย ยิ่งสร้างความเสียหายได้มากเท่าไร มากถึง 30%",
		describe_en = "Onix shakes the air and the ground to attack all enemies to deal #C0xE69900#160%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B#. The larger gap between SPD of itself and the target, the higher the the damage caused, up to 30%",
		simDesc_es = "Onix mueve su cuerpo para sacudir el aire y el suelo para atacar a todos los enemigos. Cuanto mayor sea la diferencia de velocidad entre Onix y el objetivo, mayor será el daño que inflige.",
		describe_es = "Onix sacude el aire y el suelo para atacar a todos los enemigos y repartir #C0xE69900#160%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B#. Cuanto mayor sea la brecha entre el SPD de sí mismo y el objetivo, mayor será el daño causado, hasta un 30%.",
		starEffectDesc_vn = "Efeito adicional: Há 35% de chance de empurrar aleatoriamente 1 Pokémon uma grade para frente (quando os Pokémon na linha de frente são derrotados)",
		starEffectDesc_id = "Efek tambahan: Ada 35% kemungkinan mendorong 1 Pokémon satu kotak ke depan secara acak (saat Pokémon di garis depan dikalahkan)",
		starEffectDesc_es = "Efecto adicional: hay un 35% de posibilidades de empujar aleatoriamente a 1 Pokémon una cuadrícula hacia adelante (cuando los Pokémon en la primera línea son derrotados)",
		describe_vn = "Onix sacode o ar e o solo para atacar todos os inimigos para lidar com #C0xE69900#160%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B#. Quanto maior a distância entre o SPD e o alvo, maior será o dano causado, até 30%",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: มีโอกาส 35% ที่จะสุ่มผลักโปเกมอน 1 ตัวไปข้างหน้าหนึ่งตาราง (เมื่อกำจัดโปเกมอนในแนวหน้าได้)",
		describe_id = "Onix mengguncang udara dan tanah untuk menyerang semua musuh untuk menghasilkan #C0xE69900#160%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B#. Semakin besar jarak antara SPD dirinya dan target, semakin tinggi damage yang ditimbulkan, hingga 30%",
		simDesc_en = "Onix moves its body to shake the air and the ground to attack all enemies. The larger the difference in speed between Onix and the target, the higher the damage it deals.",
		simDesc_vn = "Onix move seu corpo para sacudir o ar e o solo para atacar todos os inimigos. Quanto maior a diferença de velocidade entre o Onix e o alvo, maior será o dano que ele causa.",
		describe_kr = "오닉스가 공기와 땅을 흔들어 적 전체를 공격해 딜을 합니다 #C0xE69900#160%P.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#P.DMG#C0x5B545B#. 자신의 SPD와 대상 사이의 간격이 클수록 피해량이 증가하며 최대 30%까지 증가합니다.",
		simDesc_th = "Onix ขยับร่างกายเพื่อเขย่าอากาศและพื้นเพื่อโจมตีศัตรูทั้งหมด ยิ่งความเร็วระหว่าง Onix กับเป้าหมายแตกต่างกันมากเท่าใด ความเสียหายที่สร้างก็จะยิ่งสูงขึ้นเท่านั้น",
		starEffectDesc_kr = "추가 효과: 35% 확률로 무작위로 1마리의 포켓몬을 한 그리드 앞으로 밀어낸다(전선의 포켓몬이 쓰러졌을 때)",
		simDesc_kr = "오닉스는 몸을 움직여 공기와 땅을 흔들어 적 전체를 공격한다. 오닉스와 대상 사이의 속도 차이가 클수록 더 큰 데미지를 줍니다.",
		starEffectDesc_en = "Additional effect: There is a 35% chance of randomly pushing 1 Pokémon one grid forward (when Pokémons in the front line are defeated)",
		id = 3004313,
		simDesc_id = "Onix menggerakkan tubuhnya untuk mengguncang udara dan tanah untuk menyerang semua musuh. Semakin besar perbedaan kecepatan antara Onix dan target, maka semakin tinggi damage yang ditimbulkannya."
	},
