	[3011211] = {
		simDesc_vn = "Usando sua elasticidade, Azurill ataca o único alvo inimigo com sua cauda",
		describe_es = "Azurill usa la elasticidad de la cola para atacar a un solo enemigo y tratar#C0x3D8A99#80%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_th = "ด้วยการใช้หางที่เด้งกลับ Azurill โจมตีเป้าหมายศัตรูตัวเดียวด้วยหางของมัน",
		describe_kr = "아주릴은 꼬리의 탄력성을 이용해 적 1명을 공격해 딜을 합니다#C0x3D8A99#80%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_kr = "아주릴은 탄력을 이용해 적 한 명을 꼬리로 공격한다.",
		describe_en = "Azurill uses the elasticity of tail to attack a single enemy to deal#C0x3D8A99#80%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		describe_th = "อาซูริลใช้ความยืดหยุ่นของหางเพื่อโจมตีศัตรูตัวเดียวเพื่อสร้าง#C0x3D8A99#80%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_id = "Menggunakan kelenturannya, Azurill menyerang satu target musuh dengan ekornya",
		describe_vn = "Azurill usa a elasticidade da cauda para atacar um único inimigo para lidar#C0x3D8A99#80%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_es = "Usando su capacidad de rebote, Azurill ataca al único objetivo enemigo con su cola.",
		id = 3011211,
		describe_id = "Azurill menggunakan elastisitas ekornya untuk menyerang satu musuh dan menghasilkan#C0x3D8A99#80%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_en = "Using its bounciness, Azurill attacks the single enemy target with its tail"
	},
