	[3024313] = {
		describe_th = "โฮโอบินไปบนท้องฟ้าแล้วยิงลำแสงคล้ายแสงแดดออกจากปากเพื่อโจมตีศัตรูทั้งหมดเพื่อสร้างความเสียหาย#C0xE69900#180%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#และสร้างความเสียหาย ชั้น Holy Burn แก่เป้าหมายทั้งหมด (สร้างความเสียหายจริง 40% P.ATK) เป็นเวลา 2 รอบ สร้างความเสียหาย [Holy Bird Blessing] กับโปเกมอนพันธมิตรยกเว้นตัวมันเอง (แนะนำให้ใช้โปเกมอนพันธมิตรในแนวหน้า); เมื่อโปเกมอนตัวนี้ถูกฆ่ามันจะกลายเป็นไข่ฟีนิกซ์ซึ่งจะแตกหลังจากถูกโจมตี 6 ครั้ง ถ้าไม่แตกจะฟื้นคืนชีพเมื่อสิ้นสุดรอบถัดไป หลังจากเกิดใหม่ ฟื้นฟู HP และ Rage 30% [Holy Bird Blessing] สามารถทริกเกอร์ได้เพียงครั้งเดียวเท่านั้นในการต่อสู้",
		describe_en = "Ho-Oh flies in the sky and shoots a sunshine-like beam from the mouth to attack all enemies to deal#C0xE69900#180%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#and inflict a layer of Holy Burn to all targets (dealing a true damage of 40% P.ATK) for 2 rounds; inflict [Holy Bird Blessing] to an allied Pokémon except itself (an allied Pokmoen in the front line will be preferred); when this Pokémon gets killed, it will become an phoenix egg which will be broken after being attacked 6 times If it's not broken, revive at the end of the next round. After the rebirth, recover 30% HP and Rage. [Holy Bird Blessing] can be trigger once only in a battle",
		simDesc_es = "Ho-Oh vuela por el cielo y dispara rayos de sol ardientes desde su boca para atacar a todos los enemigos e infligir una acumulación de Holy Burn mientras bendice a un aliado además de él mismo.",
		describe_es = "Ho-Oh vuela en el cielo y dispara un rayo parecido al sol desde la boca para atacar a todos los enemigos y tratar#C0xE69900#180%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#e infligir un capa de Holy Burn a todos los objetivos (que causa un daño real del 40% P.ATK) durante 2 rondas; infligir [Holy Bird Blessing] a un Pokémon aliado excepto a él mismo (se preferirá un Pokmoen aliado en la primera línea); Cuando maten a este Pokémon, se convertirá en un huevo de fénix que se romperá después de ser atacado 6 veces. Si no se rompe, revive al final de la siguiente ronda. Después del renacimiento, recupera el 30% de HP y Rage. [Holy Bird Blessing] se puede activar solo una vez en una batalla",
		starEffectDesc_vn = "Aumento de efeito: alvos que recebem o [Holy Bird Blessing] podem reter 80% de HP e todos os pontos de raiva",
		starEffectDesc_id = "Peningkatan efek: Target yang menerima [Holy Bird Blessing] dapat mempertahankan 80% HP dan semua poin kemarahan",
		starEffectDesc_es = "Aumento del efecto: los objetivos que reciben el [Holy Bird Blessing] pueden conservar el 80% de HP y todos los puntos de ira.",
		describe_vn = "Ho-Oh voa no céu e dispara um raio de sol da boca para atacar todos os inimigos para lidar#C0xE69900#180%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#e infligir um camada de Holy Burn para todos os alvos (causando um dano real de 40% P.ATK) por 2 rodadas; infligir [Holy Bird Blessing] a um Pokémon aliado exceto ele mesmo (um Pokmoen aliado na linha de frente será preferido); quando este Pokémon for morto, ele se tornará um ovo de fênix que será quebrado após ser atacado 6 vezes. Se não for quebrado, reviva no final da próxima rodada. Após o renascimento, recupere 30% de HP e Rage. [Holy Bird Blessing] só pode ser acionado uma vez em uma batalha",
		starEffectDesc_th = "บูสต์เอฟเฟกต์: เป้าหมายที่ได้รับ [Holy Bird Blessing] สามารถรักษา HP 80% และคะแนนความโกรธทั้งหมดได้",
		describe_id = "Ho-Oh terbang di langit dan menembakkan sinar seperti sinar matahari dari mulutnya untuk menyerang semua musuh untuk menangani#C0xE69900#180%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B#dan menimbulkan kerusakan lapisan Holy Burn ke semua target (menimbulkan true damage sebesar 40% P.ATK) selama 2 ronde; memberikan [Holy Bird Blessing] kepada Pokémon sekutu kecuali dirinya sendiri (Pokmoen sekutu yang berada di garis depan akan lebih diutamakan); ketika Pokémon ini terbunuh, ia akan menjadi telur phoenix yang akan pecah setelah diserang sebanyak 6 kali. Jika tidak pecah, hidupkan kembali di akhir ronde berikutnya. Setelah kelahiran kembali, pulihkan 30% HP dan Rage. [Holy Bird Blessing] hanya dapat dipicu satu kali dalam pertempuran",
		simDesc_en = "Ho-Oh flies in the sky and shoots burning sunrays from its mouth to attack all enemies, and inflict a stack of Holy Burn while Blessing an ally besides itself",
		simDesc_vn = "Ho-Oh voa no céu e dispara raios de sol ardentes de sua boca para atacar todos os inimigos e infligir uma pilha de Queimadura Sagrada enquanto abençoa um aliado além de si mesmo",
		describe_kr = "호오가 하늘을 날아 입에서 햇빛 같은 광선을 쏘아 적군 전체를 공격하여 딜을 가합니다#C0xE69900#180%P.ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#P.DMG#C0x5B545B# 2라운드 동안 모든 대상에게 Holy Burn 층(40% P.ATK의 실제 피해를 줍니다); 자신을 제외한 동맹 포켓몬에게 [Holy Bird Blessing]를 적용합니다(전선에 있는 동맹 포켓몬이 선호됩니다). 이 포켓몬이 죽으면 불사조 알이 되며, 6번 공격을 받으면 부서집니다. 깨지지 않으면 다음 라운드가 끝날 때 부활합니다. 환생 후 HP와 분노를 30% 회복합니다. [Holy Bird Blessing] 전투 중 한 번만 발동 가능",
		simDesc_th = "Ho-Oh บินขึ้นไปบนท้องฟ้าและยิงแสงอาทิตย์ที่ลุกโชนออกจากปากของมันเพื่อโจมตีศัตรูทั้งหมด และสร้างสแตค Holy Burn ในขณะที่อวยพรเพื่อนร่วมทีมนอกเหนือจากตัวมันเอง",
		starEffectDesc_kr = "효과 부스트: [Holy Bird Blessing]를 받은 대상은 HP 80%와 모든 분노 포인트를 유지할 수 있습니다.",
		simDesc_kr = "호오가 하늘을 날아 입에서 불타는 태양 광선을 발사하여 모든 적을 공격하고, 자신 이외의 아군을 축복하면서 홀리 번 중첩을 부여합니다.",
		starEffectDesc_en = "Effect boost: Targets that receive the [Holy Bird Blessing] can retain 80% HP and all rage points",
		id = 3024313,
		simDesc_id = "Ho-Oh terbang di langit dan menembakkan sinar matahari yang membakar dari mulutnya untuk menyerang semua musuh, dan menimbulkan tumpukan Holy Burn sambil memberkati sekutu selain dirinya sendiri."
	},
