	[3072211] = {
		simDesc_vn = "Jigglypuff canta suavemente e ataca um único alvo inimigo com sua voz",
		describe_es = "Jigglypuff canta suavemente y ataca a un solo objetivo enemigo con su voz, causando#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_th = "Jigglypuff ร้องเพลงเบา ๆ และโจมตีศัตรูเป้าหมายเดียวด้วยเสียงของมัน",
		describe_kr = "Jigglypuff는 부드럽게 노래하며 목소리로 단일 적 대상을 공격하여#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리합니다.",
		simDesc_kr = "Jigglypuff는 나지막하게 노래하며 그 목소리로 적 1명을 공격합니다.",
		describe_en = "Jigglypuff sings softly and attacks a single enemy target with its voice, dealing#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		describe_th = "จิกกลีพัฟร้องเพลงเบาๆ และโจมตีศัตรูเป้าหมายเดียวด้วยเสียง สร้างความเสียหาย#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_id = "Jigglypuff bernyanyi dengan lembut dan menyerang satu target musuh dengan suaranya",
		describe_vn = "Jigglypuff canta suavemente e ataca um único alvo inimigo com sua voz, distribuindo#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_es = "Jigglypuff canta suavemente y ataca a un solo objetivo enemigo con su voz.",
		id = 3072211,
		describe_id = "Jigglypuff bernyanyi dengan lembut dan menyerang satu target musuh dengan suaranya, menimbulkan#C0x3D8A99#90% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#",
		simDesc_en = "Jigglypuff sings softly and attacks a single enemy target with its voice"
