	[3072212] = {
		simDesc_vn = "Jigglypuff pula furiosamente e ataca um único alvo inimigo, com chance de adormecer o alvo",
		describe_es = "Jigglypuff salta enojado y ataca a un solo objetivo enemigo, causando#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, con un 50% de probabilidad de poner al objetivo a dormir durante 1 redondo",
		simDesc_th = "Jigglypuff กระโดดขึ้นและโจมตีเป้าหมายศัตรูตัวเดียวด้วยความโกรธ พร้อมมีโอกาสที่จะทำให้เป้าหมายหลับ",
		describe_kr = "Jigglypuff가 화가 나서 뛰어올라 단일 적 대상을 공격하여 #C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 공격하며, 50% 확률로 1 동안 대상을 잠들게 합니다. 둥근",
		simDesc_kr = "Jigglypuff가 화가 나서 뛰어올라 단일 적 대상을 공격하고 일정 확률로 대상을 잠들게 합니다.",
		describe_en = "Jigglypuff angrily jumps up and strikes at a single enemy target, dealing#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, with 50% chance of putting the target to sleep for 1 round",
		describe_th = "จิกกลีพัฟกระโดดขึ้นโจมตีศัตรูเป้าหมายเดียวด้วยความโกรธ สร้างความเสียหาย#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# โดยมีโอกาส 50% ที่จะทำให้เป้าหมายหลับเป็นเวลา 1 วินาที กลม",
		simDesc_id = "Jigglypuff dengan marah melompat dan menyerang satu target musuh, dengan kemungkinan membuat target tertidur",
		describe_vn = "Jigglypuff pula com raiva e ataca um único alvo inimigo, distribuindo#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, com 50% de chance de colocar o alvo para dormir por 1 redondo",
		simDesc_es = "Jigglypuff salta enojado y ataca a un solo objetivo enemigo, con la posibilidad de ponerlo a dormir.",
		id = 3072212,
		describe_id = "Jigglypuff dengan marah melompat dan menyerang satu target musuh, menimbulkan#C0x3D8A99#140% SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#, dengan 50% kemungkinan membuat target tertidur selama 1 bulat",
		simDesc_en = "Jigglypuff angrily jumps up and strikes at a single enemy targe, with a chance of putting the target to sleep"
	},
	[3072213] = {
		describe_th = "จิกกลีพัฟร้องเพลงบนเวทีอย่างมีความสุข สร้างความเสียหาย#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#SP.DMG#C0x5B545B#ให้กับศัตรูทั้งหมด โดยมีโอกาส 40% ที่จะทำให้ยูนิตศัตรู 3 ตัวหลับเป็นเวลา 1 รอบ",
		describe_en = "Jigglypuff happily sings on stage, dealing#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#SP.DMG#C0x5B545B#to all enemies, with 40% chance of putting 3 enemy units to sleep for 1 round",
		simDesc_es = "Jigglypuff canta alegremente en el escenario, atacando a todos los enemigos, con un 40 % de probabilidad de poner a dormir a 3 unidades enemigas.",
		describe_es = "Jigglypuff canta felizmente en el escenario, causando#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#SP.DMG#C0x5B545B#a todos los enemigos, con un 40% de probabilidad de poner a dormir a 3 unidades enemigas durante 1 ronda.",
		starEffectDesc_vn = "Recupera 5% de HP ao colocar um alvo para dormir com sucesso",
		starEffectDesc_id = "Memulihkan 5% HP ketika berhasil membuat target tertidur",
		starEffectDesc_es = "Recupera un 5% de HP cuando logras dormir a un objetivo.",
		describe_vn = "Jigglypuff canta alegremente no palco, distribuindo#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#SP.DMG#C0x5B545B#para todos os inimigos, com 40% de chance de colocar 3 unidades inimigas para dormir por 1 rodada",
		starEffectDesc_th = "ฟื้นฟู HP 5% เมื่อทำให้เป้าหมายเข้าสู่โหมดสลีปได้สำเร็จ",
		describe_id = "Jigglypuff dengan gembira bernyanyi di atas panggung, memberikan#C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#SP.DMG#C0x5B545B#ke semua musuh, dengan 40% kemungkinan membuat 3 unit musuh tertidur selama 1 ronde",
		simDesc_en = "Jigglypuff happily sings on stage, attacking all enemies, with a 40% chance of putting 3 enemy units to sleep",
		simDesc_vn = "Jigglypuff canta alegremente no palco, atacando todos os inimigos, com 40% de chance de colocar 3 unidades inimigas para dormir",
		describe_kr = "Jigglypuff는 무대에서 즐겁게 노래하며 #C0x3D8A99#130% SP.ATK#C0x5B545B#+$(skillLevel*4*30)$#C0xF13B54#SP.DMG#C0x5B545B#를 모든 적에게 처리하고 40% 확률로 3개의 적 유닛을 1라운드 동안 잠들게 합니다.",
		simDesc_th = "Jigglypuff ร้องเพลงบนเวทีอย่างมีความสุข โจมตีศัตรูทั้งหมด โดยมีโอกาส 40% ที่จะทำให้ศัตรู 3 ตัวหลับ",
		starEffectDesc_kr = "대상을 수면에 성공 시 HP 5% 회복",
		simDesc_kr = "Jigglypuff는 무대에서 신나게 노래하며 모든 적을 공격하고 40% 확률로 적 유닛 3개를 잠들게 합니다.",
		starEffectDesc_en = "Recovers 5% HP when successfully puttting a target to sleep",
		id = 3072213,
		simDesc_id = "Jigglypuff dengan gembira bernyanyi di atas panggung, menyerang semua musuh, dengan peluang 40% membuat 3 unit musuh tertidur"
	},
	[3072216] = {
		describe_en = "There is a $(20+skillLevel*0.1-0.1)$% chance of putting an enemy that attacks it to sleep for 1 round",
		describe_es = "Hay un $(20+skillLevel*0.1-0.1)$% de probabilidad de poner a dormir a un enemigo que lo ataca durante 1 ronda.",
		describe_kr = "$(20+skillLevel*0.1-0.1)$%의 확률로 자신을 공격하는 적을 1라운드 동안 잠들게 합니다.",
		starEffectDesc_th = "แต่ละครั้งที่ศัตรูเข้าสู่โหมดสลีปได้สำเร็จ มันจะลบล้างสถานะสถานะหนึ่งรายการในตัวมันเอง และเพิ่ม SP.ATK 5% สำหรับแต่ละสถานะที่ถูกลบล้าง",
		starEffectDesc_kr = "적이 수면에 성공할 때마다 자신의 상태이상을 1개 해제하고, 해제된 상태이상 하나당 SP.ATK가 5% 증가합니다.",
		starEffectDesc_vn = "Cada vez que o inimigo é adormecido com sucesso, ele dissipa uma condição de status em si mesmo e aumenta 5% de SP.ATK para cada condição de status dissipada.",
		describe_th = "มีโอกาส $(20+skillLevel*0.1-0.1)$% ที่จะทำให้ศัตรูที่โจมตีเข้าสู่โหมดสลีปเป็นเวลา 1 รอบ",
		starEffectDesc_id = "Setiap kali musuh berhasil ditidurkan, ia menghilangkan satu kondisi status pada dirinya sendiri, dan meningkatkan 5% SP.ATK untuk setiap kondisi status yang dihilangkan.",
		describe_vn = "Há $(20+skillLevel*0.1-0.1)$% de chance de colocar um inimigo que o ataca para dormir por 1 rodada",
		starEffectDesc_en = "Each time when the enemy is successfully put to sleep, it dispels one status condition on itself, and increases 5% SP.ATK for each status condition dispelled",
		starEffectDesc_es = "Cada vez que el enemigo es puesto a dormir exitosamente, disipa una condición de estado sobre sí mismo y aumenta un 5% SP.ATK por cada condición de estado disipada.",
		id = 3072216,
		describe_id = "Ada peluang $(20+skillLevel*0.1-0.1)$% membuat musuh yang menyerangnya tertidur selama 1 ronde"
	},
