	[3074113] = {
		describe_th = "เมตากรอสซ่อนแขนทั้งสี่ของมันและใช้กำลังทั้งหมดเพื่อโจมตีศัตรูในแนวหน้า สร้างความเสียหาย#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#P.DMG#C0x5B545B# ใช้คะแนนพลังงานทั้งหมดที่เพิ่ม สร้างความเสียหายสูงสุด 40% ต่อจุดพลังงานแต่ละจุดที่ถูกดูดซับ",
		describe_en = "Metagross hides its four limbs and uses all its strength to strike enemies in the front line, dealing#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#P.DMG#C0x5B545B#, consumes all energy points that increase 40% Ultimate damage for each energy point absorbed.",
		simDesc_es = "Metagross esconde sus cuatro extremidades y usa toda su fuerza para atacar a un solo objetivo enemigo. Cada vez que aumenta un punto de energía, definitivamente causará daño máximo.",
		describe_es = "Metagross esconde sus cuatro extremidades y usa toda su fuerza para golpear a los enemigos en la línea del frente, causando#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#P.DMG#C0x5B545B#, consume todos los puntos de energía que aumentan. 40% de daño máximo por cada punto de energía absorbido.",
		starEffectDesc_vn = "Efeito adicional: Mantém 300 pontos de raiva após fazer o movimento Ultimate e aumenta sua redução de P.DMG em 20% por 2 rodadas",
		starEffectDesc_id = "Efek tambahan: Mempertahankan 300 poin kemarahan setelah melakukan gerakan Ultimate dan meningkatkan pengurangan P.DMG sebesar 20% selama 2 putaran",
		starEffectDesc_es = "Efecto adicional: Mantiene 300 puntos de ira después de realizar el movimiento definitivo y aumenta su reducción de P.DMG en un 20 % durante 2 rondas.",
		describe_vn = "Metagross esconde seus quatro membros e usa toda sua força para atacar os inimigos na linha de frente, distribuindo#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#P.DMG#C0x5B545B#, consome todos os pontos de energia que aumentam 40% de dano final para cada ponto de energia absorvido.",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เก็บ 300 rage point หลังจากทำท่า Ultimate และเพิ่มการลด P.DMG 20% เป็นเวลา 2 รอบ",
		describe_id = "Metagross menyembunyikan keempat anggota tubuhnya dan menggunakan seluruh kekuatannya untuk menyerang musuh di garis depan, menangani#C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#P.DMG#C0x5B545B#, menghabiskan semua poin energi yang meningkat 40% Kerusakan pamungkas untuk setiap titik energi yang diserap.",
		simDesc_en = "Metagross hides its four limbs and uses all its strength to strike a single enemy target. Whenever an energy point increases, it will definitely deal Ultimate damage",
		simDesc_vn = "Metagross esconde seus quatro membros e usa toda a sua força para atingir um único alvo inimigo. Sempre que um ponto de energia aumenta, ele definitivamente causará dano final",
		describe_kr = "메타그로스는 사지를 숨기고 온 힘을 다해 최전선의 적을 공격하며 #C0xE69900#230% P.ATK#C0x5B545B#+$(skillLevel*4*42)$#C0xF13B54#P.DMG#C0x5B545B#, 증가하는 에너지 포인트를 모두 소모합니다. 흡수된 에너지 포인트당 40% 궁극기 피해를 입힙니다.",
		simDesc_th = "Metagross ซ่อนแขนทั้งสี่ของมัน และใช้พละกำลังทั้งหมดเพื่อโจมตีเป้าหมายศัตรูตัวเดียว เมื่อใดก็ตามที่จุดพลังงานเพิ่มขึ้น มันจะสร้างความเสียหายขั้นสุดยอดอย่างแน่นอน",
		starEffectDesc_kr = "추가 효과: 궁극기 사용 후 분노 포인트 300을 유지하고 2라운드 동안 P.DMG 감소를 20% 증가시킵니다.",
		simDesc_kr = "메타그로스는 네 개의 팔다리를 숨기고 온 힘을 다해 적 한 명을 공격합니다. 에너지 포인트가 증가할 때마다 반드시 궁극기 피해를 입힙니다.",
		starEffectDesc_en = "Additional effect: Keeps 300 rage points after making the Ultimate move and increases its P.DMG reduction by 20% for 2 rounds",
		id = 3074113,
		simDesc_id = "Metagross menyembunyikan keempat anggota tubuhnya dan menggunakan seluruh kekuatannya untuk menyerang satu sasaran musuh. Setiap kali titik energi meningkat, pasti akan memberikan damage Ultimate"
	},
