	[40000016] = {
		describe_en = "When own HP is below 60%, enters the Stealth status for 1 round. (Cannot be selected in the Stealth status, but still take AoE DMG. CD: 3 rounds)",
		describe_es = "Cuando su propio HP está por debajo del 60%, entra en estado Sigiloso durante 1 ronda. (No se puede seleccionar en estado Sigiloso, pero aun así recibe DAÑO AoE. CD: 3 rondas)",
		describe_kr = "자신의 HP가 60% 이하일 때 1라운드 동안 스텔스 상태가 된다. (스텔스 상태에서는 선택할 수 없지만 여전히 AoE DMG를 받습니다. CD: 3라운드)",
		starEffectDesc_th = "เพิ่มเอฟเฟกต์: +25% Crit DMG ระหว่างซ่อนตัว รับเครื่องหมายเลือดเย็นเป็นครั้งแรกโดยใช้ Stealth",
		starEffectDesc_kr = "효과 부스트: 스텔스 중 치명타 피해량 +25%, 스텔스를 사용하여 처음으로 냉혈한 혈액 표시를 받습니다.",
		starEffectDesc_vn = "Aumento de efeito: +25% de DMG crítico durante Stealth, receba marca de sangue frio pela 1ª vez usando Stealth",
		describe_th = "เมื่อ HP ของตัวเองต่ำกว่า 60% จะเข้าสู่สถานะซ่อนตัวเป็นเวลา 1 รอบ (ไม่สามารถเลือกได้ในสถานะ Stealth แต่ยังคงรับ AoE DMG. CD: 3 รอบ)",
		starEffectDesc_id = "Peningkatan efek: +25% Crit DMG selama Stealth, menerima tanda darah dingin untuk pertama kalinya menggunakan Stealth",
		describe_vn = "Quando o próprio HP está abaixo de 60%, entra no status Stealth por 1 rodada. (Não pode ser selecionado no status Stealth, mas ainda recebe AoE DMG. CD: 3 rodadas)",
		starEffectDesc_en = "Effect boost: +25% Crit DMG during Stealth, receive cold blood mark for 1st time using Stealth",
		starEffectDesc_es = "Aumento del efecto: +25% de daño crítico durante Stealth, recibe marca de sangre fría por primera vez usando Stealth",
		id = 40000016,
		describe_id = "Ketika HP sendiri di bawah 60%, memasuki status Stealth selama 1 putaran. (Tidak dapat dipilih dalam status Stealth, namun tetap menerima AoE DMG. CD: 3 ronde)"
	},
	[40000022] = {
		simDesc_vn = "Decidueye dobra suas asas e ataca de baixa altitude, chutando o inimigo ferozmente.",
		describe_es = "Decidueye dobla sus alas y carga desde baja altura, pateando ferozmente a un solo enemigo. Inflige (#C0xE69900#160% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Ingrese al estado [Stealth] después del ataque (Sigilo: efecto especial, no se puede seleccionar hasta que el propietario lo use, pero aún así recibe daño AoE. Dura hasta 3 rondas). El sigilo tiene un tiempo de reutilización de 1 ronda.",
		simDesc_th = "Decidueye ติดปีกและพุ่งจากระดับความสูงต่ำ เตะศัตรูอย่างดุเดือด",
		describe_kr = "데시듀아이는 날개를 접고 낮은 고도에서 돌진해 적 한 명을 맹렬하게 걷어찬다. (#C0xE69900#160% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. 공격 후 [Stealth] 상태로 들어갑니다(스텔스: 특수 효과, 소유자가 사용할 때까지 선택할 수 없지만 여전히 AoE DMG를 받습니다. 최대 3라운드까지 지속됩니다). 스텔스에는 1라운드의 재사용 대기시간이 있습니다.",
		simDesc_kr = "데시듀아이는 날개를 접고 낮은 고도에서 돌진해 적을 맹렬하게 걷어차냅니다.",
		describe_en = "Decidueye tucks in its wings and charges from a low altitude, kicking a single enemy fiercely. Inflicts (#C0xE69900#160% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Enter the [Stealth] status after the attack (Stealth: Special effect, cannot be selected until the owner uses, but still take AoE DMG. Lasts up to 3 rounds). Stealth has a 1 round cooldown",
		describe_th = "Decidueye ติดปีกและพุ่งจากระดับความสูงต่ำ เตะศัตรูตัวเดียวอย่างดุเดือด สร้างความเสียหาย (#C0xE69900#160% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. เข้าสู่สถานะ [Stealth] หลังการโจมตี (ซ่อนตัว: เอฟเฟกต์พิเศษ ไม่สามารถเลือกได้จนกว่าเจ้าของจะใช้ แต่ยังคงได้รับความเสียหาย AoE อยู่ได้นานถึง 3 รอบ) Stealth มีคูลดาวน์ 1 รอบ",
		simDesc_id = "Decidueye melipat sayapnya dan menyerang dari ketinggian rendah, menendang musuh dengan ganas.",
		describe_vn = "Decidueye dobra suas asas e ataca de baixa altitude, chutando ferozmente um único inimigo. Inflige (#C0xE69900#160% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Entre no status [Stealth] após o ataque (Stealth: Efeito especial, não pode ser selecionado até que o proprietário use, mas ainda recebe AoE DMG. Dura até 3 rodadas). Stealth tem um cooldown de 1 rodada",
		simDesc_es = "Decidueye dobla sus alas y carga desde baja altura, pateando ferozmente al enemigo.",
		id = 40000022,
		describe_id = "Decidueye melipat sayapnya dan menyerang dari ketinggian rendah, menendang satu musuh dengan ganas. Dampak (#C0xE69900#160% P.ATK#C0x5B545B#+$(skillLevel*4*48)$)#C0xF13B54#P.DMG#C0x5B545B#. Masukkan status [Stealth] setelah serangan (Stealth: Efek spesial, tidak dapat dipilih hingga pemiliknya menggunakannya, namun tetap menerima AoE DMG. Berlangsung hingga 3 ronde). Stealth memiliki cooldown 1 putaran",
		simDesc_en = "Decidueye tucks in its wings and charges from a low altitude, kicking the enemy fiercely."
	},
	[40000026] = {
		describe_en = "Can attack a rear-line enemy directly;\nKnocking out the enemy grants $(400+skillLevel*3-3)$ Rage",
		describe_es = "Puede atacar a un enemigo de retaguardia directamente;\nNoquear al enemigo otorga $(400+skillLevel*3-3)$ Rabia",
		describe_kr = "후방의 적을 직접 공격할 수 있습니다;\n 적을 쓰러뜨리면 획득 $(400+skillLevel*3-3)$ 분노",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เมื่อสังหารเป้าหมาย จะเพิ่มความเสียหายคริติคอลเพิ่มเติม 20%",
		starEffectDesc_kr = "추가 효과 : 적 처치시 치명타 데미지 20% 추가 증가",
		starEffectDesc_vn = "Efeito adicional:Ao matar um alvo,Aumenta 20% de dano crítico extra",
		describe_th = "สามารถโจมตีศัตรูแนวหลังได้โดยตรง \n การน็อคศัตรูจะได้รับ $(400+skillLevel*3-3)$ ความเดือดดาล",
		starEffectDesc_id = "Efek tambahan: Saat membunuh target, Meningkatkan tambahan 20% kerusakan kritis",
		describe_vn = "Pode atacar um inimigo da linha de retaguarda diretamente;\nNocautear o inimigo concede $(400+skillLevel*3-3)$ Raiva",
		starEffectDesc_en = "Additional effect:When killing a target,Increases extra 20% crit damage",
		starEffectDesc_es = "Efecto adicional: al matar a un objetivo, aumenta un 20 % el daño crítico adicional.",
		id = 40000026,
		describe_id = "Dapat menyerang musuh di garis belakang secara langsung;\nMenghancurkan musuh akan memberikan $(400+skillLevel*3-3)$ Kemarahan"
	},
	[40000036] = {
		describe_en = "When attacked, restores own $(20+skillLevel*0.2-0.2)$% SP.ATK as HP.\nAfter its move, planting [Leech Seed] on an ally for 3 rounds (Leech Seed: Before every round, restores HP by $(30+skillLevel*0.2-0.2)$% of Mega Venusaur's SP.ATK)",
		describe_es = "Cuando es atacado, restaura su propio $(20+skillLevel*0.2-0.2)$% SP.ATK como HP.\nDespués de su movimiento, planta [Leech Seed] en un aliado durante 3 rondas (Leech Seed: antes de cada ronda, restaura HP en un $(30+skillLevel*0.2-0.2)$% del SP de Mega Venusaur. ATK)",
		describe_kr = "공격 시 자신의 SP.ATK $(20+skillLevel*0.2-0.2)$%를 HP로 회복합니다.\n이동 후 3라운드 동안 아군에게 [Leech Seed]를 심습니다. (리치 ​​씨앗: 매 라운드 전 메가 비너사우루스 SP의 $(30+skillLevel*0.2-0.2)$%만큼 HP를 회복합니다. .ATK)",
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: จำนวนการฟื้นตัวของทักษะทั้งหมด +20%",
		starEffectDesc_kr = "추가 효과 : 모든 스킬의 회복량 +20%",
		starEffectDesc_vn = "Efeito extra: Quantidade de recuperação de todas as suas habilidades +20%",
		describe_th = "เมื่อถูกโจมตี จะฟื้นฟู $(20+skillLevel*0.2-0.2)$% SP.ATK ของตัวเองเป็น HP \n หลังจากเคลื่อนที่แล้ว ให้ปลูก [Leech Seed] บนพันธมิตรเป็นเวลา 3 รอบ (เมล็ดปลิง: ก่อนทุกรอบ จะฟื้นฟู HP $(30+skillLevel*0.2-0.2)$% ของ SP ของเมก้าวีนัสซอร์ .โจมตี)",
		starEffectDesc_id = "Efek ekstra: Jumlah pemulihan semua keterampilannya +20%",
		describe_vn = "Quando atacado, restaura $(20+skillLevel*0.2-0.2)$% SP.ATK como HP.\nApós seu movimento, plantando [Leech Seed] em um aliado por 3 rodadas (Leech Seed: Antes de cada rodada, restaura HP em $(30+skillLevel*0.2-0.2)$% do SP do Mega Venusaur .ATK)",
		starEffectDesc_en = "Extra effect: Recovery amount of all its skills +20%",
		starEffectDesc_es = "Efecto extra: Cantidad de recuperación de todas sus habilidades +20%",
		id = 40000036,
		describe_id = "Saat diserang, pulihkan $(20+skillLevel*0.2-0.2)$% SP.ATK sebagai HP.\nSetelah bergerak, tanam [Leech Seed] pada sekutu selama 3 ronde (Leech Seed: Sebelum setiap ronde, pulihkan HP sebesar $(30+skillLevel*0.2-0.2)$% SP Mega Venusaur .ATK)"
	},
	[40000046] = {
		describe_en = [[
Stays in the [#L10#Land Forme#L0#] in round 1-3 and switches to [#L10#Sky Forme#L0#] in round 4-6, and so forth
#F20#
#F40#[#L10#Land Forme#L0#]: create [#L10#Barrier#L0#] to block the first 3 linear damages for all allies over a big round (Blocks $(10+skillLevel*0.1-0.1)$% for front-line allies and $(20+skillLevel*0.2-0.2)$% for rear-line allies)
#F20#
#F40#When it enters the [#L10#Land Forme#L0#], places a [#L10#Bouquet Seed#L0#] before every ally for 2 rounds: The 3 allies with the lowest HP will restore HP before they move (60% of Shaymin's SP.ATK)
#F20#
#F40#When [#L10#Bouquet Seed#L0#] disappears, Shaymin restores 500 Rage and has a 40% chance to coil all enemies for 1 round]],
		describe_es = [[
Permanece en [#L10#Land Forme#L0#] en las rondas 1-3 y cambia a [#L10#Sky Forme#L0#] en las rondas 4-6, y así sucesivamente
#F20#
#F40#[#L10#Land Forme#L0#]: crea [#L10#Barrier#L0#] para bloquear los primeros 3 lineales daños para todos los aliados durante una ronda grande (Bloqueos $(10+skillLevel*0.1-0.1)$% para los aliados de primera línea y $(20+skillLevel*0.2-0.2)$% para los aliados de retaguardia)
#F20#
#F40#Cuando ingresa al [#L10#Land Forme#L0#], coloca un [#L10#Bouquet Seed#L0#] antes de cada aliado durante 2 rondas: Los 3 aliados con menos HP restaurarán HP antes de moverse (60 % del SP.ATK de Shaymin)
#F20#
#F40#Cuando [#L10#Bouquet Seed#L0#] desaparece, Shaymin se restaura 500 de ira y tiene un 40 % de probabilidad de enrollar a todos los enemigos durante 1 ronda.]],
		describe_kr = [[
1~3라운드에서는 [#L10#Land Forme#L0#]에 머물고 4~6라운드에서는 [#L10#Sky Forme#L0#]로 전환하는 식으로 진행됩니다
#F20#
#F40#[#L10#Land Forme#L0#]: [#L10#Barrier#L0#]를 생성하여 처음 3개의 선형을 차단합니다. 큰 라운드에 걸쳐 모든 아군에게 피해를 입힙니다. (전선 아군은 $(10+skillLevel*0.1-0.1)$%, 후방 아군은 $(20+skillLevel*0.2-0.2)$% 차단)
#F20#
#F40# [#L10#Land Forme#L0#]에 들어가면 [#L10#Bouquet Seed#L0#] 2라운드 동안 모든 아군 전: HP가 가장 낮은 아군 3명이 이동하기 전에 HP를 회복합니다(셰이민 SP.ATK의 60%)
#F20#
#F40#[#L10#Bouquet Seed#L0#]가 사라지면 셰이민이 회복합니다. 분노가 500이고 40%의 확률로 모든 적을 1라운드 동안 휘감습니다.]],
		starEffectDesc_th = "เอฟเฟกต์พิเศษ: เมื่อ [Bouquet Seed] อยู่ที่นั่น เปลี่ยนความเสียหาย 12% ของ Shaymin ที่ได้รับไปเป็นการรักษา",
		starEffectDesc_kr = "추가 효과: [Bouquet Seed]가 있을 때 DMG Shaymin의 12%가 치유로 전환됩니다.",
		starEffectDesc_vn = "Efeito extra: Quando [Bouquet Seed] está lá, converte 12% do DMG que Shaymin recebe em Cura",
		describe_th = [[
