	[50000517] = {
		zawakeEffectDesc_kr = "픽츄는 볼에서 강력한 전류를 방출하여 딜을 #C0x3D8A99#90%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#하며, 2라운드 동안 제어율이 5% 증가합니다.",
		zawakeEffectDesc_vn = "Pickchu libera poderosas correntes elétricas das bochechas para lidar com#C0x3D8A99#90%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# e aumenta a taxa de controle em 5% por 2 rodadas",
