	[1040311] = {
		zawakeEffectDesc_es = "Nihilego usa el cabezazo de doble filo para atacar al único enemigo, causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, luego aumenta su propio SP.ATK en un 40% durante 2 rondas.\n#F10#\n#F40##L10# [Parasitism]:#L0# el [Host] aumenta P.ATK,SP.ATK en un 50 % durante 1 ronda antes del ataque.",
		zawakeEffectDesc_vn = "Nihilego usa a Cabeçada Dupla para atacar o único inimigo, causando #C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, depois aumenta o próprio SP.ATK em 40% para 2 rodadas.\n#F10#\n#F40##L10# [Parasitism]:#L0# o [Host] aumenta P.ATK,SP.ATK em 50% por 1 rodada antes do ataque.",
		describe_th = "นิฮิเลโกใช้หัวโขกสองคมโจมตีศัตรูตัวเดียว สร้าง #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# จากนั้นเพิ่ม SP.ATK ของตัวเอง 20% เป็นเวลา 2 วินาที รอบ.\n#F10#\n#F40##L10# [Parasitism]:#L0# [Host] เพิ่ม P.ATK,SP.ATK 30% เป็นเวลา 1 รอบก่อนการโจมตี",
		zawakeEffectDesc_kr = "니힐레고는 양날 박치기를 사용해 적 한 명을 공격해 #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리한 후 2번 동안 자신의 SP.ATK가 40% 증가합니다. rounds.\n#F10#\n#F40##L10# [Parasitism]:#L0# [Host]은 공격 전 1라운드 동안 P.ATK,SP.ATK가 50% 증가합니다.",
		zawakeEffectDesc_th = "นิฮิเลโกใช้หัวโขกสองคมโจมตีศัตรูตัวเดียว สร้าง #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# จากนั้นเพิ่ม SP.ATK ของตัวเอง 40% เป็นเวลา 2 วินาที รอบ.\n#F10#\n#F40##L10# [Parasitism]:#L0# การ [Host] เพิ่ม P.ATK,SP.ATK 50% เป็นเวลา 1 รอบก่อนการโจมตี",
		describe_en = "Nihilego uses the Double-Edge Headbutt to attack the single enemy,dealing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#,then increases own SP.ATK by 20% for 2 rounds.\n#F10#\n#F40##L10# [Parasitism]:#L0# the [Host] increases P.ATK,SP.ATK by 30% for 1 round before the attack.",
		describe_es = "Nihilego usa el cabezazo de doble filo para atacar al único enemigo, causando #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, luego aumenta su propio SP.ATK en un 20% durante 2 rondas.\n#F10#\n#F40##L10# [Parasitism]:#L0# el [Host] aumenta P.ATK,SP.ATK en un 30 % durante 1 ronda antes del ataque.",
		zawakeSimpleDesc_en = "Increase self's special attack by 40% for 2 rounds after normal attack; [host] increase double attack by 50% for 1 round before using normal attack",
		describe_vn = "Nihilego usa a Cabeçada Dupla para atacar o único inimigo, lidando com #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, depois aumenta o próprio SP.ATK em 20% para 2 rodadas.\n#F10#\n#F40##L10# [Parasitism]:#L0# o [Host] aumenta P.ATK,SP.ATK em 30% por 1 rodada antes do ataque.",
		zawakeEffectDesc_en = "Nihilego uses the Double-Edge Headbutt to attack the single enemy,dealing #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#,then increases own SP.ATK by 40% for 2 rounds.\n#F10#\n#F40##L10# [Parasitism]:#L0# the [Host] increases P.ATK,SP.ATK by 50% for 1 round before the attack.",
		zawakeSimpleDesc_vn = "Aumenta o ataque especial de si mesmo em 40% por 2 rodadas após o ataque normal; [host] aumente o ataque duplo em 50% por 1 rodada antes de usar o ataque normal",
		zawakeSimpleDesc_id = "Meningkatkan serangan spesial diri sebesar 40% selama 2 ronde setelah serangan normal; [host] meningkatkan serangan ganda sebesar 50% selama 1 putaran sebelum menggunakan serangan normal",
		zawakeSimpleDesc_es = "Aumenta el ataque especial del yo en un 40% durante 2 rondas después del ataque normal; [host] aumenta el ataque doble en un 50% durante 1 ronda antes de usar el ataque normal",
		describe_id = "Nihilego menggunakan Double-Edge Headbutt untuk menyerang musuh tunggal, menimbulkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, lalu meningkatkan SP.ATK miliknya sebesar 20% sebanyak 2 putaran.\n#F10#\n#F40##L10# [Parasitism]:#L0# [Host] meningkatkan P.ATK,SP.ATK sebesar 30% selama 1 putaran sebelum serangan.",
		zawakeSimpleDesc_kr = "일반 공격 후 2라운드 동안 자신의 특수 공격력이 40% 증가합니다. [host] 일반 공격을 사용하기 전 1라운드 동안 이중 공격이 50% 증가합니다.",
		zawakeEffectDesc_id = "Nihilego menggunakan Double-Edge Headbutt untuk menyerang musuh tunggal, menimbulkan #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, lalu meningkatkan SP.ATK miliknya sebesar 40% sebanyak 2 putaran.\n#F10#\n#F40##L10# [Parasitism]:#L0# [Host] meningkatkan P.ATK,SP.ATK sebesar 50% selama 1 putaran sebelum serangan.",
		describe_kr = "니힐레고는 양날 박치기를 사용해 적 한 명을 공격해 #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리한 후 2번 동안 자신의 SP.ATK가 20% 증가합니다. \n#F10#\n#F40##L10# [Parasitism]:#L0# [Host]은 공격 전 1라운드 동안 P.ATK,SP.ATK가 30% 증가합니다.",
		zawakeSimpleDesc_th = "เพิ่มการโจมตีพิเศษของตัวเอง 40% เป็นเวลา 2 รอบหลังจากการโจมตีปกติ [host] เพิ่มการโจมตีสองเท่า 50% เป็นเวลา 1 รอบ ก่อนที่จะใช้การโจมตีปกติ",
		id = 1040311
	},
	[1040312] = {
		zawakeEffectDesc_es = "Nihilego usa el elemento tóxico para atacar a los enemigos seguidos, causando #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#. Además, aplica una acumulación de [Neurotoxins] al objetivo. durante 2 rondas.\n#F10#\n#F40##L10# Parasitismo: #L0# El [host] extiende el tiempo de enfriamiento con 3 rondas después de usar el movimiento pequeño. Además aplica 1 acumulación de [Neurotoxins] a todos los enemigos.",
		zawakeEffectDesc_vn = "Nihilego usa o elemento tóxico para atacar os inimigos em sequência, distribuindo #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#.Adicionalmente aplique uma pilha de [Neurotoxins] ao alvo por 2 rodadas.\n#F10#\n#F40##L10# Parasitismo: #L0# O [host] prolonga o tempo de resfriamento com 3 rodadas após usar o movimento pequeno. Além disso, aplica 1 pilha de [Neurotoxins] a todos os inimigos",
		describe_th = "นิฮิเลโกใช้ธาตุพิษโจมตีศัตรูติดต่อกัน สร้าง #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# เพิ่มสแต็ค [Neurotoxins] ไปยังเป้าหมายเพิ่มเติม เป็นเวลา 2 รอบ\n#F10#\n#F40##L10# ปรสิต: #L0# [host] ขยายเวลาเย็นด้วย 3 รอบหลังจากใช้ท่าเล็ก ๆ",
		zawakeEffectDesc_kr = "니힐레고는 독성 원소를 사용하여 연속적으로 적을 공격하며 #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리합니다. 추가로 대상에게 [Neurotoxins] 스택을 적용합니다. 2라운드.\n#F10#\n#F40##L10# 기생: #L0# [host]은 작은 움직임을 사용한 후 3라운드로 쿨타임을 연장합니다. 추가로 모든 적에게 [Neurotoxins] 1스택을 적용합니다.",
		zawakeEffectDesc_th = "นิฮิเลโกใช้ธาตุพิษโจมตีศัตรูติดต่อกัน สร้าง #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B# เพิ่มสแต็ค [Neurotoxins] ไปยังเป้าหมายเพิ่มเติม เป็นเวลา 2 รอบ\n#F10#\n#F40##L10# ปรสิต: #L0# [host] ขยายเวลาเย็นด้วย 3 รอบหลังจากใช้ท่าเล็ก ๆ นอกจากนี้ ยังใช้ 1 สแต็ค [Neurotoxins] กับศัตรูทั้งหมดอีกด้วย",
		describe_en = "Nihilego use the toxic element to attack the enemies in a row, dealing #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#.Additionally apply a stack of [Neurotoxins] to the target for 2 rounds.\n#F10#\n#F40##L10# Parasitism: #L0# The [host] extend the cool time with 3 rounds after using the small move.",
		describe_es = "Nihilego usa el elemento tóxico para atacar a los enemigos seguidos, causando #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#. Además, aplica una acumulación de [Neurotoxins] al objetivo. durante 2 rondas.\n#F10#\n#F40##L10# Parasitismo: #L0# El [host] extiende el tiempo de enfriamiento con 3 rondas después de usar el movimiento pequeño.",
		zawakeSimpleDesc_en = "After Nihilego himself or [Host] uses a small skill, add 1 layer of [Toxic Element] to all enemies for 2 rounds",
		describe_vn = "Nihilego usa o elemento tóxico para atacar os inimigos em sequência, distribuindo #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#.Adicionalmente aplique uma pilha de [Neurotoxins] ao alvo por 2 rodadas.\n#F10#\n#F40##L10# Parasitismo: #L0# O [host] prolonga o tempo de resfriamento com 3 rodadas após usar o movimento pequeno.",
		zawakeEffectDesc_en = "Nihilego use the toxic element to attack the enemies in a row, dealing #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#.Additionally apply a stack of [Neurotoxins] to the target for 2 rounds.\n#F10#\n#F40##L10# Parasitism: #L0# The [host] extend the cool time with 3 rounds after using the small move. Additionally applies 1 stack of [Neurotoxins] to all enemies",
		zawakeSimpleDesc_vn = "Após o próprio Nihilego ou [Host] usar uma pequena habilidade, adicione 1 camada de [Toxic Element] a todos os inimigos por 2 rodadas",
		zawakeSimpleDesc_id = "Setelah Nihilego sendiri atau [Host] menggunakan skill kecil, tambahkan 1 lapis [Toxic Element] ke semua musuh selama 2 ronde",
		zawakeSimpleDesc_es = "Después de que el propio Nihilego o [Host] use una pequeña habilidad, agrega 1 capa de [Toxic Element] a todos los enemigos durante 2 rondas.",
		describe_id = "Nihilego menggunakan elemen beracun untuk menyerang musuh berturut-turut, menimbulkan #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#. Selain itu menerapkan tumpukan [Neurotoxins] ke target untuk 2 ronde.\n#F10#\n#F40##L10# Parasitisme: #L0# [host] memperpanjang waktu cooldown dengan 3 ronde setelah menggunakan gerakan kecil.",
		zawakeSimpleDesc_kr = "니힐레고 자신이나 [Host]가 작은 스킬을 사용한 후 2라운드 동안 모든 적에게 [Toxic Element]의 1레이어를 추가합니다.",
		zawakeEffectDesc_id = "Nihilego menggunakan elemen beracun untuk menyerang musuh berturut-turut, menimbulkan #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#. Selain itu menerapkan tumpukan [Neurotoxins] ke target untuk 2 ronde.\n#F10#\n#F40##L10# Parasitisme: #L0# [host] memperpanjang waktu cooldown dengan 3 ronde setelah menggunakan gerakan kecil. Selain itu menerapkan 1 tumpukan [Neurotoxins] ke semua musuh",
		describe_kr = "니힐레고는 독성 원소를 사용하여 연속적으로 적을 공격하며 #C0x3D8A99#160%SP.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#SP.DMG#C0x5B545B#를 처리합니다. 추가로 대상에게 [Neurotoxins] 스택을 적용합니다. 2라운드.\n#F10#\n#F40##L10# 기생: #L0# [host]은 작은 움직임을 사용한 후 3라운드로 쿨타임을 연장합니다.",
