	[18141] = {
		zawakeEffectDesc_kr = "Dusknoir는 유령 그림자 주먹을 소환하여 적 하나를 공격하여 거래를 합니다#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#40% 확률로 1라운드 동안 적을 블랙홀에 흡수합니다. (블랙홀에 흡수된 적들은 공격할 수 없고, 공격을 받을 수도 없습니다)",
		zawakeEffectDesc_vn = "Dusknoir invoca punhos de sombra fantasma para atacar um único inimigo e lidar com #C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#com 40% de chance de absorver inimigos em um buraco negro por 1 rodada (inimigos absorvidos em um buraco negro não podem atacar ou ser atacados)",
		simDesc_es = "Dusknoir invoca puños de sombra fantasma para atacar a un solo objetivo enemigo.",
		describe_en = "Dusknoir summons ghost shadow fists to attack a single enemy to deal#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#with 30% chance to absorb enemies into a black hole for 1 round (enemies absorbed in a black hole can't attack or be attacked)",
		zawakeEffectDesc_th = "ดัสค์นัวร์เรียกหมัดเงาผีมาโจมตีศัตรูตัวเดียวเพื่อสร้างความเสียหาย#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B# พร้อมโอกาส 40% ที่จะดูดซับศัตรูเข้าสู่หลุมดำเป็นเวลา 1 รอบ (ศัตรูที่ถูกดูดกลืนในหลุมดำไม่สามารถโจมตีหรือถูกโจมตีได้)",
		describe_es = "Dusknoir invoca puños de sombra fantasma para atacar a un solo enemigo y lidiar con #C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#con un 30% de probabilidad de absorber enemigos en un agujero negro durante 1 ronda. (Los enemigos absorbidos en un agujero negro no pueden atacar ni ser atacados)",
		simDesc_vn = "Dusknoir invoca punhos de sombras fantasmas para atacar um único alvo inimigo",
		zawakeSimpleDesc_en = "with 30% chance to absorb enemies into a black hole for 1 round \n#F20#\n#F40##C0x5c9970#→with 40% chance to absorb enemies into a black hole for 1 round",
		describe_vn = "Dusknoir invoca punhos de sombra fantasma para atacar um único inimigo e lidar com #C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#com 30% de chance de absorver inimigos em um buraco negro por 1 rodada (inimigos absorvidos em um buraco negro não podem atacar ou ser atacados)",
		zawakeEffectDesc_id = "Dusknoir memanggil tinju bayangan hantu untuk menyerang satu musuh untuk menangani#C0xE69900#100%P.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#P.DMG#C0x5B545B#dengan peluang 40% untuk menyerap musuh ke dalam lubang hitam selama 1 putaran (musuh yang terserap dalam lubang hitam tidak dapat menyerang atau diserang)",
