	[36312] = {
		zawakeEffectDesc_kr = "#C0xC0C0C0#다이아몬드의 성스러운 빛, 비를 내려주세요#C0x5B545B#\n#F10#\n#F40#디안시는 머리에 있는 보석에서 강력한 빛을 방출하여 적 하나를 공격하며 #C0x3D8A99#180%SP.ATK를 처리합니다. #C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 그리고 디안시의 P.&SP.DMG 합계의 400%를 흡수할 수 있는 2라운드 파워 젬 실드를 자신과 가장 높은 아군 포켓몬에게 적용합니다. ATK(최대 P.&SP.ATK 소요). 동시에 다른 무작위 바위/요정 포켓몬에게 2라운드 파워 젬 실드를 줍니다. 공격 전 이 쉴드를 사용하는 아군의 P.&Sp.ATK가 일시적으로 20% 증가합니다(파워 젬 중첩 불가). 요정형 포켓몬이 추가되면 치유율이 15% 증가합니다. 바위타입 포켓몬이 추가되면 데미지 감소가 10% 증가합니다. 파워 젬 실드가 파괴되면 2라운드 동안 자신의 P.&Sp.ATK가 15% 감소합니다(2회 중첩 가능).",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Santa luz do Diamante, por favor chova sobre nós#C0x5B545B#\n#F10#\n#F40#Diancie libera uma luz forte da gema na cabeça para atacar um único inimigo, distribuindo #C0x3D8A99#180%SP.ATK #C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e infligindo um escudo de gema de poder de 2 rodadas que pode absorver 400% da soma do P.&SP.DMG de Diancie para si mesmo e um Pokémon aliado com o maior ATK(leva no máximo P.&SP.ATK). Ao mesmo tempo, concede um escudo de power gem de 2 rodadas a outro Pokémon aleatório do tipo Rock/Fairy. Aumento temporário de 20% de P.&Sp.ATK para se aliar a este escudo antes de atacar (Power Gem não pode ser empilhado). Quando Pokémon do tipo Fada são adicionados, aumenta a taxa de cura em 15%; quando Pokémon do tipo Rock é adicionado, aumenta a redução de DMG em 10%; quando o escudo da gema de poder é quebrado, ele também reduz o P.&Sp.ATK do lançador em 15% por 2 rodadas (pode acumular 2 vezes)",
		simDesc_es = "Diancie libera una luz deslumbrante de la gema en su cabeza para curar a todos los aliados.",
		describe_en = "#C0xC0C0C0#The holy light of diamond, please shine on us#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on its head to attack a single enemy, dealing #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, grants itself and the ally with the highest ATK a power gem shield for 2 rounds, which can absorb damage equal to 300% of the sum of Diancie's SP.DEF and P.DEF, and grants another random Rock/Fairy type ally a power gem shield for 2 rounds. The ally holds power gem shield temporarily increases 10% P.&Sp.ATK before attacking (Power Gems are not stackable). Fairy-Type ally with Power Gem increases 15% Healing Rate; Rock-Type ally with Power Gem increases 10% DMG Reduction.",
		zawakeEffectDesc_th = "#C0xC0C0C0#แสงศักดิ์สิทธิ์ของเพชร โปรดโปรยลงมาให้เราหน่อย#C0x5B545B#\n#F10#\n#F40#Diancie ปล่อยแสงอันแรงกล้าจากอัญมณีบนหัวเพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#180%SP.ATK #C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และสร้างโล่อัญมณีพลัง 2 รอบที่สามารถดูดซับ 400% ของผลรวมของ P.&SP.DMG ของ Diancie ให้กับตนเองและโปเกมอนพันธมิตรที่มีค่าสูงสุด ATK(รับพลังโจมตีสูงสุด&SP.ATK) ในเวลาเดียวกัน สร้างเกราะอัญมณีพลัง 2 รอบให้กับโปเกมอนประเภทร็อค/แฟรี่แบบสุ่มตัวอื่น เพิ่ม P.&Sp.ATK 20% ชั่วคราวให้กับพันธมิตรด้วยโล่นี้ก่อนโจมตี (Power Gem ไม่สามารถทับซ้อนกันได้) เมื่อเพิ่มโปเกมอนประเภทนางฟ้า เพิ่มอัตราการรักษา 15% เมื่อเพิ่มโปเกมอนประเภทร็อค เพิ่มการลดความเสียหาย 10% เมื่อโล่อัญมณีพลังถูกทำลาย จะลด P.&Sp.ATK ของผู้ร่ายลง 15% เป็นเวลา 2 รอบ (สามารถซ้อนทับได้ 2 ครั้ง)",
		describe_es = "#C0xC0C0C0#La luz sagrada del diamante, por favor brilla sobre nosotros#C0x5B545B#\n#F10#\n#F40#Diancie libera una luz fuerte de la gema en su cabeza para atacar a un solo enemigo, causando #C0x3D8A99#180%SP .ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, se otorga a sí mismo y al aliado con mayor ATK un escudo de gemas de poder durante 2 rondas, que puede absorber daño equivalente al 300% de la suma del SP de Diancie. .DEF y P.DEF, y otorga a otro aliado aleatorio de tipo Roca/Hada un escudo de gemas de poder durante 2 rondas. El aliado que tiene un escudo de gemas de poder aumenta temporalmente un 10% P.&Sp.ATK antes de atacar (las gemas de poder no son acumulables). El aliado tipo Hada con Power Gem aumenta un 15% la tasa de curación; El aliado tipo roca con Power Gem aumenta un 10% la reducción de daño.",
		simDesc_vn = "Diancie libera uma luz ofuscante da gema em sua cabeça para curar todos os aliados",
		zawakeSimpleDesc_en = "#C0x5c9970#The shield value of the power gem shield is increased to 400%, and the temporarily increased P. & Sp. ATK before the shield attacks is increased to 20%; when the power gem shield is broken, it also reduces the caster's P. & Sp. ATK by 15% for 2 rounds (can stack 2 times)",
		describe_vn = "#C0xC0C0C0#A luz sagrada do diamante, por favor, brilhe sobre nós#C0x5B545B#\n#F10#\n#F40#Diancie libera uma luz forte da gema em sua cabeça para atacar um único inimigo, distribuindo #C0x3D8A99#180%SP .ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, concede a si mesmo e ao aliado com o maior ATK um escudo de gema de poder por 2 rodadas, que pode absorver dano igual a 300% da soma do SP de Diancie .DEF e P.DEF, e concede a outro aliado aleatório do tipo Pedra/Fada um escudo de gema de poder por 2 rodadas. O aliado detém o escudo da gema de poder e aumenta temporariamente 10% de P.&Sp.ATK antes de atacar (as gemas de poder não são acumuláveis). Aliado Fairy-Type com Power Gem aumenta 15% da Taxa de Cura; Aliado Rock-Type com Power Gem aumenta 10% de redução de DMG.",
		zawakeEffectDesc_id = "#C0xC0C0C0#Cahaya Suci Berlian, tolong hujani kami#C0x5B545B#\n#F10#\n#F40#Diancie melepaskan cahaya kuat dari permata di kepala untuk menyerang musuh tunggal, menimbulkan #C0x3D8A99#180%SP.ATK #C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan memberikan perisai permata kekuatan 2 putaran yang dapat menyerap 400% jumlah P.&SP.DMG Diancie kepada diri sendiri dan Pokémon sekutu dengan nilai tertinggi ATK(membutuhkan maks. P.&SP.ATK). Pada saat yang sama, berikan perisai permata kekuatan 2 putaran ke Pokémon tipe Batu/Peri acak lainnya. Peningkatan sementara 20% P.&Sp.ATK ke sekutu dengan perisai ini sebelum menyerang (Permata Kekuatan tidak dapat ditumpuk). Saat Pokémon tipe Peri ditambahkan, meningkatkan tingkat penyembuhan sebesar 15%; ketika Pokémon tipe Rock ditambahkan, meningkatkan Pengurangan DMG sebesar 10%; ketika perisai permata kekuatan rusak, itu juga mengurangi P.&Sp.ATK kastor sebesar 15% selama 2 putaran (dapat ditumpuk 2 kali)",
		zawakeEffectDesc_es = "#C0xC0C0C0#Santa luz de Diamante, por favor llueve sobre nosotros#C0x5B545B#\n#F10#\n#F40#Diancie libera una luz fuerte de la gema en la cabeza para atacar a un solo enemigo, causando #C0x3D8A99#180%SP.ATK #C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e inflige un escudo de gemas de poder de 2 rondas que puede absorber el 400% de la suma del P.&SP.DMG de Diancie a uno mismo y a un Pokémon aliado con el mayor ATK (toma máx. P.&SP.ATK). Al mismo tiempo, otorga un escudo de gemas de poder de 2 rondas a otro Pokémon aleatorio de tipo Roca/Hada. Aumento temporal del 20% de P.&Sp.ATK para aliarse con este escudo antes de atacar (Power Gem no se puede acumular). Cuando se agrega Pokémon de tipo Hada, aumenta la tasa de curación en un 15%; cuando se agrega Pokémon de tipo Roca, aumenta la reducción de daño en un 10%; Cuando el escudo de la gema de poder se rompe, también reduce el P.&Sp.ATK del lanzador en un 15% durante 2 rondas (se puede acumular 2 veces).",
		describe_th = "#C0xC0C0C0#แสงศักดิ์สิทธิ์ของเพชร โปรดส่องแสงมาที่เรา#C0x5B545B#\n#F10#\n#F40#Diancie ปล่อยแสงอันแรงกล้าจากอัญมณีบนหัวของมันเพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหาย #C0x3D8A99#180%SP .ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# มอบโล่อัญมณีพลังให้ตัวเองและพันธมิตรที่มี ATK สูงสุดเป็นเวลา 2 รอบ ซึ่งสามารถดูดซับความเสียหายได้เท่ากับ 300% ของผลรวม SP ของ Diancie .DEF และ P.DEF และมอบโล่อัญมณีพลังแก่พันธมิตรประเภท Rock/Fairy แบบสุ่มอีกตัวเป็นเวลา 2 รอบ พันธมิตรที่ถือโล่อัญมณีพลังจะเพิ่ม P.&Sp.ATK 10% ชั่วคราวก่อนโจมตี (อัญมณีพลังไม่สามารถซ้อนกันได้) พันธมิตรประเภทนางฟ้าที่มี Power Gem จะเพิ่มอัตราการรักษา 15%; พันธมิตรประเภทร็อคที่มี Power Gem จะเพิ่มการลด DMG 10%",
		zawakeSimpleDesc_th = "#C0x5c9970#ค่าโล่ของโล่อัญมณีพลังเพิ่มขึ้นเป็น 400% และค่า P. & Sp. เพิ่มขึ้นชั่วคราว ATK ก่อนการโจมตีด้วยโล่เพิ่มขึ้นเป็น 20%; เมื่อโล่อัญมณีพลังถูกทำลาย มันจะลด P. & Sp ของผู้ร่ายด้วย ATK 15% เป็นเวลา 2 รอบ (สามารถซ้อนได้ 2 ครั้ง)",
		zawakeSimpleDesc_kr = "#C0x5c9970#파워젬 실드의 실드값이 400%로 증가되며, 일시적으로 P.&Sp가 증가합니다. 방패 공격 전 공격력이 20%로 증가됩니다. 파워 젬 쉴드가 깨지면 시전자의 P. & Sp도 감소합니다. 2라운드 동안 공격력 15% 증가(2회 중첩 가능)",
		describe_id = "#C0xC0C0C0#Cahaya suci berlian, mohon menyinari kami#C0x5B545B#\n#F10#\n#F40#Diancie melepaskan cahaya kuat dari permata di kepalanya untuk menyerang satu musuh, menimbulkan #C0x3D8A99#180%SP .ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, memberi dirinya sendiri dan sekutu dengan ATK tertinggi sebuah perisai permata kekuatan selama 2 putaran, yang dapat menyerap kerusakan sebesar 300% dari jumlah SP Diancie .DEF dan P.DEF, dan memberi sekutu tipe Rock/Fairy acak lainnya sebuah perisai permata kekuatan selama 2 putaran. Sekutu yang memegang perisai permata kekuatan untuk sementara meningkatkan 10% P.&Sp.ATK sebelum menyerang (Permata Kekuatan tidak dapat ditumpuk). Sekutu Tipe Peri dengan Permata Kekuatan meningkatkan 15% Tingkat Penyembuhan; Sekutu Tipe Batu dengan Permata Kekuatan meningkatkan 10% Pengurangan DMG.",
		simDesc_en = "Diancie releases a dazzling light from the gem on its head to heal all allies",
		zawakeEffectDesc_en = "#C0xC0C0C0#Holy light of Diamond, please rain on us#C0x5B545B#\n#F10#\n#F40#Diancie releases a strong light from the gem on the head to attack single enemy, dealing #C0x3D8A99#180%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and inflicting a 2-round power gem shield that can absorb 400% of the sum of Diancie's P.&SP.DMG to self and an allied Pokémon with the highest ATK(takes max. P.&SP.ATK). At the same time, deals a 2-round power gem shield to another random Rock-/Fairy-type Pokémon. Temporary increase 20% of P.&Sp.ATK to ally with this shield before attacking(Power Gem can not be stack). When Fairy-type Pokémon is added, increases healing rate by 15%; when Rock-type Pokémon is added, increases DMG Reduction by 10%; when the power gem shield is broken, it also reduces the caster's P.&Sp.ATK by 15% for 2 rounds(can stack 2 times)",
		describe_kr = "#C0xC0C0C0#다이아몬드의 성스러운 빛을 비춰주세요#C0x5B545B#\n#F10#\n#F40#디안시는 머리에 있는 보석에서 강한 빛을 방출해 적 하나를 공격하며 #C0x3D8A99#180%SP를 발산합니다. .ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 자신과 ATK가 가장 높은 아군에게 2라운드 동안 파워 젬 실드를 부여합니다. 이 실드는 Diancie SP 합계의 300%에 해당하는 피해를 흡수할 수 있습니다. .DEF 및 P.DEF, 또 다른 무작위 바위/요정 유형 아군에게 2라운드 동안 파워 젬 쉴드를 부여합니다. 파워 젬 실드를 보유하고 있는 아군은 공격하기 전에 P.&Sp.ATK가 일시적으로 10% 증가합니다. (파워 젬은 쌓을 수 없습니다.) 파워 젬을 보유한 요정형 아군은 치유 속도를 15% 증가시킵니다. 파워 젬이 있는 암석형 아군은 데미지 감소를 10% 증가시킵니다.",
		simDesc_th = "Diancie ปล่อยแสงเจิดจ้าจากอัญมณีบนหัวเพื่อรักษาเพื่อนร่วมทีมทั้งหมด",
		zawakeSimpleDesc_vn = "#C0x5c9970#O valor do escudo da gema de poder foi aumentado para 400%, e o P. & Sp. O ATK antes dos ataques do escudo é aumentado para 20%; quando o escudo da gema de poder é quebrado, ele também reduz o P. e Sp do lançador. ATK em 15% por 2 rodadas (pode acumular 2 vezes)",
		zawakeSimpleDesc_id = "#C0x5c9970#Nilai perisai dari perisai permata kekuatan ditingkatkan menjadi 400%, dan P. & Sp meningkat sementara. ATK sebelum serangan perisai ditingkatkan menjadi 20%; ketika perisai permata kekuatan rusak, itu juga mengurangi P. & Sp kastor. ATK sebesar 15% selama 2 ronde (bisa di stack 2 kali)",
		zawakeSimpleDesc_es = "#C0x5c9970#El valor del escudo de la gema de poder aumenta al 400%, y el P. & Sp. aumentado temporalmente. El ATK antes de los ataques del escudo aumenta al 20%; Cuando el escudo de la gema de poder se rompe, también reduce la P. y Sp del lanzador. ATK en un 15 % durante 2 rondas (se puede acumular 2 veces)",
		simDesc_kr = "디안시가 머리에 있는 보석에서 눈부신 빛을 발산하여 아군 전체를 치유합니다.",
		id = 36312,
		simDesc_id = "Diancie melepaskan cahaya menyilaukan dari permata di kepalanya untuk menyembuhkan semua sekutu"
	},
