	[36515] = {
		describe_vn = "#C0xC0C0C0#Enquanto for para você, por mais perigoso que seja, eu irei!#C0x5B545B#",
		describe_kr = "#C0xC0C0C0#당신을 위해서라면 아무리 위험해도 가겠습니다!#C0x5B545B#",
		describe_en = "#C0xC0C0C0#As long as it is for you, no matter how dangerous it is, I will go!#C0x5B545B#",
		describe_id = "#C0xC0C0C0#Selama itu untukmu, betapapun berbahayanya, aku akan pergi!#C0x5B545B#",
