	[38311] = {
		describe_vn = "O Stufful usa sua pequena garra peluda para atacar um único alvo inimigo, distribuindo #C0xE69900#90% P.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#P.DMG#C0x5B545B#, e aumenta seu próprio P.ATK em 25% por 3 rodadas.",
		describe_kr = "스터풀은 작은 털복숭이 발톱으로 단일 적 대상을 공격해 #C0xE69900#90% P.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#P.DMG#C0x5B545B#를 주고 자신의 P.ATK를 25% 증가시킵니다. 3라운드 동안.",
		describe_en = "The Stufful uses its small furry claw to attack a single enemy target, dealing #C0xE69900#90% P.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#P.DMG#C0x5B545B#, and increases its own P.ATK by 25% for 3 rounds.",
		describe_id = "Stufful menggunakan cakar kecilnya yang berbulu untuk menyerang satu target musuh, menyebabkan #C0xE69900#90% P.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#P.DMG#C0x5B545B#, dan meningkatkan P.ATK miliknya sebesar 25% selama 3 putaran.",
		id = 38311,
		describe_es = "El Stufful usa su pequeña garra peluda para atacar a un solo objetivo enemigo, causando #C0xE69900#90% P.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#P.DMG#C0x5B545B#, y aumenta su propio P.ATK en un 25%. durante 3 rondas.",
		describe_th = "พวก Stufful ใช้กรงเล็บขนเล็กๆ ของมันโจมตีศัตรูเป้าหมายเดียว สร้างความเสียหาย #C0xE69900#90% P.ATK#C0x5B545B#+$(skillLevel*4*24)$ #C0xF13B54#P.DMG#C0x5B545B# และเพิ่ม P.ATK ของมันเอง 25% เป็นเวลา 3 รอบ"
	},
	[38312] = {
		describe_vn = "O Stufful dá uma cambalhota frontal para esmagar um único alvo inimigo, distribuindo #C0xE69900#170% P.ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#P.DMG#C0x5B545B#. Quando o ataque desencadeia um acerto crítico, um ataque básico adicional é executado. Se nenhum acerto crítico ocorrer, ele aumenta sua própria taxa de acerto crítico em 20% por 2 rodadas.",
		describe_kr = "Stufful은 전방 공중제비를 수행하여 단일 적 대상을 분쇄하여 #C0xE69900#170% P.ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#P.DMG#C0x5B545B#를 처리합니다. 해당 공격이 치명타 발생 시 추가 기본 공격이 수행됩니다. 치명타가 발생하지 않으면 2라운드 동안 자신의 치명타율이 20% 증가합니다.",
		describe_en = "The Stufful performs a front somersault to crush a single enemy target, dealing #C0xE69900#170% P.ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#P.DMG#C0x5B545B#. When the attack triggers a critical hit, an additional basic attack is performed. If no critical hit occurs, it increases its own critical hit rate by 20% for 2 rounds.",
		describe_id = "Stufful melakukan jungkir balik ke depan untuk menghancurkan satu target musuh, menyebabkan #C0xE69900#170% P.ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#P.DMG#C0x5B545B#. Ketika serangan tersebut memicu serangan kritis, serangan dasar tambahan akan dilakukan. Jika tidak terjadi serangan kritis, ia meningkatkan tingkat serangan kritisnya sendiri sebesar 20% selama 2 putaran.",
		id = 38312,
		describe_es = "The Stufful realiza un salto mortal frontal para aplastar a un solo objetivo enemigo, causando #C0xE69900#170% P.ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#P.DMG#C0x5B545B#. Cuando el ataque provoca un golpe crítico, se realiza un ataque básico adicional. Si no se produce ningún golpe crítico, aumenta su propia tasa de golpe crítico en un 20% durante 2 rondas.",
		describe_th = "พวก Stufful ตีลังกาหน้าเพื่อบดขยี้ศัตรูเป้าหมายเดียว สร้างความเสียหาย #C0xE69900#170% P.ATK#C0x5B545B#+$(skillLevel*4*48)$ #C0xF13B54#P.DMG#C0x5B545B# เมื่อการโจมตีทำให้เกิดการโจมตีแบบคริติคอล การโจมตีพื้นฐานเพิ่มเติมจะดำเนินการ หากไม่มีการโจมตีคริติคอลจะเพิ่มอัตราการโจมตีคริติคอลของตัวเอง 20% เป็นเวลา 2 รอบ"
	},
	[38313] = {
		describe_th = "Stufful รวบรวมความแข็งแกร่งและพุ่งเข้าใส่อย่างดุเดือด ทำให้ #C0xE69900#390% P.ATK#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#P.DMG#C0x5B545B# ไปยังเป้าหมายในคอลัมน์ เพิ่มอัตราคริติคอลและ P.ATK ของตัวเอง 35% เป็นเวลา 2 รอบ หากโจมตี 2 เป้าหมาย มีโอกาส 100% ที่จะ【สตัน】เป้าหมายทั้งสองนี้เป็นเวลา 1 รอบ",
		describe_en = "The Stufful gathers strength and charges fiercely, causing #C0xE69900#390% P.ATK#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#P.DMG#C0x5B545B# to targets in a column. It increases its own critical hit rate and P.ATK by 35% for 2 rounds. If it attacks 2 targets, there is a 100% chance to【Stun】these two targets for 1 round.",
		simDesc_es = "El Stufful reúne fuerza y ​​carga hacia adelante, atacando a los enemigos en una columna, al mismo tiempo que aumenta su propia tasa de golpes críticos y P.ATK.",
		describe_es = "El Stufful reúne fuerza y ​​carga ferozmente, causando #C0xE69900#390% P.ATK#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#P.DMG#C0x5B545B# a los objetivos en una columna. Aumenta su propia tasa de golpes críticos y P.ATK en un 35% durante 2 rondas. Si ataca a 2 objetivos, hay un 100% de posibilidades de aturdir a estos dos objetivos durante 1 ronda.",
		starEffectDesc_vn = "【Atordoamento】Alvos com P.ATK menor que ele mesmo por 1-2 rodadas.\nAtordoamento: Um efeito negativo que reduz ambos os ataques em 20%, inflige 20% de vulnerabilidade e tem uma chance igual à diferença de P.ATK para imobilizar o alvo. Quando Bewear ataca alvos na primeira fila que estão atordoados e não há unidades na última fila, eles serão empurrados de volta para a última fila. Ao atacar alvos atordoados na última fileira, há 30% de chance de removê-los diretamente do campo de batalha (ineficaz contra chefes e alvos com raridade maior que ela).",
		starEffectDesc_id = "【Stun】Target dengan P.ATK lebih rendah dari dirinya selama 1-2 ronde.\nStun: Efek negatif yang mengurangi kedua serangan sebesar 20%, menimbulkan kerentanan 20%, dan memiliki peluang yang sama dengan selisih P.ATK untuk melumpuhkan target. Ketika Bewear menyerang target di barisan depan yang terkena stun dan tidak ada unit di barisan belakang, maka mereka akan terdorong kembali ke barisan belakang. Saat menyerang target di barisan belakang yang terkena stun, ada 30% kemungkinan untuk langsung mengeluarkan mereka dari medan perang (tidak efektif melawan bos dan target dengan rarity lebih tinggi dari dirinya sendiri).",
		starEffectDesc_es = "【Aturdimiento】Objetivos con P.ATK más bajo que él durante 1-2 rondas.\nAturdimiento: un efecto negativo que reduce ambos ataques en un 20%, inflige un 20% de vulnerabilidad y tiene una probabilidad igual a la diferencia en P.ATK de inmovilizar. el objetivo. Cuando Bewear ataca objetivos en la primera fila que están aturdidos y no hay unidades en la última fila, serán empujados de regreso a la última fila. Al atacar objetivos en la última fila que están aturdidos, hay un 30% de probabilidad de eliminarlos directamente del campo de batalla (ineficaz contra jefes y objetivos con una rareza mayor que él).",
		describe_vn = "O Stufful reúne forças e ataca ferozmente, causando #C0xE69900#390% P.ATK#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#P.DMG#C0x5B545B# em alvos em uma coluna. Aumenta sua própria taxa de acerto crítico e P.ATK em 35% por 2 rodadas. Se atacar 2 alvos, há 100% de chance de 【Atordoar】 esses dois alvos por 1 rodada.",
		starEffectDesc_th = "【สตัน】กำหนดเป้าหมายที่มี P.ATK ต่ำกว่าตัวเองเป็นเวลา 1-2 รอบ \nสตัน: เอฟเฟกต์ด้านลบที่ลดการโจมตีทั้งสองลง 20% สร้างความเสียหาย 20% และมีโอกาสเท่ากับส่วนต่างของ P.ATK ที่จะ ทำให้เป้าหมายไม่เคลื่อนที่ เมื่อ Bewear โจมตีเป้าหมายแถวหน้าที่ถูกสตันและไม่มียูนิตในแถวหลัง พวกเขาจะถูกผลักกลับไปแถวหลัง เมื่อโจมตีเป้าหมายแถวหลังที่มึนงง มีโอกาส 30% ที่จะลบพวกเขาออกจากสนามรบโดยตรง (ไม่มีประสิทธิภาพกับบอสและเป้าหมายที่มีความหายากสูงกว่าตัวมันเอง)",
		describe_id = "Stufful mengumpulkan kekuatan dan menyerang dengan ganas, menyebabkan #C0xE69900#390% P.ATK#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#P.DMG#C0x5B545B# mengenai target dalam satu kolom. Ini meningkatkan tingkat serangan kritis dan P.ATK sebesar 35% selama 2 putaran. Jika menyerang 2 target, ada kemungkinan 100% untuk melakukan 【Stun】 pada kedua target tersebut selama 1 putaran.",
		simDesc_en = "The Stufful gathers strength and charges forward, attacking enemies in a column, while also boosting its own critical hit rate and P.ATK.",
		simDesc_vn = "O Stufful reúne força e avança, atacando os inimigos em uma coluna, ao mesmo tempo que aumenta sua própria taxa de acerto crítico e P.ATK.",
		describe_kr = "스터풀은 힘을 모아 맹렬하게 돌진해 #C0xE69900#390% P.ATK#C0x5B545B#+$(skillLevel*4*75)$ #C0xF13B54#P.DMG#C0x5B545B#가 열의 대상에게 발생합니다. 2라운드 동안 자신의 치명타율과 공격력이 35% 증가합니다. 2명의 대상을 공격할 경우 100% 확률로 1라운드 동안 두 대상을 모두【스턴】시킵니다.",
		simDesc_th = "Stufful รวบรวมความแข็งแกร่งและพุ่งไปข้างหน้า โจมตีศัตรูที่อยู่ในแนวเสา ในขณะเดียวกันก็เพิ่มอัตราการโจมตีคริติคอลและ P.ATK ของตัวเองด้วย",
		starEffectDesc_kr = "【스턴】 자신보다 낮은 P.ATK를 1~2라운드 동안 대상으로 삼습니다.\n스턴: 두 공격 모두 20% 감소하고 20% 취약성을 부여하며 P.ATK 차이만큼 확률로 받는 부정적인 효과입니다. 표적을 고정시킵니다. Bewear가 기절한 앞줄의 대상을 공격하고 뒷줄에 유닛이 없으면 뒷줄로 밀려납니다. 기절한 뒷줄의 대상을 공격할 때, 30% 확률로 전장에서 직접 제거됩니다. (자신보다 희귀도가 높은 보스 및 대상에게는 효과가 없습니다.)",
		simDesc_kr = "스터풀은 힘을 모아 전방으로 돌진하며 일렬로 늘어선 적을 공격하는 동시에 자신의 치명타율과 P.ATK를 증가시킵니다.",
		starEffectDesc_en = "【Stun】Targets with lower P.ATK than itself for 1-2 rounds.\nStun: A negative effect that reduces both attacks by 20%, inflicts 20% vulnerability, and has a chance equal to the difference in P.ATK to immobilize the target. When Bewear attacks targets in the front row who are stunned and there are no units in the back row, they will be pushed back to the back row. When attacking targets in the back row who are stunned, there is a 30% chance to directly remove them from the battlefield (ineffective against bosses and targets with a rarity higher than itself).",
		id = 38313,
		simDesc_id = "Stufful mengumpulkan kekuatan dan menyerang ke depan, menyerang musuh dalam satu kolom, sekaligus meningkatkan tingkat serangan kritis dan P.ATK miliknya."
	},
	[38316] = {
		describe_en = "Furry: Reduces the DMG received from active skill attacks by #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, but increases the P.DMG received from fire attribute attacks by 50%. For each normal type teammate on entry, increases its own maximum health by 20%. For each fighting type teammate on entry, increases its own defense rate and defense penetration rate by 20%.",
		describe_es = "Furry: Reduce el DAÑO recibido por ataques de habilidades activas en un #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, pero aumenta el P.DMG recibido por ataques de atributo de fuego en un 50%. Por cada compañero de equipo de tipo normal al ingresar, aumenta su propia salud máxima en un 20%. Por cada compañero de equipo de tipo luchador al ingresar, aumenta su propia tasa de defensa y su tasa de penetración de defensa en un 20%.",
		describe_kr = "퍼리 : 액티브 스킬 공격으로 받는 데미지가 #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B# 감소하지만, 불 속성 공격으로 받는 데미지가 50% 증가합니다. 입장 시 일반형 팀원 한 명당 자신의 최대 체력이 20% 증가합니다. 입장 시 전투 유형 팀원 한 명당 자신의 방어율과 방어 침투율이 20% 증가합니다.",
		starEffectDesc_th = "เมื่อถูกโจมตีและกระตุ้นการต่อต้าน การโจมตีพื้นฐานจะตอบโต้เป้าหมาย หากไม่มีความต้านทาน อัตราการต้านทานตัวเองจะเพิ่มขึ้น 30% เป็นเวลา 2 รอบ (สามารถซ้อนทับได้สูงสุด 2 ครั้ง)",
		starEffectDesc_kr = "공격을 받고 저항이 발동되면 기본 공격이 대상을 반격합니다. 저항이 없으면 2라운드 동안 자기 저항률이 30% 증가합니다. (최대 2회 중첩 가능)",
		starEffectDesc_vn = "Ao ser atacado e desencadear resistência, os ataques básicos irão contra-atacar o alvo; se não houver resistência, a taxa de auto-resistência será aumentada em 30% por 2 rodadas (pode ser acumulada até 2 vezes).",
		describe_th = "ขนยาว: ลด DMG ที่ได้รับจากการโจมตีด้วยทักษะแอ็กทีฟลง #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B# แต่เพิ่ม P.DMG ที่ได้รับจากการโจมตีด้วยธาตุไฟ 50% สำหรับเพื่อนร่วมทีมประเภทปกติแต่ละคนที่เข้ามา จะเพิ่มพลังชีวิตสูงสุดของตัวเอง 20% สำหรับเพื่อนร่วมทีมประเภทการต่อสู้แต่ละคนที่เข้ามา จะเพิ่มอัตราการป้องกันและอัตราการเจาะเกราะของตัวเอง 20%",
		starEffectDesc_id = "Saat diserang dan memicu perlawanan, serangan dasar akan menyerang balik target; jika tidak ada resistensi, tingkat resistensi diri akan ditingkatkan sebesar 30% selama 2 putaran (dapat ditumpuk hingga 2 kali).",
		describe_vn = "Furry: Reduz o DMG recebido de ataques de habilidades ativas em #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, mas aumenta o P.DMG recebido de ataques de atributos de fogo em 50%. Para cada companheiro de equipe do tipo normal na entrada, aumenta sua própria saúde máxima em 20%. Para cada companheiro de equipe do tipo lutador ao entrar, aumenta sua própria taxa de defesa e taxa de penetração de defesa em 20%.",
		starEffectDesc_en = "When being attacked and triggering resistance, basic attacks will counterattack the target; if there is no resistance, the self-resistance rate will be increased by 30% for 2 rounds (can be stacked up to 2 times).",
		starEffectDesc_es = "Al ser atacado y desencadenar resistencia, los ataques básicos contraatacarán al objetivo; si no hay resistencia, la tasa de autorresistencia aumentará en un 30% durante 2 rondas (se puede acumular hasta 2 veces).",
		id = 38316,
		describe_id = "Furry: Mengurangi DMG yang diterima dari serangan skill aktif sebesar #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, namun meningkatkan P.DMG yang diterima dari serangan atribut api sebesar 50%. Untuk setiap rekan setim tipe normal yang masuk, meningkatkan kesehatan maksimumnya sendiri sebesar 20%. Untuk setiap rekan satu tim yang bertipe bertarung saat masuk, meningkatkan tingkat pertahanan dan tingkat penetrasi pertahanannya sendiri sebesar 20%."
	},
	[38321] = {
		describe_vn = "O Bewear usa suas garras para atacar um único alvo inimigo, distribuindo #C0xE69900#100% P.DMG#C0x5B545B#+$(skillLevel*4*24)$ com base em seu P.ATK e aumentando seu próprio P.ATK em 25% por 3 rodadas.",
		describe_kr = "Bewear는 발톱을 사용하여 단일 적 대상을 공격합니다. P.ATK에 따라 #C0xE69900#100% P.DMG#C0x5B545B#+$(skillLevel*4*24)$를 처리하고 3라운드 동안 자신의 P.ATK를 25%만큼 증가시킵니다.",
		describe_en = "The Bewear uses its claws to attack a single enemy target., dealing #C0xE69900#100% P.DMG#C0x5B545B#+$(skillLevel*4*24)$ based on its P.ATK, and boosting its own P.ATK by 25% for 3 rounds.",
		describe_id = "Bewear menggunakan cakarnya untuk menyerang satu target musuh, menimbulkan #C0xE69900#100% P.DMG#C0x5B545B#+$(skillLevel*4*24)$ berdasarkan P.ATK-nya, dan meningkatkan P.ATK-nya sendiri sebesar 25% selama 3 ronde.",
		id = 38321,
		describe_es = "El Bewear usa sus garras para atacar a un solo objetivo enemigo, causando #C0xE69900#100% P.DMG#C0x5B545B#+$(skillLevel*4*24)$ según su P.ATK y aumentando su propio P.ATK en un 25% durante 3 rondas.",
		describe_th = "Bewear ใช้กรงเล็บของมันโจมตีศัตรูเป้าหมายเดียว สร้างความเสียหาย #C0xE69900#100% P.DMG#C0x5B545B#+$(skillLevel*4*24)$ ตาม P.ATK ของมัน และเพิ่ม P.ATK ของตัวเอง 25% เป็นเวลา 3 รอบ"
	},
	[38322] = {
		describe_vn = "O Bewear desfere um ataque terrestre poderoso contra um único alvo, distribuindo #C0xE69900#180% P.DMG#C0x5B545B#+$(skillLevel*4*48)$ com base em seu P.ATK. Se o ataque desencadear um acerto crítico, ele segue adicionalmente com um ataque básico. Se nenhum acerto crítico ocorrer, ele aumenta sua própria taxa de acerto crítico em 20% por 2 rodadas.",
		describe_kr = "Bewear는 P.ATK를 기준으로 #C0xE69900#180% P.DMG#C0x5B545B#+$(skillLevel*4*48)$를 처리하여 단일 대상에 대해 강력한 지상 타격을 가합니다. 공격이 치명타를 유발하면 추가로 기본 공격이 이어집니다. 치명타가 발생하지 않으면 2라운드 동안 자신의 치명타율이 20% 증가합니다.",
		describe_en = "The Bewear delivers a powerful ground strike against a single target, dealing #C0xE69900#180% P.DMG#C0x5B545B#+$(skillLevel*4*48)$ based on its P.ATK. If the attack triggers a critical hit, it additionally follows up with a basic attack. If no critical hit occurs, it boosts its own critical hit rate by 20% for 2 rounds.",
		describe_id = "Bewear melancarkan serangan darat yang kuat terhadap satu target, mengakibatkan #C0xE69900#180% P.DMG#C0x5B545B#+$(skillLevel*4*48)$ berdasarkan P.ATK-nya. Jika serangan tersebut memicu serangan kritis, serangan tersebut juga akan ditindaklanjuti dengan serangan dasar. Jika tidak terjadi serangan kritis, ia meningkatkan tingkat serangan kritisnya sendiri sebesar 20% selama 2 putaran.",
		id = 38322,
		describe_es = "El Bewear lanza un poderoso ataque terrestre contra un solo objetivo, causando #C0xE69900#180% P.DMG#C0x5B545B#+$(skillLevel*4*48)$ según su P.ATK. Si el ataque desencadena un golpe crítico, además sigue con un ataque básico. Si no se produce ningún golpe crítico, aumenta su propia tasa de golpes críticos en un 20% durante 2 rondas.",
		describe_th = "Bewear โจมตีภาคพื้นดินอย่างทรงพลังต่อเป้าหมายเดียว สร้างความเสียหาย #C0xE69900#180% P.DMG#C0x5B545B#+$(skillLevel*4*48)$ ตาม P.ATK ของมัน หากการโจมตีทำให้เกิดการโจมตีคริติคอล มันจะติดตามผลด้วยการโจมตีพื้นฐานเพิ่มเติม หากไม่มีการโจมตีคริติคอล มันจะเพิ่มอัตราการโจมตีคริติคอลของตัวเอง 20% เป็นเวลา 2 รอบ"
	},
	[38323] = {
		describe_en = "The Bewear utilizes the force of mountain-splitting to attack targets in a column, dealing #C0xE69900#400% P.DMG#C0x5B545B#+$(skillLevel*4*75)$ based on its P.ATK. It boosts its own critical hit rate and P.ATK by 35% for 2 rounds. If it attacks 2 targets, it has a 100% chance to inflict those targets with【Stun】for 1 round.",
		describe_es = "El Bewear utiliza la fuerza de división de montañas para atacar objetivos en una columna, causando #C0xE69900#400% P.DMG#C0x5B545B#+$(skillLevel*4*75)$ según su P.ATK. Aumenta su propia tasa de golpes críticos y P.ATK en un 35% durante 2 rondas. Si ataca a 2 objetivos, tiene un 100% de posibilidades de infligirles 【Aturdimiento】 durante 1 ronda.",
		describe_kr = "Bewear는 산을 가르는 힘을 활용하여 열의 대상을 공격하며 P.ATK를 기준으로 #C0xE69900#400% P.DMG#C0x5B545B#+$(skillLevel*4*75)$를 처리합니다. 2라운드 동안 자신의 치명타율과 공격력이 35% 증가합니다. 2명의 대상을 공격하면 100% 확률로 해당 대상에게 1라운드 동안 【스턴】을 건다.",
		starEffectDesc_th = "【สตัน】กำหนดเป้าหมายที่มี P.ATK ต่ำกว่าตัวเองเป็นเวลา 1-2 รอบ \nสตัน: เอฟเฟกต์ด้านลบที่ลดการโจมตีทั้งสองลง 20% สร้างความเสียหาย 20% และมีโอกาสเท่ากับส่วนต่างของ P.ATK ที่จะ ทำให้เป้าหมายไม่เคลื่อนที่ เมื่อ Bewear โจมตีเป้าหมายแถวหน้าที่ถูกสตันและไม่มียูนิตในแถวหลัง พวกเขาจะถูกผลักกลับไปแถวหลัง เมื่อโจมตีเป้าหมายแถวหลังที่มึนงง มีโอกาส 30% ที่จะลบพวกเขาออกจากสนามรบโดยตรง (ไม่มีประสิทธิภาพกับบอสและเป้าหมายที่มีความหายากสูงกว่าตัวมันเอง)",
		starEffectDesc_kr = "【스턴】 자신보다 낮은 P.ATK를 1~2라운드 동안 대상으로 삼습니다.\n스턴: 두 공격 모두 20% 감소하고 20% 취약성을 부여하며 P.ATK 차이만큼 확률로 받는 부정적인 효과입니다. 표적을 고정시킵니다. Bewear가 기절한 앞줄의 대상을 공격하고 뒷줄에 유닛이 없으면 뒷줄로 밀려납니다. 기절한 뒷줄의 대상을 공격할 때, 30% 확률로 전장에서 직접 제거됩니다. (자신보다 희귀도가 높은 보스 및 대상에게는 효과가 없습니다.)",
		starEffectDesc_vn = "【Atordoamento】Alvos com P.ATK menor que ele mesmo por 1-2 rodadas.\nAtordoamento: Um efeito negativo que reduz ambos os ataques em 20%, inflige 20% de vulnerabilidade e tem uma chance igual à diferença de P.ATK para imobilizar o alvo. Quando Bewear ataca alvos na primeira fila que estão atordoados e não há unidades na última fila, eles serão empurrados de volta para a última fila. Ao atacar alvos atordoados na última fileira, há 30% de chance de removê-los diretamente do campo de batalha (ineficaz contra chefes e alvos com raridade maior que ela).",
		describe_th = "Bewear ใช้พลังแยกภูเขาเพื่อโจมตีเป้าหมายในแนวเสา สร้างความเสียหาย #C0xE69900#400% P.DMG#C0x5B545B#+$(skillLevel*4*75)$ ตาม P.ATK ของมัน เพิ่มอัตราคริติคอลและ P.ATK ของตัวเอง 35% เป็นเวลา 2 รอบ หากโจมตี 2 เป้าหมาย จะมีโอกาส 100% ที่จะสร้างความเสียหายให้เป้าหมายเหล่านั้นด้วย【สตัน】เป็นเวลา 1 รอบ",
		starEffectDesc_id = "【Stun】Target dengan P.ATK lebih rendah dari dirinya selama 1-2 ronde.\nStun: Efek negatif yang mengurangi kedua serangan sebesar 20%, menimbulkan kerentanan 20%, dan memiliki peluang yang sama dengan selisih P.ATK untuk melumpuhkan target. Ketika Bewear menyerang target di barisan depan yang terkena stun dan tidak ada unit di barisan belakang, maka mereka akan terdorong kembali ke barisan belakang. Saat menyerang target di barisan belakang yang terkena stun, ada 30% kemungkinan untuk langsung mengeluarkan mereka dari medan perang (tidak efektif melawan bos dan target dengan rarity lebih tinggi dari dirinya sendiri).",
		describe_vn = "O Bewear utiliza a força de divisão de montanhas para atacar alvos em uma coluna, distribuindo #C0xE69900#400% P.DMG#C0x5B545B#+$(skillLevel*4*75)$ com base em seu P.ATK. Ele aumenta sua própria taxa de acerto crítico e P.ATK em 35% por 2 rodadas. Se atacar 2 alvos, tem 100% de chance de infligir 【Atordoamento】 a esses alvos por 1 rodada.",
		starEffectDesc_en = "【Stun】Targets with lower P.ATK than itself for 1-2 rounds.\nStun: A negative effect that reduces both attacks by 20%, inflicts 20% vulnerability, and has a chance equal to the difference in P.ATK to immobilize the target. When Bewear attacks targets in the front row who are stunned and there are no units in the back row, they will be pushed back to the back row. When attacking targets in the back row who are stunned, there is a 30% chance to directly remove them from the battlefield (ineffective against bosses and targets with a rarity higher than itself).",
		starEffectDesc_es = "【Aturdimiento】Objetivos con P.ATK más bajo que él durante 1-2 rondas.\nAturdimiento: un efecto negativo que reduce ambos ataques en un 20%, inflige un 20% de vulnerabilidad y tiene una probabilidad igual a la diferencia en P.ATK de inmovilizar. el objetivo. Cuando Bewear ataca objetivos en la primera fila que están aturdidos y no hay unidades en la última fila, serán empujados de regreso a la última fila. Al atacar objetivos en la última fila que están aturdidos, hay un 30% de probabilidad de eliminarlos directamente del campo de batalla (ineficaz contra jefes y objetivos con una rareza mayor que él).",
		id = 38323,
		describe_id = "Bewear memanfaatkan kekuatan membelah gunung untuk menyerang target dalam satu kolom, mengakibatkan #C0xE69900#400% P.DMG#C0x5B545B#+$(skillLevel*4*75)$ berdasarkan P.ATK-nya. Ini meningkatkan tingkat serangan kritis dan P.ATK sebesar 35% selama 2 putaran. Jika menyerang 2 target, ia mempunyai peluang 100% untuk memberikan efek Stun kepada target tersebut selama 1 putaran."
	},
	[38326] = {
		describe_en = "Furry: Reduces the damage taken from active skill attacks by #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, but increases the damage taken from fire-type attacks by 50%. Upon entering, for each normal-type ally, it increases its own max HP by 20%. For each fighting-type ally, it increases its own defense and defense penetration rates by 20%.",
		describe_es = "Furry: Reduce el daño recibido por ataques de habilidades activas en un #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, pero aumenta el daño recibido por ataques de tipo fuego en un 50%. Al entrar, por cada aliado de tipo normal, aumenta su propio HP máximo en un 20%. Para cada aliado de tipo combatiente, aumenta su propia defensa y sus tasas de penetración de defensa en un 20%.",
		describe_kr = "퍼리 : 액티브 스킬 공격으로 받는 피해량이 #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B# 감소하지만, 불 속성 공격으로 받는 피해량이 50% 증가합니다. 입장 시 일반형 아군 한 명당 자신의 최대 HP가 20% 증가합니다. 전투형 아군 하나당 자신의 방어력과 방어 관통력이 20% 증가합니다.",
		starEffectDesc_th = "เมื่อถูกโจมตีและกระตุ้นการต่อต้าน การโจมตีพื้นฐานจะตอบโต้เป้าหมาย หากไม่มีความต้านทาน อัตราการต้านทานตัวเองจะเพิ่มขึ้น 30% เป็นเวลา 2 รอบ (สามารถซ้อนทับได้สูงสุด 2 ครั้ง)",
		starEffectDesc_kr = "공격을 받고 저항이 발동되면 기본 공격이 대상을 반격합니다. 저항이 없으면 2라운드 동안 자기 저항률이 30% 증가합니다. (최대 2회 중첩 가능)",
		starEffectDesc_vn = "Ao ser atacado e desencadear resistência, os ataques básicos irão contra-atacar o alvo; se não houver resistência, a taxa de auto-resistência será aumentada em 30% por 2 rodadas (pode ser acumulada até 2 vezes).",
		describe_th = "ขนยาว: ลดความเสียหายที่ได้รับจากการโจมตีด้วยทักษะใช้งานลง #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B# แต่เพิ่มความเสียหายที่ได้รับจากการโจมตีประเภทไฟ 50% เมื่อเข้ามา พันธมิตรประเภทปกติจะเพิ่ม HP สูงสุดของตัวเอง 20% สำหรับพันธมิตรประเภทการต่อสู้แต่ละประเภท จะเพิ่มอัตราการป้องกันและการเจาะเกราะของตัวเอง 20%",
		starEffectDesc_id = "Saat diserang dan memicu perlawanan, serangan dasar akan menyerang balik target; jika tidak ada resistensi, tingkat resistensi diri akan ditingkatkan sebesar 30% selama 2 putaran (dapat ditumpuk hingga 2 kali).",
		describe_vn = "Furry: Reduz o dano recebido de ataques de habilidades ativas em #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, mas aumenta o dano recebido de ataques do tipo fogo em 50%. Ao entrar, para cada aliado do tipo normal, aumenta seu próprio HP máximo em 20%. Para cada aliado do tipo lutador, aumenta sua própria defesa e taxas de penetração de defesa em 20%.",
		starEffectDesc_en = "When being attacked and triggering resistance, basic attacks will counterattack the target; if there is no resistance, the self-resistance rate will be increased by 30% for 2 rounds (can be stacked up to 2 times).",
		starEffectDesc_es = "Al ser atacado y desencadenar resistencia, los ataques básicos contraatacarán al objetivo; si no hay resistencia, la tasa de autorresistencia aumentará en un 30% durante 2 rondas (se puede acumular hasta 2 veces).",
		id = 38326,
		describe_id = "Furry: Mengurangi damage yang diterima dari serangan skill aktif sebesar #C0x5c9970#$(40+skillLevel*0.1-0.1)$%#C0x5B545B#, namun meningkatkan damage yang diterima dari serangan tipe api sebesar 50%. Saat masuk, untuk setiap sekutu bertipe normal, ia meningkatkan HP maksimumnya sebesar 20%. Untuk setiap sekutu tipe bertarung, ia meningkatkan tingkat pertahanan dan penetrasi pertahanannya sendiri sebesar 20%."
	},
	[3971] = {
		zawakeEffectDesc_es = "#C0xC0C0C0#¿No le tienes miedo a la sombra?#C0x5B545B#\n#F10#\n#F40#El Shiny Mega Gengar extiende su brillo para atacar al único enemigo, causando#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, y aumenta SPD y SP.ATK en un 20% durante 3 rondas. Y aplica 1 pila de [Grudge Poison] al objetivo. Y 50% de probabilidad de aplicar adicionalmente 1 pila de [Grudge Poison]",
		zawakeEffectDesc_vn = "#C0xC0C0C0#Você não sente medo da sombra?#C0x5B545B#\n#F10#\n#F40#O Shiny Mega Gengar espalha o brilho para atacar o único inimigo, lidando com#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumenta SPD e SP.ATK em 20% por 3 rodadas. E aplica 1 pilha de [Grudge Poison] ao alvo. E 50% de chance de aplicar adicionalmente 1 pilha de [Grudge Poison]",
		describe_th = "#C0xC0C0C0#คุณไม่กลัวเงาเหรอ#C0x5B545B#\n#F10#\n#F40#เก็นการ์มันเงากระจายแสงเพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหาย#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SPD และ SP.ATK 15% เป็นเวลา 2 รอบ และใช้ [Grudge Poison] 1 กองกับเป้าหมาย",
		zawakeEffectDesc_kr = "#C0xC0C0C0#그림자가 두렵지 않으신가요?#C0x5B545B#\n#F10#\n#F40#빛나는 메가 젠가는 빛을 퍼뜨려 적 하나를 공격해 처리합니다#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 3라운드 동안 SPD와 SP.ATK가 20% 증가합니다. 그리고 대상에게 [Grudge Poison] 1스택을 적용합니다. 그리고 50% 확률로 [Grudge Poison] 1스택을 추가로 적용합니다.",
		zawakeEffectDesc_th = "#C0xC0C0C0#คุณไม่กลัวเงาเหรอ#C0x5B545B#\n#F10#\n#F40#เมก้าเก็นการ์มันเงากระจายแสงเพื่อโจมตีศัตรูตัวเดียว สร้างความเสียหาย#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SPD และ SP.ATK 20% เป็นเวลา 3 รอบ และใช้ [Grudge Poison] 1 กองกับเป้าหมาย และโอกาส 50% ที่จะใช้ [Grudge Poison] เพิ่มเติม 1 กอง",
		describe_en = "#C0xC0C0C0#Don't you feel afraid of the shadow?#C0x5B545B#\n#F10#\n#F40#The Shiny Mega Gengar spreads the shine to attack the single enemy,dealing#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and increases SPD and SP.ATK by 15% for 2 rounds. And applies 1 stack of [Grudge Poison] to the target.",
		describe_es = "#C0xC0C0C0#¿No le tienes miedo a la sombra?#C0x5B545B#\n#F10#\n#F40#El Shiny Mega Gengar extiende su brillo para atacar al único enemigo, causando#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, y aumenta SPD y SP.ATK en un 15% durante 2 rondas. Y aplica 1 pila de [Grudge Poison] al objetivo.",
		zawakeSimpleDesc_en = "increase SPD and SP.ATK by 15% for 2 rounds. \n#F20# \n#F40##C0x5c9970#→increase SPD and SP.ATK by 20% for 3 rounds. And 50% chance to additionally apply 1 stack of [Grudge Poison]",
		describe_vn = "#C0xC0C0C0#Você não tem medo da sombra?#C0x5B545B#\n#F10#\n#F40#O Shiny Mega Gengar espalha o brilho para atacar o único inimigo, lidando com#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumenta SPD e SP.ATK em 15% por 2 rodadas. E aplica 1 pilha de [Grudge Poison] ao alvo.",
		zawakeEffectDesc_en = "#C0xC0C0C0#Don't you feel afraid of the shadow?#C0x5B545B#\n#F10#\n#F40#The Shiny Mega Gengar spreads the shine to attack the single enemy,dealing#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and increases SPD and SP.ATK by 20% for 3 rounds. And applies 1 stack of [Grudge Poison] to the target.And 50% chance to additionally apply 1 stack of [Grudge Poison]",
		zawakeSimpleDesc_vn = "aumente SPD e SP.ATK em 15% por 2 rodadas. \n#F20# \n#F40##C0x5c9970#→aumentar SPD e SP.ATK em 20% por 3 rodadas. E 50% de chance de aplicar adicionalmente 1 pilha de [Grudge Poison]",
		zawakeSimpleDesc_id = "meningkatkan SPD dan SP.ATK sebesar 15% selama 2 putaran. \n#F20# \n#F40##C0x5c9970#→meningkatkan SPD dan SP.ATK sebesar 20% selama 3 ronde. Dan peluang 50% untuk menerapkan 1 tumpukan [Grudge Poison] tambahan",
		zawakeSimpleDesc_es = "aumenta SPD y SP.ATK en un 15% durante 2 rondas. \n#F20# \n#F40##C0x5c9970#→aumenta SPD y SP.ATK en un 20% durante 3 rondas. Y 50 % de posibilidades de aplicar adicionalmente 1 pila de [Grudge Poison]",
		describe_id = "#C0xC0C0C0#Apakah kamu tidak merasa takut dengan bayangan?#C0x5B545B#\n#F10#\n#F40#Shiny Mega Gengar menyebarkan sinarnya untuk menyerang musuh tunggal, menangani#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan meningkatkan SPD dan SP.ATK sebesar 15% selama 2 ronde. Dan menerapkan 1 tumpukan [Grudge Poison] ke target.",
		zawakeSimpleDesc_kr = "2라운드 동안 SPD와 SP.ATK가 15% 증가합니다. \n#F20# \n#F40##C0x5c9970#→3라운드 동안 SPD, SP.ATK가 20% 증가합니다. 그리고 50% 확률로 [Grudge Poison] 1스택 추가 적용",
		zawakeEffectDesc_id = "#C0xC0C0C0#Apakah kamu tidak merasa takut dengan bayangan?#C0x5B545B#\n#F10#\n#F40#Shiny Mega Gengar menyebarkan sinarnya untuk menyerang musuh tunggal, menangani#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan meningkatkan SPD dan SP.ATK sebesar 20% selama 3 ronde. Dan menerapkan 1 tumpukan [Grudge Poison] ke target. Dan peluang 50% untuk menerapkan 1 tumpukan [Grudge Poison] tambahan",
		describe_kr = "#C0xC0C0C0#그림자가 두렵지 않으신가요?#C0x5B545B#\n#F10#\n#F40#빛나는 메가 젠가는 빛을 퍼뜨려 적 하나를 공격해 처리합니다#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, 2라운드 동안 SPD와 SP.ATK가 15% 증가합니다. 그리고 대상에 [Grudge Poison] 1스택을 적용합니다.",
		zawakeSimpleDesc_th = "เพิ่ม SPD และ SP.ATK 15% เป็นเวลา 2 รอบ \n#F20# \n#F40##C0x5c9970#→เพิ่ม SPD และ SP.ATK 20% เป็นเวลา 3 รอบ และโอกาส 50% ที่จะใช้ [Grudge Poison] 1 กองเพิ่มเติม",
		id = 3971
