	[4033] = {
		describe_id = "Mega Steelix menyelinap ke dalam tanah lalu keluar dari sana untuk menyerang semua musuh, yang menyebabkan #C0xE69900#200%P.ATK#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#P.DMG#C0x5B545B#, Jarak antar SPD yang lebih besar dan targetnya, semakin tinggi damage yang ditimbulkan, hingga 40%, setelah itu akan secara acak mendorong 1 Pokémon satu grid ke depan atau bertukar posisi dengan 1 Pokémon di garis depan 【tidak seimbang】 dan menyebabkannya tidak seimbang selama 3 ronde.",
		zawakeEffectDesc_vn = "Efeito adicional: faz com que uma unidade inimiga com o SPD mais alto atinja [Tight Binding] por 2 rodadas\n#F10#\n#F40#[Tight Binding]: fazendo com que o SPD do alvo se torne 1 e ele não possa receber o efeito normal de aumento de SPD durante o período",
		describe_vn = "Mega Steelix se esgueira para o chão e sai dele para atacar todos os inimigos, o que causa #C0xE69900#200%P.ATK#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#P.DMG#C0x5B545B#, A maior lacuna entre o SPD de si mesmo e o alvo, maior o dano causado, até 40%, depois disso empurrará aleatoriamente 1 Pokémon uma grade para frente ou trocará de posição com 1 Pokémon na linha de frente 【desequilibrado】 e o desequilibrará por 3 rodadas.",
		starEffectDesc_id = "Efek tambahan: menyebabkan unit musuh dengan SPD tertinggi menjadi 【Tight-Binding】 selama 2 ronde n#F10#\n#F40#【Tight-Binding】: efek negatif khusus, menyebabkan SPD target sama dengan Mega Steelix, dan target tidak dapat menerima efek peningkatan SPD normal selama periode tersebut",
		zawakeEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: ทำให้ยูนิตศัตรูที่มี SPD สูงสุดเป็น [Tight Binding] เป็นเวลา 2 รอบ\n#F10#\n#F40#[Tight Binding]: ทำให้ SPD ของเป้าหมายกลายเป็น 1 และไม่สามารถรับเอฟเฟกต์การเสริม SPD ปกติได้ในระหว่าง ระยะเวลา",
		starEffectDesc_kr = "추가 효과: SPD가 가장 높은 적 유닛을 2라운드 동안 【긴결】하게 합니다. n#F10#\n#F40#【긴결】: 특별한 부정적인 효과, 대상 SPD를 Mega Steelix와 동일하게 하며, 대상은 해당 기간 동안 정상적인 SPD 증폭 효과를 받을 수 없습니다.",
		describe_es = "Mega Steelix se cuela en el suelo y luego sale para atacar a todos los enemigos, lo que causa #C0xE69900#200%P.ATK#C0x5B545B#+$(skillLevel*4*30)$ #C0xF13B54#P.DMG#C0x5B545B#, la brecha más grande entre su SPD. y el objetivo, mayor será el daño causado, hasta un 40%, después de eso empujará aleatoriamente a 1 Pokémon una cuadrícula hacia adelante o intercambiará posición con 1 Pokémon en la línea del frente 【desequilibrado】 y lo desequilibrará durante 3 rondas.",
