	[40413] = {
		describe_th = "บัซโวลโจมตีเป้าหมายศัตรูตัวเดียวด้วยการโจมตีเพียงครั้งเดียว สร้างความเสียหาย #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B# หาก HP ต่ำกว่า 50% การโจมตีนี้จะมีอัตราแวมไพร์ 30% และเข้า [Wrath of Bug] 2 รอบ ทุกๆ 1% ของชีวิตที่สูญเสียไป โบนัสความเสียหายจะเพิ่มขึ้น 2% และเมื่อถูกโจมตีจะใช้การโจมตีพื้นฐานเพื่อตอบโต้ศัตรู",
		zawakeEffectDesc_vn = "Buzzwole ataca um único alvo inimigo com um golpe, causando#C0xE69900#620%P.ATK#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#P.DMG#C0x5B545B#, se seu HP for inferior a 50%, este ataque carregará um Taxa de vampiro de 30%; E entre [Wrath of Bug] por 2 rodadas: para cada 1% de vida perdida, o bônus de dano aumenta em 2%, o P.ATK aumenta em 20% e, quando atacado, usará um ataque básico para contra-atacar o inimigo",
		simDesc_es = "Buzzwole ataca a un solo objetivo enemigo, causando P.DMG, si su HP está por debajo del 50%, este ataque viene con succión de sangre; Y entra [Wrath of Bug] por 2 rondas",
		describe_es = "Buzzwole ataca a un solo objetivo enemigo con un solo golpe, causando #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#. Si su HP es inferior al 50%, este ataque tendrá una tasa de vampiro del 30%; Y entra [Wrath of Bug] durante 2 rondas: por cada 1% de vida perdida, el bono de daño aumenta un 2%, y cuando sea atacado, utilizará un ataque básico para contraatacar al enemigo.",
		zawakeEffectDesc_th = "บัซโวลโจมตีเป้าหมายศัตรูตัวเดียวด้วยการโจมตีเพียงครั้งเดียว สร้างความเสียหาย#C0xE69900#620%P.ATK#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#P.DMG#C0x5B545B# หาก HP ต่ำกว่า 50% การโจมตีนี้จะมี อัตราแวมไพร์ 30%; และเข้า [Wrath of Bug] 2 รอบ ทุกๆ 1% ของชีวิตที่สูญเสียไป โบนัสความเสียหาย เพิ่มขึ้น 2% P.ATK เพิ่มขึ้น 20% และเมื่อถูกโจมตีจะใช้การโจมตีพื้นฐานตอบโต้ศัตรู",
		starEffectDesc_id = "Selama [Wrath of Bug], semua kerusakan serangan dasar tipe Bug dan tipe Pertarungan serta tingkat kerusakan blok meningkat sebesar 30%, dan setiap serangan aktif mengundang 1 Pokémon tipe Bug dan tipe Pertarungan untuk menyerang musuh",
		starEffectDesc_es = "Durante [Wrath of Bug], el daño de todos los ataques básicos de tipo Insecto y de tipo Lucha y la tasa de ruptura de bloqueo aumentaron en un 30 %, y cada ataque activo invitaba a 1 Pokémon de tipo Insecto y de tipo Lucha a atacar al enemigo.",
		zawakeSimpleDesc_en = "Basic coefficient increased to 620%; [Wrath of Bug] gets an additional 20% P.ATK",
		describe_vn = "Buzzwole ataca um único alvo inimigo com um golpe, causando #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#. Se seu HP for inferior a 50%, este ataque terá uma taxa de vampiro de 30%; E entre [Wrath of Bug] por 2 rodadas: para cada 1% de vida perdida, o bônus de dano é aumentado em 2%, e quando atacado, usará um ataque básico para contra-atacar o inimigo",
		starEffectDesc_th = "ในช่วง [Wrath of Bug] ความเสียหายจากการโจมตีพื้นฐานประเภทแมลงและประเภทต่อสู้และอัตราการทำลายบล็อกเพิ่มขึ้น 30% และการโจมตีที่ใช้งานแต่ละครั้งจะเชิญโปเกมอนประเภทแมลงและประเภทต่อสู้ 1 ตัวมาโจมตีศัตรู",
		starEffectDesc_vn = "Durante [Wrath of Bug], todo o dano de ataque básico do tipo Bug e do tipo Fighting e a taxa de quebra de bloqueio aumentaram em 30%, e cada ataque ativo convidou 1 Pokémon do tipo Bug e do tipo Fighting para atacar o inimigo",
		zawakeEffectDesc_kr = "버즈월은 단일 적 대상을 일격으로 공격하여 #C0xE69900#620%P.ATK#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#P.DMG#C0x5B545B#, HP가 50% 미만일 경우 이 공격은 뱀파이어 비율 30%; 그리고 2라운드 동안 [Wrath of Bug]를 입력합니다. 생명력 손실이 1%마다 피해 보너스가 2% 증가하고 P.ATK가 20% 증가하며, 공격을 받으면 기본 공격을 사용하여 적을 반격합니다.",
		describe_en = "Buzzwole attacks a single enemy target with one blow, dealing #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#. If its HP is lower than 50%, this attack will carry a 30% vampire rate; And enter [Wrath of Bug] for 2 rounds: for every 1% of life lost, the damage bonus is increased by 2%, and when attacked, it will use a basic attack to counterattack the enemy",
		zawakeEffectDesc_id = "Buzzwole menyerang satu target musuh dengan satu pukulan, menimbulkan#C0xE69900#620%P.ATK#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#P.DMG#C0x5B545B#, jika HPnya lebih rendah dari 50%, serangan ini akan menghasilkan tingkat vampir 30%; Dan masuk [Wrath of Bug] untuk 2 ronde: setiap 1% nyawa yang hilang, bonus damage meningkat sebesar 2%, P.ATK meningkat sebesar 20%, dan ketika diserang akan menggunakan serangan dasar untuk menyerang balik musuh",
		describe_id = "Buzzwole menyerang satu target musuh dengan satu pukulan, menyebabkan #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#. Jika HP-nya lebih rendah dari 50%, serangan ini akan membawa tingkat vampir sebesar 30%; Dan masukkan [Wrath of Bug] untuk 2 ronde: untuk setiap 1% nyawa yang hilang, bonus kerusakan meningkat sebesar 2%, dan ketika diserang, ia akan menggunakan serangan dasar untuk menyerang balik musuh",
		simDesc_en = "Buzzwole attacks a single enemy target, causing P.DMG, if its HP is below 50%, this attack comes with blood sucking; And enter [Wrath of Bug] for 2 rounds",
		simDesc_vn = "Buzzwole ataca um único alvo inimigo, causando P.DMG, se seu HP estiver abaixo de 50%, esse ataque vem com sucção de sangue; E entre [Wrath of Bug] por 2 rodadas",
		describe_kr = "버즈월레는 단일 적 대상을 일격으로 공격해 #C0xE69900#600% P.ATK#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54#P.DMG#C0x5B545B#를 줍니다. HP가 50%보다 낮으면 이 공격은 30%의 뱀파이어 비율을 갖습니다. 그리고 2라운드 동안 [Wrath of Bug]를 입력합니다. 생명력 손실이 1%마다 피해 보너스가 2% 증가하고, 공격을 받으면 기본 공격을 사용하여 적을 반격합니다.",
		simDesc_th = "Buzzwole โจมตีศัตรูเป้าหมายเดียว ทำให้เกิด P.DMG หาก HP ต่ำกว่า 50% การโจมตีนี้จะมาพร้อมกับการดูดเลือด และเข้า[Wrath of Bug] 2 รอบ",
		zawakeEffectDesc_es = "Buzzwole ataca a un solo objetivo enemigo de un solo golpe, causando#C0xE69900#620%P.ATK#C0x5B545B#+$(skillLevel*4*36)$ #C0xF13B54#P.DMG#C0x5B545B#, si su HP es inferior al 50%, este ataque llevará un 30% tasa de vampiros; Y ingresa [Wrath of Bug] por 2 rondas: por cada 1% de vida perdida, el bono de daño aumenta un 2%, P.ATK aumenta un 20%, y cuando sea atacado, usará un ataque básico para contraatacar al enemigo.",
