		describe_kr = [[
#L10#원 히트 킬:#L0#오라 스킬, 아군의 첫 번째 궁극기 스킬의 데미지가 증가됩니다#C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# (격투형과 어둠형이 2배가 됩니다)
#F10#
#F40##L10#상상의 위험에 용감하게 맞서세요:#L0#자신의 차례가 되기 전에 HP가 가장 낮은 적에게 [Imaginary] 1레이어를 추가합니다. 팀 내 격투형, 암흑형이 기본 공격 및 궁극기 스킬 시전 시 대상에 [Imaginary] 추가
#F10#
#F40#상상: 부정적 효과, 레이어당 취약성 10%, 공격 시 데미지 20% 감소 Kubfu 시리즈는 최대 3겹까지 쌓은 후 [Dangerous] 2회분씩 추가됩니다. [Dangerous]가 사라지면 [Imaginary]도 사라집니다
위험: 부정적인 효과, 해제 불가, 치유 차단, 데미지 감소 및 P.DEF 50% 감소, 격투 타입 포켓몬의 공격을 받으면 방패를 무시하고 이동할 수 없습니다. 공유됨]],
		starEffectDesc_th = "การเข้าสู่สนามรบจะเพิ่ม [Imaginary] ให้กับเป้าหมายศัตรูที่มี HP ต่ำที่สุด เมื่อมีศัตรู [Dangerous] ปรากฎบนสนาม เพิ่มค่าความโกรธของตัวเอง 300 แต้มและ SPD 40% เป็นเวลา 1 รอบ",
		starEffectDesc_kr = "전장에 입장하면 HP가 가장 낮은 적 대상에게 [Imaginary]가 추가됩니다. 필드에 [Dangerous] 적이 나타나면 1라운드 동안 자신의 분노 포인트가 300포인트 증가하고 SPD가 40% 증가합니다.",
		starEffectDesc_vn = "Entrar no campo de batalha adiciona [Imaginary] ao alvo inimigo com o HP mais baixo; quando um inimigo [Dangerous] aparecer no campo, aumente seus próprios 300 pontos de Fúria e 40% de SPD por 1 rodada",
		describe_th = [[
#L10#One Hit Kill:#L0#ทักษะออร่า DMG ของทักษะอัลติเมทแรกของพันธมิตรเพิ่มขึ้น#C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# (ประเภทการต่อสู้และความมืดจะเพิ่มเป็นสองเท่า)
#F10#
#F40##L10#เผชิญหน้ากับอันตรายในจินตนาการด้วยความกล้าหาญ:#L0#เพิ่ม [Imaginary] 1 ชั้นให้กับศัตรูที่มี HP ต่ำสุดก่อนถึงเทิร์นของตัวเอง เมื่อประเภทการต่อสู้และความมืดในทีมทำการโจมตีพื้นฐานและทักษะอัลท์ เพิ่ม [Imaginary] ไปยังเป้าหมาย
#F10#
#F40#จินตภาพ: เอฟเฟกต์เชิงลบ 10% ช่องโหว่ต่อเลเยอร์ DMG ลดลง 20% เมื่อโจมตี ซีรีส์ Kubfu หลังจากซ้อนถึง 3 ชั้น [Dangerous] จะมาเพิ่ม 2 รอบ เมื่อ [Dangerous] หายไป [Imaginary] ก็จะหายไปเช่นกัน
 อันตราย: เอฟเฟกต์เชิงลบ ไม่สามารถลบล้างได้ บล็อกการรักษา ลดการลดความเสียหาย 50% และ P.DEF การถูกโจมตีจากโปเกมอนประเภทต่อสู้จะเพิกเฉยต่อโล่และไม่สามารถ แบ่งปัน]],
		starEffectDesc_id = "Memasuki medan perang menambah [Imaginary] pada target musuh dengan HP terendah; ketika [Dangerous] musuh muncul di lapangan, tingkatkan 300 poin Rage dan 40% SPD selama 1 ronde",
		describe_vn = [[
#L10#One hit kill:#L0#Aura Skill, o DMG da primeira habilidade Ult do aliado é aumentado#C0x5c9970#$(15+skillLevel*0.05-0.05)$%#C0x5B545B# (tipo Fighting e Dark será duplicado)
#F10#
