	[70481] = {
		zawakeEffectDesc_kr = "뮤츠는 초능력을 모아 적 1명을 공격하는 파워폭탄을 만들어 딜을 #C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#하고, 자신의 SP.ATK를 30% 증가시킵니다. 2라운드 동안 속도가 15% 증가합니다.",
		zawakeEffectDesc_vn = "Mewtwo reúne o superpoder para fazer uma bomba poderosa para atacar um único inimigo para lidar com #C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumentar seus próprios 30% de SP.ATK e 15% de velocidade por 2 rodadas",
		simDesc_es = "Mew reúne una bomba de energía con su poder psíquico para atacar a un solo objetivo enemigo.",
		describe_en = "Mewtwo gathers the super power to make a power bomb to attack a single enemy to deal#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, and increase own 20% SP.ATK and 10% Speed for 2 rounds",
		zawakeEffectDesc_th = "มิวทูรวบรวมพลังพิเศษเพื่อสร้างระเบิดพลังโจมตีศัตรูหนึ่งตัวเพื่อสร้างความเสียหาย#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# และเพิ่ม SP.ATK ของตัวเอง 30% และความเร็ว 15% เป็นเวลา 2 รอบ",
		describe_es = "Mewtwo reúne el superpoder para hacer una bomba de poder para atacar a un solo enemigo y tratar#C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B# y aumentar su propio 20% SP.ATK. y 10% de velocidad durante 2 rondas",
		simDesc_vn = "Mew reúne uma bomba de energia com seu poder psíquico para atacar um único alvo inimigo",
		zawakeSimpleDesc_en = "increase own 20% SP.ATK and 10% Speed for 2 rounds\n#F20#\n#F40##C0x5c9970#→increase own 30% SP.ATK and 15% Speed for 2 rounds",
		describe_vn = "Mewtwo reúne o superpoder para fazer uma bomba poderosa para atacar um único inimigo para lidar com #C0x3D8A99#100%SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, e aumentar seus próprios 20% de SP.ATK e 10% de velocidade por 2 rodadas",
		zawakeEffectDesc_id = "Mewtwo mengumpulkan kekuatan super untuk membuat bom kekuatan untuk menyerang satu musuh untuk menangani#C0x3D8A99#100% SP.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#SP.DMG#C0x5B545B#, dan meningkatkan 30% SP.ATK miliknya dan Kecepatan 15% untuk 2 putaran",
