	[9916] = {
		describe_id = "Sebelum setiap serangan aktif, tingkatkan tingkat rebound diri #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# selama 1 putaran (dapat ditumpangkan 3 kali). Saat diri menerima kerusakan fatal, jika ada unit di bidang musuh yang telah \"stepped on the shadow\", simpan 1 poin HP, konsumsi \"stepped on the shadow\" unit musuh secara acak, lalu tukarkan nilai nyawa dengan unit tersebut. Wobbuffet bersifat autoimun [Step on Shadow]",
		zawakeEffectDesc_vn = "Antes de cada ataque ativo, melhore a si mesmo #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# taxa de rebote por 2 rodadas (pode ser sobreposto 3 vezes).Quando o próprio recebe dano fatal, se houver uma unidade no campo do inimigo que tenha sido \"stepped on the shadow\", mantenha 1 ponto de HP, consuma o \"stepped on the shadow\" de uma unidade inimiga aleatória e depois troque o valor da vida com ele. Com certeza, Weng é autoimune [Step on Shadow]",
		describe_vn = "Antes de cada ataque ativo, aumente a taxa de rebote por 1 rodada (pode ser sobreposta 3 vezes). Quando o próprio recebe dano fatal, se houver uma unidade no campo do inimigo que tenha sido #C0x5c9970#, mantenha 1 ponto de HP, consuma o $(20+skillLevel*0.2-0.2)$ de uma unidade inimiga aleatória e depois troque o valor da vida com ele.Wobbuffet é autoimune #C0x5B545B#",
		starEffectDesc_id = "Efek tambahan: Di awal pertempuran, buat elf acak yang batas atas nyawanya lebih rendah dari milikmu secara permanen mendapatkan [Shadow Stepping]. Saat kamu menerima serangan aktif, kamu punya peluang 40% terkena pukulan ekor, dan kamu akan mendapatkan efek [Double Refund] tambahan selama 1 putaran (dapat ditumpangkan dengan efek pelunasan ganda dari skill kecil)",
		zawakeEffectDesc_th = "ก่อนการโจมตีแต่ละครั้ง ให้ปรับปรุงตนเอง #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# อัตราการตอบสนอง 2 รอบ (สามารถซ้อนทับได้ 3 ครั้ง) เมื่อตนเองได้รับความเสียหายร้ายแรง ถ้ามียูนิตในสนามของศัตรูที่ได้รับ \"stepped on the shadow\" เก็บ 1 แต้ม HP ใช้ \"stepped on the shadow\" ของยูนิตศัตรูแบบสุ่ม แล้วแลกมูลค่าชีวิตกับมัน แน่นอนว่าเวงเป็นภูมิต้านทานตัวเอง [Step on Shadow]",
		starEffectDesc_kr = "추가 효과 : 전투 시작 시 생명력 상한이 자신보다 낮은 랜덤 엘프를 영구 획득 [Shadow Stepping]. 액티브 공격을 받을 때 꼬리에 맞을 확률이 40%, 그리고 1라운드 동안 추가 [Double Refund] 효과를 얻을 수 있습니다. (소량 스킬의 이중 상환 효과와 중첩 가능)",
		describe_es = "Antes de cada ataque activo, aumenta la tasa de rebote del yo #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# durante 1 ronda (se puede superponer 3 veces). Cuando el yo recibe daño fatal, si hay una unidad en el campo enemigo que ha sido \"stepped on the shadow\", conserva 1 punto de HP, consume el \"stepped on the shadow\" de una unidad enemiga aleatoria y luego intercambia el valor de vida con ella. Wobbuffet es autoinmune [Step on Shadow]",
		zawakeSimpleDesc_en = "Increase the rebound rate for 1 round before receiving an active attack\n#F20#\n#F40##C0x5c9970#→Increase the rebound rate for 2 rounds before receiving an active attack",
		starEffectDesc_es = "Efecto adicional: al comienzo de la batalla, haz que un elfo aleatorio cuyo límite superior de vida sea inferior al tuyo obtenga permanentemente [Shadow Stepping]. Cuando recibes un ataque activo, tienes un 40% de posibilidades de ser golpeado por la cola. y obtendrás un efecto [Double Refund] adicional durante 1 ronda (se puede superponer con el efecto de doble reembolso de las habilidades pequeñas)",
		starEffectDesc_th = "เอฟเฟกต์เพิ่มเติม: เมื่อเริ่มการต่อสู้ สุ่มสร้างเอลฟ์ที่มีขีดจำกัดชีวิตสูงสุดต่ำกว่าของคุณเองจะได้รับถาวร [Shadow Stepping] เมื่อคุณได้รับการโจมตีที่ใช้งานอยู่ คุณมีโอกาส 40% ที่จะถูกหางโจมตี และคุณจะได้รับเอฟเฟกต์ [Double Refund] เพิ่มเติม 1 รอบ (สามารถซ้อนทับเอฟเฟกต์การชำระคืนสองเท่าของทักษะขนาดเล็กได้)",
		zawakeEffectDesc_id = "Sebelum setiap serangan aktif, tingkatkan tingkat rebound diri #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# selama 2 ronde (dapat ditumpangkan 3 kali). Saat diri menerima kerusakan fatal, jika ada unit di bidang musuh yang telah \"stepped on the shadow\", simpan 1 poin HP, konsumsi \"stepped on the shadow\" unit musuh secara acak, lalu tukarkan nilai nyawa dengan unit tersebut. Benar saja, Weng mengidap autoimun [Step on Shadow]",
		zawakeEffectDesc_es = "Antes de cada ataque activo, mejora la tasa de rebote #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# durante 2 rondas (se puede superponer 3 veces). Cuando el yo recibe daño fatal, si hay una unidad en el campo enemigo que ha sido \"stepped on the shadow\", conserva 1 punto de HP, consume el \"stepped on the shadow\" de una unidad enemiga aleatoria y luego intercambia el valor de vida con ella. Efectivamente, Weng es autoinmune [Step on Shadow]",
		describe_en = "Before each active attack, increase self #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# rebound rate for 1 round (can be superimposed 3 times).When self receives fatal damage, if there is a unit on the enemy's field that has been \"stepped on the shadow\", keep 1 point of HP, consume the \"stepped on the shadow\" of a random enemy unit, and then exchange the life value with it.Wobbuffet is autoimmune [Step on Shadow]",
		zawakeSimpleDesc_th = "เพิ่มอัตราการเด้งกลับ 1 รอบ ก่อนที่จะรับการโจมตีที่ใช้งานอยู่\n#F20#\n#F40##C0x5c9970#→เพิ่มอัตราการเด้งกลับ 2 รอบ ก่อนที่จะได้รับการโจมตีที่ใช้งานอยู่",
		zawakeEffectDesc_kr = "각 활성 공격 전 자신을 향상 #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# 2라운드 동안 반동률(3회 중첩 가능). 자신이 치명적인 피해를 받았을 때 적 필드에 유닛이 있는 경우 \"stepped on the shadow\", HP 1점을 유지하고, 무작위 적 유닛의 \"stepped on the shadow\"를 소비한 다음 생명 값을 그것과 교환합니다.물론, Weng은 자가 면역입니다 [Step on Shadow]",
		zawakeSimpleDesc_kr = "액티브 어택 받기 전 1라운드 리바운드 증가\n#F20#\n#F40##C0x5c9970#→액티브 공격 받기 전 2라운드 리바운드 증가",
		zawakeEffectDesc_en = "Before each active attack, improve self #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# rebound rate for 2 rounds (can be superimposed 3 times).When self receives fatal damage, if there is a unit on the enemy's field that has been \"stepped on the shadow\", keep 1 point of HP, consume the \"stepped on the shadow\" of a random enemy unit, and then exchange the life value with it.Sure enough, Weng is autoimmune [Step on Shadow]",
		describe_kr = "각 활성 공격 전 자신에게 #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# 1라운드 반동률이 증가합니다(3회 중첩 가능). 자신이 치명적인 피해를 입었을 때 적 필드에 적 필드에 있는 유닛이 있는 경우 \"stepped on the shadow\", HP 1점을 유지하고, 무작위 적 유닛의 \"stepped on the shadow\"를 소비한 다음 생명값을 그것과 교환합니다.워버핏은 자가면역입니다[Step on Shadow]",
		zawakeSimpleDesc_vn = "Aumente a taxa de rebote por 1 rodada antes de receber um ataque ativo\n#F20#\n#F40##C0x5c9970#→Aumente a taxa de rebote por 2 rodadas antes de receber um ataque ativo",
		zawakeSimpleDesc_id = "Tingkatkan tingkat rebound selama 1 putaran sebelum menerima serangan aktif\n#F20#\n#F40##C0x5c9970#→Naikkan tingkat rebound selama 2 putaran sebelum menerima serangan aktif",
		starEffectDesc_vn = "Efeito adicional: No início da batalha, faça com que um elfo aleatório cujo limite superior de vida seja inferior ao seu obtenha permanentemente [Shadow Stepping]. Ao receber um ataque ativo, você tem 40% de chance de ser atingido pela cauda, e você obterá um efeito [Double Refund] adicional por 1 rodada (pode ser sobreposto ao efeito de reembolso duplo de pequenas habilidades)",
		zawakeSimpleDesc_es = "Aumenta la tasa de rebote durante 1 ronda antes de recibir un ataque activo\n#F20#\n#F40##C0x5c9970# →Aumenta la tasa de rebote durante 2 rondas antes de recibir un ataque activo",
		describe_th = "ก่อนการโจมตีแต่ละครั้ง เพิ่มอัตราการฟื้นตัวของตัวเอง #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B# 1 รอบ (สามารถซ้อนทับได้ 3 ครั้ง) เมื่อตนเองได้รับความเสียหายร้ายแรง หากมียูนิตในสนามของศัตรูที่ได้รับ \"stepped on the shadow\" เก็บ 1 แต้ม HP ใช้ \"stepped on the shadow\" ของยูนิตศัตรูแบบสุ่ม แล้วแลกมูลค่าชีวิตกับมัน วอบบัฟเฟตมีภูมิคุ้มกันอัตโนมัติ [Step on Shadow]",
		starEffectDesc_en = "Additional effect: At the beginning of the battle, make a random elf whose upper limit of life is lower than your own permanently get [Shadow Stepping].When you receive an active attack, you have a 40% chance of being hit by the tail, and you will get an additional [Double Refund] effect for 1 round (can be superimposed with the double repayment effect of small skills)",
		id = 9916
	},
